QUOTES: list[dict[str, Any]] = [
    {"id": "c1a1-01", "text": "蒹葭苍苍，白露为霜。所谓伊人，在水一方。", "source": "《诗经·秦风·蒹葭》", "concept": "可望难即", "explanation": "芦苇密密地立着，露水结成了霜，想见的人还在水的另一边。不是没有路，是路要等水退、等天亮。隔着一段距离的想念，也可以是一种安静的陪伴。", "western": "柏拉图在《会饮》里把爱若斯写成对美的欲求：它永远停在缺乏与拥有之间，所以总带着一点疼。", "tags": ["期待", "迷茫", "平静", "晨间"]},
    {"id": "c1a1-02", "text": "昔我往矣，杨柳依依。今我来思，雨雪霏霏。", "source": "《诗经·小雅·采薇》", "concept": "去来之间", "explanation": "当年离家，柳枝轻轻拂着衣袖；如今回来，雪下得正密。同一条路，去时和回时是两种心情。时间没有改变路，只是把人换了一副心境。", "western": "赫拉克利特说，人不能两次踏进同一条河流：河水一直在流，踏进河水的人也已经不是原来那个。", "tags": ["变化", "低落", "雨", "反思"]},
    {"id": "c1a1-03", "text": "它山之石，可以攻玉。", "source": "《诗经·小雅·鹤鸣》", "concept": "借石磨玉", "explanation": "别的山上的石头，也能用来打磨自己的玉。借来的眼光、别人的一句话，未必属于你，却可能刚好磨掉你身上的一处毛糙。", "western": "波普尔认为知识靠批评生长：一个猜想被别人的石头敲过，才可能变硬，没被敲过的多半还软着。", "tags": ["反思", "专注", "迷茫"]},
    {"id": "c1a1-04", "text": "高山仰止，景行行止。", "source": "《诗经·小雅·车舝》", "concept": "仰望之心", "explanation": "看见高山就抬头，看见大路就走上去。仰望不是自卑，是给自己一个可以校准的方向；知道自己还差多远，心里反而踏实。", "western": "康德把“敬重”看作唯一不由愉悦而生的情感：它来自我们意识到自己该做什么，而不是别人有多好。", "tags": ["期待", "感激", "反思"]},
    {"id": "c1a1-05", "text": "靡不有初，鲜克有终。", "source": "《诗经·大雅·荡》", "concept": "有始有终", "explanation": "开始一件事时，人总是齐全的：热情、计划、决心都在。难的是中间那段没有掌声的路，走不到最后，未必是懒，多半是那一段没人替你照亮。", "western": "亚里士多德认为德性不是天生的，而是靠重复的行为养成的习惯；做一次不算，做成习惯才算。", "tags": ["拖延", "专注", "反思"]},
    {"id": "c1a1-06", "text": "知我者，谓我心忧；不知我者，谓我何求。", "source": "《诗经·王风·黍离》", "concept": "被误读的忧", "explanation": "懂我的人，看得出我心里堵着什么；不懂的人，只问我到底想要什么。同一份沉默，被读成两种东西。被误读的时候，不必急着解释。", "western": "克尔凯郭尔认为真理只对单个的个体成立，人群反而把它稀释；被误读因此几乎是独自存在的常态。", "tags": ["孤独", "低落", "社交"]},
    {"id": "c1a1-07", "text": "风雨如晦，鸡鸣不已。既见君子，云胡不喜。", "source": "《诗经·郑风·风雨》", "concept": "雨中相见", "explanation": "天暗得像傍晚，雨一直下，鸡还在叫。就在这样的天气里见到你，哪能不高兴。坏天气没有变好，是有人进来，把它分担了一半。", "western": "爱比克泰德说，让人不安的不是事情本身，而是人对事情的判断；同一个雨天，可以被判成两种天气。", "tags": ["雨", "平静", "期待", "社交"]},
    {"id": "c1a1-08", "text": "衡门之下，可以栖迟。", "source": "《诗经·陈风·衡门》", "concept": "简处可安", "explanation": "一根横木当门，底下也能安身歇息。不是没有更好的地方，是此刻这些已经够用。把想要的东西减掉几样，日子会先松一口气。", "western": "伊壁鸠鲁说，面包和水也能带来与盛宴相同的快乐，只要吃的人心里不再缺什么。", "tags": ["平静", "放空", "休息"]},
    {"id": "c1a1-09", "text": "满招损，谦受益，时乃天道。", "source": "《尚书·大禹谟》", "concept": "留空之益", "explanation": "装满了就往外溢，留一点空才装得下新的东西。谦虚不是把自己说小，是给还没发生的事留位置。人一觉得够满，耳朵就先关上了。", "western": "苏格拉底把“知道自己不知道”当作智慧的开端；承认无知不是退让，是给求知留出一道门。", "tags": ["平静", "反思", "期待"]},
    {"id": "c1a1-10", "text": "功崇惟志，业广惟勤。", "source": "《尚书·周官》", "concept": "志勤相济", "explanation": "要做成一件大事，先得有方向；要把它做久，靠的是每天肯动手。志向定高度，勤勉定长度，缺一样，事情都停在半路。", "western": "西蒙娜·薇依把注意力看作一种稀有的给予：不打扰地看着一件事，本身就是对它的尊重。", "tags": ["专注", "拖延", "期待"]},
    {"id": "c1a1-11", "text": "若升高，必自下；若陟遐，必自迩。", "source": "《尚书·太甲下》", "concept": "自迩而行", "explanation": "想登高，得从脚下这一级开始；想走远，得从最近的一段开始。远不是另一件事，它只是很多个眼前接起来的样子。", "western": "亚里士多德用潜能与现实解释运动：远路此刻只是尚未实现的近步，一步一步才把它变成现实。", "tags": ["拖延", "专注", "晨间"]},
    {"id": "c1a1-12", "text": "人心惟危，道心惟微，惟精惟一，允执厥中。", "source": "《尚书·大禹谟》", "concept": "允执其中", "explanation": "心思容易偏，微妙的道理容易看不清。所以要把散开的念头收回来，专注在一处，再守住不偏不倚的那条线。不是没有杂念，是知道把重心放哪。", "western": "亚里士多德把德性定在两种极端之间：勇敢在鲁莽与怯懦之间，靠当下的判断，而不是取中间数。", "tags": ["专注", "平静", "反思"]},
    {"id": "c1a1-13", "text": "好问则裕，自用则小。", "source": "《尚书·仲虺之诰》", "concept": "问则有余", "explanation": "肯问的人，知道的会越来越多；总觉得自己对的人，路会越走越窄。问一句不丢人，它只是承认世界比你手里的答案大一点。", "western": "哈贝马斯把理解建立在彼此的提问与回应上：理性不是一个人的独白，而是共同完成的商谈。", "tags": ["反思", "社交", "迷茫"]},
    {"id": "c1a1-14", "text": "天行健，君子以自强不息。", "source": "《周易·乾卦》", "concept": "不息之力", "explanation": "天体一刻不停地转，人也可以借这个意象提醒自己：不必猛冲，只要不停。真正的自强常常很安静，是今天也做了昨天那一小步。", "western": "斯宾诺莎把万物保存自身、延展自身力量的倾向称为“努力”，人的德性就长在这股努力里。", "tags": ["专注", "晨间", "运动"]},
    {"id": "c1a1-15", "text": "地势坤，君子以厚德载物。", "source": "《周易·坤卦》", "concept": "承载之德", "explanation": "大地不挑拣，什么都接住，所以能长东西。厚德不是没有原则，是容量够大：能听不同的声音，也能承接别人的重量，而不急着反弹。", "western": "列维纳斯认为，他者的面容先于我的自由向我提出要求；责任不是交换来的，是被动接住的。", "tags": ["平静", "释然", "社交"]},
    {"id": "c1a1-16", "text": "穷则变，变则通，通则久。", "source": "《周易·系辞下》", "concept": "穷而后通", "explanation": "走到尽头，事情自己会转向；转开了，路才通；通了，才能长久。卡住的时候不一定是坏事，它常常在提醒：原来的走法已经用完了。", "western": "怀特海的过程哲学认为，实在不是静止的东西，而是一个个正在生成的事件；变化不是意外，是它的构成。", "tags": ["变化", "释然", "反思"]},
    {"id": "c1a1-17", "text": "君子藏器于身，待时而动。", "source": "《周易·系辞下》", "concept": "待时而动", "explanation": "把本事收在身上，不急着给人看，等该动的时候再动。等待不是空等，是把工具磨好、把手练稳，让机会来的时候你接得住。", "western": "马基雅维利把命运比作会泛滥的河：平时修堤的人，汛期才有余地，光靠勇气挡不住水。", "tags": ["期待", "专注", "迷茫"]},
    {"id": "c1a1-18", "text": "无平不陂，无往不复。", "source": "《周易·泰卦》", "concept": "往复之理", "explanation": "没有一直平坦的路，也没有只去不回的事。顺的时候别把话说满，难的时候也别认定到底了。起落是路的形状，不是你的失败。", "western": "尼采的“永恒轮回”不是宿命论，而是一个问题：若一切都要再来一次，你能否仍然肯定它。", "tags": ["变化", "释然", "低落"]},
    {"id": "c1a1-19", "text": "大学之道，在明明德，在亲民，在止于至善。", "source": "《礼记·大学》", "concept": "明德新民", "explanation": "学习这件事，先要把自己心里那点明亮擦出来，再推及身边的人，最后停在一个更好的地方。它不是往上爬，是往里走，再往外照。", "western": "康德在《什么是启蒙》里说，启蒙就是人敢于运用自己的理智，不必等别人替他判断。", "tags": ["反思", "专注", "期待"]},
    {"id": "c1a1-20", "text": "知止而后有定，定而后能静。", "source": "《礼记·大学》", "concept": "知止能定", "explanation": "先知道自己停在哪儿，心才定得下来；定下来，才静得下来。焦躁常常不是因为事多，是因为没有划出“到这里就够了”的那条线。", "western": "海德格尔晚期讲“泰然任之”：不是抓住或推开事物，而是让它们作为它们自己待在那里。", "tags": ["平静", "放空", "焦虑"]},
    {"id": "c1a1-21", "text": "苟日新，日日新，又日新。", "source": "《礼记·大学》", "concept": "日新又新", "explanation": "假如今天能洗净一次，就天天洗，再天天洗。更新不是一次彻底的改造，是允许自己每天重来一遍，包括那些昨天没做好的部分。", "western": "奥古斯丁把转变写成一次性的皈依时刻；日新却把更新摊到每一天，允许它反复发生。", "tags": ["晨间", "期待", "变化"]},
    {"id": "c1a1-22", "text": "博学之，审问之，慎思之，明辨之，笃行之。", "source": "《礼记·中庸》", "concept": "学问思辨行", "explanation": "广泛地学，仔细地问，慎重地想，清楚地分辨，然后真的去做。五步里最容易停在前四步：想明白了，却始终没有开始那一下。", "western": "笛卡尔在《方法谈》里立下四条规则：只接受清晰分明的，分解难题，由简入繁，处处复核。", "tags": ["阅读", "写论文", "专注", "反思"]},
    {"id": "c1a1-23", "text": "君子素其位而行，不愿乎其外。", "source": "《礼记·中庸》", "concept": "素位而行", "explanation": "处在什么位置，就把那个位置上的事做好，不总盯着别处。不是认命，是先把手边这一摊弄清楚；脚下的地稳了，才谈得上换地方。", "western": "斯多葛派区分“在我之内的”与“不在我之内的”，把力气只花在前者上，这是他们说的自由。", "tags": ["专注", "平静", "反思"]},
    {"id": "c1a1-24", "text": "人一能之，己百之；人十能之，己千之。", "source": "《礼记·中庸》", "concept": "以百当一", "explanation": "别人一遍会，我就做一百遍；别人十遍会，我就做一千遍。这不是笨办法，是把差距换算成次数：只要次数够，慢也能到。", "western": "亚里士多德认为，潜能要经过反复的现实活动才能定型；天资只是起点，练习决定它长成什么。", "tags": ["专注", "复习考试", "拖延"]},
    {"id": "c1a1-25", "text": "学然后知不足，教然后知困。", "source": "《礼记·学记》", "concept": "教学相长", "explanation": "学了，才知道自己缺什么；教了，才知道哪里其实没懂。困惑不是退步的信号，它往往是你刚走到边界上，看见了外面的地方。", "western": "杜威认为理解来自做事与受挫的循环：没被一件事卡住过的人，也很难真的懂它。", "tags": ["复习考试", "反思", "阅读"]},
    {"id": "c1a1-26", "text": "藏焉修焉，息焉游焉。", "source": "《礼记·学记》", "concept": "藏修息游", "explanation": "学习要有收进去的时候，也要有放开来的时候：藏起来修，停下来游。一直绷着，学问会僵；会休息的人，才走得长。", "western": "亚里士多德把闲暇看作活动的目的之一：不为别的而做的事，才最像人自己的事。", "tags": ["休息", "放空", "平静"]},
    {"id": "c1a1-27", "text": "凡音之起，由人心生也。", "source": "《礼记·乐记》", "concept": "音由心生", "explanation": "声音是从人心里生出来的。心里动了，才成声，才成音。所以看一个人常听什么，往往比听他怎么说，更早知道他在什么状态里。", "western": "海德格尔认为情绪不是心里的杂音，而是人已经处在世界之中的方式；调子变了，世界也跟着变。", "tags": ["平静", "反思", "夜晚"]},
    {"id": "c1a1-28", "text": "大乐必易，大礼必简。", "source": "《礼记·乐记》", "concept": "易简之真", "explanation": "最好的音乐往往简单，最好的礼也往往朴素。把多余的装饰去掉，剩下的才见真章。费力堆出来的东西，常常是在替不放心打掩护。", "western": "奥卡姆的剃刀说，不必增设多余的假设；能简单说清的，就不靠层层堆叠来撑住。", "tags": ["平静", "放空", "释然"]},
    {"id": "c1a1-29", "text": "毋不敬，俨若思，安定辞。", "source": "《礼记·曲礼上》", "concept": "敬而安定", "explanation": "不轻慢，神情像在思量什么，说话稳当。敬不是怕谁，是把眼前这件事当回事。人一认真，姿态先安静下来，话也不容易说错。", "western": "康德区分“合乎义务”与“出于义务”：同一件事，是怕罚还是认它对，分量并不一样。", "tags": ["专注", "平静", "社交"]},
    {"id": "c1a1-30", "text": "礼尚往来。往而不来，非礼也。", "source": "《礼记·曲礼上》", "concept": "往来成礼", "explanation": "礼讲的是有来有往：只来不往，关系就断在半路。回应不必贵重，但要有着落。人情的温度，常常就藏在“我收到了，也回你一句”里。", "western": "塞涅卡在《论恩惠》里说，恩惠一旦被记账、被催讨，就不再是恩惠，而成了一笔债。", "tags": ["社交", "感激", "平静"]},
    {"id": "c1a2-01", "text": "学而时习之，不亦说乎？", "source": "《论语·学而》", "concept": "习而能悦", "explanation": "学过的东西，隔些日子再拿起来练一遍，常会忽然多懂一点。那种重复里的新鲜不是浪费时间，而是让知识慢慢长在身上。", "western": "亚里士多德认为德性靠习惯养成，像学琴一样，在反复练习里把外在的规矩变成本能。", "tags": ["复习考试", "专注", "期待"]},
    {"id": "c1a2-02", "text": "温故而知新，可以为师矣。", "source": "《论语·为政》", "concept": "温故知新", "explanation": "旧笔记、旧书、旧经验，再翻一次时常会照见当时没看懂的部分。不是原地打转，而是让过去的东西在今天的眼光里重新发亮。", "western": "克尔凯郭尔区分回忆与重复：回忆向后看，重复则把过去重新活成向前的一步。", "tags": ["复习考试", "阅读", "反思"]},
    {"id": "c1a2-03", "text": "知之为知之，不知为不知，是知也。", "source": "《论语·为政》", "concept": "知之为知", "explanation": "能坦然说一句“这个我还不懂”，心里反而松一点。把不知道的地方标出来，才知道下一步该往哪里学，不必用含糊撑住场面。", "western": "苏格拉底说，他的智慧只在于知道自己无知；承认无知不是退让，而是求知的入口。", "tags": ["反思", "焦虑", "释然"]},
    {"id": "c1a2-04", "text": "君子欲讷于言而敏于行。", "source": "《论语·里仁》", "concept": "讷言敏行", "explanation": "话少一点，手上的事快一点。很多承诺不必先说出来，等做成了，别人自然看得见；没做成时，也少了一份要向人解释的压力。", "western": "塞涅卡说，哲学教人去做，而不是教人去说；把原则活进日常，比谈论它更难，也算数。", "tags": ["拖延", "专注", "反思"]},
    {"id": "c1a2-05", "text": "德不孤，必有邻。", "source": "《论语·里仁》", "concept": "德者不孤", "explanation": "认真做事、待人厚道，未必立刻有人回应，但同类的人会慢慢靠近。你不必为了合群改掉自己，安静地做好该做的，就是邀请。", "western": "西塞罗在《论友谊》里说，友谊让顺境更亮，也让逆境变得可以承受。", "tags": ["孤独", "社交", "感激"]},
    {"id": "c1a2-06", "text": "工欲善其事，必先利其器。", "source": "《论语·卫灵公》", "concept": "利器善事", "explanation": "想把事情做好，先把工具和环境收拾顺：清一张桌子，装好该装的软件，备好明天要用的资料。磨刀不误砍柴，心也会跟着定下来。", "western": "培根说，赤手空拳或单凭理解都做不成大事；事情要靠工具与助力完成。", "tags": ["代码", "专注", "拖延"]},
    {"id": "c1a2-07", "text": "逝者如斯夫，不舍昼夜。", "source": "《论语·子罕》", "concept": "川上之叹", "explanation": "时间像河水一样不停，白天黑夜都在走。它不催你，也不等你；能做的只是在这一段水流里，选一件此刻愿意投入的事。", "western": "奥古斯丁在《忏悔录》里追问时间：过去已不在，未来尚未在，只有当下的注意力是真实的。", "tags": ["变化", "夜晚", "释然"]},
    {"id": "c1a2-08", "text": "君子坦荡荡，小人长戚戚。", "source": "《论语·述而》", "concept": "坦荡与戚戚", "explanation": "心里没藏事，走路就轻；总怕别人怎么看，连休息都不安稳。把能说清的说清，把该放下的放下，胸中那块地方才会宽出来。", "western": "马可·奥勒留提醒自己，判断可以收回；外界喧哗时，心不必跟着一起起哄。", "tags": ["平静", "焦虑", "释然"]},
    {"id": "c1a2-09", "text": "穷则独善其身，达则兼善天下。", "source": "孟子《尽心上》", "concept": "独善兼善", "explanation": "力气不足的时候，先把自己的日子过稳：吃饭、睡觉、把眼前一件事做完。有余力了，再把手伸向别人，不必在低谷里责怪自己不够无私。", "western": "蒙田退居塔楼读书写作，不是弃世，而是在动荡里先把自己安顿好，再谈公共责任。", "tags": ["低落", "疲惫", "平静"]},
    {"id": "c1a2-10", "text": "富贵不能淫，贫贱不能移，威武不能屈。", "source": "孟子《滕文公下》", "concept": "不屈其志", "explanation": "顺境不让你飘，困境不让你变形，压力不让你改口。不是硬撑成一块石头，而是心里有一条线，知道自己不愿拿什么去换。", "western": "康德把人格尊严放在一切交换之外：人不是可标价、可胁迫的物品，不能因处境被收买。", "tags": ["低落", "专注", "平静"]},
    {"id": "c1a2-11", "text": "故天将降大任于是人也，必先苦其心志，劳其筋骨。", "source": "孟子《告子下》", "concept": "动心忍性", "explanation": "重的东西落到肩上之前，人往往先被磨了一轮：睡不好、做不顺、反复怀疑自己。这不是命运在挑人，而是你在长力气，只是过程不好看。", "western": "爱比克泰德说，困难显出一个人训练了什么；就像摔跤手需要对手，人也需要难题来练习。", "tags": ["疲惫", "焦虑", "期待"]},
    {"id": "c1a2-12", "text": "尽信书，则不如无书。", "source": "孟子《尽心下》", "concept": "读书有疑", "explanation": "书上的话是别人走到某处留下的记录，不是替你生活的说明书。读到不合的地方，先停一停，用自己的经验对一对，再决定收下多少。", "western": "笛卡尔用普遍怀疑清理成见：先不把任何东西当作确定，再从中找不可怀疑的起点。", "tags": ["阅读", "反思", "迷茫"]},
    {"id": "c1a2-13", "text": "人有不为也，而后可以有为。", "source": "孟子《离娄下》", "concept": "有所不为", "explanation": "想做的事太多，等于没有选择。先划掉几件此刻不做的，剩下的那一件才有完整的时间。拒绝不是损失，是把力气还给真正重要的事。", "western": "伯林区分消极自由与积极自由，提醒人：守住“不做什么”的边界，和决定“做什么”同样重要。", "tags": ["拖延", "专注", "反思"]},
    {"id": "c1a2-14", "text": "大人者，不失其赤子之心者也。", "source": "孟子《离娄下》", "concept": "赤子之心", "explanation": "长大不必把好奇和真诚一起交出去。见多了复杂，仍愿意为一朵云停一下，为一句真话动容，这份没被磨钝的部分，值得留着。", "western": "尼采把精神的终点写成“婴儿”：不再背负，也不再对抗，而是像初生者一样肯定当下。", "tags": ["平静", "释然", "感激"]},
    {"id": "c1a2-15", "text": "仰不愧于天，俯不怍于人。", "source": "孟子《尽心上》", "concept": "俯仰无愧", "explanation": "白天做的事，晚上还能面对自己；答应别人的话，心里没有欠着。无愧不是从没出错，而是错了肯认，认了肯改，睡觉时不必绕开自己。", "western": "亚当·斯密设想一位“公正的旁观者”：即使无人看见，我们也知道自己的行为能否经得起他的目光。", "tags": ["夜晚", "平静", "反思"]},
    {"id": "c1a2-16", "text": "不积跬步，无以至千里；不积小流，无以成江海。", "source": "荀子《劝学》", "concept": "跬步千里", "explanation": "今天只写三行、只背十个词，看起来离目标很远。可路是一步一步接起来的，江海也是一滴一滴汇成的；先让今天不断线。", "western": "休谟认为习惯是人心最可靠的向导：重复让微小的行为沉淀成性格与判断。", "tags": ["拖延", "专注", "写论文"]},
    {"id": "c1a2-17", "text": "锲而舍之，朽木不折；锲而不舍，金石可镂。", "source": "荀子《劝学》", "concept": "锲而不舍", "explanation": "刻两下就停，软木也断不了；一直刻下去，金属也能留下花纹。难点常常不在难度，而在反复中断后还愿不愿意回来，把刀重新对准原处。", "western": "波普尔把科学看作不断试错与修正的过程：关键不是一次成功，而是失败后仍愿意再试。", "tags": ["拖延", "专注", "疲惫"]},
    {"id": "c1a2-18", "text": "青，取之于蓝，而青于蓝。", "source": "荀子《劝学》", "concept": "青出于蓝", "explanation": "从别人那里学来的东西，不必永远停在模仿。把你读过的、练过的重新组合，慢慢会长出自己的颜色；超过老师，也不是背叛。", "western": "黑格尔认为精神在自我否定中前进：后来者不是重复前人，而是把前人转化为自己的环节。", "tags": ["期待", "复习考试", "阅读"]},
    {"id": "c1a2-19", "text": "君子生非异也，善假于物也。", "source": "荀子《劝学》", "concept": "善假于物", "explanation": "人和人的天资差得没有想象中多，差别常在会不会借力：用笔记替记忆，用工具替重复，向懂的人问一句。会借力，不是偷懒。", "western": "麦克卢汉说媒介是人的延伸；工具放大我们的能力，也悄悄改写我们感知世界的方式。", "tags": ["代码", "专注", "反思"]},
    {"id": "c1a2-20", "text": "道虽迩，不行不至；事虽小，不为不成。", "source": "荀子《修身》", "concept": "行则必至", "explanation": "再近的路，不迈步也到不了；再小的事，不动手也完不成。别等状态好了才开始，先做那个最小、最不费力的动作，路会自己接上。", "western": "萨特强调人由行动定义，而不是由意图定义；再近的目标，不迈步就仍停在纸上。", "tags": ["拖延", "晨间", "专注"]},
    {"id": "c1a2-21", "text": "君子役物，小人役于物。", "source": "荀子《修身》", "concept": "役物不役", "explanation": "东西是拿来用的，不是拿来供着的。手机、成绩、别人的评价，一旦你靠它们确认自己，它们就反过来牵着你走。用完之后，记得放回原处。", "western": "海德格尔担忧人被技术安排所支配；他主张对物保持从容，让物是物，而不是占有之链。", "tags": ["焦虑", "反思", "平静"]},
    {"id": "c1a2-22", "text": "天行有常，不为尧存，不为桀亡。", "source": "荀子《天论》", "concept": "天行有常", "explanation": "四季和昼夜不因谁的善恶改道，世界有它自己的节律。遇到不公平时，它不解释原因，只提醒你：不必把一切归咎于自己。", "western": "斯宾诺莎认为自然按必然性运行，不因人的祈愿改变；理解这一点，反而能少些怨怼。", "tags": ["变化", "平静", "释然"]},
    {"id": "c1a2-23", "text": "赠人以言，重于金石珠玉。", "source": "荀子《非相》", "concept": "赠言如玉", "explanation": "一句恰好的话，可能被记很多年：不是大道理，而是“我看见你这段时间很辛苦”。送东西会旧，这样的话不会；今天也可以说给一个人听。", "western": "布伯区分“我—它”与“我—你”：真正的对话不是交换信息，而是把对方当作不可替代的人来相遇。", "tags": ["社交", "感激", "孤独"]},
    {"id": "c1a2-24", "text": "大直若屈，大巧若拙，大辩若讷。", "source": "老子《道德经》", "concept": "大巧若拙", "explanation": "真正稳的东西，常常不急着显出来。会做的人不必处处证明会做，把力气放在事情上，外表朴素一点，反而让人放心。", "western": "维特根斯坦晚期主张，哲学不必建造体系，只需把混淆的语言理清；朴素常是深思的结果。", "tags": ["平静", "反思", "释然"]},
    {"id": "c1a2-25", "text": "知人者智，自知者明。", "source": "老子《道德经》", "concept": "自知者明", "explanation": "看懂别人不难，难的是看懂自己：为什么这句话让我难受，为什么这件事总拖到最后。把原因写下来，比急着改掉自己更有用。", "western": "克尔凯郭尔认为，人必须经由选择成为自己；旁观式地打量自我，永远得不到真正的自知。", "tags": ["反思", "迷茫", "平静"]},
    {"id": "c1a2-26", "text": "曲则全，枉则直，洼则盈，敝则新。", "source": "老子《道德经》", "concept": "曲以求全", "explanation": "有时候弯一下，反而保住了整件事；低一点，才有空间装进新东西。这不是叫你委屈自己，而是别把每一次退让都当成失败。", "western": "斯多葛派把顺应自然看作自由：不是让事情顺从愿望，而是让愿望学会顺着事情调整。", "tags": ["低落", "变化", "释然"]},
    {"id": "c1a2-27", "text": "飘风不终朝，骤雨不终日。", "source": "老子《道德经》", "concept": "飘风骤雨", "explanation": "急风刮不了一早上，暴雨也下不了一整天。情绪最猛的时候，先别做决定，也别给它下定义；找个地方坐一会儿，等这阵过去。", "western": "马可·奥勒留提醒自己，情绪来时像一阵风；不必把它当成自我，只需看它吹过。", "tags": ["焦虑", "雨", "平静"]},
    {"id": "c1a2-28", "text": "为学日益，为道日损。", "source": "老子《道德经》", "concept": "为道日损", "explanation": "学习是一天天往身上加，理解自己却常要往下减：少一点比较，少一点非要怎样。不是不要努力，而是把压在心里的多余东西挪开。", "western": "艾克哈特主张“放下”：不是增加知识，而是腾空占有，让更根本的东西得以进来。", "tags": ["放空", "休息", "释然"]},
    {"id": "c1a2-29", "text": "自见者不明，自是者不彰。", "source": "老子《道德经》", "concept": "自见不明", "explanation": "总想让人看见自己，反而看不清事情；总觉得自己对，反而听不见别的可能。把“我”往后放一放，话才进得来，路也才宽。", "western": "拉罗什福科在《箴言集》里揭穿自爱：我们以为在陈述事实，常常是在替自己辩护。", "tags": ["反思", "社交", "平静"]},
    {"id": "c1a2-30", "text": "反者道之动，弱者道之用。", "source": "老子《道德经》", "concept": "反者道动", "explanation": "事情走到极处会转向，柔软的地方反而能久。低谷不只是一条向下的线，它也在悄悄换方向；此刻先别把话说死。", "western": "赫拉克利特认为对立面互相依存：上坡路与下坡路是同一条路，冲突本身维系着世界的秩序。", "tags": ["变化", "反思", "平静"]},
    {"id": "c1a3-01", "text": "吾生也有涯，而知也无涯。", "source": "《庄子·养生主》", "concept": "有涯与无涯", "explanation": "生命的时间有限，知识却没有尽头。承认这一点，不是劝人放弃学习，而是允许自己不必读完全部，再挑几件真正想弄懂的事慢慢来。", "western": "库萨的尼古拉在《论有学问的无知》中说，越是求知，越会看见自己无知的边界；有限的人只能带着边界继续问。", "tags": ["迷茫", "专注", "反思", "阅读"]},
    {"id": "c1a3-02", "text": "井蛙不可以语于海者，拘于虚也。", "source": "《庄子·秋水》", "concept": "井蛙之限", "explanation": "井底的蛙不是笨，只是它的世界只有井口那么大。人也常被自己的位置限制，遇见不同的说法时，先别急着否定，也许对方站在另一口井里。", "western": "伽达默尔认为，人总带着历史形成的“前见”去理解世界；承认自己的视角有限，才有机会真正听见别人。", "tags": ["迷茫", "社交", "反思"]},
    {"id": "c1a3-03", "text": "泉涸，鱼相与处于陆，相呴以湿，相濡以沫。", "source": "《庄子·大宗师》", "concept": "相濡与相忘", "explanation": "泉水干了，鱼挤在陆地上用湿气互相润着。困境里的相互扶持很珍贵，但庄子也提醒：有时候松开手、各自回到水里，才是更长久的善意。", "western": "蒙田在《随笔集》里把友谊写成灵魂的相通，几乎不分彼此；庄子则提示，亲密也可以有松开手的余地。", "tags": ["孤独", "社交", "失去", "释然"]},
    {"id": "c1a3-04", "text": "人生天地之间，若白驹之过隙，忽然而已。", "source": "《庄子·知北游》", "concept": "白驹过隙", "explanation": "人活在天地间，像白马从缝隙前一闪而过。时间短得让人心慌，也短得让人不必把每件小事都拖到以后；今天想见的人，可以今天就联系。", "western": "塞涅卡在《论生命之短暂》里说，生命并不短，是我们浪费得太多；把时间还给自己，短暂的一天也会变得厚。", "tags": ["焦虑", "变化", "晨间"]},
    {"id": "c1a3-05", "text": "人皆知有用之用，而莫知无用之用也。", "source": "《庄子·人间世》", "concept": "无用之用", "explanation": "人人都盯着“有用”，却很少看见“无用”的价值。发呆、散步、一段没有产出的下午，未必是浪费；它们常常在暗处把一个人慢慢养回来。", "western": "康德在《判断力批判》里谈“无目的的合目的性”：美的事物不服务于任何用途，却让人感到自由和愉悦。", "tags": ["疲惫", "休息", "放空", "释然"]},
    {"id": "c1a3-06", "text": "天下兼相爱则治，交相恶则乱。", "source": "《墨子·兼爱上》", "concept": "兼爱则治", "explanation": "天下人彼此相爱，秩序就会安定；彼此憎恶，冲突就会起来。兼爱不是空泛的口号，而是从眼前这段关系开始：你怎样对待别人，也在决定自己活在怎样的环境里。", "western": "康德在《道德形而上学奠基》中要求把人当作目的而非手段；尊重别人，也意味着不把关系只算成一笔收益。", "tags": ["社交", "感激", "舒展"]},
    {"id": "c1a3-07", "text": "志不强者智不达，言不信者行不果。", "source": "《墨子·修身》", "concept": "志强言信", "explanation": "志向不坚定，聪明也容易散掉；说话不算数，行动就难有结果。两句话其实在说同一件事：心里定得住，脚下才走得远；先守住一件小承诺。", "western": "威廉·詹姆斯在《心理学原理》里说，意志的核心是注意：把注意力反复放回同一件事，行动才不被情绪带走。", "tags": ["专注", "拖延", "写论文"]},
    {"id": "c1a3-08", "text": "染于苍则苍，染于黄则黄。", "source": "《墨子·所染》", "concept": "所染之变", "explanation": "丝线放进青色染料就变青，放进黄色就变黄。人也会被身边的人和日常慢慢染色；不必责怪自己不够坚定，先看看每天相处最多的是什么。", "western": "亚里士多德在《尼各马可伦理学》中说，德性由习惯养成：我们反复做什么，就会成为什么样的人。", "tags": ["社交", "变化", "反思"]},
    {"id": "c1a3-09", "text": "千丈之堤，以蝼蚁之穴溃。", "source": "《韩非子·喻老》", "concept": "蚁穴之患", "explanation": "很长的堤坝，可能毁在一个小小的蚁穴上。生活里真正拖垮人的，常常不是大事，而是每天漏掉的一点睡眠、一次拖延、一句没说出口的话。", "western": "汉娜·阿伦特用“平庸之恶”提醒：巨大的灾难，往往由许多不假思索的小小服从累积而成。", "tags": ["焦虑", "拖延", "睡眠"]},
    {"id": "c1a3-10", "text": "世异则事异，事异则备变。", "source": "《韩非子·五蠹》", "concept": "世异备变", "explanation": "时代变了，事情也会变；事情变了，应对的方法就得跟着调整。过去的经验仍然珍贵，但它不是万能钥匙，遇到新局面时，允许自己换一种做法。", "western": "赫拉克利特说，人不能两次踏进同一条河流；世界一直在流变，固守旧办法，反而会让自己被水留在原地。", "tags": ["变化", "迷茫", "反思"]},
    {"id": "c1a3-11", "text": "顾小利，则大利之残也。", "source": "《韩非子·十过》", "concept": "小利残大", "explanation": "只盯着眼前一点小便宜，常常会把更大的东西弄坏。比如为了省十分钟而熬夜赶完，第二天却要用一整天来补；先问一句，这点好处值得吗。", "western": "亚里士多德把实践智慧看作能看见长远之善的能力；它不反对眼前的好处，只是不让你被它牵着走。", "tags": ["烦躁", "反思", "拖延"]},
    {"id": "c1a3-12", "text": "祸福无门，唯人所召。", "source": "《左传·襄公二十三年》", "concept": "祸福自召", "explanation": "祸福没有一扇固定的门，往往是人自己的选择把它们招来。不是说所有遭遇都该由你负责，而是在能选择的那一块里，别轻易把自己交给运气。", "western": "萨特说，人被判定为自由，哪怕不选择也是一种选择；处境不能全由你定，但如何回应，仍落在你手里。", "tags": ["反思", "迷茫", "平静"]},
    {"id": "c1a3-13", "text": "居安思危，思则有备，有备无患。", "source": "《左传·襄公十一年》", "concept": "居安思危", "explanation": "在安稳的时候想一想可能的风险，不是给自己找焦虑，而是提前留一盏灯。准备不必很重，哪怕只是存一份备份、约好一个可以求助的人。", "western": "塞涅卡提倡预先设想可能的失去，不是为了吓自己，而是让心提前练习，等事情真的来时少一点慌乱。", "tags": ["焦虑", "反思", "夜晚"]},
    {"id": "c1a3-14", "text": "人谁无过？过而能改，善莫大焉。", "source": "《左传·宣公二年》", "concept": "过而能改", "explanation": "谁都会犯错。真正让人走出来的，不是反复责备自己，而是承认那件事、补上能补的部分，然后允许自己继续往前。改过本身就是一种善。", "western": "波普尔把“可错性”当作知识的一部分：承认自己可能错，才会去检验、修正，而不是把错误藏起来。", "tags": ["低落", "反思", "复习考试"]},
    {"id": "c1a3-15", "text": "筚路蓝缕，以启山林。", "source": "《左传·宣公十二年》", "concept": "筚路蓝缕", "explanation": "驾着简陋的车、穿着破旧的衣服去开山造林。很多事一开始都不体面，甚至有点狼狈；如果你正在这样的阶段，不必急着证明自己，先把第一步走稳。", "western": "加缪在《西西弗斯神话》里说，推石上山的过程本身足以充实人心；艰难的起步不必等一个辉煌的结果才值得。", "tags": ["疲惫", "期待", "专注"]},
    {"id": "c1a3-16", "text": "防民之口，甚于防川。", "source": "《国语·周语上》", "concept": "防口甚川", "explanation": "堵住别人的嘴，比堵住河流更危险。水一旦没有出口就会决堤，情绪和意见也一样；听见不同的声音，未必舒服，却常常比压下去更安全。", "western": "密尔在《论自由》中主张，压制的意见可能是对的，也可能是错的；只有让不同声音相遇，判断才有机会被校正。", "tags": ["烦躁", "社交", "反思"]},
    {"id": "c1a3-17", "text": "和实生物，同则不继。", "source": "《国语·郑语》", "concept": "和而同异", "explanation": "不同的东西调和在一起，才能生出新东西；完全一样，反而难以持续。关系里出现分歧时，先别急着把对方改成自己，差异有时正是活力所在。", "western": "赫拉克利特认为，对立面的张力才构成和谐，就像弓与琴需要相反的力才能发出声音。", "tags": ["社交", "反思", "舒展"]},
    {"id": "c1a3-18", "text": "从善如登，从恶如崩。", "source": "《国语·周语下》", "concept": "从善如登", "explanation": "学好像登山，一步一步很慢；学坏像山崩，一下就滑下去。这不是吓人，而是说好习惯需要反复练习；偶尔退步也不必绝望，重新往上走就好。", "western": "亚里士多德说，德性不像天赋那样自然长成，而要靠反复实践；登山式的缓慢，正是它真实的样子。", "tags": ["拖延", "变化", "反思"]},
    {"id": "c1a3-19", "text": "前事之不忘，后事之师。", "source": "《战国策·赵策一》", "concept": "前事之师", "explanation": "过去的事不是包袱，而是一位不收学费的老师。回头看时，别只盯着当时的难堪，也看看自己是怎么走过来的；那份经验，下次还用得上。", "western": "桑塔亚那说，忘记过去的人注定要重蹈覆辙；记忆不是用来责备自己的，而是让下一次选择多一盏灯。", "tags": ["反思", "迷茫", "夜晚"]},
    {"id": "c1a3-20", "text": "行百里者半于九十。", "source": "《战国策·秦策五》", "concept": "半于九十", "explanation": "走一百里路，走到九十里时，其实只算走了一半。越接近终点，人越容易松劲；如果你正在最后一段，不必突然加速，把呼吸稳住，一小段一小段走完。", "western": "西蒙娜·薇依把注意力称为一种慷慨：在疲惫的最后一段，仍愿意把心放回眼前这一步，本身就是力量。", "tags": ["疲惫", "专注", "复习考试"]},
    {"id": "c1a3-21", "text": "父母之爱子，则为之计深远。", "source": "《战国策·赵策四》", "concept": "爱子计远", "explanation": "父母爱孩子，就会替他想到很远的地方。爱不只是把眼前的路铺平，也包括让他学会自己走路；如果你正被这样的爱托着，也可以慢慢接过方向盘。", "western": "温尼科特提出“足够好的母亲”：好的照顾不是替孩子挡住一切，而是在合适时慢慢退开，让他长出力气。", "tags": ["社交", "感激", "变化"]},
    {"id": "c1a3-22", "text": "流水不腐，户枢不蠹。", "source": "《吕氏春秋·尽数》", "concept": "流水不腐", "explanation": "流动的水不会发臭，常转的门轴不会被虫蛀。身体和心也一样，长时间停着容易发沉；不必逼自己剧烈运动，出门走一小圈，让气血动起来就好。", "western": "怀特海的过程哲学认为，世界不是静止事物的集合，而是不断生成的事件；人也在活动中更新自己。", "tags": ["疲惫", "运动", "晨间"]},
    {"id": "c1a3-23", "text": "石可破也，而不可夺坚；丹可磨也，而不可夺赤。", "source": "《吕氏春秋·诚廉》", "concept": "坚赤不改", "explanation": "石头可以被打碎，却夺不走它的坚硬；朱砂可以被磨细，却改不了它的红。处境会磨损人，但有些底色不必交出去；你可以柔软，也可以仍然是自己。", "western": "康德说，人格尊严没有等价物，不能被随意交换或折价；外在处境可以变，人作为目的的那一面不该被抹掉。", "tags": ["低落", "反思", "平静"]},
    {"id": "c1a3-24", "text": "察己则可以知人，察今则可以知古。", "source": "《吕氏春秋·察今》", "concept": "察己知人", "explanation": "看清自己，就更容易理解别人；看清当下，也更容易读懂过去。人和时代都有相似的难处；下次对别人不耐烦时，不妨先问一句，我是不是也这样过。", "western": "苏格拉底把“认识你自己”当作哲学的起点；他追问，不是为了裁判别人，而是先弄清自己知道什么、不知道什么。", "tags": ["反思", "社交", "平静"]},
    {"id": "c1a3-25", "text": "临河而羡鱼，不如归家织网。", "source": "《淮南子·说林训》", "concept": "临河羡鱼", "explanation": "站在河边羡慕鱼，不如回家去织一张网。想要什么，先看看自己手上有没有相应的工具；把羡慕的时间挪一点出来，做一件能靠近它的小事。", "western": "马克思在《关于费尔巴哈的提纲》里说，问题在于改变世界；光在岸边设想，不如动手做一点，哪怕网还织得不好。", "tags": ["拖延", "期待", "代码"]},
    {"id": "c1a3-26", "text": "不贵尺之璧，而重寸之阴。", "source": "《淮南子·原道训》", "concept": "寸阴为重", "explanation": "不把一尺长的美玉看得多贵重，却珍惜一寸长的光阴。时间不是抽象的，它落在你今天愿意认真对待的那半个小时里；把它给谁，就等于把生命给谁。", "western": "柏格森区分钟表时间和“绵延”：真正被感到的时间不是刻度，而是专注时变厚、走神时变薄的那种质地。", "tags": ["专注", "写论文", "晨间"]},
    {"id": "c1a3-27", "text": "心欲小而志欲大，智欲圆而行欲方。", "source": "《淮南子·主术训》", "concept": "心小志大", "explanation": "心要保持谨慎，志向可以放得很大；思虑要圆融周全，行动却要有自己的方寸。不是让你变得圆滑，而是心里能转弯，脚下仍站得住。", "western": "帕斯卡说，人既伟大又可怜：会思考让人高贵，也会因思考而看见自己的有限；两者同时成立，人才完整。", "tags": ["迷茫", "反思", "期待"]},
    {"id": "c1a3-28", "text": "燕雀安知鸿鹄之志哉！", "source": "司马迁《史记·陈涉世家》", "concept": "鸿鹄之志", "explanation": "燕雀不会懂鸿鹄要飞多远。你心里那个暂时说不清的念头，不必急着让所有人点头；先把它养大一点，等你飞起来，解释会变得不那么重要。", "western": "尼采在《查拉图斯特拉如是说》里写人应当超越自身；不是踩着别人往上，而是把今天的自己当作要跨过的一步。", "tags": ["期待", "孤独", "迷茫"]},
    {"id": "c1a3-29", "text": "桃李不言，下自成蹊。", "source": "司马迁《史记·李将军列传》", "concept": "桃李成蹊", "explanation": "桃树李树不会说话，树下却被人走出一条小路。真正让人靠近的，常常不是你说了什么，而是你一直怎么做；不必急着解释自己，把事做好，路会慢慢出现。", "western": "维特根斯坦在《逻辑哲学论》里说，不可言说之物会自己显示；一个人的分寸，也常是这样被看见的。", "tags": ["平静", "社交", "反思"]},
    {"id": "c1a3-30", "text": "智者千虑，必有一失；愚者千虑，必有一得。", "source": "司马迁《史记·淮阴侯列传》", "concept": "千虑一失", "explanation": "再聪明的人，想了很多遍也会漏掉一处；再普通的人，认真想过也总有一点可取。所以不必把自己的失误放大，也别轻易看轻别人的一句话。", "western": "蒙田的座右铭是“我知道什么？”；他不断提醒自己，人的判断有限，谦逊不是无能，而是给真相留位置。", "tags": ["焦虑", "反思", "实验"]},
    {"id": "c1b-001", "text": "路漫漫其修远兮，吾将上下而求索。", "source": "屈原《离骚》", "concept": "求索之路", "explanation": "前路又长又远，看不清尽头。求索不是一次冲刺，而是把目光放远、把脚步放低；今天只走眼前这一段，也是在回应那句“上下而求索”。路不会因此变短，但脚下是真的。", "western": "海德格尔说，人被抛入世界时并没有拿到一张地图；所谓筹划，就是在不确定里为自己开出一条可走的方向，而不是等路先修好。", "tags": ["迷茫", "专注", "期待", "反思"]},
    {"id": "c1b-002", "text": "亦余心之所善兮，虽九死其犹未悔。", "source": "屈原《离骚》", "concept": "心甘情愿", "explanation": "心里认定值得的事，哪怕反复受挫也愿意再来一次。“九死”不是鼓励硬撑，而是把代价说清楚：这条路是你自己选的，所以走得下去。悔与不悔，先问值不值得。", "western": "尼采的“命运之爱”要求人连不可避免的事也一并肯定；不是因为它好，而是因为它已是你这条路的一部分，承认之后人才站得稳。", "tags": ["专注", "期待", "低落", "反思"]},
    {"id": "c1b-003", "text": "朝饮木兰之坠露兮，夕餐秋菊之落英。", "source": "屈原《离骚》", "concept": "清苦自养", "explanation": "清晨喝木兰上落下的露水，傍晚吃秋菊初开的花瓣。屈原写的不是食谱，而是一种自我洁净：在浑浊的环境里，仍然选择用清爽的东西养活自己。", "western": "爱比克泰德说，真正属于我们的只有自己的判断与选择；外界给什么无法指定，但拿什么滋养自己，仍是一件可以练习的事。", "tags": ["晨间", "平静", "专注", "孤独"]},
    {"id": "c1b-004", "text": "长太息以掩涕兮，哀民生之多艰。", "source": "屈原《离骚》", "concept": "为他者难过", "explanation": "长长地叹气，擦掉眼泪，为的是许多人过得艰难。自己的委屈可以是私事，但看见别人的难处时，那份难过值得被认真对待，而不是赶紧压下去。", "western": "列维纳斯认为伦理始于看见他人的脸：那张脸在我行动之前就向我提出要求。为他者难过不是多余的情绪，而是原初的回应。", "tags": ["低落", "社交", "反思"]},
    {"id": "c1b-005", "text": "沅有芷兮澧有兰，思公子兮未敢言。", "source": "屈原《九歌·湘夫人》", "concept": "未说出口", "explanation": "沅水边有香芷，澧水边有兰草，香气都在，话却说不出口。想念一个人而不敢讲并不丢脸；它只说明这份心意很重要，重要到怕说坏了。说不出口的，往往最重。", "western": "克尔凯郭尔在《恐惧与颤栗》里写，最内在的东西常常无法被直接说出，一开口就走了样。未言明的思念，也是一种存在的方式。", "tags": ["孤独", "期待", "低落"]},
    {"id": "c1b-006", "text": "袅袅兮秋风，洞庭波兮木叶下。", "source": "屈原《九歌·湘夫人》", "concept": "秋气初起", "explanation": "秋风轻轻吹，洞庭湖起了波纹，树叶一片片落下。秋天不是突然到的，它先给你一点凉意、一点声音，提醒季节在换，人的心绪也常跟着换。先别急着给心情命名。", "western": "海德格尔认为情绪不是心里的杂音，而是人置身世界时先于思考的敞开方式；你先感到秋意，然后才“知道”秋天来了。", "tags": ["平静", "低落", "变化", "放空"]},
    {"id": "c1b-007", "text": "悲莫悲兮生别离，乐莫乐兮新相知。", "source": "屈原《九歌·少司命》", "concept": "聚散的重量", "explanation": "最难过的是活着却要分开，最快乐的是刚认识一个合得来的人。两句并排，不是要你悲观，而是提醒：相聚的欢喜里，本来就带着离别的分量。", "western": "亚里士多德在《尼各马可伦理学》里说，朋友是“另一个自己”；正因如此，与朋友的相聚和离散才会牵动最深的快乐与疼痛。", "tags": ["失去", "社交", "感激"]},
    {"id": "c1b-008", "text": "时不可兮骤得，聊逍遥兮容与。", "source": "屈原《九歌·湘夫人》", "concept": "等待的从容", "explanation": "好时机不会一下子就来，那就先从容地待着，慢慢走、慢慢看。等待不一定是浪费；在等待里把日子过好，机会来时你才有力气接住。慢下来，也算在往前走。", "western": "塞内加在《论生命之短暂》里说，人并非时间太少，而是浪费太多；把等待也算进生活，时间才真正归你所有。等，也是一种用法。", "tags": ["期待", "平静", "休息", "放空"]},
    {"id": "c1b-009", "text": "举世皆浊我独清，众人皆醉我独醒。", "source": "屈原《渔父》", "concept": "清醒的代价", "explanation": "所有人都浑着，只有你还想干净；所有人都醉着，只有你还醒着。清醒常让人孤单，但它不是优越感，只是你暂时无法说服自己闭上眼睛。先允许这份不合群存在。", "western": "柏拉图在《理想国》的洞穴喻里写，走出洞穴的人见了光，再回暗处会不适应；清醒的第一代价，往往是与同伴暂时的隔膜。", "tags": ["孤独", "反思", "迷茫", "低落"]},
    {"id": "c1b-010", "text": "沧浪之水清兮，可以濯吾缨。", "source": "屈原《渔父》", "concept": "因水而用", "explanation": "沧浪的水清，就用来洗帽带；水浊，就用来洗脚。渔父不是教你随波逐流，而是说：同一片水，你可以看它的样子，决定怎么用它。水怎么流，你仍可以选择怎么洗。", "western": "斯多葛派讲“顺应自然”：马可·奥勒留说，投进火里的杂物反而让火烧得更旺。环境不必先改好，应对的方式仍在自己手里。", "tags": ["释然", "平静", "变化", "反思"]},
    {"id": "c1b-011", "text": "青青园中葵，朝露待日晞。", "source": "汉乐府《长歌行》", "concept": "晨光未定", "explanation": "园里的葵菜青翠，叶上的露水等着太阳把它晒干。清晨的世界像一天还没开始，许多事只是“待”，还不到下判断的时候，先让它亮一会儿。光来了，露水自然会散。", "western": "柏格森说时间是绵延，不是钟表刻度；清晨的“待”不是空白，而是尚未展开的生成，催不来，也省不掉。早晨的时间最像原料。", "tags": ["晨间", "期待", "平静", "晴"]},
    {"id": "c1b-012", "text": "阳春布德泽，万物生光辉。", "source": "汉乐府《长歌行》", "concept": "春日的恩泽", "explanation": "春天把温暖铺开，万物都亮了起来。这句没有说谁努力了，只写光如何落在每一株草木上；人有时也需要先被照亮，才想得起自己也能生长。", "western": "斯宾诺莎说，万物都尽力保存并展开自身，他称之为“努力”（conatus）；阳光不是道德命令，却让这种展开成为可能。被照亮之后，人才谈得上努力。", "tags": ["晨间", "舒展", "晴", "期待"]},
    {"id": "c1b-013", "text": "江南可采莲，莲叶何田田。", "source": "汉乐府《江南》", "concept": "丰盛的当下", "explanation": "江南可以采莲，莲叶密密地铺满水面。诗句反复咏叹，不急着讲道理，只让你看见一片好风景；快乐有时就这么简单，先看见，再走进去。不必等到值得，才允许自己高兴。", "western": "伊壁鸠鲁把快乐理解为身体无痛苦、心灵无纷扰；一片莲叶不解决任何问题，却能让纷扰暂时退场，这就已经算数。", "tags": ["舒展", "平静", "放空", "晴"]},
    {"id": "c1b-014", "text": "上邪！我欲与君相知，长命无绝衰。", "source": "汉乐府《上邪》", "concept": "决绝的心意", "explanation": "天啊，我想和你相知相守，让这份情意一辈子不断、不衰。古人表达感情可以这样直白，把愿望喊给天听；认真喜欢一个人，本来不必太含蓄。", "western": "克尔凯郭尔把这种全然的投入称为“无限的激情”：它不是计算过回报的选择，而是主体愿意押上自己的那种决断。", "tags": ["期待", "社交", "感激"]},
    {"id": "c1b-015", "text": "十五从军征，八十始得归。", "source": "汉乐府《十五从军征》", "concept": "被拉长的时间", "explanation": "十五岁出征，八十岁才回来。一句诗跨过六十五年，中间的日子被省略了；有些失去不是一件事，而是一整段时间，回来时家已不是原来的家。", "western": "柏格森区分钟表时间与绵延：六十五年能被一句话压缩，但落在当事人身上的漫长，无法被任何数字还原。数字记得住年份，记不住人。", "tags": ["失去", "低落", "变化"]},
    {"id": "c1b-016", "text": "青青河畔草，绵绵思远道。", "source": "汉乐府《饮马长城窟行》", "concept": "由景及远", "explanation": "河边的草青得连绵不断，思念就顺着这条路伸向远方。景物本身没有情绪，是看的人把它看成了心事；承认这一点，反而能松一口气。想家的时候，就承认想家。", "western": "梅洛-庞蒂说知觉从来不是中性的记录，我们总带着身体处境去看；所以草色会变成思念，是知觉本来的样子。看的方式，就是活的方式。", "tags": ["孤独", "低落", "放空"]},
    {"id": "c1b-017", "text": "枯桑知天风，海水知天寒。", "source": "汉乐府《饮马长城窟行》", "concept": "无声的感知", "explanation": "叶子落尽的桑树最知道风从哪来，深广的海水最知道天有多冷。有些感受说不出，身体却先知道；不必急着解释，先承认它确实冷。冷是真实的，不必先解释它。", "western": "海德格尔把这种先于命题的情绪称作“现身情态”：人总已在某种情绪里与世界相遇，理性往往后到一步。身体比语言更早知情。", "tags": ["低落", "孤独", "反思"]},
    {"id": "c1b-018", "text": "悲歌可以当泣，远望可以当归。", "source": "汉乐府《悲歌》", "concept": "替代的安慰", "explanation": "唱一支悲歌，就当作哭过了；朝故乡的方向远望，就当作回去了一趟。这不是自欺，而是人在无法立刻改变处境时，给自己留的一点缓冲。缓冲不是逃，是给自己留口气。", "western": "斯多葛派把这种替代看作对不可控之事的重新描述：回不去是事实，但如何安放这份想回去的心，仍在自己手里。", "tags": ["低落", "孤独", "释然"]},
    {"id": "c1b-019", "text": "胡马依北风，越鸟巢南枝。", "source": "古诗十九首《行行重行行》", "concept": "依恋的方位", "explanation": "北方的马依恋北风，南方的鸟把巢筑在朝南的枝上。连动物都记着自己的来处，人想家、想旧地方，就更不必觉得难为情。记着来处，不等于回不去就输了。", "western": "巴什拉在《空间的诗学》里说，家屋是我们最初的宇宙；方位感先于概念，人靠身体记住“哪里是家”。家是一种身体记忆。", "tags": ["孤独", "低落", "休息"]},
    {"id": "c1b-020", "text": "相去日已远，衣带日已缓。", "source": "古诗十九首《行行重行行》", "concept": "身体记住的思念", "explanation": "离开的日子一天天变远，衣带一天天变松。诗不直说瘦，只写衣服宽了；有些心事不必讲满，身体会替你留下证据，但别让它一直留着。照看一下身体，它一直在替你记事。", "western": "梅洛-庞蒂认为身体不是心灵的容器，而是我们拥有世界的媒介；情绪会改写身体的分量，所以思念也有形状。身体是意义发生的地方。", "tags": ["失去", "低落", "孤独"]},
    {"id": "c1b-021", "text": "人生天地间，忽如远行客。", "source": "古诗十九首《青青陵上柏》", "concept": "客居天地", "explanation": "人活在天地之间，忽然就像一个赶远路的客人。这不是要你消极，而是说：既然只是过客，就不必把每一处暂住的地方都当成终审判决。过客也可以认真住一晚。", "western": "海德格尔用“被抛”形容人的处境：我们没有选择出生，却必须在既定的世界里安排行程；客居感正由此而来。被抛不是失败，是起点。", "tags": ["迷茫", "孤独", "反思"]},
    {"id": "c1b-022", "text": "生年不满百，常怀千岁忧。", "source": "古诗十九首《生年不满百》", "concept": "忧的尺度", "explanation": "人活不到一百年，却常替一千年以后的事发愁。担忧本身没错，但它往往跑得比事实远；把时间尺度调回来，事情会显出本来的大小。把担心写下来，它就没那么大。", "western": "塞内加说，人受苦更多来自想象而非现实；斯多葛派因此练习区分“已经发生的”和“我担心会发生的”。恐惧多半长着想象的形状。", "tags": ["焦虑", "反思", "休息"]},
    {"id": "c1b-023", "text": "河汉清且浅，相去复几许。", "source": "古诗十九首《迢迢牵牛星》", "concept": "近而不能", "explanation": "银河看起来又清又浅，两岸相隔能有多远呢？可就是过不去。世上有些距离不用里数计算，看着近，其实隔着一整套无法挪动的条件。有些近，只能近到看得见。", "western": "萨特讲“目光”：他人看我，我也看他，彼此近在眼前，却永远无法占据对方的视角；距离是结构性的，不全是路程。距离有时是视角的问题。", "tags": ["孤独", "失去", "低落"]},
    {"id": "c1b-024", "text": "盈盈一水间，脉脉不得语。", "source": "古诗十九首《迢迢牵牛星》", "concept": "隔水的相望", "explanation": "只隔一条清浅的水，却只能含情相望，说不上一句话。最磨人的往往不是彻底断开，而是明明还在意，却被什么挡着，只能看着。看着，也是一种相处的方式。", "western": "列维纳斯说，与他人的关系始终带着一段无法取消的距离；越想靠近，越会意识到对方并不属于我，而这正是关系成立的条件。", "tags": ["孤独", "失去", "低落"]},
    {"id": "c1b-025", "text": "对酒当歌，人生几何。", "source": "曹操《短歌行》", "concept": "短促的当下", "explanation": "对着酒就该唱歌，人生能有多长呢。曹操不是在劝人及时行乐，而是在问一个很硬的问题：时间有限，你打算拿它换什么，答案不必宏大。先回答今天，别急着回答一生。", "western": "伊壁鸠鲁说，死亡与我们无关：我们存在时死亡不在，死亡来时我们已不在；要打量的只有此刻怎么活。此刻是唯一能下手的地方。", "tags": ["夜晚", "反思", "社交"]},
    {"id": "c1b-026", "text": "山不厌高，海不厌深。", "source": "曹操《短歌行》", "concept": "容纳的尺度", "explanation": "山不嫌自己太高，海不嫌自己太深。这句原是说招纳人才，也可以读成一种自我要求：把自己撑大一点，容得下更多不一样的东西。容得下异样，才撑得住自己。", "western": "斯宾诺莎说，心灵的力量在于理解而非排斥；能容纳的越多，人被外界搅动的程度越小，自由也随之增加。理解得多一点，被搅动就少一点。", "tags": ["舒展", "反思", "专注"]},
    {"id": "c1b-027", "text": "老骥伏枥，志在千里。", "source": "曹操《龟虽寿》", "concept": "未熄的志向", "explanation": "老马伏在马槽边，心里仍想着千里之外。志向不一定马上兑现，它可以只是一个方向，提醒你还没有把自己完全交给年纪和处境。方向还在，就不算晚。", "western": "尼采说，人心里必须仍有混沌，才能生出跳舞的星辰；那些未被磨平的愿望，正是人还能继续生成的证据。生成不设年龄限制。", "tags": ["期待", "专注", "反思"]},
    {"id": "c1b-028", "text": "日月之行，若出其中。", "source": "曹操《观沧海》", "concept": "以海为量", "explanation": "太阳和月亮的运行，好像都从这片海里升起。站在海边的人会突然发现，自己的烦恼只是很小的一块；这不是逃避，而是把参照系换大。把心放大一点，事就小一点。", "western": "康德把面对浩大对象时的震动称为“崇高”：想象力被撑到极限，反而唤起理性对整体的把握，人由窘迫转为舒展。", "tags": ["舒展", "放空", "平静"]},
    {"id": "c1b-029", "text": "秋风萧瑟天气凉，草木摇落露为霜。", "source": "曹丕《燕歌行》", "concept": "秋的转场", "explanation": "秋风萧瑟，天气转凉，草木摇落，露水结成霜。四件事排在一起，季节就完成了交接；人的情绪也常这样，被几个具体的细节慢慢带走。季节换了，人也该换一件衣服。", "western": "海德格尔说，情绪让人发现自己“已经在”某个世界里；不是先有悲凉才看见秋天，而是悲凉让秋天显了形。情绪先到，解释后到。", "tags": ["夜晚", "低落", "变化", "放空"]},
    {"id": "c1b-030", "text": "明月皎皎照我床，星汉西流夜未央。", "source": "曹丕《燕歌行》", "concept": "长夜的刻度", "explanation": "明亮的月光照到床上，银河向西流去，夜还长得很。睡不着时，时间会变得很有质感；不必逼自己立刻入睡，先陪这段夜色坐一会儿。夜还长，不必一次想完所有事。", "western": "帕斯卡说，人所有的不幸几乎都来自不能独自安静地待在房间里；长夜难熬，往往是我们与自己靠得太近。独处是一种需要练习的能力。", "tags": ["夜晚", "孤独", "睡眠", "平静"]},
    {"id": "c1b-031", "text": "人生如寄，多忧何为。", "source": "曹丕《善哉行》", "concept": "暂住与轻装", "explanation": "人生像临时寄住，何必装那么多忧愁。这不是叫你什么都不在乎，而是提醒：既然是寄住，行李可以少一点，心也可以轻一点。轻装不是不负责，是走得更远。", "western": "斯多葛派把外物看作借用：塞内加说，只有时间真正属于我们，其余都归命运保管，所以不必为保管期限焦虑。借用之物，迟早要还。", "tags": ["释然", "平静", "放空"]},
    {"id": "c1b-032", "text": "人生处一世，去若朝露晞。", "source": "曹植《赠白马王彪》", "concept": "短暂的清醒", "explanation": "人活一世，离开时像朝露被太阳晒干。曹植写这句时正与兄弟分别，句子很短，分量很重；知道会失去，并不让当下变轻，反而让它更具体。具体地过今天，比想通更管用。", "western": "卢克莱修在《物性论》里说，正是死亡让生命有限，有限才使每一刻有重量；无限延续的东西，反而无所谓珍惜。有限性不是敌人。", "tags": ["失去", "低落", "反思"]},
    {"id": "c1b-033", "text": "丈夫志四海，万里犹比邻。", "source": "曹植《赠白马王彪》", "concept": "距离的相对性", "explanation": "有志向的人把四海都当去处，万里之外也像隔壁。这句不是否认离别的难，而是给分离一个更宽的说法：关系不必靠距离来证明。想念就说，别用距离当借口。", "western": "斯多葛派认为整个宇宙是一座大城邦，理性的人彼此是同胞；地理上的远近，并不改变这种归属感。世界公民不靠地图生活。", "tags": ["舒展", "社交", "期待"]},
    {"id": "c1b-034", "text": "明月照高楼，流光正徘徊。", "source": "曹植《七哀诗》", "concept": "光里的徘徊", "explanation": "明月照着高楼，月光流动，像在楼边来回踱步。写的是光，其实是人：当一个人心里有事，连光都像在替他犹豫，替他拿不定主意。犹豫的时候，先让光陪你一会儿。", "western": "加斯东·巴什拉说，月光会改变空间的温度，让房间变成可以做梦的地方；诗里的徘徊，是空间先替人动了情。空间也参与情绪的形成。", "tags": ["夜晚", "孤独", "放空"]},
    {"id": "c1b-035", "text": "惊风飘白日，光景驰西流。", "source": "曹植《箜篌引》", "concept": "白日疾驰", "explanation": "疾风把太阳吹得飘起来，光阴向西奔流。诗人把时间写成能被风带走的东西；当你觉得一天莫名其妙就没了，这句会懂你。抓不住的一天，也仍然属于你。", "western": "赫拉克利特说人不能两次踏进同一条河；流变不是意外，而是世界的常态，连“抓住”的念头也要跟着放下。流动之中，仍有当下可握。", "tags": ["变化", "焦虑", "夜晚"]},
    {"id": "c1b-036", "text": "亭亭山上松，瑟瑟谷中风。", "source": "刘桢《赠从弟》", "concept": "风中的定力", "explanation": "山上松树挺立，谷中风声瑟瑟。诗先写风有多大，再写松有多直：定力从来不是没有风，而是风来了，形状还在，还知道自己朝哪长。风停之前，先站稳。", "western": "爱比克泰德把这种状态比作不被激流带走的舵：不动心不是麻木，而是在风浪里仍按自己的判断行动。自由在于判断，不在于天气。", "tags": ["专注", "平静", "反思"]},
    {"id": "c1b-037", "text": "风声一何盛，松枝一何劲。", "source": "刘桢《赠从弟》", "concept": "相互较劲的生长", "explanation": "风刮得那么猛，松枝却那么刚劲。两个“一何”并排，像在看一场角力；有些力量只有在对抗里才显出来，平时看不出来，也不必急着证明。别急着顺风，也别怕逆风。", "western": "尼采说，一棵树要长得高大，就得把根扎进更深的黑暗与坚硬里；阻力不是生长的反面，而是它的条件。阻力是生长的必要条件。", "tags": ["专注", "舒展", "反思"]},
    {"id": "c1b-038", "text": "岂不罹凝寒，松柏有本性。", "source": "刘桢《赠从弟》", "concept": "松柏的本性", "explanation": "难道松柏没挨过严寒吗？只是它们本来就这样。与其羡慕别人的稳，不如认识自己的“本性”，顺着它用力，比模仿别人省力得多。认识自己，比改造自己更急。", "western": "斯宾诺莎说，德性就是依自己的本性而行动；不是把自己改造成别人，而是把本来如此的力量展开。顺着本性，力量才不拧巴。", "tags": ["反思", "专注", "平静"]},
    {"id": "c1b-039", "text": "出门无所见，白骨蔽平原。", "source": "王粲《七哀诗》", "concept": "无遮蔽的看见", "explanation": "走出门什么都看不见，只有白骨覆盖平原。诗人本想看看外面的世界，结果看到的是世界的伤口；有些看见会改变一个人之后要走的路。", "western": "列维纳斯说，他人的受苦在我行动之前就对我提出要求；看见不是旁观，而是一种无法推卸的被召唤。被召唤的人无法假装没看见。", "tags": ["低落", "失去", "反思"]},
    {"id": "c1b-040", "text": "夜中不能寐，起坐弹鸣琴。", "source": "阮籍《咏怀》", "concept": "深夜的安顿", "explanation": "半夜睡不着，索性起来坐着弹琴。阮籍的夜很长，琴声也未必能解决什么；但人总得给自己找一个不伤害自己的去处，哪怕只坐一会儿。起来做点什么，比躺着数羊有用。", "western": "克尔凯郭尔说焦虑是“自由的眩晕”；夜里醒着，是人站得离自己的可能性太近，需要一个动作把自己接住。焦虑提醒人：选择还在自己手上。", "tags": ["夜晚", "焦虑", "睡眠", "孤独"]},
    {"id": "c1b-041", "text": "薄帷鉴明月，清风吹我襟。", "source": "阮籍《咏怀》", "concept": "清凉的照见", "explanation": "薄薄的帐幔映着明月，清风吹动衣襟。两句都很轻，却把一个人的房间写得很空；孤独有时不是没有人，而是空间太清楚地照见了你。房间很空，你也可以只是待着。", "western": "巴什拉说，夜晚的房屋会变成一个小小的宇宙；月光与风把房间撑开，人就在这被撑开的空间里与自己相处。独处时，空间会说话。", "tags": ["夜晚", "孤独", "平静", "放空"]},
    {"id": "c1b-042", "text": "孤鸿号外野，翔鸟鸣北林。", "source": "阮籍《咏怀》", "concept": "声音的孤单", "explanation": "失群的大雁在野外哀号，飞鸟在北边的林子里鸣叫。诗人没有说自己孤独，只写外面的声音；有时心里的东西，要先借别的嗓子说出来。听见外面的声音，就还没完全断开。", "western": "海德格尔说，情绪总带着“世界性”：孤独不是脑子里一个念头，而是整个世界都染上了同样的回音，连鸟叫都像在替你说话。", "tags": ["孤独", "夜晚", "低落"]},
    {"id": "c1b-043", "text": "目送归鸿，手挥五弦。", "source": "嵇康《赠秀才入军》", "concept": "手眼两分", "explanation": "眼睛望着远去的归雁，手指还在琴弦上拨动。手在做一件事，心已经飘到天边；这不是分心，而是身体与目光各自找到了去处。让手和眼各做各的，也是一种休息。", "western": "梅洛-庞蒂说，身体不是听命于心灵的工具，它有自己与世界的合谋；手在弹，眼在望，人同时活在不同的深处。身体先于意识与世界合谋。", "tags": ["放空", "平静", "专注"]},
    {"id": "c1b-044", "text": "俯仰自得，游心太玄。", "source": "嵇康《赠秀才入军》", "concept": "自得的游心", "explanation": "低头抬头都自在，心思游向那深远的地方。嵇康写的是一种不依赖外物的满足；它不热闹，却很难被夺走，也不需要向谁证明。门槛不高，却需要练习。", "western": "斯宾诺莎把这种最高的安定称为“对神的理智之爱”：人在理解整体的一刻，得到的是不随境遇涨落的满足。它属于斯宾诺莎所说的第三种知识。", "tags": ["平静", "放空", "舒展"]},
    {"id": "c1b-045", "text": "郢人逝矣，谁与尽言。", "source": "嵇康《赠秀才入军》", "concept": "知音的缺席", "explanation": "那个能听懂我说话的人已经不在了，还能和谁把话说完呢。失去一个懂你的人，世界不会塌，但很多话会突然失去落点，你只是不想随便找个人说。", "western": "亚里士多德说，朋友是另一个自己；失去这样的朋友，等于失去一面能照见自己的镜子，悲伤因此格外深。镜子碎了，人才知道它曾照过什么。", "tags": ["失去", "孤独", "社交"]},
    {"id": "c1b-046", "text": "郁郁涧底松，离离山上苗。", "source": "左思《咏史》", "concept": "位置的错位", "explanation": "山涧底的松树郁郁葱葱，山顶上的小苗却稀稀疏疏地占着高处。左思写的是门第，也是所有“位置比能力更响”的场合；看清结构，不等于否定自己，先看清，再决定要不要挪。", "western": "卢梭在《论人类不平等的起源》里区分自然的不平等与人为的不平等；让人难受的往往不是天赋差异，而是位置被谁先占住，这件事值得分辨。", "tags": ["迷茫", "反思", "低落"]},
    {"id": "c1b-047", "text": "非必丝与竹，山水有清音。", "source": "左思《招隐》", "concept": "自然的乐音", "explanation": "不一定非要丝竹管弦，山水本身就有清亮的声音。左思不是在贬低音乐，而是提醒：能让人安静下来的东西，未必需要花钱买票，安静也可以是免费的。", "western": "卢梭在《一个孤独漫步者的遐想》里写到，在湖边听水声时，他感到的是一种纯粹的“存在之乐”，不需要任何附加理由。", "tags": ["平静", "放空", "舒展"]},
    {"id": "c1b-048", "text": "遵四时以叹逝，瞻万物而思纷。", "source": "陆机《文赋》", "concept": "感物而动", "explanation": "顺着四季感叹时光流逝，看着万物而思绪纷纭。陆机写的是写作的起点：先被世界触动，才有话想说；写不出来时，不妨先去看看外面，让眼睛先忙起来。", "western": "杜威在《艺术即经验》里说，经验要成为艺术，先得有一个完整的“做与受”的循环；感受在前，表达才不至于空转，做与受要成对。", "tags": ["写论文", "阅读", "反思", "变化"]},
    {"id": "c1b-049", "text": "石韫玉而山辉，水怀珠而川媚。", "source": "陆机《文赋》", "concept": "内蕴外显", "explanation": "山石里藏着玉，整座山就有了光；水里含着珠，整条河就显得柔媚。好的内容会从内部改变形式，不必急着往外面贴金，写东西也一样，先把料备足。", "western": "海德格尔说，作品之所以是作品，在于它让某种东西自行显现；光不是涂上去的，而是从里面透出来的，作品因此有了自己的重量。", "tags": ["专注", "写论文", "平静"]},
    {"id": "c1b-050", "text": "结庐在人境，而无车马喧。", "source": "陶渊明《饮酒·其五》", "concept": "闹中取静", "explanation": "把房子盖在人来人往的地方，却听不到车马的喧闹。陶渊明没有搬到深山，他只是换了一种与世界相处的方式；安静不一定需要远方，也不必等到有空。", "western": "塞内加说，人可以把喧嚣关在门外，也可以把自己关在喧嚣之外；真正的退隐是心神的收拢，而不是换一个地址。", "tags": ["平静", "专注", "休息", "晨间"]},
    {"id": "c1b-051", "text": "问君何能尔，心远地自偏。", "source": "陶渊明《饮酒·其五》", "concept": "心远地偏", "explanation": "你问他怎么能做到？心离得远了，住的地方自然就偏了。这句把因果说得很轻：不是环境先变好，而是你先退开半步，环境才松了口，才让出一点空隙。", "western": "马可·奥勒留在《沉思录》里说，人找不到比自己的心灵更安静的退处；地方偏不偏，取决于你把注意力放在哪里。退处，其实是一种注意力。", "tags": ["平静", "释然", "专注"]},
    {"id": "c1b-052", "text": "山气日夕佳，飞鸟相与还。", "source": "陶渊明《饮酒·其五》", "concept": "归鸟的时辰", "explanation": "傍晚山间的雾气正好，飞鸟结伴回巢。陶渊明只写了一个“还”字，就把一天的收束写完了；人也需要这样一个时刻，知道今天可以到此为止，而不必一直往前。", "western": "海德格尔说，人应当学会“栖居”，而不是永远在赶路；归巢的鸟提醒我们，结束本身也是生活的一部分，人不必一直冲刺。", "tags": ["夜晚", "平静", "休息", "放空"]},
    {"id": "c1b-053", "text": "人生无根蒂，飘如陌上尘。", "source": "陶渊明《杂诗》", "concept": "无根之身", "explanation": "人生没有根蒂，像路边的尘土被风吹散。陶渊明没有把这写成绝望，而是接着说：既然飘着，遇见谁都可以像兄弟，先别急着替自己难过。飘着的人，更懂得互相扶一把。", "western": "海德格尔的“被抛”说的正是这种没有提前商量过的处境；承认无根，反而让人对偶然遇到的人更慷慨。飘着的人，也需要彼此。", "tags": ["迷茫", "孤独", "反思"]},
    {"id": "c1b-054", "text": "落地为兄弟，何必骨肉亲。", "source": "陶渊明《杂诗》", "concept": "相遇即亲", "explanation": "降生到世上就是兄弟，何必一定要同一个血缘。这句听着温暖，其实很硬：它要求你把“自己人”的范围放大，而不只是对熟人好，也不只是对有用的人好。", "western": "斯多葛派认为所有人同属一个理性共同体，塞内加称之为“人类城邦”；亲疏是制度画的线，不是天性画的。共同体得靠日常去兑现。", "tags": ["社交", "舒展", "感激"]},
    {"id": "c1b-055", "text": "纵浪大化中，不喜亦不惧。", "source": "陶渊明《形影神·神释》", "concept": "随化而安", "explanation": "把自己放进天地的大化里，不因为顺遂而狂喜，也不因为变故就恐惧。这不是没有情绪，而是情绪不再替你做全部的决定，你仍然可以自己拿主意。", "western": "斯宾诺莎说，若能理解万物皆出于必然，心灵的被动就会减少；自由不是改变必然，而是认得它，然后照它活。认得之后，才有从容。", "tags": ["释然", "平静", "反思"]},
    {"id": "c1b-056", "text": "好读书，不求甚解。", "source": "陶渊明《五柳先生传》", "concept": "读书的松", "explanation": "喜欢读书，但不咬文嚼字地死抠。陶渊明不是反对深入，而是反对把读书变成苦役；先读得进去，比一次读得全对更重要，读不下去时也别硬撑。", "western": "维特根斯坦说，不要想，先看；许多理解是在使用中长出来的，而不是在定义里被钉死的，读书也一样。先读进去，再谈读透。", "tags": ["阅读", "专注", "平静"]},
    {"id": "c1b-057", "text": "池塘生春草，园柳变鸣禽。", "source": "谢灵运《登池上楼》", "concept": "忽然的春天", "explanation": "池塘边长出了春草，园中柳树间的鸟声也换了。谢灵运病了很久，一抬头才发现季节已经换过；有些恢复不是想通的，是某天忽然看见的，看见就已经开始。", "western": "梅洛-庞蒂说，世界不是我思考的对象，而是我生活于其中的场域；身体的康复，往往先表现为重新看见颜色和声音。", "tags": ["晨间", "舒展", "晴", "变化"]},
    {"id": "c1b-058", "text": "昏旦变气候，山水含清晖。", "source": "谢灵运《石壁精舍还湖中作》", "concept": "光中的山水", "explanation": "早晚之间气候在变，山水含着清亮的光。谢灵运写景很密，却总留一处空；那处空，是给看风景的人站进去的，不必急着填满，也不必急着说点什么。", "western": "艾丽丝·默多克说，专注于美的事物会让人暂时放下自我，她称之为“去自我化”；看山水，是一种道德练习。美让人先从自己里出来。", "tags": ["平静", "放空", "舒展"]},
    {"id": "c1b-059", "text": "云日相辉映，空水共澄鲜。", "source": "谢灵运《登江中孤屿》", "concept": "天水的互照", "explanation": "云与太阳互相映照，天空与江水一同澄澈新鲜。两个“相”“共”把世界写成互相成全的关系；人也一样，被什么照着，就会显出什么颜色，彼此都在给对方光。", "western": "梅洛-庞蒂用“交织”形容看与被看的关系：我看风景时，风景也在回看我；澄明不是单向的给予，而是互相成全。看，也是一种被看。", "tags": ["平静", "舒展", "晴"]},
    {"id": "c1b-060", "text": "泻水置平地，各自东西南北流。", "source": "鲍照《拟行路难·其四》", "concept": "起点的偶然", "explanation": "把水倒在平地上，它自己往东南西北流去。鲍照用这个动作说明：人的去向常常由不得自己；承认这一点，不是认命，而是不再把一切算在自己头上，也不再苛责当初。", "western": "萨特说人被判定为自由，但自由总在既定的处境里行使；水往哪流，既有地势，也有水本身；地势与水性，都得算进去。", "tags": ["迷茫", "低落", "反思"]},
    {"id": "c1b-061", "text": "心非木石岂无感，吞声踯躅不敢言。", "source": "鲍照《拟行路难·其四》", "concept": "说不出的愤怒", "explanation": "心不是木头石头，怎么会没有感觉；可话到嘴边还是咽了回去，只能来回踱步。鲍照写的不是软弱，而是一个人清楚知道说了也没用的时刻，那种清醒更难受。", "western": "福柯说，话语总在权力关系里被分配；不是所有真话都有位置可说，沉默因此不全是怯懦，也可能是对处境的准确判断。", "tags": ["低落", "烦躁", "孤独", "反思"]},
    {"id": "c1b-062", "text": "时危见臣节，世乱识忠良。", "source": "鲍照《代出自蓟北门行》", "concept": "逆境的显影", "explanation": "时局危险，才看得出一个人的操守；世道混乱，才认得出谁真的可靠。这句不是鼓吹苦难，而是说：平常看不出的事，压力会替你显影，也会替你筛掉一些东西。", "western": "爱比克泰德说，困难会显出一个人的本色；压力不是美德的来源，却是它显形的地方，让人看见平时看不见的纹理。显影之后，选择才真正开始。", "tags": ["反思", "低落", "专注"]},
    {"id": "c1b-063", "text": "余霞散成绮，澄江静如练。", "source": "谢朓《晚登三山还望京邑》", "concept": "晚霞与江", "explanation": "剩下的晚霞散开像锦缎，清澈的江水静得像一条白练。谢朓把辽阔收进两个比喻里；看风景的时候，比喻其实是人给世界找的一个安放处，也是给自己找的。", "western": "康德认为审美判断不靠概念，而靠想象力与知性的自由游戏；霞与江之所以美，不在于它们是什么，而在于它们如何被感到。", "tags": ["夜晚", "平静", "放空", "晴"]},
    {"id": "c1b-064", "text": "天际识归舟，云中辨江树。", "source": "谢朓《暂使下都夜发新林至京邑赠西府同僚》", "concept": "远望的辨认", "explanation": "在天边认出归来的船，在云里分辨江边的树。谢朓写的是远望，也是等待：看得那么仔细，说明心里一直有人在回来的路上，只是还不敢确定是哪一艘。", "western": "巴什拉说，辽阔不是尺寸，而是一种沉思的强度；盯着天边看的人，其实是在丈量自己心里的距离。距离感，也是一种尺度。", "tags": ["期待", "孤独", "放空"]},
    {"id": "c1b-065", "text": "黯然销魂者，唯别而已矣。", "source": "江淹《别赋》", "concept": "别离的重量", "explanation": "让人心神黯淡、像丢了魂的，只有离别这一件事。江淹把话说得很满，是因为离别确实会把人拆成两半：一半留在原地，一半跟着走了，很久都合不拢。", "western": "雅斯贝尔斯把死亡、苦难、斗争称为“临界处境”：人无法绕过它们，只能在其中决定自己是谁；离别也是这样一道门。", "tags": ["失去", "低落", "孤独"]},
    {"id": "c1b-066", "text": "春草碧色，春水渌波，送君南浦，伤如之何。", "source": "江淹《别赋》", "concept": "春景中的送别", "explanation": "春草碧绿，春水泛着清波，就在南浦送你走，这份伤心该怎么办呢。景物越好，离别越难；江淹不掩饰这种不协调，反而让它更真，也更难躲开。", "western": "海德格尔说情绪总带着“在世界之中”的整体色调；不是先有离别再看见春色，而是春色本身也参与了这场难过。", "tags": ["失去", "低落", "社交"]},
    {"id": "c1b-067", "text": "日暮途远，人间何世。", "source": "庾信《哀江南赋序》", "concept": "末路的发问", "explanation": "天色晚了，路还很远，这人间究竟是什么样的世道。庾信写的是国破之后的漂泊；当一个人连时间与道路都对不上，问句本身就是他仅剩的站立方式，也是他还没放弃的证据。", "western": "本雅明在《历史哲学论纲》里写，历史的天使被风暴吹向未来，眼前的废墟不断堆高；庾信的问句，正是站在废墟上的回望。", "tags": ["迷茫", "低落", "失去", "反思"]},
    {"id": "c1b-068", "text": "树犹如此，人何以堪。", "source": "庾信《枯树赋》", "concept": "物是人非", "explanation": "树都老成这样了，人又怎么受得住。庾信借树的摇落写自己的衰老与漂泊；有些悲伤不必展开，一句反问就够重了，够重的东西也不必多说。", "western": "普鲁斯特说，真正的发现之旅不在于寻找新的风景，而在于拥有新的眼睛；同一棵树，隔了岁月再看，看见的其实是自己。", "tags": ["失去", "变化", "低落"]},
    {"id": "c1b-069", "text": "仰观宇宙之大，俯察品类之盛。", "source": "王羲之《兰亭集序》", "concept": "上下的尺度", "explanation": "抬头看宇宙的辽阔，低头看万物的繁盛。王羲之把人的视线拉开到两个方向；当视野足够大，眼前的得失会暂时失去那副逼人的面孔，人也就松了一点。", "western": "康德在《判断力批判》里区分美与崇高：面对星空这样的浩大，想象力受挫，理性却因此意识到自己的超感性使命。", "tags": ["舒展", "放空", "平静"]},
    {"id": "c1b-070", "text": "向之所欣，俯仰之间，已为陈迹。", "source": "王羲之《兰亭集序》", "concept": "欢喜的过期", "explanation": "从前喜欢的东西，一俯一仰之间就成了旧痕迹。王羲之没有劝人别喜欢，他只是提醒：喜欢会过期，所以拥有的时候要真的在场，别把心思都放在担心失去上。", "western": "赫拉克利特说万物皆流，人不能两次踏进同一条河；变化不是背叛，而是存在本来的节奏，连欢喜也有自己的季节。", "tags": ["变化", "失去", "反思"]},
    {"id": "c1b-071", "text": "后之视今，亦犹今之视昔。", "source": "王羲之《兰亭集序》", "concept": "时间的对称", "explanation": "后人看今天，就像今天的人看从前。这句把时间折了一下：你以为自己在看历史，其实也正被未来看着；于是当下多了一点分量，也多了一点被原谅的可能。", "western": "伽达默尔说，理解总以“效果历史”的方式发生：我们带着传统去看，也被后来的人带着看；视角从不悬空。视角一换，时间就宽了。", "tags": ["反思", "变化", "平静"]},
    {"id": "c1b-072", "text": "山川之美，古来共谈。", "source": "陶弘景《答谢中书书》", "concept": "共享的美", "explanation": "山川的美，自古以来人们就在谈论。陶弘景开头就把自己放进一条很长的队伍里；欣赏风景不是孤僻，它一直是一种人与人的共同语言，只是不必同时在场。", "western": "康德认为审美判断虽出于个人感受，却会要求别人也同意，他称之为“共通感”；美因此天然带着邀请。美要求有人一起承认。", "tags": ["舒展", "社交", "平静"]},
    {"id": "c1b-073", "text": "晓雾将歇，猿鸟乱鸣。", "source": "陶弘景《答谢中书书》", "concept": "清晨的声响", "explanation": "清晨的雾将要散去，猿鸟的叫声乱成一片。一个“乱”字写活了山里的早晨；刚醒来的世界不必整齐，热闹本身就是秩序，乱里有它自己的次序。", "western": "柏格森说，真实的绵延无法被切成均匀的刻度；清晨的鸟鸣是一片连续的喧响，只能整体地被听见。喧响之中，也有它的整全。", "tags": ["晨间", "舒展", "晴", "放空"]},
    {"id": "c1b-074", "text": "风烟俱净，天山共色。", "source": "吴均《与朱元思书》", "concept": "澄净的同色", "explanation": "风停了，烟尘都散尽，天和山是同一种颜色。吴均用四个字清空画面，再让山色填进来；有时安静不是加什么，而是把杂音去掉，颜色自己就会说话。", "western": "维特根斯坦说，世界的界限就是语言的界限；但在这句里，恰恰是语言的退后，让天山的颜色自己显现。退后一步，世界才开口。", "tags": ["平静", "放空", "晴"]},
    {"id": "c1b-075", "text": "鸢飞戾天者，望峰息心。", "source": "吴均《与朱元思书》", "concept": "望峰止念", "explanation": "那些像鹰一样直冲云霄、拼命往上飞的人，望见这样的山峰也会停下心思。吴均不是说进取不好，而是说：总得有个地方，让你的野心歇一歇，也让心回到身上。", "western": "尼采说，人需要从目的与功用的视角里走出来一会儿，才能恢复对世界的感受力；高峰的作用，是让攀爬暂时失效。", "tags": ["释然", "平静", "反思", "休息"]},
    {"id": "c1b-076", "text": "重岩叠嶂，隐天蔽日。", "source": "郦道元《水经注·三峡》", "concept": "被山压缩的天", "explanation": "层层岩石与山峰叠在一起，把天遮住，把太阳挡住。郦道元只写山的高与密，人却会想到自己被什么围住的时候：抬头看不见天，不代表天没了，只是暂时被挡住。", "western": "海德格尔说，空间不是空的容器，而是被事物聚集起来的；峡谷把天挤窄，也让“天”第一次显得具体。被围住的人，也会重新丈量天。", "tags": ["低落", "平静", "放空"]},
    {"id": "c1b-077", "text": "素湍绿潭，回清倒影。", "source": "郦道元《水经注·三峡》", "concept": "水的两种质地", "explanation": "白色的急流，碧绿的深潭，清波回旋，倒影其中。八个字里既有速度也有静止；一条河可以同时是冲下去的，和停下来的，人也可以同时很急和很静。", "western": "赫拉克利特说，河流既不断变化，又始终是它自己；水的同一性不在静止，而在它持续流动的方式。流动与停留，本是一体。", "tags": ["平静", "变化", "放空"]},
    {"id": "c1b-078", "text": "每至晴初霜旦，林寒涧肃。", "source": "郦道元《水经注·三峡》", "concept": "霜晨的清冷", "explanation": "每到天刚放晴、霜刚落下的早晨，树林寒冷，山涧肃静。郦道元写的是三峡的冬天；冷有冷的清楚，安静也有安静的分量，冷得很干净。清冷不是空，是把话收住了。", "western": "加斯东·巴什拉说，冬日的寒冷会让房屋变成庇护的意象；人在清冷里，反而更容易感到自己有一个可以回去的地方。", "tags": ["晨间", "平静", "孤独", "休息"]},
    {"id": "c1b-079", "text": "积财千万，不如薄伎在身。", "source": "颜之推《颜氏家训·勉学》", "concept": "随身的能力", "explanation": "攒下千万家财，也不如身上有一门薄技。颜之推说得实在：钱会散，门第会变，只有练进身体里的本事，走到哪儿都跟着你，也不会因为换了个地方就作废。", "western": "波兰尼提出“默会知识”：真正的技能难以写成说明书，只能在做中学；它长在身体里，因此不容易被夺走。技能长在手上，不长在纸上。", "tags": ["专注", "反思", "复习考试"]},
    {"id": "c1b-080", "text": "夫学者犹种树也，春玩其华，秋登其实。", "source": "颜之推《颜氏家训·勉学》", "concept": "学习的季节", "explanation": "学习像种树，春天赏花，秋天收果。颜之推把读书拆成两个季节：先有兴致，再谈收成；急着结果的树，往往连花都开不好，别急着分胜负。季节到了，自然会有收成。", "western": "杜威说，教育不是为未来做的准备，而是经验持续改组的过程；春天与秋天，本来就是同一件事的两段。两段之间，不必抢跑。", "tags": ["阅读", "复习考试", "期待", "专注"]},
    {"id": "c1b-081", "text": "登山则情满于山，观海则意溢于海。", "source": "刘勰《文心雕龙·神思》", "concept": "情随境满", "explanation": "登上山，情感就装满这座山；看海，心意就漫过这片海。刘勰写的是写作时的投入：你得先真的在那儿，文字才会有重量，读者才站得进去。情不满，写出来的字就轻。", "western": "梅洛-庞蒂说，身体与空间彼此渗透；人不是站在风景外面看，而是被风景穿过，情绪因此有了地形，看的人也在风景里面。", "tags": ["舒展", "写论文", "放空"]},
    {"id": "c1b-082", "text": "操千曲而后晓声，观千剑而后识器。", "source": "刘勰《文心雕龙·知音》", "concept": "经验的门槛", "explanation": "弹过上千支曲子才懂音律，看过上千把剑才识得兵器。刘勰不否认天赋，但他更相信次数：眼力是被一次次具体的看喂出来的，急不来，也省不掉。", "western": "休谟说，品味虽属感受，却可以由反复比较与练习而变得精细；判断力不是灵感，是经验沉淀后的稳定。看得够多，眼睛才有准头。", "tags": ["专注", "阅读", "写论文"]},
    {"id": "c1b-083", "text": "气之动物，物之感人。", "source": "钟嵘《诗品序》", "concept": "被触动的链", "explanation": "气先摇动万物，万物再感动人。钟嵘把诗的源头放在这条链子上：不是人凭空抒情，而是世界先动了一下，人才跟着动；写不出来时，先回到那个“动”上。", "western": "杜威说，经验起于有机体与环境的交互；感受很少从内部凭空冒出，它总有一个外面的起点，也有一个可以回去的方向。", "tags": ["反思", "写论文", "变化"]},
    {"id": "c1b-084", "text": "观古今胜语，多非补假，皆由直寻。", "source": "钟嵘《诗品序》", "concept": "直寻的好句", "explanation": "看古往今来那些好句子，多半不是拼凑借来的，而是直接寻到的。钟嵘推崇“直寻”，也就是眼睛先看见、心里先动，再让词跟上，而不是先找词再找感觉。", "western": "胡塞尔的口号是“回到事情本身”：先别急着套理论，把眼前的经验如其所是地描述出来，才有资格谈解释。描述先于解释，经验先于概念。", "tags": ["写论文", "专注", "反思"]},
    {"id": "c1b-085", "text": "事出于沉思，义归乎翰藻。", "source": "萧统《文选序》", "concept": "思与文的合力", "explanation": "事情经过深沉的思考，意义最终落在文采辞藻上。萧统给“文学”划了一条线：光有想法不够，还得有把它说好的能力，两者缺一都容易塌，也都容易被看出来。", "western": "海德格尔说，语言是存在之家；思想若不被说出，就还没有真正抵达，表达不是包装，而是思想的完成，不只是装饰。", "tags": ["写论文", "专注", "阅读"]},
    {"id": "c1b-086", "text": "万里赴戎机，关山度若飞。", "source": "北朝乐府民歌《木兰诗》", "concept": "奔赴的速度", "explanation": "奔赴万里之外的战场，越过一道道关山，快得像飞。木兰诗写行军不写苦，只写速度；那种利落里，其实藏着来不及害怕的紧张，和不敢停下的心。", "western": "柏格森说，绵延中的时间不能被均匀切分；奔赴的“快”不是速度计上的数字，而是一种被拉紧的、几乎失重的体验。", "tags": ["期待", "专注", "运动"]},
    {"id": "c1b-087", "text": "朔气传金柝，寒光照铁衣。", "source": "北朝乐府民歌《木兰诗》", "concept": "边地的寒夜", "explanation": "北方的寒气送来打更的声音，清冷的月光照着铁甲。两句没有一个“苦”字，冷和硬却都到了；木兰的勇敢，是在这样的夜里一点点熬出来的，不是天生就不怕。", "western": "海德格尔说，器具只有在用得顺手或突然坏掉时才显出自己的存在；铁甲在寒光里显形，人的处境也跟着显形。", "tags": ["夜晚", "疲惫", "孤独"]},
    {"id": "c1b-088", "text": "天苍苍，野茫茫，风吹草低见牛羊。", "source": "北朝乐府民歌《敕勒歌》", "concept": "草原的辽阔", "explanation": "天青青的，野茫茫的，风吹过，草低下去，才看见成群的牛羊。辽阔不是空，它把东西藏起来，又在某一刻全部还给你；只是要等一阵风。耐心本身，也是风景的一部分。", "western": "康德说，面对辽阔的自然，想象力被推到极限，人先感到自己的渺小，随后意识到理性可以把握整体，这就是崇高。", "tags": ["舒展", "放空", "平静", "晴"]},
    {"id": "c1b-089", "text": "南风知我意，吹梦到西洲。", "source": "南朝乐府民歌《西洲曲》", "concept": "托风寄梦", "explanation": "南风懂得我的心意，把我的梦吹到西洲去。现实里过不去，就让梦先到；这不是逃避，而是思念在替自己找一条可行的路，梦有时比路先到。", "western": "巴什拉说，梦把空间变成可以居住的意象；被风吹送的梦，是想象替身体完成了一次不可能的旅行。梦走得比人快一步。", "tags": ["孤独", "期待", "夜晚", "放空"]},
    {"id": "c1b-090", "text": "陇头流水，鸣声幽咽。", "source": "北朝乐府民歌《陇头歌辞》", "concept": "水声的哽咽", "explanation": "陇山的流水，声音低沉，像在哽咽。旅人听见的其实不是水，是自己的声音被水接了过去；有些难过，借一条河就能说出口，不必先解释给谁听。", "western": "海德格尔说，情绪是一种“调音”，它先把世界调成某个音高，声音才被听见；水声幽咽，是听的人先低了头。调音不同，听见的世界也不同。", "tags": ["孤独", "低落", "雨", "反思"]},
    {"id": "c2-001", "text": "落霞与孤鹜齐飞，秋水共长天一色。", "source": "王勃《滕王阁序》", "concept": "天地的共在", "explanation": "傍晚的霞光与孤独的野鸭一起飞，秋水与长天连成同一种颜色。世界并不围着你转，却愿意把这样开阔的一刻留给你，让你暂时从自己的心事里走出来。", "western": "梅洛-庞蒂的现象学认为，知觉把身体与世界连成一片；风景不是眼前的画，而是你正在参与其中的场域，看风景的人也被风景改变。", "tags": ["平静", "舒展", "放空", "晴"]},
    {"id": "c2-002", "text": "关山难越，谁悲失路之人？", "source": "王勃《滕王阁序》", "concept": "失路者的孤独", "explanation": "山高路远，走错方向的人常常无人过问。如果你正走在这样的路段，先承认它确实难，不必独自硬撑，再去找一个可以问路的人。肯开口问一句，也是一种不逞强的本事。", "western": "海德格尔把这种无措称为不在家的感受；迷路不是道德失败，而是人存在于世的一种基本可能，需要重新学习方向。", "tags": ["迷茫", "孤独", "低落", "反思"]},
    {"id": "c2-003", "text": "春江潮水连海平，海上明月共潮生。", "source": "张若虚《春江花月夜》", "concept": "广阔的生成", "explanation": "潮水、明月与海面在同一刻出现，没有谁先谁后。很多好事也是这样，不是被计划出来的，而是在你走到江边的时候，刚好发生。你能做的只是走到水边，然后抬头。", "western": "柏格森认为真实的时间是绵延，不能被切成刻度；这一刻的开阔只能整体地被经历，无法被计算，也无法被提前安排。", "tags": ["夜晚", "平静", "舒展", "期待"]},
    {"id": "c2-004", "text": "人生代代无穷已，江月年年望相似。", "source": "张若虚《春江花月夜》", "concept": "有限与延续", "explanation": "一代人走远，一代人又来，江上的月亮看起来没有变。个人的烦恼放在这样长的时间里会变小，但并不会因此变得不重要。把目光放长，不等于把此刻抹掉。", "western": "斯多葛学派用宇宙的视角稀释眼前的得失；把尺度拉远不是否定痛苦，而是给痛苦一个更稳的位置，让人重新获得呼吸。", "tags": ["夜晚", "反思", "释然", "平静"]},
    {"id": "c2-005", "text": "春眠不觉晓，处处闻啼鸟。", "source": "孟浩然《春晓》", "concept": "醒来的知觉", "explanation": "睡得沉，醒来时先听见鸟叫，才知道天已经亮了。身体比日程更早知道季节的变化，允许自己慢慢醒，不必一睁眼就进入任务。给醒来的身体几分钟，再开始今天。", "western": "现象学重视前反思的知觉：在你说出春天来了之前，耳朵和皮肤已经先知道了，意识只是随后赶来命名。身体先于语言知道答案。", "tags": ["晨间", "睡眠", "平静", "舒展"]},
    {"id": "c2-006", "text": "野旷天低树，江清月近人。", "source": "孟浩然《宿建德江》", "concept": "空旷中的靠近", "explanation": "原野太空，天好像压到树梢；江水太清，月亮像贴近了人。孤独的夜里，远处的东西反而显得亲，仿佛在替谁陪着你。远处的光也在替你守着这个夜晚。", "western": "巴什拉在《空间的诗学》里说，辽阔是一种内在的经验；人会在空旷中重新丈量自己的边界，也会在边界之外遇见安慰。", "tags": ["夜晚", "孤独", "平静", "放空"]},
    {"id": "c2-007", "text": "明月松间照，清泉石上流。", "source": "王维《山居秋暝》", "concept": "清明的秩序", "explanation": "月光穿过松枝，泉水流过石头，各自按照自己的路线。安静不是没有声音，而是声音都待在该待的位置，谁也不催谁。不必说话，待着就已经足够。", "western": "海德格尔讲物会聚集天、地、人、神；一眼泉水把世界收拢在它的流动里，让路过的人得以停留片刻。物因此有了让人停留的力量。", "tags": ["夜晚", "平静", "专注", "放空"]},
    {"id": "c2-008", "text": "大漠孤烟直，长河落日圆。", "source": "王维《使至塞上》", "concept": "辽阔的形式感", "explanation": "荒原上只有一缕直烟，长河边是一轮圆日。极简的景象反而让人心里安定，因为边界清楚，不需要再解释什么。简单的东西有时最能安顿人。", "western": "康德把这种无利害的静观称为审美判断；壮阔并不占有你，它只是让你短暂地忘记自己，从而感到自由。自由感来自不被占有的观看。", "tags": ["平静", "舒展", "晴", "放空"]},
    {"id": "c2-009", "text": "山路元无雨，空翠湿人衣。", "source": "王维《山中》", "concept": "无形的浸润", "explanation": "山路上并没有下雨，浓绿的山色却把衣服打湿了。有些影响没有声音，却在悄悄改变你，等你发现时已经深入。被改变的人往往最后才知道。", "western": "杜威认为经验是环境与有机体的交互；人被山林浸润不是被动接受，而是在关系里持续发生变化。改变常发生在觉察之前。", "tags": ["雨", "平静", "专注", "变化"]},
    {"id": "c2-010", "text": "倚杖柴门外，临风听暮蝉。", "source": "王维《辋川闲居赠裴秀才迪》", "concept": "傍晚的停留", "explanation": "拄着杖站在柴门外，风吹过来，蝉在树上叫。一天将尽的时候，不必急着总结和复盘，先站一会儿，让身体回到自己。让一天的边角也有一点空白。", "western": "海德格尔说人是在世存在；倚门听蝉不是无所事事，而是与世界保持一种清醒的往来，让存在显形。清醒的往来让时间有了质地。", "tags": ["夜晚", "休息", "平静", "放空"]},
    {"id": "c2-011", "text": "举杯邀明月，对影成三人。", "source": "李白《月下独酌·其一》", "concept": "独处中的陪伴", "explanation": "一个人喝酒，就把月亮和影子请来作伴。孤独没有被消除，但被重新安排了位置，从空缺变成了可以共处的空间。一个人也可以把夜晚过得完整。", "western": "列维纳斯强调他者的不可还原；这里的月亮不是人，却让人练习与非我共处，暂时松开对自我的紧抓。陪伴不必以同类为限。", "tags": ["夜晚", "孤独", "释然", "社交"]},
    {"id": "c2-012", "text": "天生我材必有用，千金散尽还复来。", "source": "李白《将进酒》", "concept": "对自身价值的信任", "explanation": "相信自己这块材料总会有用处，钱花完了也还能再挣。豪迈不是假装不焦虑，而是不让一时的得失替自己下定义。先相信自己，再谈结果。", "western": "尼采的命运之爱要求人肯定已经发生的一切；这不是盲目乐观，而是愿意把挫折也纳入自己的生命叙事。肯定生命也包括肯定它的重量。", "tags": ["期待", "舒展", "焦虑", "反思"]},
    {"id": "c2-013", "text": "两岸猿声啼不住，轻舟已过万重山。", "source": "李白《早发白帝城》", "concept": "穿过之后的轻", "explanation": "猿声还在身后叫，船已经过了很多座山。回头才发现，那些以为过不去的地方，早已经落在后面，成了路上的背景。不必回头解释，继续往前就好。", "western": "柏格森说时间带着不可逆的新质；走过之后你不是原来的你，轻快来自已经发生的穿行，而不是遗忘。轻快是走过之后的证据。", "tags": ["释然", "舒展", "变化", "晴"]},
    {"id": "c2-014", "text": "桃花潭水深千尺，不及汪伦送我情。", "source": "李白《赠汪伦》", "concept": "被送别的温度", "explanation": "潭水再深，也量不出朋友来送你的那份心意。被认真对待的时候，允许自己被打动，也允许自己把这份好意记住。把这份心意收下，也记得回赠。", "western": "马丁·布伯区分我与它和我与你；真正的相遇不把对方当资源，而是整个人到场，因此无法被任何尺度换算。相遇因此不能被交换。", "tags": ["感激", "社交", "舒展", "平静"]},
    {"id": "c2-015", "text": "安能摧眉折腰事权贵，使我不得开心颜。", "source": "李白《梦游天姥吟留别》", "concept": "不肯弯折的自我", "explanation": "不愿低头弯腰去讨好，因为那样连笑都笑不出来。守住底线有时要付出代价，但代价不等于全部，你仍然拥有自己。守住它，代价之外还有自由。", "western": "康德的自律概念把尊严放在服从外在目的之上；不肯折腰，是把自己当作目的而非工具，哪怕要为此承担损失。", "tags": ["烦躁", "专注", "反思", "期待"]},
    {"id": "c2-016", "text": "相看两不厌，只有敬亭山。", "source": "李白《独坐敬亭山》", "concept": "静默的相对", "explanation": "看着山，山也看着你，谁也不厌倦谁。人与风景之间也可以有一种不需要解释的关系，沉默本身就是交流。沉默里也有一种被理解的踏实。", "western": "梅洛-庞蒂认为看与被看是同一具身体的两面；在山前你不是旁观者，而是被风景回看的人。看与被看让自我有了轮廓。", "tags": ["平静", "孤独", "放空", "舒展"]},
    {"id": "c2-017", "text": "今人不见古时月，今月曾经照古人。", "source": "李白《把酒问月》", "concept": "时间中的共享", "explanation": "今天的月亮也曾照过古人。你此刻抬头看见的光，和很多年前的人看见的是同一轮，孤独因此有了一点回声。你和古人共享的，不只是月亮。", "western": "本雅明谈灵光时强调此刻与过去的相遇；一轮月亮把不相识的人接进同一个夜晚，让时间短暂地折叠。时间在共享的瞬间被折叠。", "tags": ["夜晚", "反思", "平静", "变化"]},
    {"id": "c2-018", "text": "安得广厦千万间，大庇天下寒士俱欢颜。", "source": "杜甫《茅屋为秋风所破歌》", "concept": "由己及人的愿望", "explanation": "自己的屋顶漏了，想的却是让所有受冻的人都有地方住。共情不是忘记自己，而是从自己的冷里认出别人的冷。体谅不是天生的，它常从自己的冷里长出来。", "western": "罗尔斯设想无知之幕下的选择；真正公正的安排，要经得起你随时可能成为最弱者的假设。公正要替不在场的人留位置。", "tags": ["低落", "期待", "反思", "社交"]},
    {"id": "c2-019", "text": "无边落木萧萧下，不尽长江滚滚来。", "source": "杜甫《登高》", "concept": "时间的两重声音", "explanation": "落叶无边地掉，江水不停地来。消逝与到来同时发生，人站在中间，难免觉得自己很小，却也因此被放进更大的节奏。承认渺小，反而能松开一点。", "western": "尼采的永恒轮回把时间设想为无尽循环；若一切都会再来，你愿意如何面对此刻，就成了一个严肃的问题。重复的设想逼人认真对待此刻。", "tags": ["低落", "变化", "反思", "疲惫"]},
    {"id": "c2-020", "text": "两个黄鹂鸣翠柳，一行白鹭上青天。", "source": "杜甫《绝句》", "concept": "明快的秩序", "explanation": "黄鹂在柳树上叫，白鹭排成一行飞向天空。颜色和方向都很清楚，这样简单的画面也能把人从杂乱里捞出来。让眼睛先于脑子恢复秩序。", "western": "康德认为美具有无目的的合目的性；画面没有用处，却让人的心智感到一种自由的协调，像秩序临时被看见。审美让心智感到自由。", "tags": ["晴", "晨间", "舒展", "平静"]},
    {"id": "c2-021", "text": "露从今夜白，月是故乡明。", "source": "杜甫《月夜忆舍弟》", "concept": "被记忆染色的月", "explanation": "露水从今夜开始发白，月亮还是故乡的最亮。其实月亮一样，是记忆给它加了光，让普通的东西变得不可替代。普通的东西一旦被记住，就不再普通。", "western": "休谟指出情感会投射到对象上；故乡的月亮并不更亮，是思念让知觉带上了温度，也改变了你观看的方式。情感参与了知觉的构造。", "tags": ["夜晚", "孤独", "低落", "反思"]},
    {"id": "c2-022", "text": "读书破万卷，下笔如有神。", "source": "杜甫《奉赠韦左丞丈二十二韵》", "concept": "积累后的流畅", "explanation": "读得足够多，写起来像有神助。所谓的灵感，常常是大量输入之后，手比脑子先找到了路，句子自己接上了。输入够了，手感会自己回来。练到熟，手感才会来。", "western": "波兰尼讲默会知识；真正熟练的人说不出全部规则，但身体已经记住了它们，于是动作显得毫不费力。熟练是规则沉入身体。", "tags": ["阅读", "写论文", "专注", "期待"]},
    {"id": "c2-023", "text": "星垂平野阔，月涌大江流。", "source": "杜甫《旅夜书怀》", "concept": "天地间的尺度", "explanation": "星星低垂，原野显得更宽；月亮随江涌动。人在这样的尺度里会变小，但也会松一口气，因为不必再扮演中心。不必总把自己放在画面的中央。", "western": "帕斯卡说人是一根会思想的芦苇；在无限空间面前，人渺小却仍能理解自己的渺小，这就是尊严所在。渺小与理解可以同时成立。", "tags": ["夜晚", "平静", "孤独", "放空"]},
    {"id": "c2-024", "text": "细雨鱼儿出，微风燕子斜。", "source": "杜甫《水槛遣心·其一》", "concept": "细微的生机", "explanation": "细雨里鱼浮上来，微风里燕子斜着飞。世界没有停，只是把动作放轻了，轻到你必须安静下来才看得见。把动作放轻，世界就愿意靠近。轻的触碰也能留下痕迹。", "western": "现象学关注微小知觉；不是只有强烈的事件才构成经验，轻风与斜飞也在塑造你对世界的感受和记忆。轻的知觉也在塑造经验。", "tags": ["雨", "平静", "专注", "舒展"]},
    {"id": "c2-025", "text": "为人性僻耽佳句，语不惊人死不休。", "source": "杜甫《江上值水如海势聊短述》", "concept": "对表达的执拗", "explanation": "为了一个合适的句子反复修改，不肯随便放过。认真有时显得笨，但它会让作品对得起自己，也对得起读的人。慢一点，也是在替表达负责。", "western": "维特根斯坦说语言游戏的规则在实践中生成；反复改句，是在替尚未成形的东西寻找可共享的形式。表达是替经验寻找公共形式。", "tags": ["写论文", "专注", "拖延", "焦虑"]},
    {"id": "c2-026", "text": "春潮带雨晚来急，野渡无人舟自横。", "source": "韦应物《滁州西涧》", "concept": "无人处的自在", "explanation": "傍晚的潮水带着雨来得急，荒野渡口没有船夫，小船自己横在水面。没有观众的时候，事物也有自己的秩序。不被打扰的地方，自有它的节奏。", "western": "海德格尔的让存在者存在与此相通：不被打扰、不被强行安排，本身就是一种成全，让物回到物自身。不打扰也是一种尊重。", "tags": ["雨", "平静", "放空", "孤独"]},
    {"id": "c2-027", "text": "空山松子落，幽人应未眠。", "source": "韦应物《秋夜寄邱员外》", "concept": "远方的牵挂", "explanation": "空山里松子落下的声音很清楚，想到那位隐居的朋友大概也还没睡。思念有时只是一个很轻的推测，却足以连接两个人。一句轻轻的猜测，也能把人拉近。", "western": "列维纳斯说与他人的关系先于自我；一句你应该还没睡吧，已经把远方的人接进了此刻的房间。他人先于自我进入房间。", "tags": ["夜晚", "孤独", "社交", "平静"]},
    {"id": "c2-028", "text": "细雨湿衣看不见，闲花落地听无声。", "source": "刘长卿《别严士元》", "concept": "无声的改变", "explanation": "雨小到看不见，却慢慢湿了衣服；花落到地上，也没有声音。很多改变就是这样发生的，等你察觉时，它已经完成。等你回头，它已经在身上了。", "western": "莱布尼茨的微小知觉说明，许多经验低于意识阈值，却持续影响判断；温柔也常以这种不易察觉的方式起作用。", "tags": ["雨", "平静", "变化", "反思"]},
    {"id": "c2-029", "text": "日暮苍山远，天寒白屋贫。", "source": "刘长卿《逢雪宿芙蓉山主人》", "concept": "寒冷中的投宿", "explanation": "天黑了，山显得更远；天冷了，白屋显得更贫。赶路的人需要的并不多，一处能歇脚的地方，就足以让夜晚变得可过。能歇脚的地方，就是今夜的归处。", "western": "海德格尔把栖居与庇护联系起来；住所不只是空间，而是让人可以卸下防备、恢复力气的地方。庇护让人重新获得力气。", "tags": ["疲惫", "夜晚", "休息", "孤独"]},
    {"id": "c2-030", "text": "野火烧不尽，春风吹又生。", "source": "白居易《赋得古原草送别》", "concept": "顽强的再生", "explanation": "野火把草烧掉，根还在地里，春风一吹又长出来。恢复不是回到原样，而是从还活着的部分继续，长成新的样子。只要根还在，就还有下一次。", "western": "斯宾诺莎的努力概念认为万物都倾向于保存自身；生命力不是意志口号，而是存在本身的倾向。保存自身是存在的倾向。", "tags": ["低落", "期待", "变化", "舒展"]},
    {"id": "c2-031", "text": "同是天涯沦落人，相逢何必曾相识。", "source": "白居易《琵琶行》", "concept": "处境中的相通", "explanation": "都在异乡失意，遇见时不必先交换履历。共同的处境本身，就能让人迅速靠近，因为彼此都懂那种说不出的滋味。被懂得的那一刻，异乡也没那么冷。", "western": "亚里士多德把友爱分为功利、快乐与德性三类；因处境而生的相通接近德性友爱，因为彼此看见的是人本身。相通先于身份。", "tags": ["孤独", "社交", "释然", "低落"]},
    {"id": "c2-032", "text": "试玉要烧三日满，辨材须待七年期。", "source": "白居易《放言五首·其三》", "concept": "时间里的检验", "explanation": "辨玉要烧够日子，识才要等够年头。急着给自己或别人下结论，往往会看错，因为有些质地只在时间里显出来。给自己一点时间，别急着定论。", "western": "波普尔强调理论要经受检验；人不是理论，但同样需要时间与情境，才能显出稳定的形状。时间与情境共同构成检验。", "tags": ["焦虑", "期待", "反思", "复习考试"]},
    {"id": "c2-033", "text": "我有所念人，隔在远远乡。", "source": "白居易《夜雨》", "concept": "距离中的惦念", "explanation": "心里有一个人，隔着很远的家乡。想念不一定要求回应，它只是说明这段关系还在你身上活着，仍然影响你此刻的选择。想念说明你曾经认真地爱过。", "western": "列维纳斯认为对他者的思念是一种伦理关系；即使对方不在场，责任与牵挂仍然成立，构成了自我的部分。牵挂先于回应。", "tags": ["夜晚", "孤独", "低落", "雨"]},
    {"id": "c2-034", "text": "自古逢秋悲寂寥，我言秋日胜春朝。", "source": "刘禹锡《秋词·其一》", "concept": "重新命名的能力", "explanation": "别人一到秋天就伤感，我偏觉得秋天比春天更好。不是否认萧瑟，而是拒绝被单一的季节情绪规定，把评价权拿回来。你也可以替这个季节换一种说法。", "western": "尼采说视角就是力量；换一个评价框架不是自欺，而是承认世界可以被重新描述，人也有权选择自己的镜头。镜头本来就可以换。", "tags": ["晴", "舒展", "反思", "平静"]},
    {"id": "c2-035", "text": "旧时王谢堂前燕，飞入寻常百姓家。", "source": "刘禹锡《乌衣巷》", "concept": "兴衰的迁移", "explanation": "当年豪门檐下的燕子，如今飞进普通人家。再大的繁华也会移动位置，眼前的处境同样不会永远固定，不必把它当成终局。把眼光放长，得失就没那么重。", "western": "赫拉克利特说万物皆流；兴衰不是例外，而是结构本身。承认流动，反而能减少对一时得失的执着。流动削弱了对固定的执念。", "tags": ["变化", "反思", "平静", "失去"]},
    {"id": "c2-036", "text": "千淘万漉虽辛苦，吹尽狂沙始到金。", "source": "刘禹锡《浪淘沙·其八》", "concept": "筛选后的留下", "explanation": "一遍遍淘洗很辛苦，沙子吹尽才看见金。过程里的重复不是白费，它正在把不属于你的部分一点点去掉，让真正重要的留下。留下的东西，才值得你继续带走。", "western": "杜威把思考看作经验的重新组织；反复筛选不是机械劳动，而是让真正重要的东西逐渐显形。经验在重组中显出重点。", "tags": ["专注", "期待", "复习考试", "疲惫"]},
    {"id": "c2-037", "text": "斯是陋室，惟吾德馨。", "source": "刘禹锡《陋室铭》", "concept": "空间与品格", "explanation": "屋子虽然简陋，住的人让这里有了一种气息。环境会影响人，但人对环境的布置也有发言权，哪怕只是摆好一张桌子。把身边的一小块地方照顾好。", "western": "巴什拉说家宅是灵魂的角落；一个房间的意义不只由面积决定，也由居住者投入的关系与记忆决定。栖居靠关系维持。", "tags": ["平静", "专注", "阅读", "舒展"]},
    {"id": "c2-038", "text": "孤舟蓑笠翁，独钓寒江雪。", "source": "柳宗元《江雪》", "concept": "极简的坚持", "explanation": "江上只有一只小船，老人披着蓑衣在雪里钓鱼。他未必钓得到什么，但那个姿态本身就是回答，说明他还在自己的位置上。钓不钓得到，已经不那么重要了。", "western": "加缪写西西弗推石上山，明知徒劳仍不放弃；意义有时不在结果，而在人如何站在自己的处境里。意义在姿态里而非结果里。", "tags": ["孤独", "平静", "专注", "低落"]},
    {"id": "c2-039", "text": "烟销日出不见人，欸乃一声山水绿。", "source": "柳宗元《渔翁》", "concept": "声音打开的空间", "explanation": "雾散了，太阳出来，人却看不见；只听见一声桨响，山水忽然绿了。一个声音就能把整个清晨叫醒，让世界重新有颜色。声音落下，世界才慢慢显形。", "western": "海德格尔说语言是存在之家；声音不只是信息，它先把一个可居住的世界为我们打开，然后事物才各就各位。声音先于意义。", "tags": ["晨间", "晴", "舒展", "放空"]},
    {"id": "c2-040", "text": "城上高楼接大荒，海天愁思正茫茫。", "source": "柳宗元《登柳州城楼寄漳汀封连四州》", "concept": "高处放大的愁", "explanation": "站在高楼上，荒原一直连到天边，愁绪也跟着变得没有边界。空间的开阔有时会放大心里的事，让人一时无处安放。站得高，也要允许自己看不清。", "western": "克尔凯郭尔把焦虑描述为面对可能性时的眩晕；视野越宽，人越容易感到自己的有限与选择的重量。眩晕暴露了自由的重量。", "tags": ["焦虑", "迷茫", "孤独", "反思"]},
    {"id": "c2-041", "text": "山城过雨百花尽，榕叶满庭莺乱啼。", "source": "柳宗元《柳州二月榕叶落尽偶题》", "concept": "错位的时节", "explanation": "山城一场雨，花都落了，榕叶铺满院子，黄莺乱叫。南方的春天和记忆里的不一样，陌生感本身也需要时间去适应。陌生会过去，只要你别急着离开。", "western": "休谟说因果来自习惯；当熟悉的季节脚本失效，人会更清楚地看见自己原来依赖着哪些预期。习惯失效时预期才被看见。", "tags": ["雨", "迷茫", "变化", "反思"]},
    {"id": "c2-042", "text": "曾经沧海难为水，除却巫山不是云。", "source": "元稹《离思五首·其四》", "concept": "经验塑造标准", "explanation": "见过沧海，别处的水就不再是水；见过巫山的云，别的云都失了颜色。深刻的经历会改变你的尺度，让你一时难以将就。标准被抬高之后，也需要慢慢放下。", "western": "现象学讲视域：一次强烈的经验会重组此后的知觉，让后来者都在这道背景里被看见和比较。视域重组了后来的比较。", "tags": ["失去", "反思", "低落", "释然"]},
    {"id": "c2-043", "text": "不是花中偏爱菊，此花开尽更无花。", "source": "元稹《菊花》", "concept": "最后的坚持", "explanation": "不是偏爱菊花，而是它开过之后，别的花都谢了。有些坚持不是因为最好，而是因为还在，还愿意在冷下来的时节守着一点颜色。不是最好，也可以陪自己到最后。", "western": "斯多葛学派区分值得选择与真正善；在无花可看的时节仍守着一点颜色，是一种清醒的选择。清醒的选择不靠热闹支撑。", "tags": ["平静", "专注", "期待", "释然"]},
    {"id": "c2-044", "text": "黑云压城城欲摧，甲光向日金鳞开。", "source": "李贺《雁门太守行》", "concept": "压力下的光", "explanation": "黑云压下来，城墙像要被压塌；阳光一照，铠甲又闪出金光。危急和光亮可以在同一刻出现，人不必等到安全才振作。先站稳，再等那一道光。", "western": "尼采提醒人凝视深渊时仍可肯定生命；压力不自动带来光，但光也不必等压力完全消失才出现。肯定生命不等于否认黑暗。", "tags": ["焦虑", "专注", "疲惫", "期待"]},
    {"id": "c2-045", "text": "衰兰送客咸阳道，天若有情天亦老。", "source": "李贺《金铜仙人辞汉歌》", "concept": "无情与深情", "explanation": "衰败的兰草送人上路，天如果有情，也会因此变老。把情感推到天地身上，是因为人间的情太重，一时找不到别的容器。情太重时，天地也会被借来承担。", "western": "康德区分现象与物自体，人无法知道天是否有情；但把情感投射出去，本身就是人理解失落的方式。投射让失落有了形状。", "tags": ["失去", "低落", "反思", "夜晚"]},
    {"id": "c2-046", "text": "少年心事当拏云，谁念幽寒坐呜呃。", "source": "李贺《致酒行》", "concept": "志向与困顿", "explanation": "少年人心里该有拿云一样的志向，可谁又会在意你坐在寒窗下低声叹息。志向和困顿常常同时存在，不必因为一时的冷落，就把心里的火全部熄灭。", "western": "尼采认为人必须在自身中保有混沌，才能生出跳舞的星；困顿不是志向的反面，而是它尚未成形时的样子。混沌也是创造的条件。", "tags": ["期待", "迷茫", "专注", "低落"]},
    {"id": "c2-047", "text": "停车坐爱枫林晚，霜叶红于二月花。", "source": "杜牧《山行》", "concept": "霜后的颜色", "explanation": "停下车，是因为喜欢傍晚的枫林；经霜的叶子，比二月的花还要红。美不一定出现在最顺利的季节，有时它偏要等到冷下来以后，才肯把自己交出来。", "western": "康德区分优美与崇高；霜叶的美带着一点严峻，它不讨好眼睛，却让人更久地停住，也让人想到时间的作用。严峻的美更耐看。", "tags": ["晴", "平静", "舒展", "放空"]},
    {"id": "c2-048", "text": "南朝四百八十寺，多少楼台烟雨中。", "source": "杜牧《江南春》", "concept": "烟雨里的兴衰", "explanation": "南朝留下那么多寺庙，如今多少楼台都笼在烟雨里。曾经热闹的东西会慢慢安静下来，站在雨里看，反而能看见时间的形状。安静下来，才看得见它。", "western": "本雅明在废墟的意象里看到历史的沉淀；烟雨中的楼台不是失败，而是时间替人保存下来的层次。废墟也在替时间说话。", "tags": ["雨", "反思", "变化", "平静"]},
    {"id": "c2-049", "text": "商女不知亡国恨，隔江犹唱后庭花。", "source": "杜牧《泊秦淮》", "concept": "歌声背后的因果", "explanation": "卖唱的女子未必懂得亡国的痛，隔着江还在唱旧朝的曲子。责备她很容易，但真正该追问的，是让这首歌一直有人点的那个环境。结构的问题不该由一个人背。", "western": "阿多诺提醒人注意文化工业如何把苦难变成消费品；一首歌被反复点唱，背后往往有比个人更长的因果。个人之外还有结构。", "tags": ["烦躁", "反思", "低落", "失去"]},
    {"id": "c2-050", "text": "江东子弟多才俊，卷土重来未可知。", "source": "杜牧《题乌江亭》", "concept": "未定的胜负", "explanation": "江东还有很多有才干的年轻人，胜负并没有到最后一步。失败之后先别急着写总结，局势里仍然留着没被用上的可能。别把一次失败当成定局。", "western": "詹姆斯认为信念会影响行动的结果；不是空想胜利，而是保留一种值得尝试的姿态，让下一步有路可走。信念会改变行动的路径。", "tags": ["期待", "低落", "反思", "变化"]},
    {"id": "c2-051", "text": "春蚕到死丝方尽，蜡炬成灰泪始干。", "source": "李商隐《无题》", "concept": "倾尽与心疼", "explanation": "春蚕到死才把丝吐尽，蜡烛烧成灰，泪一样的蜡才停。用尽全力去爱或去做一件事，听起来壮烈，其实也需要被心疼。也给自己留一点余力。", "western": "列维纳斯把为他者的付出看作伦理的起点；但付出不等于耗尽，真正的责任也包括让自己继续存在。付出需要边界才长久。", "tags": ["感激", "失去", "专注", "低落"]},
    {"id": "c2-052", "text": "身无彩凤双飞翼，心有灵犀一点通。", "source": "李商隐《无题·昨夜星辰昨夜风》", "concept": "距离中的默契", "explanation": "身上没有彩凤的翅膀，不能飞到你身边；心里却像有灵犀，一点就通。亲近不一定靠时刻在场，有时是两个人对同一件事的反应刚好一样。", "western": "梅洛-庞蒂说身体是通向世界的媒介；即使身体不在一处，知觉与记忆仍在替两个人保持通道，让距离变得可穿行。", "tags": ["期待", "社交", "平静", "专注"]},
    {"id": "c2-053", "text": "此情可待成追忆，只是当时已惘然。", "source": "李商隐《锦瑟》", "concept": "回望时的惘然", "explanation": "这份感情等到后来才成为回忆，可当时就已经茫然，说不清自己要什么。很多遗憾不是因为做错，而是因为那时还看不懂自己。看不清也是当时的一部分。", "western": "克尔凯郭尔说生活只能倒着理解；回望让意义出现，但也提醒人，当时的局限不该被后来的清醒苛责。回望不该变成审判。", "tags": ["失去", "反思", "低落", "释然"]},
    {"id": "c2-054", "text": "夕阳无限好，只是近黄昏。", "source": "李商隐《乐游原》", "concept": "将尽的美", "explanation": "夕阳确实好，只是天色已经接近黄昏。美好的东西常常带着将尽的意味，正因为知道它会过去，才更值得认真看一会儿。所以更要好好看这一眼。", "western": "海德格尔的向死而生不是恐吓，而是让人看见有限；承认终点，反而让此刻的光更集中，也更诚实。有限让光更集中。", "tags": ["平静", "失去", "夜晚", "舒展"]},
    {"id": "c2-055", "text": "何当共剪西窗烛，却话巴山夜雨时。", "source": "李商隐《夜雨寄北》", "concept": "把此刻寄给未来", "explanation": "什么时候才能一起坐在西窗下剪烛花，再回头说起今夜巴山的雨。把此刻的孤独写进未来的团聚，等待就多了一个具体的方向。等待也就不再是一件空事。", "western": "奥古斯丁在《忏悔录》里发现时间的三重结构；人活在当下的同时，也靠回忆与期待把自己连成一条线。时间靠回忆与期待成形。", "tags": ["雨", "期待", "孤独", "夜晚"]},
    {"id": "c2-056", "text": "鸡声茅店月，人迹板桥霜。", "source": "温庭筠《商山早行》", "concept": "早行的痕迹", "explanation": "鸡叫了，茅店上还挂着月亮；板桥的霜上，已经有早行人的脚印。天还没亮，已经有人在赶路，你并不总是最早的那个辛苦人。每个人都有自己的天亮前。", "western": "海德格尔用被抛描述人突然发现自己已在某处；清晨的霜与脚印提醒人，世界在你醒来之前就已经在运转。世界先于个人醒来。", "tags": ["晨间", "疲惫", "孤独", "专注"]},
    {"id": "c2-057", "text": "过尽千帆皆不是，斜晖脉脉水悠悠。", "source": "温庭筠《望江南·梳洗罢》", "concept": "落空的等待", "explanation": "一艘艘船过去，都不是要等的人；只剩斜阳照着江水，慢慢流远。等待落空的时候，风景还在，时间也没有停下来责怪你。你仍然可以好好看这江面。", "western": "列维纳斯说等待他者是一种朝向无限的关系；即使船没有来，等待本身已经把人从自我封闭里拉了出来。等待也有它的朝向。", "tags": ["期待", "低落", "孤独", "平静"]},
    {"id": "c2-058", "text": "玲珑骰子安红豆，入骨相思知不知。", "source": "温庭筠《南歌子词二首·其二》", "concept": "入骨的思念", "explanation": "把红豆嵌进精巧的骰子里，相思也像嵌进了骨头。想念深到一定程度，会变成身体里的一件事，不只是情绪，吃饭睡觉都带着它。身体替你说出了想念。", "western": "梅洛-庞蒂认为情绪不是纯内在的，它通过身体向外表达；把红豆放进骰子，是给看不见的思念一个可触摸的形状。", "tags": ["夜晚", "孤独", "期待", "低落"]},
    {"id": "c2-059", "text": "问君能有几多愁？恰似一江春水向东流。", "source": "李煜《虞美人·春花秋月何时了》", "concept": "愁的形状", "explanation": "要问心里有多少愁，就像一江春水往东流，数不清也拦不住。把情绪比作水，不是夸大，而是承认它有自己的方向和力量。让它流一会儿，不必堵住。", "western": "斯宾诺莎说情感会因被理解而减弱；给愁一个形状，不是消灭它，而是让自己不再完全被它吞没。理解让情绪松开一点。", "tags": ["低落", "夜晚", "反思", "变化"]},
    {"id": "c2-060", "text": "剪不断，理还乱，是离愁。", "source": "李煜《相见欢·无言独上西楼》", "concept": "无法整理的乱", "explanation": "离愁像一团乱线，剪不断，越理越乱。有些情绪不适合强行整理，先把它放在一边，等手稳一点再碰，也是一种处理。先允许它乱着，再慢慢来。", "western": "维特根斯坦提醒人，有些问题不能靠更多解释解决；面对缠绕的情绪，改变描述方式有时比追问原因更有用。换一种说法也是出路。", "tags": ["低落", "烦躁", "反思", "平静"]},
    {"id": "c2-061", "text": "梦里不知身是客，一晌贪欢。", "source": "李煜《浪淘沙令·帘外雨潺潺》", "concept": "短暂的忘怀", "explanation": "梦里忘了自己是在异乡做客，贪恋了片时的欢乐。醒来会失落，但那一晌的快乐是真的，不必因为短暂就否认它，它曾经托住过你。那一点暖意值得被记住。", "western": "弗洛伊德把梦看作愿望的伪装满足；梦里的欢愉未必虚假，它至少暴露了你仍然需要什么，也仍然在寻找。梦也在替欲望说话。", "tags": ["睡眠", "释然", "低落", "夜晚"]},
    {"id": "c2-062", "text": "流水落花春去也，天上人间。", "source": "李煜《浪淘沙令·帘外雨潺潺》", "concept": "无因的失去", "explanation": "流水带着落花走了，春天也走了，从天上到人间，隔着一整个时代。失去有时候没有具体的原因，只是季节到了，人要学着送别。告别也是生活的一部分。", "western": "尼采的永恒轮回要求人接受失去也会再来；不是麻木，而是让告别成为生命的一部分，而不是它的中断。告别属于生命本身。", "tags": ["失去", "低落", "变化", "反思"]},
    {"id": "c2-063", "text": "业精于勤，荒于嬉；行成于思，毁于随。", "source": "韩愈《进学解》", "concept": "勤与随的分界", "explanation": "学业因勤勉而精进，因玩乐而荒废；德行因思考而成全，因随意而毁掉。它不是说不能休息，而是提醒人，随意和放松并不是一回事。把力气用在真正要紧处。", "western": "亚里士多德把德性看作习惯的产物；反复的选择塑造人，正如反复的练习塑造手艺，时间会把方向变成性格。习惯会慢慢成为性格。", "tags": ["专注", "复习考试", "拖延", "反思"]},
    {"id": "c2-064", "text": "天街小雨润如酥，草色遥看近却无。", "source": "韩愈《早春呈水部张十八员外》", "concept": "远看才有的春色", "explanation": "京城的小雨润得像酥油，草色远远看有一层绿，走近了却又看不见。很多变化在远处才显形，凑得太近反而只见零星。退一步看，春色才完整。", "western": "现象学讲视角与显现的关系；同一片草地在远近之间呈现不同，不是错觉，而是知觉本身的构造。远近都是知觉的一部分。", "tags": ["雨", "晨间", "平静", "舒展"]},
    {"id": "c2-065", "text": "云横秦岭家何在？雪拥蓝关马不前。", "source": "韩愈《左迁至蓝关示侄孙湘》", "concept": "关口前的失向", "explanation": "云横在秦岭上，家在哪里；雪堵住蓝关，马也不肯往前。被贬远行的人，走到某个关口，会突然不知道自己在往哪里去。先停一停，也是一种走法。", "western": "海德格尔把这种时刻称为无家可归；它不是软弱，而是人突然看见自己并不总能掌控方向，只能一步一步走。无家可归也是人的处境。", "tags": ["迷茫", "低落", "疲惫", "孤独"]},
    {"id": "c2-066", "text": "千里马常有，而伯乐不常有。", "source": "韩愈《马说》", "concept": "被看见的运气", "explanation": "千里马其实常有，能认出千里马的人却不常有。被看见需要运气，但在那之前，你仍然可以照顾好自己的脚力和方向。先把自己养好，再等目光。", "western": "休谟说价值判断离不开观察者的感受；才能不是孤立存在的属性，它在被识别的目光里才成为机会。价值离不开被看见。", "tags": ["期待", "焦虑", "反思", "专注"]},
    {"id": "c2-067", "text": "人生到处知何似，应似飞鸿踏雪泥。", "source": "苏轼《和子由渑池怀旧》", "concept": "痕迹与经过", "explanation": "人生到处奔走，像什么呢？大概像飞鸿踩在雪泥上，留下几枚爪印，然后又飞走了。痕迹会淡，但飞过这件事本身是真的。经过本身就值得被记住。", "western": "存在主义强调人是被抛入世界的；飞鸿不选择雪地，却可以选择如何落下，意义在飞行里而不是在爪印里。飞过本身就已经很足够。", "tags": ["变化", "反思", "平静", "释然"]},
    {"id": "c2-068", "text": "小舟从此逝，江海寄余生。", "source": "苏轼《临江仙·夜饮东坡醒复醉》", "concept": "心里的出口", "explanation": "真想就这样坐小船离开，把余生交给江海。未必真的要出走，但心里留一条水路，会让眼下的束缚松一点，也给疲惫一个出口。想象出口，也能缓解现实。", "western": "加缪写西西弗也可以想象幸福；把余生交给江海，是一种对既定秩序说不的姿态，哪怕只在心里完成。姿态先于结果。", "tags": ["疲惫", "释然", "舒展", "孤独"]},
    {"id": "c2-069", "text": "枝上柳绵吹又少，天涯何处无芳草。", "source": "苏轼《蝶恋花·春景》", "concept": "别处的生长", "explanation": "枝上的柳絮越吹越少，春天快过去了；可天底下哪里没有芳草。失去一处风景，不等于世界从此荒凉，别把眼前当成全部。世界比眼前这一处更大。", "western": "莱布尼茨说可能存在许多世界；这一处的凋零不取消别处的生长，视野一换，损失就不再是唯一的结论。视野一换，结论就变。", "tags": ["失去", "期待", "变化", "舒展"]},
    {"id": "c2-070", "text": "笑渐不闻声渐悄，多情却被无情恼。", "source": "苏轼《蝶恋花·春景》", "concept": "在意的代价", "explanation": "笑声渐渐听不见，四周静下来；多情的人反而被无情的人惹恼。在意得更多的那一方，常常更容易受伤，这不是你的错。受伤说明你曾认真对待过。", "western": "斯宾诺莎说爱恨都源于观念；恼不是因为对方无情，而是因为你把快乐系在了一个不由你控制的对象上。把快乐系在自己身上。", "tags": ["低落", "孤独", "反思", "社交"]},
    {"id": "c2-071", "text": "人间如梦，一尊还酹江月。", "source": "苏轼《念奴娇·赤壁怀古》", "concept": "看透后的认真", "explanation": "人间像一场梦，还是举起酒杯，把酒洒向江上的月亮。看透不等于放弃，它也可以是一种更轻的认真，把剩下的日子过好。轻一点，也可以很认真。", "western": "尼采的酒神精神让人在虚幻中仍然起舞；知道梦会醒，并不妨碍此刻把酒举起来，也不妨碍认真。知道虚幻仍可起舞。", "tags": ["夜晚", "释然", "平静", "放空"]},
    {"id": "c2-072", "text": "竹外桃花三两枝，春江水暖鸭先知。", "source": "苏轼《惠崇春江晚景·其一》", "concept": "身体先知道", "explanation": "竹林外开了三两枝桃花，江水暖了，鸭子先知道。身体和感受往往比消息更早察觉变化，别忽略那些说不清的先兆，它们常在替你报信。身体的判断常常更早到。", "western": "波兰尼的默会知识说明，人知道的多于能说出的；鸭子不会解释水温，却已经用行动做出了判断，身体同样如此。", "tags": ["晨间", "晴", "舒展", "专注"]},
    {"id": "c2-073", "text": "九死南荒吾不恨，兹游奇绝冠平生。", "source": "苏轼《六月二十日夜渡海》", "concept": "苦难中的看见", "explanation": "被贬到南方荒远之地，几次差点死掉，我也不悔恨；这一趟的奇绝，算得上平生第一。苦难不必被美化，但人在其中看见的东西，可以属于自己。", "western": "尼采的命运之爱不是感谢伤害，而是拒绝让伤害成为唯一的叙述；人仍可承认，途中有些风景只在此处可见。叙述权要留在自己手里。", "tags": ["释然", "舒展", "反思", "感激"]},
    {"id": "c2-074", "text": "博观而约取，厚积而薄发。", "source": "苏轼《稼说送张琥》", "concept": "积累与输出", "explanation": "广泛地看，谨慎地取；积累得厚，才轻轻地发出来。写东西或做研究，不必急着展示，先把底下的部分垫厚，输出自然会稳。厚度会替你说话。稳是厚积之后的事。", "western": "杜威把学习看作经验的连续重组；广博不是堆放材料，而是在反复使用中形成判断力，让取舍得有依据。判断力来自反复使用。", "tags": ["阅读", "写论文", "专注", "拖延"]},
    {"id": "c2-075", "text": "大略如行云流水，初无定质。", "source": "苏轼《答谢民师书》", "concept": "形式的自由", "explanation": "文章大概像行云流水，本来没有固定的形状。好的表达不是套模板，而是让内容找到它自己的速度与停顿，读起来才不费力。让内容决定它的样子。", "western": "维特根斯坦说意义在使用中生成；文章的形式不该先于内容，它应随着要说的东西长出来，而不是反过来。形式跟随内容生长。", "tags": ["写论文", "阅读", "专注", "平静"]},
    {"id": "c2-076", "text": "桃李春风一杯酒，江湖夜雨十年灯。", "source": "黄庭坚《寄黄几复》", "concept": "用画面丈量距离", "explanation": "当年春风里一起喝过一杯酒，后来各自漂泊，夜里听雨，对着一盏灯过了十年。朋友之间的距离，有时用几个具体的画面就能量出来。细节比概括更接近想念。", "western": "普鲁斯特认为记忆藏在感官细节里；一杯酒、一盏灯，比抽象的想念更能把逝去的时间带回眼前。细节保存了时间。", "tags": ["夜晚", "雨", "社交", "感激"]},
    {"id": "c2-077", "text": "未到江南先一笑，岳阳楼上对君山。", "source": "黄庭坚《雨中登岳阳楼望君山》", "concept": "先到的愉悦", "explanation": "还没到江南，先笑了一下；站在岳阳楼上，对面就是君山。好心情有时先于风景到达，人还没到，心已经松开了。心情可以先替风景开门。脚步也跟着轻了。", "western": "康德说愉悦可以先于对象的判断；期待本身就能改变身体状态，让尚未发生的好事提前发生一部分。期待先改变了身体。", "tags": ["晴", "期待", "舒展", "平静"]},
    {"id": "c2-078", "text": "世上岂无千里马，人中难得九方皋。", "source": "黄庭坚《过平舆怀李子先时在并州》", "concept": "识人的稀缺", "explanation": "世上怎么会没有千里马，难得的是像九方皋那样会相马的人。才能需要被辨认，但遇不到识货的人时，也别急着把自己判成庸才。好眼光也需要时间养成。", "western": "波普尔说观察渗透理论；看见什么取决于你带着什么框架，识人也是如此，眼光本身是一种稀缺能力。框架决定了看见什么。", "tags": ["焦虑", "反思", "期待", "专注"]},
    {"id": "c2-079", "text": "两情若是久长时，又岂在朝朝暮暮。", "source": "秦观《鹊桥仙·纤云弄巧》", "concept": "距离中的长久", "explanation": "如果两个人的感情足够长久，又何必非要每天早晚都在一起。距离不是感情的反面，它有时只是换一种方式维持连接。连接不止一种形状。", "western": "列维纳斯认为距离是与他者关系的条件；完全占有会取消对方，适当的距离反而让相遇持续发生。距离让相遇持续。", "tags": ["期待", "平静", "社交", "舒展"]},
    {"id": "c2-080", "text": "自在飞花轻似梦，无边丝雨细如愁。", "source": "秦观《浣溪沙·漠漠轻寒上小楼》", "concept": "情绪的可见形式", "explanation": "飘飞的花轻得像梦，无边的雨丝细得像愁。把看不见的情绪交给看得见的景物，心里的事就有了可以安放的地方，也有了被理解的可能。", "western": "休谟指出情感会通过联想附着于对象；雨因此不只是雨，它成了愁的可见形式，也成了可分享的语言。情感借景物获得形状。", "tags": ["雨", "低落", "平静", "反思"]},
    {"id": "c2-081", "text": "雾失楼台，月迷津渡。", "source": "秦观《踏莎行·郴州旅舍》", "concept": "看不清的时刻", "explanation": "雾把楼台遮没了，月光也让渡口变得模糊。看不清前路的时候，先别急着责怪自己，有时候只是雾太浓，等它散一点再走。雾散之前，先站稳。", "western": "海德格尔说真理也包含遮蔽；看不清不是认识的失败，而是事物暂时退回到它的隐藏里，需要耐心等候。遮蔽也是真理的一面。", "tags": ["迷茫", "焦虑", "平静", "反思"]},
    {"id": "c2-082", "text": "叶上初阳干宿雨，水面清圆，一一风荷举。", "source": "周邦彦《苏幕遮·燎沉香》", "concept": "清晨的秩序", "explanation": "初升的太阳晒干荷叶上隔夜的雨，水面清亮圆润，风一吹，荷花一朵朵举起来。清晨的秩序感，有时只需要看一片叶子。一片叶子也能安顿清晨。", "western": "杜威认为审美经验来自有机体与环境的节奏；光、水与风配合的一刻，日常事物忽然有了完整的形式。节奏让日常成为形式。", "tags": ["晨间", "晴", "舒展", "平静"]},
    {"id": "c2-083", "text": "人如风后入江云，情似雨余黏地絮。", "source": "周邦彦《玉楼春·桃溪不作从容住》", "concept": "聚散的不由己", "explanation": "人像风过后飘进江上的云，情像雨停后黏在地上的柳絮。聚散都带着一点不由自己，承认这种被动，反而没那么难受。看清边界，力气才不白花。", "western": "斯多葛学派把不属于我们控制的东西交还给自然；云与絮的比喻不是消极，而是看清了哪些力气不必再花。看清可控与不可控。", "tags": ["失去", "变化", "反思", "释然"]},
    {"id": "c2-084", "text": "知否，知否？应是绿肥红瘦。", "source": "李清照《如梦令·昨夜雨疏风骤》", "concept": "对细微之物的在意", "explanation": "知道吗，知道吗？经过一夜风雨，应该是绿叶更肥，红花更瘦了。关心一朵花的变化，也是在练习对细微之物的在意。温柔常从微小处开始。温柔是可以练的。", "western": "巴什拉说微小的意象能打开广阔的心理空间；一句关于花的追问，藏着人对时间流逝的敏感，也藏着温柔。微小意象打开心理空间。", "tags": ["雨", "平静", "专注", "舒展"]},
    {"id": "c2-085", "text": "此情无计可消除，才下眉头，却上心头。", "source": "李清照《一剪梅·红藕香残玉簟秋》", "concept": "情绪的转移", "explanation": "这份情绪没有办法消除，刚离开眉头，又爬上心头。越想把它赶走，它越会换个地方出现，不如先承认它还在，再慢慢安顿。承认它，比赶走它更有用。", "western": "弗洛伊德注意到被压抑的情绪会以别的形式返回；眉头与心头的转移，正是它在寻找出口，堵不如疏。被压下的情绪会返回。", "tags": ["夜晚", "孤独", "低落", "烦躁"]},
    {"id": "c2-086", "text": "寻寻觅觅，冷冷清清，凄凄惨惨戚戚。", "source": "李清照《声声慢·寻寻觅觅》", "concept": "失落的声音", "explanation": "反复寻找，四周冷冷清清，心里凄凄惨惨。叠字把一种说不清的失落拉得很长，读出来的时候，情绪反而有了节奏，也有了被接住的感觉。被说出的失落会轻一点。", "western": "维特根斯坦说语言的节奏也是意义的一部分；重复不是啰嗦，它让无法命名的感受获得了可听见的形状。节奏让感受可被听见。", "tags": ["低落", "孤独", "疲惫", "夜晚"]},
    {"id": "c2-087", "text": "生当作人杰，死亦为鬼雄。", "source": "李清照《夏日绝句》", "concept": "不把自己看轻", "explanation": "活着要做人中豪杰，死了也要做鬼中的英雄。它不是在要求你永远强悍，而是在说，人可以选择不把自己看轻，哪怕只在一件事上。把自己当人看，是底线，不是奖励。", "western": "康德把尊严放在不可交换的位置；人不是达到目的的工具，因此也不该用成败来给自己定价，这口气要留着。尊严不随成败改变。", "tags": ["专注", "期待", "舒展", "反思"]},
    {"id": "c2-088", "text": "枕上诗书闲处好，门前风景雨来佳。", "source": "李清照《摊破浣溪沙·病起萧萧两鬓华》", "concept": "闲处的滋味", "explanation": "靠在枕上读书，闲下来的时候最好；门前的风景，下雨的时候最有味道。休息不是空白，它会让平常的东西显出被忽略的好。闲下来，感官才醒过来。", "western": "海德格尔说闲谈遮蔽存在，而真正的闲让他听见存在；无所事事的片刻，可能是感知最清醒的时候。闲让感知恢复清醒。", "tags": ["雨", "阅读", "休息", "平静"]},
    {"id": "c2-089", "text": "只恐双溪舴艋舟，载不动许多愁。", "source": "李清照《武陵春·春晚》", "concept": "愁的重量", "explanation": "只怕双溪那样的小船，载不动这么多愁。把情绪写成重量，是因为它确实压在身上，不是一句想开点就能解决的，先允许它沉一会儿。重量需要被托住，而非否认。", "western": "梅洛-庞蒂认为情绪有身体的分量；愁不是抽象的，它会改变呼吸、步速和对空间的感受，也会改变时间。情绪有身体的重量。", "tags": ["孤独", "低落", "疲惫", "释然"]},
    {"id": "c2-090", "text": "小楼一夜听春雨，深巷明朝卖杏花。", "source": "陆游《临安春雨初霁》", "concept": "安静的期待", "explanation": "在小楼里听了一夜春雨，想到明天早晨，深巷里该有人叫卖杏花了。等待不一定焦灼，它也可以是这样安静的、带着香气的推测。等待也可以有香气。", "western": "柏格森说时间有质的不同；一夜听雨不是刻度上的八小时，而是一段被声音拉长、被期待填满的绵延。绵延不能被钟表切分。", "tags": ["晨间", "雨", "期待", "平静"]},
    {"id": "c2-091", "text": "零落成泥碾作尘，只有香如故。", "source": "陆游《卜算子·咏梅》", "concept": "不可碾碎的气味", "explanation": "梅花被碾成泥土，香气却还和从前一样。外形的损毁没有带走它的气味，就像一个人经历了很多，仍然保有自己的底色，那才是你。这已经足够。", "western": "斯多葛学派把不可剥夺的品格看作真正的自由；外界可以碾碎处境，却无法替你决定要以什么气味存在，这就是内在的余地。", "tags": ["失去", "专注", "平静", "低落"]},
    {"id": "c2-092", "text": "伤心桥下春波绿，曾是惊鸿照影来。", "source": "陆游《沈园二首·其一》", "concept": "旧景点亮的怀念", "explanation": "桥下的春水又绿了，想起当年她像惊鸿一样从水边经过。景物没有变，人的位置却空了，怀念常常就是这样被一处旧景突然点亮，让人措手不及。", "western": "普鲁斯特说气味与景物能打开逝去的时间；桥水本身没有记忆，是观看者把一段关系寄存在了它的颜色里，于是旧景成了入口。", "tags": ["失去", "夜晚", "反思", "低落"]},
    {"id": "c2-093", "text": "楼船夜雪瓜洲渡，铁马秋风大散关。", "source": "陆游《书愤》", "concept": "记忆里的军旅", "explanation": "雪夜里战船停在瓜洲渡，秋风里铁骑驰过大散关。两句都是回忆里的军旅画面，短促、坚硬，像一个人在心里反复播放的旧胶片，越放越亮。", "western": "柏格森认为记忆不是仓库，而是当下对过去的重新调用；画面越具体，越说明它仍在参与现在的生活，也仍在塑造你。", "tags": ["夜晚", "专注", "疲惫", "期待"]},
    {"id": "c2-094", "text": "文章本天成，妙手偶得之。", "source": "陆游《文章》", "concept": "偶得背后的准备", "explanation": "好文章本来像是天成的，只是被一双熟练的手偶然接住。灵感不是凭空掉下来，它更常出现在你已经反复练习、随时能接住它的时刻，所以要先把功练好。", "western": "波兰尼的默会知识解释这种偶得；长期训练让判断沉入身体，所谓灵感，是准备充分之后的突然抵达，而不是凭空的运气。", "tags": ["写论文", "阅读", "专注", "期待"]},
    {"id": "c2-095", "text": "古人学问无遗力，少壮工夫老始成。", "source": "陆游《冬夜读书示子聿》", "concept": "成长的时间差", "explanation": "古人做学问不保留力气，年轻时的功夫，往往到年老才显出成果。成长有时间差，今天的努力不一定立刻回报，但它不会凭空消失，会在某天接住你。", "western": "杜威把成长看作经验的持续重组；回报不在终点，而在你逐渐获得更稳的判断与更宽的选择，时间会把功夫还给你。", "tags": ["复习考试", "专注", "疲惫", "期待"]},
    {"id": "c2-096", "text": "接天莲叶无穷碧，映日荷花别样红。", "source": "杨万里《晓出净慈寺送林子方》", "concept": "盛夏的盛大", "explanation": "荷叶一直铺到天边，绿得没有尽头；荷花被阳光一照，红得格外鲜明。盛夏把颜色推到极致，人也需要这样一段时间，允许自己盛大地存在，不必收敛。", "western": "康德的无利害愉悦在这里变成色彩的强度；美不要求你占有这片荷塘，只要求你允许自己被它照亮，哪怕只有一刻。", "tags": ["晴", "舒展", "平静", "放空"]},
    {"id": "c2-097", "text": "日长睡起无情思，闲看儿童捉柳花。", "source": "杨万里《闲居初夏午睡起·其一》", "concept": "无所事事的正当", "explanation": "白天变长了，午睡起来没什么精神，就坐着看孩子们追捉柳絮。无所事事也可以是一种正经的休息，不必每段清醒都产出点什么，发呆也算数。", "western": "罗素说闲逸对文明不可或缺；不被任务占满的时间，才让人有机会恢复感受力，也恢复对自己的耐心，闲不是浪费。", "tags": ["休息", "睡眠", "平静", "放空"]},
    {"id": "c2-098", "text": "正入万山圈子里，一山放出一山拦。", "source": "杨万里《过松源晨炊漆公店·其五》", "concept": "问题的连续", "explanation": "刚走进群山的包围，一座山放你过去，另一座又拦住去路。解决问题常常不是一次通关，而是换一种难度继续走，继续往前走就好。山不会一次走完。", "western": "波普尔把科学进展看作不断遇到新问题的过程；旧的困难解决了，新的边界才显现，这本身就是前进的证据，不是原地打转。", "tags": ["迷茫", "焦虑", "反思", "专注"]},
    {"id": "c2-099", "text": "童孙未解供耕织，也傍桑阴学种瓜。", "source": "范成大《四时田园杂兴·其三十一》", "concept": "参与先于懂得", "explanation": "小孩子还不懂耕田织布，也在桑树荫下学着种瓜。参与比懂得更早发生，很多能力是在模仿和玩耍里长出来的，不必等准备完全才开始，做着做着就懂了。", "western": "维果茨基认为学习发生在最近发展区；孩子先在模仿中够到略高于当下的位置，理解随后才跟上，参与先于懂得。", "tags": ["专注", "期待", "平静", "晨间"]},
    {"id": "c2-100", "text": "梅子金黄杏子肥，麦花雪白菜花稀。", "source": "范成大《四时田园杂兴·其二十五》", "concept": "节令的颜色", "explanation": "梅子黄了，杏子肥了，麦花雪白，菜花渐稀。初夏的田野用颜色报告节令，人只要肯看，就能从日常里读到时间走到哪一格，心里也有数了。身体先知道。", "western": "现象学强调生活世界的知觉；季节不是日历上的数字，而是颜色、气味与光线共同给出的证据，身体先读到它。语言总是慢一步。", "tags": ["晴", "平静", "舒展", "晨间"]},
    {"id": "c2-101", "text": "愿我如星君如月，夜夜流光相皎洁。", "source": "范成大《车遥遥篇》", "concept": "彼此照亮的关系", "explanation": "希望我像星，你像月，每个夜晚都用自己的光彼此照映。好的关系不是谁依附谁，而是各自发光，又愿意把光借给对方，谁也不熄灭谁。光也因此更稳。", "western": "马丁·布伯的我与你关系强调彼此成全；真正的相遇不吞没对方，而是让两个人都更完整地站在光里，各自发亮。", "tags": ["期待", "社交", "平静", "舒展"]},
    {"id": "c2-102", "text": "醉里挑灯看剑，梦回吹角连营。", "source": "辛弃疾《破阵子·为陈同甫赋壮词以寄之》", "concept": "放不下的回声", "explanation": "醉里还把灯挑亮，看那柄剑；梦里又回到号角连营的军营。一个人放不下的东西，往往会在酒里和梦里反复回来，不必急着把它赶走，先听它说完。", "western": "弗洛伊德把梦看作被压抑愿望的返回；反复出现的场景不是软弱，而是心里仍有未被安放的部分在敲门，值得被听见。", "tags": ["夜晚", "疲惫", "期待", "反思"]},
    {"id": "c2-103", "text": "稻花香里说丰年，听取蛙声一片。", "source": "辛弃疾《西江月·夜行黄沙道中》", "concept": "丰收的完整经验", "explanation": "稻花飘香，人们谈着丰年，耳边是一片蛙声。丰收不只是一个结果，它也包括这样的夜晚：气味、声音和人的闲谈，一起把希望变得具体，让人心里踏实。", "western": "杜威认为经验是人与环境的完整交互；稻香、蛙声与闲谈合在一起，才构成丰收这件事对人所是的意义，而不只是产量。", "tags": ["夜晚", "平静", "期待", "舒展"]},
    {"id": "c2-104", "text": "众里寻他千百度，蓦然回首，那人却在，灯火阑珊处。", "source": "辛弃疾《青玉案·元夕》", "concept": "松手后的发现", "explanation": "在人群里找了很多遍，突然回头，才发现那个人站在灯火稀疏的地方。重要的东西不一定在最亮处，也不一定在你正盯着的地方，回头才看见。", "western": "现象学讲注意的边缘视域；当你不再强行搜索，背景里的东西反而浮现，发现常是注意力松开的结果，而不是更用力。", "tags": ["迷茫", "期待", "反思", "释然"]},
    {"id": "c2-105", "text": "少年不识愁滋味，爱上层楼。", "source": "辛弃疾《丑奴儿·书博山道中壁》", "concept": "笨拙的敏感", "explanation": "少年时不懂愁是什么滋味，却偏爱登上高楼，为一点小事装作深沉。现在回看会觉得好笑，但那份笨拙的敏感，也是成长的一部分，不必嘲笑它。", "western": "克尔凯郭尔说少年时的忧郁常是对可能性的预感；尚未经历，却已经感到世界的重量，这种模糊并不虚假，只是还没成形。", "tags": ["低落", "反思", "释然", "平静"]},
    {"id": "c2-106", "text": "把吴钩看了，栏杆拍遍，无人会，登临意。", "source": "辛弃疾《水龙吟·登建康赏心亭》", "concept": "无人理解的表达", "explanation": "把吴钩看了又看，把栏杆拍遍，也没有人懂我登高时的心意。想被理解而不可得的时候，动作会替人说话，哪怕只是反复拍着栏杆，也算一种表达。", "western": "维特根斯坦说许多感受无法被公共语言完全说出；拍栏杆不是哑剧，而是把无法命名的东西交给身体，让它替你说。", "tags": ["孤独", "低落", "烦躁", "反思"]},
    {"id": "c2-107", "text": "我见青山多妩媚，料青山见我应如是。", "source": "辛弃疾《贺新郎·甚矣吾衰矣》", "concept": "目光的往返", "explanation": "我看青山觉得它很妩媚，料想青山看我也该是这样。把善意先递给世界，世界未必立刻回应，但你的目光已经先改变了自己的处境，世界也会软下来。", "western": "梅洛-庞蒂说看与被看互为条件；你以怎样的目光投向世界，世界也以相应的方式回到你身上，目光因此有重量。", "tags": ["舒展", "平静", "社交", "反思"]},
    {"id": "c2-108", "text": "城中桃李愁风雨，春在溪头荠菜花。", "source": "辛弃疾《鹧鸪天·陌上柔桑破嫩芽》", "concept": "角落里的生机", "explanation": "城里的桃李怕风雨，春天却藏在溪边的荠菜花里。被精心照看的东西未必最耐久，真正有生命力的，有时就在不起眼的角落，安静地开着。", "western": "尼采说价值需要重估；被忽略的荠菜花不为谁开，却保存了春天，提醒人别只盯着被照料的花园，也别轻看角落。", "tags": ["晴", "期待", "舒展", "平静"]},
    {"id": "c2-109", "text": "二十四桥仍在，波心荡，冷月无声。", "source": "姜夔《扬州慢·淮左名都》", "concept": "景物里的空缺", "explanation": "二十四桥还在，水波荡着，冷月没有声音。景物被保留下来，人却换了一批又一批，站在旧桥上，会同时感到时间的连续和空落，说不出哪一种更重。", "western": "本雅明说废墟让历史显形；桥与月仍在，人的缺席反而让时间的层次被看见，空落也是历史感的一部分，不必急着填满。", "tags": ["夜晚", "平静", "失去", "反思"]},
    {"id": "c2-110", "text": "自作新词韵最娇，小红低唱我吹箫。", "source": "姜夔《过垂虹》", "concept": "共同完成的作品", "explanation": "自己写了新词，音韵正好；小红低声唱，我吹箫相和。创作和陪伴在最日常的分工里完成，一个人不必独自拥有全部的高光，分享也是作品。", "western": "杜威认为艺术不是孤立的物件，而是经验与环境的共同完成；有人唱、有人听，作品才真正发生，分享也是创作。听众也参与完成。", "tags": ["社交", "舒展", "平静", "期待"]},
    {"id": "c2-111", "text": "数峰清苦，商略黄昏雨。", "source": "姜夔《点绛唇·丁未冬过吴松作》", "concept": "风景里的心事", "explanation": "几座山峰显得清瘦寒苦，像是在商量傍晚要不要下雨。把山写成有情绪的人，是因为看山的人心里也有一场还没落下的雨，说与不说都难。", "western": "休谟说情感会通过联想投射到自然；山并不能商量，但人需要借它来安放自己尚未决定的情绪，风景因此成了心情。", "tags": ["雨", "烦躁", "低落", "反思"]},
    {"id": "c2-112", "text": "醉翁之意不在酒，在乎山水之间也。", "source": "欧阳修《醉翁亭记》", "concept": "不为什么的松弛", "explanation": "醉翁的心思不在酒上，而在山水之间。形式只是入口，真正让人留恋的，是那种被风景接住、暂时不必解释自己的松弛，这才是他想要的。这种松弛，比风景更难遇到。", "western": "杜威区分手段与目的的经验；当手段被当作目的，人就错过事情本身，山水之乐正在于不为什么，也不急着有用。", "tags": ["平静", "放空", "舒展", "晴"]},
    {"id": "c2-113", "text": "人生自是有情痴，此恨不关风与月。", "source": "欧阳修《玉楼春·尊前拟把归期说》", "concept": "情感的内因", "explanation": "人本来就会为情所痴，这份遗憾不怪风，也不怪月。把原因从外物收回到自己身上，不是自责，而是承认情感本来就是人的一部分，这样反而清楚。", "western": "斯宾诺莎说情感属于人的自然，不必当作外来的污点；理解它的来处，比寻找替罪的风月更有用，也更能松开自己。", "tags": ["失去", "反思", "低落", "释然"]},
    {"id": "c2-114", "text": "忧劳可以兴国，逸豫可以亡身。", "source": "欧阳修《新五代史·伶官传序》", "concept": "安逸的边界", "explanation": "忧患勤劳可以让国家兴起，安逸享乐却可能毁掉一个人。它不是要求你一直紧绷，而是提醒：恢复和逃避长得有点像，需要分清，别骗自己。", "western": "尼采说人需要在阻力中生长；完全没有张力的舒适会削弱力量，但张力的方向仍要由自己判断，不能交给惯性。", "tags": ["专注", "焦虑", "反思", "休息"]},
    {"id": "c2-115", "text": "祸患常积于忽微，而智勇多困于所溺。", "source": "欧阳修《新五代史·伶官传序》", "concept": "沉溺的盲点", "explanation": "祸患常常从微小的疏忽里积起来，聪明勇敢的人，反而容易被自己沉溺的东西困住。真正要防的，未必是强敌，而是那点舍不得放下的偏好，所以要常常自省。", "western": "亚里士多德把德性看作中道；沉溺不是强度问题，而是失去了对分寸的判断，长处也会在这里翻面，所以要常常自省。", "tags": ["焦虑", "反思", "拖延", "专注"]},
    {"id": "c2-116", "text": "春风又绿江南岸，明月何时照我还。", "source": "王安石《泊船瓜洲》", "concept": "归期的错位", "explanation": "春风又把江南岸吹绿了，明月什么时候才能照着我回家。季节按时回来，人的归期却没有着落，这种错位最让人想家，也只能先看着。等一个可以回去的日子。", "western": "海德格尔说乡愁是在世存在的一种基本情绪；世界照常运转，而你不在此处，这种不合拍正是想家的形状，无法被安排。", "tags": ["期待", "孤独", "晴", "反思"]},
    {"id": "c2-117", "text": "墙角数枝梅，凌寒独自开。", "source": "王安石《梅花》", "concept": "不依赖观众的开", "explanation": "墙角有几枝梅花，冒着寒冷自己开了。没有人来看，也没有关系，它开的理由不在观众，而在它本来就到了要开的时候，孤独也可以是养分。", "western": "康德的自律概念强调行动依据自身的法则；梅不为观看而开，价值不依赖外部承认，这种自足近乎尊严，也近乎自由。", "tags": ["孤独", "专注", "平静", "舒展"]},
    {"id": "c2-118", "text": "看似寻常最奇崛，成如容易却艰辛。", "source": "王安石《题张司业诗》", "concept": "从容背后的功夫", "explanation": "看起来平常的东西，往往最不平常；完成得好像很轻松，背后却有很多艰辛。别被别人的从容骗到，也别小看自己走过的路，每一步都算数。", "western": "波兰尼用默会知识解释行家的从容；外行看见的是轻松，内行知道那是无数次练习压缩成的安静，功夫藏在看不见处。", "tags": ["专注", "写论文", "复习考试", "反思"]},
    {"id": "c2-119", "text": "无可奈何花落去，似曾相识燕归来。", "source": "晏殊《浣溪沙·一曲新词酒一杯》", "concept": "失去与回来并存", "explanation": "花落下去，没有办法；燕子飞回来，又像是见过的旧相识。失去和回来在同一句里发生，生活很少只给你其中一样，所以要一起收下。不必挑拣。", "western": "赫拉克利特说万物流动，但流动并非纯粹消失；旧的形态退场，新的相似性又回来，变化里仍有节律，失去也因此可忍。", "tags": ["失去", "平静", "变化", "释然"]},
    {"id": "c2-120", "text": "昨夜西风凋碧树，独上高楼，望尽天涯路。", "source": "晏殊《蝶恋花·槛菊愁烟兰泣露》", "concept": "孤独打开视野", "explanation": "昨夜西风把绿树吹得凋零，独自登上高楼，望到天边的路尽头。孤独有时会把视野打开，让你看见平时被人群挡住的方向，也看见自己。那是人群给不了的东西。", "western": "克尔凯郭尔说孤独是面对可能性的条件；人群会稀释选择，独自登高时，人才能听见自己真正的方向，也听见自己的怕。", "tags": ["孤独", "迷茫", "期待", "专注"]},
    {"id": "c2-121", "text": "衣带渐宽终不悔，为伊消得人憔悴。", "source": "柳永《蝶恋花·伫倚危楼风细细》", "concept": "投入的代价", "explanation": "衣带越来越松，人瘦了，也不后悔；为了心里那个人，憔悴也值得。投入本身有它的重量，但也要记得，值得不包括把自己耗空，留一点给自己。", "western": "列维纳斯把为他者负责看作主体性的核心；但责任若没有边界，会吞掉承担者，爱也需要可持续的形式，才能长久。", "tags": ["期待", "专注", "疲惫", "失去"]},
    {"id": "c2-122", "text": "今宵酒醒何处？杨柳岸，晓风残月。", "source": "柳永《雨霖铃·寒蝉凄切》", "concept": "离别后的清晨", "explanation": "今夜酒醒时会在哪里？大概是杨柳岸边，吹着晓风，天边挂着一弯残月。离别后的清晨没有戏剧性，只有一点冷和一点空，却记得很久。记忆替人把它留着。", "western": "海德格尔说情绪揭示人在世界中的处境；晓风残月不是背景，它把离别后的无所依凭直接呈现出来，比语言更早。", "tags": ["夜晚", "孤独", "低落", "失去"]},
    {"id": "c2-123", "text": "人生自古谁无死？留取丹心照汗青。", "source": "文天祥《过零丁洋》", "concept": "比生命更长的东西", "explanation": "人总有一死，只希望能留下一颗赤诚的心，被后来的人记住。它谈的不是不怕死，而是愿意让某些东西比性命更长，这需要选择。也值得敬重。", "western": "康德把人格尊严放在超越利害的位置；人可以为某种价值承担代价，这正说明他不是只受自保支配的存在，也不只是身体。", "tags": ["专注", "期待", "失去", "反思"]},
    {"id": "c2-124", "text": "疏影横斜水清浅，暗香浮动月黄昏。", "source": "林逋《山园小梅·其一》", "concept": "留白的表达", "explanation": "稀疏的梅影横斜在清浅的水上，淡淡的香气在黄昏的月色里浮动。它没有正面写梅，却让人闻到了，最好的表达有时是留白，让读者自己走近。", "western": "现象学讲显现与遮蔽的关系；梅不直接被写出，反而在影与香里更完整地到场，留白是一种积极的给予，而非空缺。", "tags": ["夜晚", "平静", "舒展", "放空"]},
    {"id": "c2-125", "text": "等闲识得东风面，万紫千红总是春。", "source": "朱熹《春日》", "concept": "多样的共同", "explanation": "很容易就认出了春风的面貌，万紫千红，都是春天。世界并没有统一的表情，它用很多种颜色同时说话，你也不必只活成一种样子，多样才是春天。", "western": "维特根斯坦说家族相似而非单一本质；万紫千红都属于春，却不必共享一个定义，多样本身就是共同体的方式，也是自由。", "tags": ["晴", "舒展", "期待", "平静"]},
    {"id": "c2-126", "text": "少年易老学难成，一寸光阴不可轻。", "source": "朱熹《偶成》", "concept": "时间的重量", "explanation": "少年很容易变老，学问却很难学成，所以一寸光阴也不该轻看。它不是催你焦虑，而是提醒时间的珍贵，值得被用在你在意的地方，包括休息。", "western": "塞涅卡说生命并不短，只是被浪费太多；时间伦理不是把每一分钟填满，而是不让它悄悄流走，也不让它只剩任务。", "tags": ["复习考试", "专注", "焦虑", "期待"]},
    {"id": "c2-127", "text": "诗者，吟咏情性也。", "source": "严羽《沧浪诗话·诗辨》", "concept": "诗的本源", "explanation": "诗，是吟咏人的情性。它不是堆砌辞藻，也不是完成一道题目，而是把心里那点真实的感受，找到有节奏、可以说出口的形式，让别人也听见。", "western": "亚里士多德说诗比历史更接近普遍；它不记录个别事件，而把人的情感提炼成可被共享的形式，让听者认出自己。", "tags": ["写论文", "阅读", "专注", "反思"]},
    {"id": "c2-128", "text": "羚羊挂角，无迹可求。", "source": "严羽《沧浪诗话·诗辨》", "concept": "无迹的诗境", "explanation": "羚羊把角挂在树上，连踪迹都找不到。好的诗境也是这样，不把意思直接说尽，留下空白，让读者自己走进去，留白的地方才有更长的余味。", "western": "海德格尔说遮蔽属于真理；完全说尽反而关闭想象，无迹可求是一种让事物自行显现的克制，也是给读者的空间。", "tags": ["阅读", "写论文", "放空", "平静"]},
    {"id": "c2-129", "text": "素月分辉，明河共影，表里俱澄澈。", "source": "张孝祥《念奴娇·过洞庭》", "concept": "内外的澄澈", "explanation": "素月分来清辉，银河投下共同的影子，里里外外都澄澈。这样的夜晚会让人想把自己也整理一遍，把浑浊的部分暂时放下，哪怕只一夜。这样的夜不多。", "western": "巴什拉说水与夜的意象能让人回到内在；澄澈不是没有杂质，而是暂时看清了杂质的位置，于是可以重新安放自己。", "tags": ["夜晚", "平静", "放空", "舒展"]},
    {"id": "c2-130", "text": "杏花疏影里，吹笛到天明。", "source": "陈与义《临江仙·夜登小阁忆洛中旧游》", "concept": "舍不得结束的夜", "explanation": "在杏花稀疏的影子里，吹笛一直吹到天亮。年轻时会有这样的夜晚，不为完成什么，只是舍不得让这一刻结束，也不必急着让它结束。天亮以后再去想。", "western": "柏格森说绵延在音乐里最容易被感到；笛声把时间拉长，使一个夜晚不再只是钟点，而成为一段质地，可以被记住。", "tags": ["夜晚", "社交", "舒展", "放空"]},
    {"id": "c2-131", "text": "问世间，情是何物，直教生死相许。", "source": "元好问《摸鱼儿·雁丘词》", "concept": "无法回答的情", "explanation": "问世间，情到底是什么，竟让人愿意以生死相托。它没有给出答案，而是把问题本身写得足够重，重到每个人都得用自己的经历回答，没有标准答案。", "western": "柏拉图把爱欲看作对完整性的追求；情之所以难答，是因为它同时连着缺乏与超越，不能只用占有解释，也不能只用理性。", "tags": ["期待", "迷茫", "反思", "低落"]},
    {"id": "c2-132", "text": "一语天然万古新，豪华落尽见真淳。", "source": "元好问《论诗三十首·其四》", "concept": "朴素的力量", "explanation": "一句天然的话，过了万古仍然新鲜；把豪华的修饰去掉，才看见真正的淳朴。好文字不靠堆叠，它靠的是把多余的东西一层层放下，最后剩下自己。", "western": "海德格尔说语言的本真在于让事物如其所是；修饰退场后，存在才显露，朴素因此不是贫乏而是准确，也是一种勇气。", "tags": ["写论文", "阅读", "专注", "释然"]},
    {"id": "c2-133", "text": "野蔓有情萦战骨，残阳何意照空城。", "source": "元好问《岐阳三首·其二》", "concept": "克制的悲悯", "explanation": "野藤像有情一样缠着战死者的骨头，残阳又为什么照着空城。诗人没有直接喊痛，只让草木和落日替他把问题问出来，答案留在风里。草木替人记着。", "western": "阿多诺说奥斯维辛之后写诗是野蛮的；面对灾难，克制的意象比抒情更诚实，因为它不替死者代言，也不消费痛苦。", "tags": ["失去", "反思", "低落", "平静"]},
    {"id": "c2-134", "text": "地也，你不分好歹何为地？天也，你错勘贤愚枉做天！", "source": "关汉卿《窦娥冤》", "concept": "向天地的控诉", "explanation": "地啊，你不分好坏，凭什么做地？天啊，你看错贤愚，白做了天。把愤怒指向天地，是因为人间已找不到可以讲理的地方，只能这样喊出来。喊出来才算活过。", "western": "尼采说价值崩塌时人会被迫重估一切；窦娥的控诉不是失礼，而是对不义秩序最直接的审判，也是弱者仅剩的武器。", "tags": ["烦躁", "低落", "反思", "焦虑"]},
    {"id": "c2-135", "text": "为善的受贫穷更命短，造恶的享富贵又寿延。", "source": "关汉卿《窦娥冤》", "concept": "不公面前的善", "explanation": "行善的人受穷、命还短，作恶的人享富贵、活得久。看见这样的不公，愤怒是正常的，重要的是别让愤怒把你变成你讨厌的那种人，也别丢掉善。", "western": "康德认为德性与幸福并不自动一致，至善需要悬设；现实的不公不证明善无意义，只证明世界尚未合乎理性，仍待改变。", "tags": ["烦躁", "低落", "反思", "期待"]},
    {"id": "c2-136", "text": "我是个蒸不烂、煮不熟、捶不匾、炒不爆、响珰珰一粒铜豌豆。", "source": "关汉卿《南吕·一枝花·不伏老》", "concept": "不可压扁的自我", "explanation": "我是个蒸不烂、煮不熟、捶不匾、炒不爆的铜豌豆。用这么硬的话说自己，不是逞强，而是告诉世界：你可以反复碾压，但我不会因此变成别的东西，这就是底线。", "western": "斯多葛学派把不可摧毁的判断力视为最后的自由；外力能改变处境，却改不了你如何回应，回应才是你的。这就是自由。", "tags": ["专注", "烦躁", "期待", "反思"]},
    {"id": "c2-137", "text": "枯藤老树昏鸦，小桥流水人家，古道西风瘦马。", "source": "马致远《天净沙·秋思》", "concept": "并置出的漂泊", "explanation": "枯藤缠着老树，昏鸦落在枝头；小桥下流水，旁边有人家；古道上西风瘦马。三组画面并置，没有一句抒情，漂泊的感觉却全出来了，这就是白描的力量。", "western": "现象学讲并置能生成意义；画面之间没有解释，读者却在缝隙里感到旅人的疲惫，意义由关系而非说明产生。关系先于说明。", "tags": ["疲惫", "孤独", "夜晚", "低落"]},
    {"id": "c2-138", "text": "百岁光阴一梦蝶，重回首往事堪嗟。", "source": "马致远《双调·夜行船·秋思》", "concept": "回望时的轻", "explanation": "百年光阴像一场梦，梦里自己化成蝴蝶；再回头，往事只剩叹息。把一生说得这么轻，不是看破一切，而是知道很多执念经不起回头看，所以松开一点。", "western": "庄周梦蝶的典故在这里与尼采的生成之思相遇；自我并非固定实体，回望时才发现，执念比岁月更早松动。松开也是理解。", "tags": ["睡眠", "反思", "释然", "变化"]},
    {"id": "c2-139", "text": "和露摘黄花，带霜烹紫蟹，煮酒烧红叶。", "source": "马致远《双调·夜行船·秋思》", "concept": "把季节过成日子", "explanation": "带着露水摘黄花，趁着霜降烹紫蟹，烧起红叶温酒。秋天不只有萧瑟，它也有自己的吃食和暖意，只要你愿意动手，季节就能被过成日子，别辜负它。", "western": "杜威把审美经验放在日常实践里；摘、烹、煮不是消遣，而是人与季节打交道的方式，生活的形式由此生长。日子因此成形。", "tags": ["晴", "舒展", "平静", "社交"]},
    {"id": "c2-140", "text": "兴，百姓苦；亡，百姓苦。", "source": "张养浩《山坡羊·潼关怀古》", "concept": "兴亡背后的代价", "explanation": "王朝兴起，百姓苦；王朝灭亡，百姓也苦。短短十个字，把兴亡的宏大叙事翻到背面，让人看见代价一直落在同一群人身上，这不该被忘记。历史不该只写帝王。", "western": "马克思主义史学关注谁承担历史的代价；宏大叙事常把痛苦抽象掉，这句话却把账重新记回具体的人身上。账要算清。", "tags": ["低落", "反思", "烦躁", "变化"]},
    {"id": "c2-141", "text": "峰峦如聚，波涛如怒，山河表里潼关路。", "source": "张养浩《山坡羊·潼关怀古》", "concept": "雄壮里的反差", "explanation": "山峰像聚拢过来，波涛像在发怒，潼关外有黄河、内有华山，地势险要。山河写得越雄壮，后面百姓的苦就越显得无处可躲，反差就在这里。山河越壮，人越轻。", "western": "康德把崇高感与人的有限并置；越宏伟的山河，越让人意识到个体在历史力量前的渺小与无力。也让人学会谦卑。", "tags": ["平静", "舒展", "反思", "晴"]},
    {"id": "c2-142", "text": "云来山更佳，云去山如画。", "source": "张养浩《雁儿落兼得胜令》", "concept": "两种显现", "explanation": "云来了，山更好看；云走了，山像一幅画。同一个山，在有无之间显出两种美，人的心境也是这样，不必执着于只有一种状态才算好，都可看。人也该允许自己多变。", "western": "现象学认为同一对象在不同显现中保持同一；云来云去改变的不是山，而是山向你呈现的方式，接受变化即接受丰富。", "tags": ["晴", "平静", "舒展", "变化"]},
    {"id": "c2-143", "text": "碧云天，黄花地，西风紧，北雁南飞。", "source": "王实甫《西厢记·长亭送别》", "concept": "秋景里的离别", "explanation": "碧云满天，黄花铺地，西风紧起来，北雁往南飞。四样东西把秋天推到眼前，没有一句说愁，离别的人却已经站在风里了，冷得很具体。冷得让人无处躲。", "western": "本雅明说意象能把时间凝住；碧云、黄花、西风与雁阵并置，秋天被压缩成一个可感的瞬间，情绪附着其上。情绪也停在那一刻。", "tags": ["低落", "孤独", "夜晚", "变化"]},
    {"id": "c2-144", "text": "晓来谁染霜林醉？总是离人泪。", "source": "王实甫《西厢记·长亭送别》", "concept": "把颜色归给悲伤", "explanation": "清晨是谁把霜林染得像喝醉了一样红？大概都是离人的眼泪。把自然的颜色归给悲伤，是夸张，也是那一刻唯一说得通的解释，不必纠正。", "western": "休谟说情感会投射到外物；霜林本身不醉，是人把离别染上了颜色，诗的真不在事实，而在感受的准确。诗因此成立。", "tags": ["失去", "低落", "夜晚", "反思"]},
    {"id": "c2-145", "text": "十年窗下无人问，一举成名天下知。", "source": "高明《琵琶记》", "concept": "被看见之前", "explanation": "十年在窗下苦读，没有人过问；一旦成名，天下都知道了。它写的是科举的光鲜，也提醒人：被看见的那一刻很短，之前的日子很长，别只等那一刻。", "western": "布尔迪厄谈场域中的承认；名声是外力授予的标签，窗下十年却是无人鼓掌的自我塑造，两者并不等价。结果之外还有十年。", "tags": ["复习考试", "期待", "焦虑", "反思"]},
    {"id": "c2-146", "text": "孤村落日残霞，轻烟老树寒鸦。", "source": "白朴《天净沙·秋》", "concept": "无人的冷清", "explanation": "孤零零的村子，落日与残霞；淡淡的烟，老树上的寒鸦。全是安静的物，没有人在场，秋天的冷就这样一点点渗进来，安静本身也有重量。冷清里也可以住人。", "western": "巴什拉说孤独的意象会打开内在空间；无人出现的风景反而更适合安放情绪，冷清因此有了可居住的形状。无人处也能安顿。", "tags": ["夜晚", "孤独", "平静", "放空"]},
    {"id": "c2-147", "text": "兴亡千古繁华梦，诗眼倦天涯。", "source": "张可久《人月圆·山中书事》", "concept": "看惯后的倦", "explanation": "千古兴亡不过是一场繁华梦，看惯了，诗人的眼睛也倦于天涯。倦不是冷漠，而是看得太多之后，对热闹有了一种安静的距离，也是一种清醒。", "western": "斯多葛学派用宇宙尺度看待兴衰；距离感不是逃避，而是把一时的喧哗放回更长的时间里衡量。距离也是尺度。", "tags": ["疲惫", "释然", "反思", "平静"]},
    {"id": "c2-148", "text": "平生不会相思，才会相思，便害相思。", "source": "乔吉《折桂令·春情》", "concept": "初遇情绪的手足无措", "explanation": "本来不懂得相思，刚学会相思，就被相思害苦了。三句一层层递进，把初恋般的狼狈写得很轻，也很准，谁都有过这样手足无措的时候，不必难为情。", "western": "斯宾诺莎说情感的力量来自我们对它的认识不足；刚被一种新情绪击中时，人往往既无力又诚实。诚实比镇定更难。", "tags": ["期待", "焦虑", "社交", "释然"]},
    {"id": "c2-149", "text": "滚滚长江东逝水，浪花淘尽英雄。", "source": "杨慎《临江仙·滚滚长江东逝水》", "concept": "历史如流水", "explanation": "长江滚滚向东流，浪花把英雄都淘尽了。历史像水，把人举起来又带走，站在这条河边，个人的成败会显得轻一些，但不是没有意义，仍要活好当下。", "western": "赫拉克利特说人不能两次踏入同一条河；历史淘洗一切，但此刻的选择仍属于你，流动不取消责任。责任仍在当下。", "tags": ["平静", "反思", "变化", "舒展"]},
    {"id": "c2-150", "text": "白发渔樵江渚上，惯看秋月春风。", "source": "杨慎《临江仙·滚滚长江东逝水》", "concept": "日常的承受力", "explanation": "白发渔夫和樵夫在江边，看惯了秋月春风。他们不是历史的旁观者，而是把兴亡当作日常天气的人，日子照样要过，鱼照样要打，这就是生活。", "western": "海德格尔说日常性常遮蔽存在；渔樵的重复不是麻木，而是把历史的重负放回可承受的生活尺度。日常也有重量。", "tags": ["平静", "放空", "释然", "孤独"]},
    {"id": "c2-151", "text": "原来姹紫嫣红开遍，似这般都付与断井颓垣。", "source": "汤显祖《牡丹亭·惊梦》", "concept": "被荒废的美", "explanation": "原来园子里姹紫嫣红开得那么好，却都交给断井残墙。美被浪费在最该被看见的时候，杜丽娘的心疼，也是对自身处境的突然明白。明白往往来得太晚。", "western": "黑格尔谈美是理念的感性显现；当显现被荒废，人感到的不只是可惜，而是自身可能性被搁置的痛。被搁置的是她自己。", "tags": ["低落", "失去", "反思", "烦躁"]},
    {"id": "c2-152", "text": "良辰美景奈何天，赏心乐事谁家院。", "source": "汤显祖《牡丹亭·惊梦》", "concept": "差一点的好时光", "explanation": "这么好的时辰和风景，天却不由人；赏心的乐事，究竟落在谁家的院子里。两句都是问句，问的不是天气，而是自己的好时光为什么总差一点。", "western": "康德区分美与利害；当美不能带来占有，人反而更清楚自己的有限，遗憾因此成为审美经验的一部分。遗憾也成了经验。", "tags": ["迷茫", "低落", "期待", "反思"]},
    {"id": "c2-153", "text": "山色如娥，花光如颊，温风如酒，波纹如绫。", "source": "袁宏道《西湖游记·初至西湖记》", "concept": "身体记住的风景", "explanation": "山色像女子的眉，花光像脸颊，暖风像酒，水波像绸缎。四个比喻都是身体能感到的东西，西湖的春天因此不只是看的，也是被皮肤记住的。", "western": "梅洛-庞蒂说身体是知觉的统一场；比喻之所以有效，是因为它把视觉换成了触觉与温度，让风景进入身体。风景进入身体。", "tags": ["晴", "舒展", "平静", "社交"]},
    {"id": "c2-154", "text": "西湖最盛，为春为月。", "source": "袁宏道《晚游六桥待月记》", "concept": "极简的指认", "explanation": "西湖最美的时候，是春天，是月夜。六个字就把最好的时辰点出来，不解释，也不铺陈，仿佛美景自己会说话，剩下的部分交给你想象。说尽了反而更少。", "western": "维特根斯坦说不可言说者应保持沉默；六个字不展开，反而把想象的空间完整地交还给读者。沉默也参与意义。", "tags": ["晴", "平静", "放空", "舒展"]},
    {"id": "c2-155", "text": "雾凇沆砀，天与云与山与水，上下一白。", "source": "张岱《湖心亭看雪》", "concept": "被简化成一种颜色", "explanation": "雾凇白茫茫一片，天、云、山、水，上上下下全是白的。世界被简化成一种颜色，人站在里面，会暂时忘记自己是谁，只剩看见，也很轻盈。人也被简化。", "western": "现象学讲悬置自然态度；当颜色与轮廓消失，人被迫回到纯粹的看，世界以最少的属性重新出现。看因此变得纯粹。", "tags": ["平静", "放空", "舒展", "晨间"]},
    {"id": "c2-156", "text": "湖上影子，惟长堤一痕、湖心亭一点。", "source": "张岱《湖心亭看雪》", "concept": "极简的构图", "explanation": "湖上的影子，只剩长堤一道痕，湖心亭一个点。大雪把细节都收走了，留下的笔画极少，却让空旷变得可以丈量，极简的画面反而更满。空处也在说话。", "western": "康德的无利害静观在此变成极简的构图；痕与点不描述湖，却让湖的辽阔被感到，少比多更接近整体。留白也是内容。", "tags": ["平静", "放空", "专注", "舒展"]},
    {"id": "c2-157", "text": "雪满山中高士卧，月明林下美人来。", "source": "高启《梅花九首·其一》", "concept": "清冷与温柔", "explanation": "大雪满山，高士安卧；月明林下，美人走来。两句都是理想化的画面，一冷一暖，一静一动，人心里对清高与温柔的两种向往都在，并不矛盾。人本来就不止一面。", "western": "尼采区分日神与酒神；雪与月是日神的清明，美人与林下是酒的暖意，两种冲动共同构成完整的想象。想象因此完整。", "tags": ["夜晚", "平静", "舒展", "期待"]},
    {"id": "c2-158", "text": "大江来从万山中，山势尽与江流东。", "source": "高启《登金陵雨花台望大江》", "concept": "山水的合力", "explanation": "大江从万山里来，山的走势也跟着江水一路向东。山水不是彼此对抗，而是互相推着走，人站在高处看，会感到一种巨大的合力，推着人向前。", "western": "柏格森说生命的冲动不断向前；山与水的关系不是静止的结构，而是持续生成的趋势，人也在其中被推动。人也被推着走。", "tags": ["舒展", "平静", "专注", "反思"]},
    {"id": "c2-159", "text": "粉骨碎身浑不怕，要留清白在人间。", "source": "于谦《石灰吟》", "concept": "为怎样的自己负责", "explanation": "就算粉身碎骨也不怕，只要把清白留在人间。它写的不是死亡，而是一个人愿意为什么样的自己负责，哪怕代价很大，这就是选择。清白比性命更重一些。", "western": "康德把人格尊严置于一切交换之上；人可以为原则承担代价，正因为他不是只按利害计算的生物。原则高于利害。", "tags": ["专注", "期待", "反思", "低落"]},
    {"id": "c2-160", "text": "别人笑我太疯癫，我笑他人看不穿。", "source": "唐寅《桃花庵歌》", "concept": "评价权的争夺", "explanation": "别人笑我太疯癫，我笑他们看不穿。两句把评价权来回掷了一次，谁更清醒其实没有定论，但至少他不肯用别人的眼光定义自己。他保住了自己的尺子。", "western": "尼采说视角决定价值；当双方都用自己的尺度衡量对方，争论就不在事实层面，而在谁有权命名清醒。命名的权力才是战场。", "tags": ["烦躁", "释然", "社交", "反思"]},
    {"id": "c2-161", "text": "半生落魄已成翁，独立书斋啸晚风。", "source": "徐渭《题墨葡萄图》", "concept": "不肯低头的姿势", "explanation": "半生落魄，已经成了老人；独自站在书斋外，对着晚风长啸。落魄没有被写成失败，反而有一种不肯低头的姿势，风一吹，人还在，就够了。晚风替他应了一声。", "western": "尼采的命运之爱不是喜欢苦难，而是肯定自己的全部；长啸不是胜利，而是拒绝让落魄成为最后的评语。评语尚未写完。", "tags": ["低落", "释然", "专注", "反思"]},
    {"id": "c2-162", "text": "人生若只如初见，何事秋风悲画扇。", "source": "纳兰性德《木兰花·拟古决绝词柬友》", "concept": "变化后的失落", "explanation": "如果人和人的关系永远像第一次见面，就不会有秋风里被弃置的画扇。变化本身没有错，痛的是曾经亲密，后来却用冷漠解释一切。后来才学会心疼当时。", "western": "柏拉图把爱欲与缺失相连；初见之所以被怀念，是因为它尚未被占有和时间修改，保留了可能性的完整。怀念保留了可能。", "tags": ["失去", "低落", "期待", "反思"]},
    {"id": "c2-163", "text": "赌书消得泼茶香，当时只道是寻常。", "source": "纳兰性德《浣溪沙·谁念西风独自凉》", "concept": "寻常里的珍贵", "explanation": "一起赌书，茶泼了满屋香；当时只觉得是寻常日子。后来才明白，最难得的幸福常常没有标记，它在的时候，人是不自知的，所以要多留心。寻常最容易被错过。", "western": "普鲁斯特说真正的发现不在新风景，而在重新看见；寻常之所以后来发光，是因为记忆改变了它的位置。记忆重排了轻重。", "tags": ["平静", "感激", "失去", "反思"]},
    {"id": "c2-164", "text": "山一程，水一程，身向榆关那畔行。", "source": "纳兰性德《长相思·山一程》", "concept": "把长路拆成段", "explanation": "山一程，水一程，人往榆关那边走。路被拆成一程一程，听起来就没那么可怕，长途也是这样，走完眼前这一段，再说下一段，心里也就安定下来。", "western": "海德格尔说人是行走的存在；把漫长路程切成段落，不是自欺，而是让有限的身体找到可完成的节奏。节奏让路变得可走。", "tags": ["疲惫", "期待", "专注", "平静"]},
    {"id": "c2-165", "text": "风一更，雪一更，聒碎乡心梦不成。", "source": "纳兰性德《长相思·山一程》", "concept": "风雪里的失眠", "explanation": "风一更，雪一更，风雪吵得人做不成回家的梦。失眠的夜里，声音会被放大，想家也会被放大，熬过去靠的不是道理，是一点一点到天亮。熬是具体的，不是道理。", "western": "现象学关注夜间知觉的改变；风雪的声响让空间变得不可居，乡愁因此不只是心理，也是身体对安稳的渴求。也渴望庇护。", "tags": ["夜晚", "孤独", "睡眠", "低落"]},
    {"id": "c2-166", "text": "我是人间惆怅客，知君何事泪纵横。", "source": "纳兰性德《浣溪沙·残雪凝辉冷画屏》", "concept": "被懂得的孤独", "explanation": "我也是人间一个惆怅的过客，所以懂你为什么泪流满面。被理解不一定要解决问题，有时只是有人告诉你：你这样，我也曾经这样，就够了。", "western": "列维纳斯说他者的脸召唤责任；一句我懂不是解释，而是把自己放到对方旁边，让孤独不再是唯一的处境。孤独被分担。", "tags": ["孤独", "低落", "社交", "释然"]},
    {"id": "c2-167", "text": "保天下者，匹夫之贱与有责焉耳矣。", "source": "顾炎武《日知录·正始》", "concept": "普通人的公共责任", "explanation": "保卫天下，即使是地位低微的普通人，也有责任。它不是要求你做多大的事，而是说公共生活不是别人的事，你也在其中，也有一份，别推开。", "western": "阿伦特说公共世界由共同行动维系；责任不属于少数英雄，而属于每个愿意出现在公共空间里的人。公共世界需要有人到场。", "tags": ["专注", "期待", "反思", "社交"]},
    {"id": "c2-168", "text": "君子之为学，以明道也，以救世也。", "source": "顾炎武《亭林文集·与人书二十五》", "concept": "学问的落点", "explanation": "君子做学问，是为了明白道理，也是为了救这个世界。学习不只为自己长本事，它最终要回到人间，回到你能帮上忙的地方，才算完成。学问要能落地。", "western": "杜威说知识是行动的工具；学习若脱离公共生活，就只是私人的装饰，明道与救世本是一件事。学问才有真正的落点。", "tags": ["阅读", "专注", "期待", "反思"]},
    {"id": "c2-169", "text": "意犹帅也，无帅之兵，谓之乌合。", "source": "王夫之《姜斋诗话》", "concept": "统摄全篇的意", "explanation": "意就像军队的统帅，没有统帅的士兵，只是一群乌合之众。写诗写文章也是这样，辞藻再多，如果没有一个统领全篇的意思，读者只会觉得散。", "western": "分析哲学重视论证的结构；没有中心命题的段落只是句子的集合，意义不来自数量，而来自组织方式。结构生成意义。", "tags": ["写论文", "专注", "反思", "阅读"]},
    {"id": "c2-170", "text": "情景名为二，而实不可离。", "source": "王夫之《姜斋诗话》", "concept": "情与景不可分", "explanation": "情和景名义上是两样东西，实际上分不开。你看见的风景总带着心情，你的心情也总要借一处风景才说得清，写作就是把它们重新缝在一起。", "western": "梅洛-庞蒂说知觉与情感不可分割；纯粹的景与纯粹的情都是抽象，经验里两者总是同时到场。抽象会丢掉经验。", "tags": ["阅读", "写论文", "平静", "反思"]},
    {"id": "c2-171", "text": "我劝天公重抖擞，不拘一格降人才。", "source": "龚自珍《己亥杂诗·其二百二十》", "concept": "对单一标准的抗议", "explanation": "我劝老天爷重新振作，不要只用一种规格降下人才。它表面在求天，实际在批评一种僵硬的选拔方式，也是在替被格式挡住的人说话。格式之外还有人才。", "western": "密尔为个性辩护；统一的标准会筛掉不合规格的才能，真正的进步需要允许不同的生活方式与心智形态。进步需要异类。", "tags": ["期待", "舒展", "反思", "焦虑"]},
    {"id": "c2-172", "text": "万一禅关砉然破，美人如玉剑如虹。", "source": "龚自珍《夜坐二首·其二》", "concept": "顿悟的一刻", "explanation": "万一哪天禅关忽然破了，眼前会出现美人如玉、宝剑如虹。它写的是顿悟的一刻，所有被压抑的想象同时打开，世界忽然有了颜色和锋刃。", "western": "威廉·詹姆斯描述宗教经验中的忽然转变；顿悟不是获得新事实，而是整个经验结构被重新组织。经验被重新组织。", "tags": ["期待", "舒展", "平静", "反思"]},
    {"id": "c2-173", "text": "一箫一剑平生意，负尽狂名十五年。", "source": "龚自珍《漫感》", "concept": "柔与锋并存", "explanation": "一支箫、一柄剑，就是平生的意愿；十五年来，空负了狂放的名声。箫是柔情，剑是锋芒，两样都想要的人，往往要在世俗里吃不少苦，也不肯改。", "western": "尼采说人必须自己创造价值；箫与剑并置，是对单一成功标准的拒绝，哪怕代价是被时代误解。价值要由自己定。", "tags": ["期待", "释然", "反思", "低落"]},
    {"id": "c2-174", "text": "似此星辰非昨夜，为谁风露立中宵。", "source": "黄景仁《绮怀·其十五》", "concept": "身体的滞后", "explanation": "这样的星辰已经不是昨夜的了，可我还是在风露里站到半夜，究竟是为了谁。明知时过境迁，身体却还停在旧习惯里，这种滞后很真实。慢的那一拍也是真的。", "western": "柏格森说绵延有滞后性；理智已经接受失去，身体仍按旧节奏等待，情感的时间总比事实慢半拍。情感有自己的钟。", "tags": ["夜晚", "失去", "孤独", "低落"]},
    {"id": "c2-175", "text": "十有九人堪白眼，百无一用是书生。", "source": "黄景仁《杂感》", "concept": "自嘲里的骄傲", "explanation": "十个人里有九个值得翻白眼，而最没用的，就是书生。前一句是愤世，后一句是自嘲，把读书人的尴尬说得很狠，也藏着一点不肯认输的骄傲。", "western": "布尔迪厄谈文化资本的无效时刻；自嘲不是否定学问，而是识破学问在特定场域里并不能兑换成尊重。尊重从来不是自动发放的。", "tags": ["低落", "反思", "释然", "焦虑"]},
    {"id": "c2-176", "text": "全家都在风声里，九月衣裳未剪裁。", "source": "黄景仁《都门秋思·其三》", "concept": "具体的贫困", "explanation": "全家都缩在风声里，九月了，过冬的衣裳还没剪裁。贫困没有被写成哭喊，只是一件没做完的衣裳，具体的缺口比抽象的同情更让人难受。", "western": "西蒙娜·薇依关注受苦的具体性；贫穷不是概念，而是没有裁好的冬衣，伦理从看见这些细节开始。伦理始于看见。", "tags": ["低落", "疲惫", "反思", "孤独"]},
    {"id": "c2-177", "text": "古今之成大事业、大学问者，必经过三种之境界。", "source": "王国维《人间词话》", "concept": "成长的三重境界", "explanation": "古今做成大事业、大学问的人，都要经过三种境界。王国维借三句词说成长：先迷茫远望，再憔悴坚持，最后在回头处遇见答案，一步都急不得。", "western": "克尔凯郭尔把人生分为审美、伦理与宗教阶段；境界不是技巧的层级，而是人存在方式的转变，无法跳过。阶段无法跳过。", "tags": ["复习考试", "写论文", "专注", "期待"]},
    {"id": "c2-178", "text": "有我之境，以我观物，故物皆著我之色彩。", "source": "王国维《人间词话》", "concept": "情绪染色的观看", "explanation": "有我之境，是用我的眼光看万物，所以万物都染上我的颜色。难过时雨也沉重，开心时风也轻，世界没有变，是观看的人把情绪放了进去。承认它反而更接近真实。", "western": "休谟说心灵把情感投射到对象；所谓客观风景，其实总带着观察者的温度，承认这一点反而更接近真实。真实包含温度。", "tags": ["反思", "专注", "平静", "写论文"]},
    {"id": "c2-179", "text": "无我之境，以物观物，故不知何者为我，何者为物。", "source": "王国维《人间词话》", "concept": "放下成见的看", "explanation": "无我之境，是用物的方式看物，所以分不清哪个是我，哪个是物。不是没有自己，而是暂时放下成见，让事物按它本来的样子出现，这很难得。", "western": "现象学的悬置试图回到事物本身；放下自然的执念，不是取消自我，而是让对象从功利的观看里解放出来。对象因此得以显现。", "tags": ["平静", "放空", "专注", "舒展"]},
    {"id": "c2-180", "text": "一切景语皆情语。", "source": "王国维《人间词话》", "concept": "景中总有人在", "explanation": "所有写景的话，其实都是在写情。风景不会自己开口，是人选了它、看了它、把它写下来，所以每一处景里，都站着一个正在感受的人，读景也是读人。", "western": "海德格尔说人在世界之中，情绪先于对象；纯粹中立的风景描述并不存在，景总是被人的处境照亮。每一次看都带着立场。", "tags": ["阅读", "写论文", "平静", "反思"]},
    {"id": "wang-mian-plum", "text": "不要人夸好颜色，只留清气满乾坤。", "source": "王冕《墨梅》", "concept": "内在尺度", "explanation": "不必把外界的认可当成唯一评分。你愿意怎样做人、怎样做事，也可以成为自己的尺度。", "western": "斯宾诺莎说，荣誉与恐惧都依赖他人的眼光；把评价权收回自己，才谈得上自由。", "tags": ["低落", "焦虑", "开心", "平静"]},
    {"id": "wang-wan-sunrise", "text": "海日生残夜，江春入旧年。", "source": "王湾《次北固山下》", "concept": "新旧的交替", "explanation": "新的东西往往不是等旧的完全消失才出现，而是在旧时光还没结束时，已经悄悄发芽。", "western": "赫拉克利特强调流变：新的一天不是旧日的延续，而是在旧日里就已经开始。", "tags": ["低落", "焦虑", "平静", "成长"]},
    {"id": "thoreau-deliberate", "text": "我希望活得深刻，吸取生命中的全部精华。", "source": "梭罗《瓦尔登湖》（意译）", "concept": "有意识地生活", "explanation": "深刻不意味着把每一天都过得很重。它也可以只是知道自己在做什么，并愿意为它留下注意。", "western": "梭罗与爱默生都相信，生活需要被有意识地选择；不选择，也是默认了别人替你选。", "tags": ["专注", "平静", "阅读", "成长"]},
    {"id": "mencius-mind", "text": "心之官则思，思则得之，不思则不得也。", "source": "《孟子·告子上》", "concept": "思考的主动性", "explanation": "答案很少自动出现。给问题一点安静的时间，思绪才有机会从嘈杂里浮出来。", "western": "笛卡尔以「我思」为起点；孟子更早把「思」看作心自身的能力，而非外来的恩赐。", "tags": ["专注", "焦虑", "复习考试"]},
    {"id": "liu-yuxi-new-trees", "text": "沉舟侧畔千帆过，病树前头万木春。", "source": "刘禹锡《酬乐天扬州初逢席上见赠》", "concept": "更新的可能", "explanation": "有些旧的枝叶需要落下，新的东西才长得出来。结束并不总是损失，有时是空间。", "western": "尼采的「生成」拒绝把失败当作终局；病树旁边，春天照样按自己的节律发生。", "tags": ["低落", "孤独", "烦躁", "平静"]},
    {"id": "epictetus-first-principle", "text": "先决定你想成为怎样的人，再去做你该做的事。", "source": "爱比克泰德《语录》（意译）", "concept": "身份与行动", "explanation": "当行动和想成为的人对齐时，选择会变简单。今天不必做完一生的功课，只需做一件符合方向的小事。", "western": "亚里士多德认为德性来自习惯；爱比克泰德补上一句：先定方向，习惯才不至于空转。", "tags": ["专注", "焦虑", "写论文", "复习考试"]},
    {"id": "plato-good-life", "text": "重要的不是仅仅活着，而是好好地活着。", "source": "柏拉图《克里同篇》（意译）", "concept": "生活的质量", "explanation": "“好好生活”不是每天高效，而是让行动与在意的东西保持一致，并给自己留下恢复的空间。", "western": "苏格拉底在《克里同篇》里宁可受罚也不逃走：活得好，优先于仅仅活着。", "tags": ["疲惫", "低落", "平静", "反思"]},
    {"id": "socrates-know-yourself", "text": "认识你自己。", "source": "德尔斐神庙箴言 · 苏格拉底常引", "concept": "自我认识", "explanation": "了解自己的限度、偏好和触发点，不是给自己贴标签，而是为了做出更适合自己的选择。", "western": "福柯把「认识自己」读成一种实践：不是发现一个固定的我，而是持续地照看自己。", "tags": ["平静", "焦虑", "反思", "成长"]},
    {"id": "rilke-future", "text": "未来进入我们，是为了在我们之中发生转变。", "source": "里尔克《给青年诗人的信》（意译）", "concept": "成为的过程", "explanation": "你不是等到未来某天才突然变好，而是在每一个微小的选择里，慢慢长成下一位自己。", "western": "柏格森说时间是创造性的绵延；未来不是等待发生的日程，而是正在改写你的力量。", "tags": ["舒展", "专注", "低落", "成长"]},
    {"id": "tagore-stars", "text": "如果你因错过太阳而流泪，那么你也会错过群星。", "source": "泰戈尔《飞鸟集》", "concept": "失去与看见", "explanation": "遗憾可以存在，但不必占据全部视野。抬起头时，生活里仍有别的光正在等你。", "western": "斯多葛提醒人区分可控与不可控：太阳已经落下，星星仍在你能抬头的地方。", "tags": ["低落", "孤独", "平静", "成长"]},
    {"id": "heraclitus-river", "text": "人不能两次踏进同一条河流。", "source": "赫拉克利特", "concept": "万物流变", "explanation": "昨天没做好的事，不必原样带进今天。你和你面对的问题，其实都已经变了。", "western": "赫拉克利特的流变论是西方过程思想的源头；同一性在时间中始终是个近似值。", "tags": ["失去", "变化", "焦虑", "低落"]},
    {"id": "su-shi-orange-season", "text": "一年好景君须记，最是橙黄橘绿时。", "source": "苏轼《赠刘景文》", "concept": "成熟的季节", "explanation": "不是只有春天值得庆祝。果实成熟的时节，也自有它的颜色和重量。", "western": "尼采的「 Amor fati 」：不是忍受季节，而是在橙黄橘绿里认出此刻的成熟。", "tags": ["开心", "舒展", "平静", "成长"]},
    {"id": "heraclitus-character", "text": "性格即命运。", "source": "赫拉克利特（残篇）", "concept": "习惯塑造人生", "explanation": "我们反复选择的反应方式，会慢慢成为生活的方向。改变不必从宏大的誓言开始，可以从今天的一次停顿开始。", "western": "亚里士多德说德性是习惯的产物；赫拉克利特更早把性格与命运系在同一根绳上。", "tags": ["焦虑", "烦躁", "专注", "成长"]},
    {"id": "pascal-reed", "text": "人是一根会思想的芦苇。", "source": "帕斯卡《思想录》", "concept": "脆弱与尊严", "explanation": "人很脆弱，却知道自己脆弱；会疲惫，也能反思疲惫。承认有限，并不抹掉你的尊严。", "western": "帕斯卡在《思想录》里把人的伟大放在思想：脆弱与尊严，是同一件事的两面。", "tags": ["疲惫", "低落", "焦虑", "反思"]},
    {"id": "nietzsche-why", "text": "一个人知道自己为什么而活，就可以忍受任何一种生活。", "source": "尼采《偶像的黄昏》（意译）", "concept": "意义与承受", "explanation": "意义不是每天都有宏大的答案。有时只是记得：我仍在为了什么而学习、照顾自己、继续尝试。", "western": "尼采追问的不是「怎样活」，而是「为何活」；有了理由，承受才有形状。", "tags": ["低落", "疲惫", "专注", "成长"]},
    {"id": "camus-summer", "text": "在隆冬，我终于知道，我身上有一个不可战胜的夏天。", "source": "加缪《重返蒂巴萨》（意译）", "concept": "内在生命力", "explanation": "低谷不会抹掉你曾经拥有和仍然拥有的力量。先守住一点温度，再等生活回暖。", "western": "加缪在《西西弗神话》里拒绝自杀与希望两端；不可战胜的夏天，是对荒诞的温柔反抗。", "tags": ["低落", "孤独", "疲惫", "成长"]},
    {"id": "montaigne-what-know", "text": "我知道什么？", "source": "蒙田随笔集题词", "concept": "承认不确定", "explanation": "承认自己不知道，是继续思考的起点。比起急着得到正确答案，保留一点疑问更像真正的清醒。", "western": "蒙田的怀疑不是虚无，而是苏格拉底式的自知无知：先承认边界，才可能不狂妄。", "tags": ["焦虑", "烦躁", "反思", "成长"]},
    {"id": "socrates-examined", "text": "未经审视的人生不值得过。", "source": "苏格拉底", "concept": "自我审视", "explanation": "停下来问一句“我真正想要什么”，不是浪费时间，而是在校正方向。", "western": "苏格拉底把哲学生活当作每日的自我盘问；未经审视，等于把人生交给了默认设置。", "tags": ["焦虑", "平静", "反思"]},
    {"id": "laozi-first-step", "text": "千里之行，始于足下。", "source": "《道德经》", "concept": "行动的起点", "explanation": "焦虑常常来自把整段路一次看完。今天只需要找到第一步，不必同时抵达终点。", "western": "亚里士多德认为行动先于德性；千里之行，是把「成为」拆成今天这一步。", "tags": ["焦虑", "疲惫", "写论文", "复习考试"]},
    {"id": "xunzi-steps", "text": "不积跬步，无以至千里。", "source": "《荀子·劝学》", "concept": "复利式积累", "explanation": "今天只推进一点点，看起来微不足道，却让你没有停在原地。连续性比强度更可靠。", "western": "休谟说习惯是人生最大的向导；跬步之所以有效，是因为它把意志变成了惯性。", "tags": ["复习考试", "写论文", "专注", "低落"]},
    {"id": "rilke-questions", "text": "去爱问题本身，像爱一间上了锁的房间。", "source": "里尔克《给青年诗人的信》（意译）", "concept": "与不确定共处", "explanation": "不是每个问题都需要今天解决。和问题一起生活一段时间，答案有时会在经历中长出形状。", "western": "克尔凯郭尔主张在不确定中决断；里尔克更缓一些：先与问题同住，别急着要答案。", "tags": ["焦虑", "疲惫", "反思", "成长"]},
    {"id": "laozi-small", "text": "天下难事，必作于易；天下大事，必作于细。", "source": "《道德经》", "concept": "微小行动的杠杆", "explanation": "宏大的目标容易让人僵住。把它缩成“先写三行”或“先看一页”，行动就重新开始了。", "western": "维特根斯坦说解决之道常在于把大问题拆成可处理的小问题；细节是入口，不是琐碎。", "tags": ["写论文", "复习考试", "专注", "拖延"]},
    {"id": "su-shi-no-weather", "text": "回首向来萧瑟处，归去，也无风雨也无晴。", "source": "苏轼《定风波·莫听穿林打叶声》", "concept": "情绪的退潮", "explanation": "强烈的感受会过去，并非变得无意义。回头看时，你会知道自己曾走过，也仍然在走。", "western": "斯多葛的「无动于衷」并非麻木，而是风雨过后不再额外给自己加戏。", "tags": ["平静", "低落", "焦虑", "成长"]},
    {"id": "analects-harmony", "text": "君子和而不同，小人同而不和。", "source": "《论语·子路》", "concept": "差异中的共存", "explanation": "关系不需要把彼此磨成同一种形状。保留不同，同时寻找可以一起完成的事。", "western": "罗尔斯的「理性多元」与「和而不同」相通：分歧不必被消除，只需被妥善安放。", "tags": ["烦躁", "孤独", "社交", "人际"]},
    {"id": "su-shi-mountain", "text": "不识庐山真面目，只缘身在此山中。", "source": "苏轼《题西林壁》", "concept": "反思的距离", "explanation": "身处问题之中很难看到全貌。找朋友聊一聊，或隔一天再看，都是给视角移动的机会。", "western": "胡塞尔的现象学要求「回到事情本身」；走出山里，是为了看见自己一直带着的视角。", "tags": ["焦虑", "烦躁", "低落", "反思"]},
    {"id": "gong-zizhen-fallen-flower", "text": "落红不是无情物，化作春泥更护花。", "source": "龚自珍《己亥杂诗·其五》", "concept": "结束中的转化", "explanation": "一次失败、一段关系的结束，不会只留下空缺。经验会以另一种方式参与你的下一段生活。", "western": "黑格尔的「扬弃」：结束不是消失，而是被保存进下一个阶段。", "tags": ["孤独", "低落", "平静", "失去"]},
    {"id": "bai-juyi-warm-wine", "text": "晚来天欲雪，能饮一杯无？", "source": "白居易《问刘十九》", "concept": "小小的邀请", "explanation": "孤独时不必立刻倾诉全部。发一句简单的邀请，和一个人共享一顿饭，也可能是连接的开始。", "western": "亚里士多德把友谊看作德性生活的必需品；一杯酒，是把关系从日程里捞出来。", "tags": ["孤独", "低落", "人际", "社交"]},
    {"id": "laozi-water", "text": "上善若水，水善利万物而不争。", "source": "《道德经》", "concept": "柔性的力量", "explanation": "温柔不是没有边界，而是不必用对抗证明自己。绕开一块石头，也仍然可以向前。", "western": "斯多葛的「顺应自然」与水的智慧相邻：不与世界硬碰，才留得住自己的力量。", "tags": ["平静", "烦躁", "人际", "舒展"]},
    {"id": "analects-learn-think", "text": "学而不思则罔，思而不学则殆。", "source": "《论语·为政》", "concept": "输入与消化", "explanation": "一直吸收会迷路，一直空想会耗尽。读一点、想一点、做一点，知识才真正成为自己的。", "western": "康德区分感性与知性；只学不思是材料堆积，只思不学是空中楼阁。", "tags": ["专注", "焦虑", "复习考试", "阅读"]},
    {"id": "su-shi-young-again", "text": "谁道人生无再少？门前流水尚能西！", "source": "苏轼《浣溪沙·游蕲水清泉寺》", "concept": "重新开始", "explanation": "重新开始并不意味着回到过去。你可以带着已经经历的东西，从一个新的位置再出发。", "western": "尼采的「永恒轮回」逼问：若人生再来一次，你是否愿意？苏轼答得更轻：水还能向西。", "tags": ["开心", "舒展", "低落", "成长"]},
    {"id": "lu-you-practice", "text": "纸上得来终觉浅，绝知此事要躬行。", "source": "陆游《冬夜读书示子聿》", "concept": "实践认识论", "explanation": "想清楚很重要，但真正的确定感常在小实验之后。先运行一次，再根据结果调整。", "western": "杜威的实用主义与「躬行」一致：真理要在做里被检验，而不只是在说里被相信。", "tags": ["写论文", "实验", "专注", "代码"]},
    {"id": "marcus-obstacle", "text": "阻碍行动的东西，会推动行动；挡住道路的东西，也可以成为道路。", "source": "马可·奥勒留《沉思录》（意译）", "concept": "障碍转化", "explanation": "困难不自动变成礼物，但它迫使我们寻找新的路径。先问：眼前这个阻碍，能教我调整哪一步？", "western": "马可·奥勒留把障碍纳入德性的练习；斯多葛的训练，是把阻力转成材料。", "tags": ["焦虑", "烦躁", "低落", "写论文"]},
    {"id": "su-shi-home", "text": "此心安处是吾乡。", "source": "苏轼《定风波·南海归赠王定国侍人寓娘》", "concept": "内在安定", "explanation": "安全感不全在环境里，也来自你对自己的态度。今天也试着做自己的同盟。", "western": "海德格尔说「栖居」不是地址，而是与世界相处的方式；心安处，才是可居之处。", "tags": ["焦虑", "低落", "平静"]},
    {"id": "su-shi-light-joy", "text": "人间有味是清欢。", "source": "苏轼《浣溪沙·细雨斜风作晓寒》", "concept": "日常的清欢", "explanation": "不是每一天都要发生大事。一碗热饭、一段散步、一页读进去的书，都可以是生活的证据。", "western": "伊壁鸠鲁的快乐是清淡的：不追刺激，只求不被多余的欲望打扰。", "tags": ["平静", "舒展", "开心", "运动"]},
    {"id": "tao-chrysanthemum", "text": "采菊东篱下，悠然见南山。", "source": "陶渊明《饮酒·其五》", "concept": "日常里的自足", "explanation": "幸福不一定在远处。有时它只是手上的一件小事，和抬头时恰好看见的一片风景。", "western": "海德格尔引用荷尔德林谈「栖居」；采菊与见山，是同一件事的两面——在场。", "tags": ["平静", "舒展", "开心", "放空"]},
    {"id": "du-fu-summit", "text": "会当凌绝顶，一览众山小。", "source": "杜甫《望岳》", "concept": "视野与耐心", "explanation": "登高之前，眼前只有一级一级的台阶。别急着否定过程，它正在把你带到更开阔的地方。", "western": "尼采的「远视」需要攀登；视野不是天赋，而是走到更高处换来的。", "tags": ["专注", "复习考试", "运动", "开心"]},
    {"id": "tao-yuanming-morning", "text": "盛年不重来，一日难再晨。", "source": "陶渊明《杂诗》", "concept": "时间的不可逆", "explanation": "珍惜当下不等于责怪我做得不够。它只是提醒：此刻值得被好好使用，也值得被好好休息。", "western": "塞涅卡说我们并非时间太少，而是浪费太多；「难再晨」是对注意力的提醒。", "tags": ["专注", "晨间", "复习考试"]},
    {"id": "epictetus-control", "text": "困扰人的不是事情本身，而是人对事情的看法。", "source": "爱比克泰德《手册》", "concept": "控制二分法", "explanation": "把问题分成两栏：能做的与不能做的。只在前一栏里消耗力气，心会轻一些。", "western": "爱比克泰德的控制二分法是斯多葛的入口；把力气放在自己能做的那一栏。", "tags": ["焦虑", "写论文", "复习考试"]},
    {"id": "zhuangzi-fish", "text": "子非鱼，安知鱼之乐？", "source": "《庄子·秋水》", "concept": "视角的边界", "explanation": "你看到的自己，不一定是全部的你。别用一个下午的状态，为整段人生下结论。", "western": "维特根斯坦说「我的语言的界限即世界的界限」；你不是鱼，正因你有一套自己的语法。", "tags": ["低落", "焦虑", "反思"]},
    {"id": "xin-qiji-green-hills", "text": "青山遮不住，毕竟东流去。", "source": "辛弃疾《菩萨蛮·书江西造口壁》", "concept": "生命的前行", "explanation": "情绪会像山一样挡住视线，但你的生活不会彻底停在这里。时间仍然在把你带向下一步。", "western": "斯宾诺莎的必然性：青山遮不住东流，不是因为乐观，而是因为规律不因情绪改道。", "tags": ["焦虑", "低落", "疲惫", "成长"]},
    {"id": "analects-winter-pine", "text": "岁寒，然后知松柏之后凋也。", "source": "《论语·子罕》", "concept": "困境中的品性", "explanation": "艰难不会自动让人成长，但它会让我们看见自己真正珍惜什么，以及谁愿意一起留下来。", "western": "亚里士多德认为德性在困境中才显形；岁寒，是一场不设预告的考试。", "tags": ["低落", "焦虑", "孤独", "疲惫"]},
    {"id": "zhuangzi-summer-insect", "text": "夏虫不可以语于冰者，笃于时也。", "source": "《庄子·秋水》", "concept": "经验的边界", "explanation": "每个人看见的世界都受自己的经历限制。遇到分歧时，先承认彼此站在不同的季节里。", "western": "康德区分经验的条件与经验的边界；夏虫的局限，是它从未拥有过另一种经验。", "tags": ["烦躁", "人际", "反思", "平静"]},
    {"id": "wang-wei-clouds", "text": "行到水穷处，坐看云起时。", "source": "王维《终南别业》", "concept": "偶然与松弛", "explanation": "走不动的时候，坐着并不是失败。允许一段留白，新的可能才有位置出现。", "western": "海德格尔的「泰然任之」：不强求结果，让事物按其本己的方式出现。", "tags": ["低落", "平静", "放空", "休息"]},
    {"id": "aristotle-happiness", "text": "幸福取决于我们自己。", "source": "亚里士多德《尼各马可伦理学》（意译）", "concept": "德性与实践", "explanation": "幸福不是等来的运气，也不是永远开心，而是在具体生活中练习选择、关系和自我照顾。", "western": "亚里士多德把幸福看作「合乎德性的实现活动」；它不是状态，而是持续做的事。", "tags": ["开心", "舒展", "平静", "成长"]},
    {"id": "wang-yangming-unity", "text": "知是行之始，行是知之成。", "source": "王阳明《传习录》", "concept": "知行合一", "explanation": "想法只有开始行动，才会长出真实的形状；行动也需要理解，才能不变成盲目忙碌。", "western": "杜威反对知与行的割裂；王阳明更彻底：知而不行，只是未知。", "tags": ["专注", "写论文", "复习考试", "焦虑"]},
    {"id": "kierkegaard-backward", "text": "生活只能倒着被理解，但必须正着去生活。", "source": "克尔凯郭尔《日记》（意译）", "concept": "回望与前行", "explanation": "意义常在事后才显现。不要因为当下还看不懂整段故事，就否认这一页的价值。", "western": "克尔凯郭尔说「生活只能倒着理解，却必须正着过」；这句话本身就是他的方法论。", "tags": ["低落", "焦虑", "平静", "成长"]},
    {"id": "wang-bo-ambition", "text": "穷且益坚，不坠青云之志。", "source": "王勃《滕王阁序》", "concept": "逆境中的志向", "explanation": "处境可以暂时很小，愿望不必跟着缩小。先把那份志气收好，再从能做的一步开始。", "western": "尼采的「权力意志」不是压倒他人，而是在逆境中仍能自我提升。", "tags": ["低落", "焦虑", "疲惫", "写论文"]},
    {"id": "lu-you-path", "text": "山重水复疑无路，柳暗花明又一村。", "source": "陆游《游山西村》", "concept": "视角转换", "explanation": "有些路不是断了，只是还没走到转弯处。先往前挪一小步，风景会自己更新。", "western": "库恩的范式转换：不是路消失了，而是你换了一个看路的框架。", "tags": ["焦虑", "低落", "写论文", "复习考试"]},
    {"id": "laozi-contentment", "text": "知足不辱，知止不殆，可以长久。", "source": "《道德经》第四十四章", "concept": "知足与边界", "explanation": "知道什么时候已经足够，也是一种能力。边界不是停下成长，而是让成长不至于反噬自己。", "western": "伊壁鸠鲁把知足视为最大的财富；边界清楚，欲望才不至于无限膨胀。", "tags": ["疲惫", "平静", "焦虑", "休息"]},
    {"id": "heidegger-poetic", "text": "人，诗意地栖居。", "source": "海德格尔《……人诗意地栖居……》", "concept": "栖居的态度", "explanation": "诗意不必远在山水之间。把一杯水喝得认真，把窗边的光看进眼里，也是在生活，而不只是经过生活。", "western": "海德格尔借荷尔德林说，人应当「诗意地栖居」；诗意不是装饰，而是与世界相处的尺度。", "tags": ["开心", "舒展", "平静", "放空"]},
    {"id": "analects-self-reliance", "text": "君子求诸己，小人求诸人。", "source": "《论语·卫灵公》", "concept": "回到自身", "explanation": "不是所有问题都该自己扛，而是先看看哪些部分在你能负责的范围里，哪些应该交还给环境和他人。", "western": "斯多葛把注意力收回自身；求诸己，是唯一不会落空的方向。", "tags": ["焦虑", "烦躁", "人际", "反思"]},
    {"id": "su-shi-rain", "text": "莫听穿林打叶声，何妨吟啸且徐行。", "source": "苏轼《定风波》", "concept": "斯多葛式从容", "explanation": "雨声无法关掉，脚步却可以由自己决定。把注意力从“为什么下雨”移回“怎样走”。", "western": "爱比克泰德说困扰人的是判断而非事情；雨声照旧，脚步可以自己定。", "tags": ["焦虑", "低落", "雨", "平静"]},
    {"id": "wang-bo-friend", "text": "海内存知己，天涯若比邻。", "source": "王勃《送杜少府之任蜀州》", "concept": "关系的距离", "explanation": "不必每次难过都独自消化。给信任的人发一句“今天有点累”，本身就是一种照顾。", "western": "亚里士多德把友谊分为三类；真正的朋友，是即便远隔也能共享同一种善。", "tags": ["低落", "孤独", "社交"]},
    {"id": "wang-anshi-high-view", "text": "不畏浮云遮望眼，自缘身在最高层。", "source": "王安石《登飞来峰》", "concept": "视角的高度", "explanation": "情绪像云，会暂时挡住视野。先不急着做永久判断，等一阵风过去，再看全局。", "western": "培根说知识即力量；站得高不是傲慢，而是减少被浮云误导的概率。", "tags": ["焦虑", "烦躁", "低落", "平静"]},
    {"id": "montaigne-life", "text": "世上最伟大的事，是懂得如何属于自己。", "source": "蒙田《随笔集》", "concept": "成为自己", "explanation": "优秀不是把自己改造成标准答案。保留一点自己的节奏和偏好，也是一种清醒。", "western": "蒙田的随笔就是「属于自己」的练习；不表演，不辩解，只如实地写。", "tags": ["舒展", "平静", "低落"]},
    {"id": "su-shi-traveler", "text": "人生如逆旅，我亦是行人。", "source": "苏轼《临江仙·送钱穆父》", "concept": "旅人的视角", "explanation": "把暂时的处境看成一段旅程，而不是永久身份。你正在经过它，而不是成为它。", "western": "海德格尔的「在世存在」本就是一种旅途；旅人视角，让得失都轻一点。", "tags": ["孤独", "低落", "疲惫", "平静"]},
    {"id": "bai-juyi-temple-flower", "text": "人间四月芳菲尽，山寺桃花始盛开。", "source": "白居易《大林寺桃花》", "concept": "不同的节奏", "explanation": "别人已经开花时，你也许还在等待自己的季节。不同步不等于落后。", "western": "莱布尼茨的「前定和谐」各有节律；山寺的桃花，只是还没到它的四月。", "tags": ["焦虑", "低落", "舒展", "成长"]},
    {"id": "zhang-jiuling-orchid", "text": "草木有本心，何求美人折。", "source": "张九龄《感遇十二首·其一》", "concept": "不被观看的价值", "explanation": "你的价值并不只在被喜欢、被表扬时才成立。没人看见的时候，你仍然可以完整地存在。", "western": "康德的无利害关怀：美不依赖被观看，草木的价值也不靠折取来证明。", "tags": ["孤独", "低落", "平静", "舒展"]},
    {"id": "zhu-xi-spring-water", "text": "问渠那得清如许？为有源头活水来。", "source": "朱熹《观书有感·其一》", "concept": "持续输入", "explanation": "心变得迟钝时，不一定是你退步了。给自己换一点新鲜输入，让死水重新流动。", "western": "杜威说经验需要不断更新；源头活水，是给心智留一条输入的通道。", "tags": ["疲惫", "专注", "阅读", "写论文"]},
    {"id": "liu-yuxi-autumn", "text": "晴空一鹤排云上，便引诗情到碧霄。", "source": "刘禹锡《秋词》", "concept": "心境塑造视野", "explanation": "心情好的时候，世界会显得更宽。把这份开阔记下来，留给以后阴天的自己。", "western": "尼采说视角决定世界的样子；晴空一鹤，是心情先把天推高了。", "tags": ["舒展", "晴", "开心"]},
    {"id": "du-fu-rain", "text": "随风潜入夜，润物细无声。", "source": "杜甫《春夜喜雨》", "concept": "看不见的影响", "explanation": "微小的照顾、阅读和坚持，常常没有即时反馈。它们正在安静地改变你。", "western": "培根谈「润物无声」式的影响；真正改变人的，往往是不被察觉的日常。", "tags": ["平静", "舒展", "孤独", "阅读"]},
    {"id": "kierkegaard-anxiety", "text": "焦虑是自由的眩晕。", "source": "克尔凯郭尔《焦虑的概念》（意译）", "concept": "自由与可能", "explanation": "焦虑常常出现在选择太多、未来尚未确定的时候。它不是能力不足的证据，而是面对可能性时身体的回声。", "western": "克尔凯郭尔把焦虑看作「自由的眩晕」；它提醒你，可能性正在你面前打开。", "tags": ["焦虑", "烦躁", "反思", "成长"]},
    {"id": "pascal-heart", "text": "心有其理，理性对此一无所知。", "source": "帕斯卡《思想录》（意译）", "concept": "感性与理性", "explanation": "有些感受无法马上讲出道理。先允许它存在，再慢慢为它找到语言，往往比逼自己立刻想通更有用。", "western": "帕斯卡区分「几何精神」与「细腻精神」；有些真，只能被感受而不能被证明。", "tags": ["孤独", "低落", "平静", "人际"]},
    {"id": "great-learning-still", "text": "知止而后有定，定而后能静，静而后能安。", "source": "《礼记·大学》", "concept": "定与静", "explanation": "先决定此刻不做什么，心才会慢慢有边界。一次只守住一件小事，也算安定。", "western": "斯多葛的「专注当下」与「知止」相通：先划定边界，安静才有落点。", "tags": ["专注", "焦虑", "写论文", "复习考试"]},
    {"id": "li-bai-wind", "text": "长风破浪会有时，直挂云帆济沧海。", "source": "李白《行路难》", "concept": "时间中的希望", "explanation": "希望不是假装困难不存在，而是承认此刻很难，同时不把此刻当成永远。", "western": "斯宾诺莎的必然与自由并不矛盾；承认风浪，才谈得上挂帆。", "tags": ["低落", "焦虑", "舒展"]},
    {"id": "laozi-fortune", "text": "祸兮福之所倚，福兮祸之所伏。", "source": "《道德经》", "concept": "变化的双面性", "explanation": "此刻的失手，不必然写成结局；此刻的顺利，也不必成为必须永远保持的证明。", "western": "黑格尔的辩证法：祸福互为条件，否定性本身推动着下一步。", "tags": ["焦虑", "低落", "平静"]},
    {"id": "zhongyong-balance", "text": "一张一弛，文武之道也。", "source": "《礼记·杂记下》", "concept": "节律与恢复", "explanation": "休息不是效率的敌人，而是注意力的一部分。会停下来，才能走得更久。", "western": "亚里士多德的中道不是折中，而是恰如其分；张弛之间，是分寸感。", "tags": ["运动", "休息", "焦虑", "舒展"]},
    {"id": "zheng-xie-bamboo", "text": "千磨万击还坚劲，任尔东西南北风。", "source": "郑燮《竹石》", "concept": "韧性", "explanation": "韧不是不会折断，而是被压力推弯之后，仍知道自己的根在哪里，并慢慢站回来。", "western": "斯多葛的「韧性」来自判断的稳定；风从四面来，根却不必移动。", "tags": ["疲惫", "焦虑", "烦躁", "专注"]},
    {"id": "spinoza-understand", "text": "不哭，不笑，不诅咒，只去理解。", "source": "斯宾诺莎《政治论》（意译）", "concept": "理解先于评判", "explanation": "面对情绪时，先描述发生了什么，而不是立刻给自己下结论。理解不是纵容，而是找到改变的条件。", "western": "斯宾诺莎的这句本身就是方法论：理解先于评判，情绪才有被安放的位置。", "tags": ["烦躁", "低落", "平静", "反思"]},
    {"id": "yang-wanli-lotus", "text": "小荷才露尖尖角，早有蜻蜓立上头。", "source": "杨万里《小池》", "concept": "微小新生的价值", "explanation": "刚冒出来的一点点兴趣、进步或勇气，也值得被看见。不是所有成长一开始都很盛大。", "western": "杜威看重「萌芽状态」的经验；尖尖角之所以重要，是因为它指向尚未展开的可能。", "tags": ["开心", "舒展", "专注", "成长"]},
    {"id": "liu-yuxi-sunset", "text": "莫道桑榆晚，为霞尚满天。", "source": "刘禹锡《酬乐天咏老见示》", "concept": "晚一点也没关系", "explanation": "起步晚、进度慢、重新来过，都不等于错过。你仍然可以在自己的时刻里发光。", "western": "塞涅卡说生命的价值不在长度；桑榆虽晚，霞光仍可满天。", "tags": ["疲惫", "低落", "焦虑", "舒展"]},
    {"id": "seneca-life-length", "text": "生命并非短暂，而是我们浪费了太多。", "source": "塞涅卡《论生命之短暂》（意译）", "concept": "时间的所有权", "explanation": "时间不只属于任务，也属于睡眠、吃饭、发呆和关系。把恢复算进生活，不是浪费。", "western": "塞涅卡在《论生命之短暂》里说，我们并非时间太少，而是把时间花在了不属于自己的事上。", "tags": ["疲惫", "焦虑", "专注", "休息"]},
    {"id": "w1-001", "text": "万物皆流，无物常驻。", "source": "赫拉克利特《残篇》", "concept": "万物流变", "explanation": "你以为停滞不动的那件事，其实一直在变。情绪、关系和处境都像河水一样流动，不必用今天一时的感受，替未来写下最后的定论。先别急着定稿。", "western": "赫拉克利特以河流说明存在的变化，巴门尼德却坚持存在不动；这一对立奠定了西方哲学中“变”与“恒”的争论，也与《易传》“生生之谓易”的生成观遥相呼应。", "tags": ["变化", "焦虑", "反思", "平静"]},
    {"id": "w1-002", "text": "太阳每天都是新的。", "source": "赫拉克利特《残篇》", "concept": "日新之德", "explanation": "新的一天并不是昨天的简单延长。哪怕同一件难事还摆在面前，你也可以换一种眼光重新看它，给自己一次不算旧账的重新开始。今天先看一步。", "western": "赫拉克利特用日新的太阳说明时间的循环与更新；《大学》所言“苟日新，日日新”把更新落在每日的德性工夫上，二者都把“新”当作每天要做的功课。", "tags": ["晨间", "期待", "变化", "舒展"]},
    {"id": "w1-003", "text": "战争是万物之父，也是万物之王。", "source": "赫拉克利特《残篇》", "concept": "冲突创生", "explanation": "冲突不只带来破坏，也逼出秩序和创造。面对矛盾时，先别急着消灭它，看看它能否推动你找到新的平衡，而不是停在原地。冲突也能是一条路。", "western": "赫拉克利特把斗争视为生成的根源，这与老子“反者道之动”及中国思想中“相反相成”的洞见暗合；但赫拉克利特更强调冲突本身的创生力量，而非以柔化之。", "tags": ["烦躁", "反思", "变化"]},
    {"id": "w1-004", "text": "自然喜欢隐藏自己。", "source": "赫拉克利特《残篇》", "concept": "隐显之间", "explanation": "真相常常不摆在表面。愿意多看一眼、多问一句，才可能看见事物藏起来的那一面；对别人如此，对自己也一样，耐心是看见的条件。耐心会给你细节。", "western": "海德格尔曾以“涌现”与“遮蔽”解释这句残篇，与老子“道隐无名”相近；西方从此留下一道解释学难题：自然是否只能以遮蔽的方式被看见。", "tags": ["迷茫", "反思", "阅读"]},
    {"id": "w1-005", "text": "生与死、醒与睡、少与老，是同一回事。", "source": "赫拉克利特《残篇》", "concept": "生死相转", "explanation": "很多看似对立的状态，其实在同一条路上轮换。累到极处会想睡，睡够了会想动；别把此刻当成永久，也别把反面当成敌人。轮换不是重复。", "western": "赫拉克利特以对立面的相互转化说明宇宙的节律，与庄子“方生方死，方死方生”相近；但赫拉克利特保留统一的逻各斯，庄子则以“道通为一”消解分别。", "tags": ["变化", "疲惫", "平静"]},
    {"id": "w1-006", "text": "不同的音调造成最美的和谐。", "source": "赫拉克利特《残篇》", "concept": "对立统一", "explanation": "关系里的差异不一定非要消除。不同的节奏、意见和脾气，调好了反而能奏出比整齐更丰富的声音；先学会听见，再谈改变。先听完，再回应。", "western": "赫拉克利特主张对立面的张力构成和谐，类似《国语》“和实生物，同则不继”；西方后世把这种张力理解为辩证法，而中国更常把它落在礼乐之和上。", "tags": ["社交", "烦躁", "反思"]},
    {"id": "w1-007", "text": "存在者存在，不存在者不存在。", "source": "巴门尼德《残篇》", "concept": "存在之思", "explanation": "先把话说清楚：一件事若真实存在，就不能同时又说它不存在。训练自己区分事实与想象，能少掉许多无谓的恐慌和争论。事实比想象安静。", "western": "巴门尼德以此开辟西方本体论，把“存在”确定为思想的对象；老子却以“无”为天地之始，两条路分别通向存在论与生成论，后来在黑格尔那里再次交汇。", "tags": ["专注", "反思", "平静"]},
    {"id": "w1-008", "text": "思想与存在是同一的。", "source": "巴门尼德《残篇》", "concept": "思有同一", "explanation": "你能想到的东西，至少以某种方式进入了你的世界。反过来，长期想什么，也会慢慢塑造你看见什么、成为什么；念头并非毫无重量。念头会变成方向。", "western": "巴门尼德把思想与存在等同，奠定了西方以理性把握世界的传统；王阳明“心外无物”虽语境不同，也把心与物放在同一关系中讨论，但一个走向逻辑，一个走向良知。", "tags": ["专注", "反思", "期待"]},
    {"id": "w1-009", "text": "存在者不生不灭，完整而单一。", "source": "巴门尼德《残篇》", "concept": "存在之恒", "explanation": "有些东西不能被切成碎片来理解。面对一段经历，先看它的整体，而不是只盯着最刺眼的那一块；整体往往比碎片更诚实。先看整体，再看缺口。", "western": "巴门尼德用“一”对抗生成变化，成为西方形而上学中永恒秩序的雏形；这与佛教“不生不灭”、庄子“道通为一”可作跨传统的对照，但旨趣并不相同。", "tags": ["平静", "迷茫", "反思"]},
    {"id": "w1-010", "text": "原子与虚空，是万物的本原。", "source": "德谟克利特《残篇》", "concept": "原子与空", "explanation": "复杂的世界可以拆成很小的单元来看。把一团乱麻拆成几个具体问题，你才找得到下手的地方；拆得够细，恐惧也会变小。拆小以后，就不那么吓人。", "western": "德谟克利特以原子与虚空解释万物，是西方唯物论的开端；它与张载“气”的聚散、王充的自然之说都试图用同一原理说明世界，但一个诉诸粒子，一个诉诸气。", "tags": ["专注", "写论文", "实验"]},
    {"id": "w1-011", "text": "节制使快乐增加，使享受更强烈。", "source": "德谟克利特《残篇》", "concept": "节制的快乐", "explanation": "不是越多越快乐。给欲望留一点空隙，下一次的满足反而更清楚、更有味道；这也是对自己精力的温柔管理，而不是苦行。留白也是享受的一部分。", "western": "德谟克利特把节制视为快乐的技艺，接近亚里士多德的中道；《礼记》“发而皆中节”也讲节度，但中国更强调礼的调节，希腊更强调个人理性的尺度。", "tags": ["拖延", "反思", "平静"]},
    {"id": "w1-012", "text": "当我们说快乐是目的，并不是指放纵。", "source": "伊壁鸠鲁《致美诺寇的信》", "concept": "快乐非放纵", "explanation": "快乐不是把每个欲望都喂饱。真正让人安稳的，常常是身体不痛、心里不慌；先分清“想要”和“需要”，快乐会变得干净，也更容易留住，不必一次做到完美。", "western": "伊壁鸠鲁区分了动态快乐与静态快乐，后者是免于痛苦的状态，与庄子“至乐无乐”相近；但伊壁鸠鲁仍以感觉为尺度，庄子则要人超越分别。", "tags": ["焦虑", "释然", "平静"]},
    {"id": "w1-013", "text": "我知道我一无所知。", "source": "苏格拉底（柏拉图《申辩篇》转述）", "concept": "无知之知", "explanation": "承认不知道，不是否定自己，而是把心腾空。只有先放下“我早就懂了”，新的东西才进得来；无知之知，其实是一种开放的姿态。承认不懂，才学得进去。", "western": "苏格拉底的无知之知是一种反讽式智慧，经柏拉图转述而流传；孔子说“知之为知之，不知为不知”，同样把诚实当作求知的起点，但苏格拉底用它追问定义。", "tags": ["复习考试", "阅读", "反思"]},
    {"id": "w1-014", "text": "美德就是知识本身。", "source": "苏格拉底（柏拉图《普罗泰戈拉篇》转述）", "concept": "德性即知", "explanation": "很多做不好的事，不是意志不够，而是还没看清。把后果看明白，选择往往会变得比想象中容易；看清不是万能，但至少让你不再盲选，也不再反复责怪自己。", "western": "苏格拉底认为无人自愿作恶，恶源于无知，这一理性主义伦理观经柏拉图转述；孟子以“四端”言善端，更强调本心的扩充而非知识，二者对恶的解释因此分途。", "tags": ["反思", "专注", "迷茫"]},
    {"id": "w1-015", "text": "我是神赐给这座城的一只牛虻。", "source": "苏格拉底（柏拉图《申辩篇》转述）", "concept": "牛虻之责", "explanation": "有时你的责任就是不断提醒、追问，让身边的人保持清醒。被嫌烦不等于做错，但也要学会温柔地叮，别把尖锐当成目的。提醒也可以有温度。", "western": "苏格拉底以此自喻哲学的公共职责，最后因此获罪；这与孟子“士尚志”、范仲淹“先忧后乐”的承担意识相通，都是把自我放进城邦或天下之中。", "tags": ["社交", "焦虑", "反思"]},
    {"id": "w1-016", "text": "没有人是自愿作恶的。", "source": "苏格拉底（柏拉图《普罗泰戈拉篇》转述）", "concept": "恶非自愿", "explanation": "人做坏事，常因误以为那样能带来好处。与其急着审判，不如先弄清他到底在追求什么、看错了什么；理解不等于纵容。先理解，再决定要不要原谅。", "western": "苏格拉底把恶归因于认知错误，因而相信教育可以矫正人；荀子却主张性恶、须以礼义化之。两者都重视教化，但对人性起点的判断相反，教育的方向也不同。", "tags": ["烦躁", "反思", "社交"]},
    {"id": "w1-017", "text": "正义就是每个人做自己分内的事。", "source": "柏拉图《理想国》", "concept": "各司其职", "explanation": "一个团队真正乱起来，往往不是没人努力，而是有人越位、有人缺位。守好自己的那一格，也是一种正义；但先弄清那一格到底是什么。边界清楚，协作才不累。", "western": "柏拉图把正义理解为灵魂与城邦各部分的秩序，类似《论语》“君君臣臣”的名分秩序；但柏拉图更强调理性统摄欲望，孔子更重礼与仁的相互成就。", "tags": ["专注", "社交", "平静"]},
    {"id": "w1-018", "text": "除非哲学家成为王，城邦才有安宁。", "source": "柏拉图《理想国》", "concept": "哲人治国", "explanation": "治理需要的不只是手腕，还有对“什么是好生活”的清醒判断。放到小处也一样：做决定前先想清楚价值排序，再谈具体方法。价值排序先于方法。", "western": "柏拉图的哲人王设想把知识置于权力之上，与孔子“为政以德”相近；但希腊诉诸理性观照，中国更重德性示范与礼乐教化，对“谁来统治”的答案并不相同。", "tags": ["迷茫", "反思", "专注"]},
    {"id": "w1-019", "text": "教育不是把知识灌入灵魂，而是把灵魂转向光明。", "source": "柏拉图《理想国》", "concept": "灵魂转向", "explanation": "学习不是往脑子里塞更多东西，而是换一个看的方向。方向对了，原本看不见的联系会自己浮出来；先转身，再谈努力。方向比速度更要紧。", "western": "柏拉图的“灵魂转向”把教育理解为存在方式的改变，接近《大学》“明明德”；西方强调理性之光的照耀，中国更强调德性的自我显明，一个诉诸超越之光，一个诉诸本心之明。", "tags": ["复习考试", "阅读", "专注"]},
    {"id": "w1-020", "text": "哲学就是练习死亡。", "source": "柏拉图《斐多》", "concept": "练习死亡", "explanation": "把死亡放进视野，不是消极，而是帮你删掉不重要的东西。知道生命有限，眼前的取舍会诚实很多，也更容易原谅自己的慢。有限，反而让选择清楚。", "western": "柏拉图认为哲学让灵魂脱离身体感官，提前练习死亡；庄子妻死鼓盆而歌则以齐生死化解哀伤。一个向超越处走，一个在自然中安顿，终点都不在葬礼。", "tags": ["疲惫", "休息", "反思"]},
    {"id": "w1-021", "text": "死亡不过是灵魂从身体中解脱。", "source": "柏拉图《斐多》", "concept": "灵魂解脱", "explanation": "对失去的恐惧，常来自把“我”只等同于这副身体和眼前生活。若相信还有更宽的生命，告别会多一些从容，少一些抓紧。告别也可以是一种归还。", "western": "柏拉图的身体—灵魂二元论深刻塑造了西方宗教与伦理，与佛教“四大离散”、庄子“气之聚散”形成对照：柏拉图重灵魂不朽，佛教与庄子则重流转或回归自然。", "tags": ["失去", "平静", "夜晚"]},
    {"id": "w1-022", "text": "爱是对美的渴望，也是对不朽的欲求。", "source": "柏拉图《会饮》", "concept": "爱欲之美", "explanation": "喜欢一个人，常常是被对方身上某种光吸引。看清你渴望的究竟是什么，才不会把全部重量都压在一个人身上；爱也可以指向创造。爱不是把对方当成答案。", "western": "柏拉图把爱欲理解为向美与善上升的动力，从具体身体到美本身；这与孔子“好德如好色”的告诫不同，希腊更愿意为爱欲保留一条通往超越的路。", "tags": ["期待", "孤独", "反思"]},
    {"id": "w1-023", "text": "爱是对完整性的渴望。", "source": "柏拉图《会饮》", "concept": "完整之爱", "explanation": "人会觉得孤独，是因为总想找回缺失的那一半。但完整不必只靠另一个人给，也可以由自己慢慢长出来；先学会成为自己的同伴，再谈相遇。", "western": "阿里斯托芬的神话把爱解释为对原初整体的追慕，与《诗经》“执子之手”的相伴不同，它把爱放在本体论的缺口上：人因分裂而爱，因爱而暂得完整。", "tags": ["孤独", "期待", "释然"]},
    {"id": "w1-024", "text": "看见美本身的人，才能生出真正的德性。", "source": "柏拉图《会饮》", "concept": "美与德性", "explanation": "真正的改变不是模仿别人做好事，而是先看见值得追求的美。心里有了更高的尺度，行动才不容易走样；美会替你把方向校准。先看见，再成为。", "western": "柏拉图的美的阶梯把审美、认识与德性连成一条上升之路，类似孔子“兴于诗，立于礼，成于乐”；但希腊以美本身为终点，中国以人格的完成收束。", "tags": ["专注", "期待", "舒展"]},
    {"id": "w1-025", "text": "他们会把影子当作真实的事物。", "source": "柏拉图《理想国》", "concept": "洞穴之影", "explanation": "人很容易把屏幕上的、别人嘴里的东西当成全部真相。偶尔转身看看光源，才知道自己一直盯着什么；看见影子，已经是走出的开始。转身，是走出洞穴的第一步。", "western": "柏拉图的洞穴喻揭示意见与真理的等级，培根后来的“四假象”、马克思的意识形态批判都可视为其回响；庄子“朝菌不知晦朔”也谈认知局限，但更偏相对。", "tags": ["迷茫", "反思", "阅读"]},
    {"id": "w1-026", "text": "善是知识和真理的根源。", "source": "柏拉图《理想国》", "concept": "善的理念", "explanation": "知道得再多，若没有善意引导，也可能用错地方。学习之前先问一句：我想用这些知识去做什么？答案会决定知识最后长成什么。善意会给知识定方向。", "western": "柏拉图把善比作太阳，既照亮可知世界，也使万物得以存在；这与《易》“元者善之长也”都把善放在根源处，但希腊的善是理念，中国的善是生生之德。", "tags": ["专注", "反思", "写论文"]},
    {"id": "w1-027", "text": "求知是所有人的本性。", "source": "亚里士多德《形而上学》", "concept": "求知本性", "explanation": "好奇不是幼稚，而是人的本能。顺着那个“为什么”多走一步，学习就不再只是任务，而会变成一种自然的伸展；好奇心需要被保护。好奇需要一点安静。", "western": "亚里士多德在《形而上学》开篇把求知欲视为人性，与孔子“学而时习之”、荀子“劝学”都把学习看作人的完成方式；希腊更重惊异，中国更重工夫。", "tags": ["阅读", "专注", "期待"]},
    {"id": "w1-028", "text": "幸福是灵魂合乎德性的现实活动。", "source": "亚里士多德《尼各马可伦理学》", "concept": "幸福即德性", "explanation": "幸福不是一阵好心情，而是把在乎的价值活进日常。今天做一件与你想成为的人相符的事，就是幸福的砖；它需要反复砌，而不是等来。今天先砌一块。", "western": "亚里士多德的目的论幸福观强调活动而非状态，与孟子“君子有三乐”、宋儒“孔颜之乐”相近；但希腊以德性功能的实现为标准，中国更重天理与人伦的安顿。", "tags": ["舒展", "平静", "专注"]},
    {"id": "w1-029", "text": "我们由习惯养成德性，也由习惯败坏德性。", "source": "亚里士多德《尼各马可伦理学》", "concept": "习惯成德", "explanation": "品格不是一次决定，而是每天小选择的累积。想变好，不必发大誓，只要把一个小动作重复到不需要意志力；那时它就成了你。重复到不用下决心。", "western": "亚里士多德以习惯解释德性生成，接近荀子“化性起伪”；但亚氏认为习惯完善人的自然功能，荀子则认为习惯改造人的自然倾向，二者对“自然”的评价不同。", "tags": ["拖延", "专注", "反思"]},
    {"id": "w1-030", "text": "德性在于两个极端之间的中道。", "source": "亚里士多德《尼各马可伦理学》", "concept": "中道之德", "explanation": "太软和太硬都不好。勇敢在鲁莽与怯懦之间，慷慨在挥霍与吝啬之间；找到适合此刻的那个度，比死守一条规则更难，也更成熟。度，要在具体情境里找。", "western": "亚里士多德的中道不是折中，而是情境中的恰当，与孔子“过犹不及”、中庸“执两用中”高度呼应；希腊以实践智慧定位中道，中国以礼与时中安顿它。", "tags": ["烦躁", "反思", "平静"]},
    {"id": "w1-031", "text": "朋友是另一个自我。", "source": "亚里士多德《尼各马可伦理学》", "concept": "他我之友", "explanation": "真正的朋友不是只会附和的人，而是能让你看见自己盲点的人。和他相处时，你会更接近真实的自己；朋友也是一面温柔的镜子。被照见，也照见对方。", "western": "亚里士多德把友爱分为利益、快乐与德性三类，最高者以彼此的善为目的，与孔子“友直，友谅，友多闻”、孟子“友其德”相通，但希腊更强调平等与相互性。", "tags": ["社交", "孤独", "舒展"]},
    {"id": "w1-032", "text": "吾爱吾师，吾更爱真理。", "source": "亚里士多德《尼各马可伦理学》", "concept": "真理优先", "explanation": "尊重一个人，不等于放弃自己的判断。把人和观点分开看，你既能保持感激，也能保持清醒；真正的师承，不是复制老师，而是学会自己走路。", "western": "这句通行中译概括了亚里士多德在《尼各马可伦理学》中的立场：虔敬要求优先尊重真理；它与王阳明“求之于心”的独立判断相近，但希腊仍以理性真理为准绳。", "tags": ["复习考试", "反思", "专注"]},
    {"id": "w1-033", "text": "思辨活动是最完满的幸福。", "source": "亚里士多德《尼各马可伦理学》", "concept": "思辨之福", "explanation": "有些快乐来自得到，有些快乐来自想明白。留一点不被打扰的时间给思考，你会尝到一种更安静的满足；它不喧哗，却能留很久。思考也需要留白。", "western": "亚里士多德把沉思生活置于实践生活之上，接近柏拉图对观照的推崇；中国儒家则更重躬行，朱熹虽讲“格物致知”，最终仍落在人伦日用。", "tags": ["专注", "放空", "平静"]},
    {"id": "w1-034", "text": "有一个自身不动的推动者。", "source": "亚里士多德《形而上学》", "concept": "不动的推动者", "explanation": "有些改变需要外力的第一推，但第一推之后，事情会按自己的方式继续。开始很难，开始了就会容易一点；先让自己被推动一次。先开始，再谈坚持。", "western": "亚里士多德以不动的推动者解释运动的终极根据，后来被托马斯·阿奎那接续为上帝存在的论证；这与老子“道法自然”的无为生成形成有趣对照。", "tags": ["拖延", "期待", "专注"]},
    {"id": "w1-035", "text": "快乐是幸福生活的起点与终点。", "source": "伊壁鸠鲁《致美诺寇的信》", "concept": "快乐原则", "explanation": "快乐不是放纵，而是身体和心灵没有被打扰的状态。先把不必要的痛去掉，幸福就已经在附近了；它常常是减法，而不是加法。少一点，反而多一点。", "western": "伊壁鸠鲁的快乐是消极的免于痛苦，而非感官刺激的累积，接近庄子“至乐无乐”；但伊壁鸠鲁仍以感觉为标准，庄子则要人超越分别。", "tags": ["舒展", "平静", "休息"]},
    {"id": "w1-036", "text": "死亡与我们无关，我们不必怕它。", "source": "伊壁鸠鲁《致美诺寇的信》", "concept": "死亡无关", "explanation": "我们活着时，死亡还没来；死亡来时，我们已经不在。很多对未来的恐惧，其实是对想象中场景的恐惧，而不是对正在发生之事的反应。把想象和事实分开。", "western": "伊壁鸠鲁以感觉论消解死亡恐惧，与庄子“死生，命也”的坦然相近；但伊壁鸠鲁要人借此安心享受当下，庄子则把生死放进气的聚散。", "tags": ["焦虑", "夜晚", "平静"]},
    {"id": "w1-037", "text": "趁年轻时就该研究哲学，年老时也不要厌倦。", "source": "伊壁鸠鲁《致美诺寇的信》", "concept": "哲学终身", "explanation": "学习不是某个年龄段的任务。年轻时开始，是为了少走弯路；年老时继续，是为了不被经验困住；任何时候开始，都不算晚。今天翻开一页，也算开始。", "western": "伊壁鸠鲁把哲学视为贯穿一生的治疗，与孔子“朝闻道，夕死可矣”、荀子“学至乎没而后止”相近；但伊壁鸠鲁以快乐为尺度，儒家以成人为尺度。", "tags": ["阅读", "专注", "期待"]},
    {"id": "w1-038", "text": "无物能从无中生有。", "source": "卢克莱修《物性论》", "concept": "无中生有", "explanation": "突然出现的东西，背后往往有长期的积累。看不到来路时，不必慌，先去找那条被忽略的线索；每一份结果都有前史，也都有代价，只是你还没看见那条线。", "western": "卢克莱修继承伊壁鸠鲁的原子论，以“无中不能生有”反对神创与奇迹；这与王充“天地合气，万物自生”的自然主义相近，但一个用原子，一个用气。", "tags": ["写论文", "实验", "专注"]},
    {"id": "w1-039", "text": "一切事物都由种子与虚空构成。", "source": "卢克莱修《物性论》", "concept": "种子与虚空", "explanation": "看得见的结构之外，还有看不见的空隙。关系、计划和身体都需要留白，塞得太满反而无法运转；空不是没有，它让有得以发生，也让呼吸进来。", "western": "卢克莱修用“种子”与“虚空”解释生成与消散，接近《老子》“有无相生”；但罗马诗人要人摆脱宗教恐惧，老子则要人回到无为之德。", "tags": ["放空", "休息", "舒展"]},
    {"id": "w1-040", "text": "死亡不过是感觉的停止。", "source": "卢克莱修《物性论》", "concept": "死亡即止", "explanation": "害怕死亡时，你其实在害怕失去感受。可那时感受已经停止，痛苦也就没有落脚的地方；真正需要面对的，多半是此刻对失去的想象。此刻才是能握住的地方。", "western": "卢克莱修延续伊壁鸠鲁，以感觉论否认死后受苦，与佛教“受蕴灭”的分析有表面相似；但卢克莱修否认轮回，佛教则以业力相续。", "tags": ["失去", "平静", "夜晚"]},
    {"id": "w1-041", "text": "有些事取决于我们，有些则不然。", "source": "爱比克泰德《手册》", "concept": "控制二分", "explanation": "把精力分成两堆：能改变的和不能改变的。只在前一堆里用力，你会明显轻下来；这不是放弃，而是把力气用在有回报的地方，也用在能让你安心的地方。", "western": "爱比克泰德的“控制二分”是斯多葛自由观的核心，接近孔子“不知命无以为君子”；但斯多葛把自由放在判断之内，孔子把知命放在道德实践之中。", "tags": ["焦虑", "专注", "平静"]},
    {"id": "w1-042", "text": "不要要求事情按你的意愿发生，而要接受它们如其所是。", "source": "爱比克泰德《手册》", "concept": "顺应事态", "explanation": "期待落空时，先别急着和现实较劲。看清它本来的样子，再决定下一步，比反复问“为什么不是那样”更有用；接受是行动的起点。接受不是同意，是看清。", "western": "爱比克泰德把痛苦归于对事实的添加，与庄子“安时而处顺”、佛教“如实观”相近；斯多葛强调意志的退让，庄子则连“我”也一并放下。", "tags": ["烦躁", "释然", "平静"]},
    {"id": "w1-043", "text": "不要说“我失去了”，要说“我归还了”。", "source": "爱比克泰德《手册》", "concept": "归还之思", "explanation": "失去让人痛，是因为把它当成永远属于自己。换成“曾经借我一段时间”，感激会慢慢盖过不甘；你仍然可以怀念，但不必再把它攥紧，手松开，才有新的位置。", "western": "爱比克泰德以“归还”重述拥有，接近《庄子·养生主》“适来，夫子时也；适去，夫子顺也”；两者都把占有改写成暂时的托付。", "tags": ["失去", "感激", "释然"]},
    {"id": "w1-044", "text": "记住你是一个演员，扮演派给你的角色。", "source": "爱比克泰德《手册》", "concept": "人生如戏", "explanation": "角色有大小，演得好坏却由自己决定。不必嫉妒别人的剧本，把手里这一场认真演完，就已经很好；但别把角色当成全部的你。演好这一场就够了。", "western": "爱比克泰德以剧场隐喻说明命运与自由的分工，类似孔子“不在其位，不谋其政”；但斯多葛的剧本由宇宙理性写定，儒家的角色由人伦关系规定。", "tags": ["社交", "焦虑", "反思"]},
    {"id": "w1-045", "text": "如果你想自由，就不要渴望依赖他人的东西。", "source": "爱比克泰德《手册》", "concept": "内在自由", "explanation": "把安全感全放在别人的评价上，你就把自由的钥匙交了出去。培养一点不靠掌声也能成立的东西；那不是清高，是给自己留退路。退路也是自由的一部分。", "western": "爱比克泰德认为自由是意志的独立，与庄子“乘天地之正”的逍遥形似而神异：斯多葛在必然中守住内心，庄子则要超越一切对待。", "tags": ["焦虑", "孤独", "舒展"]},
    {"id": "w1-046", "text": "你有支配自己心灵的力量，而不受外部事件支配。", "source": "马可·奥勒留《沉思录》", "concept": "心灵主权", "explanation": "外面发生什么，你未必能选；怎么解释、怎么回应，仍有一块属于你。先把这块地守住，别急着被带走，也别急着反击；稳住判断，再决定下一步。", "western": "马可·奥勒留把自由收缩到判断之内，是斯多葛“控制二分”的实践版；这与孟子“万物皆备于我”的反身而诚相近，但一个面对宇宙必然，一个面对人伦本心。", "tags": ["焦虑", "专注", "平静"]},
    {"id": "w1-047", "text": "最好的报复，是不要成为伤害你的人那样。", "source": "马可·奥勒留《沉思录》", "concept": "不作恶报", "explanation": "被伤害之后，人最容易变成自己讨厌的样子。守住底线不是为了放过对方，而是为了不把对方的阴影，长成自己的一部分；报复若以毁掉自己为代价，就太贵了。", "western": "马可·奥勒留把宽恕理解为自我保全，与孔子“以直报怨”、老子“报怨以德”都不同：斯多葛不要求爱敌人，只要求不让恶改变自己的理性。", "tags": ["烦躁", "低落", "反思"]},
    {"id": "w1-048", "text": "宇宙是变化，人生是看法。", "source": "马可·奥勒留《沉思录》", "concept": "变化与意见", "explanation": "同一件事，换个解释，感受就不同。不是要你自欺，而是提醒：你此刻的痛苦里，有一部分来自你的解读；把解释权拿回来，情绪才有转弯的余地。", "western": "马可·奥勒留把存在分为流变与判断两层，接近佛教“一切唯心造”；但斯多葛仍相信宇宙理性，佛教则以缘起性空消解实体，二者对“看法”的归宿不同。", "tags": ["变化", "反思", "平静"]},
    {"id": "w1-049", "text": "向内看，善的泉源就在你心里。", "source": "马可·奥勒留《沉思录》", "concept": "内心泉源", "explanation": "向外找认可，常常越找越渴。安静下来问自己：我真正敬重什么样的生活？答案往往比想象中清楚，只是被噪音盖住了；安静，是听见它的条件。", "western": "马可·奥勒留把善的根源放在内在理性，与孟子“仁义礼智根于心”、王阳明“心即理”相通；但斯多葛的内心是宇宙理性的一部分，儒家的心则连着人伦。", "tags": ["焦虑", "孤独", "平静"]},
    {"id": "w1-050", "text": "你随时可以退入自己的心灵。", "source": "马可·奥勒留《沉思录》", "concept": "心灵退隐", "explanation": "不必等到假期才能休息。哪怕周围很吵，也可以退回到自己的呼吸和念头里，待上几分钟；这不是逃避，是给心找一个临时的房间。几分钟也够用。", "western": "马可·奥勒留把心灵视为随时可归的堡垒，接近陶渊明“心远地自偏”；斯多葛的退隐是为了恢复理性，陶渊明的退隐则为了保全自然之真。", "tags": ["疲惫", "休息", "专注"]},
    {"id": "w1-051", "text": "清晨对自己说：我醒来是为了做人的工作。", "source": "马可·奥勒留《沉思录》", "concept": "晨间立志", "explanation": "早上先别急着刷消息。给自己一句话，说明今天为什么起床，一天的方向会稳很多；哪怕只完成一件小事，也算没有辜负这次醒来。方向比速度重要。", "western": "马可·奥勒留以晨间自省确认人的社会本性，类似曾子“吾日三省吾身”；但斯多葛的早晨是面向宇宙秩序的整备，儒家的反省落在人伦过失上。", "tags": ["晨间", "专注", "期待"]},
    {"id": "w1-052", "text": "不要像会活一千年那样行动。", "source": "马可·奥勒留《沉思录》", "concept": "向死而生", "explanation": "总觉得来日方长，事情就会一直往后拖。把今天当成有限的一天，反而更容易选出真正重要的事；拖延常常是对“无限时间”的幻觉。今天只做最重要的一件。", "western": "马可·奥勒留以死亡限制行动的拖延，接近《古诗十九首》“人生忽如寄”的警醒；但斯多葛由此走向当下的尽责，汉诗更多落在生命的怅惘。", "tags": ["拖延", "焦虑", "专注"]},
    {"id": "w1-053", "text": "人们彼此为对方而生。", "source": "马可·奥勒留《沉思录》", "concept": "相互依存", "explanation": "人不是孤岛。你今天的耐心、援手和一句回应，可能正是另一个人撑下去的理由；反过来，你也不必独自扛过所有难关。接受帮助也是相互依存。", "western": "马可·奥勒留以社会性规定人的本性，与亚里士多德“人是政治动物”一脉相承，也接近《论语》“己欲立而立人”；斯多葛更强调宇宙公民的连带。", "tags": ["社交", "孤独", "舒展"]},
    {"id": "w1-054", "text": "我们受苦的次数，多于实际遭遇的。", "source": "塞涅卡《书信集》", "concept": "想象之苦", "explanation": "很多焦虑发生在事情到来之前。把想象和事实分开，你会发现真正需要处理的，往往没有那么多；先问一句：这是已经发生的，还是我预演的？", "western": "塞涅卡把恐惧视为想象对未来的预支，与庄子“不逆寡，不雄成”的应物态度相近；斯多葛用理性校正想象，庄子用“无心”取消预演。", "tags": ["焦虑", "反思", "平静"]},
    {"id": "w1-055", "text": "到处都去，等于哪里都没去。", "source": "塞涅卡《书信集》", "concept": "读书贵专", "explanation": "同时打开太多窗口，注意力就碎了。今天只选一个方向深入一点，比在每个方向都浅尝更让人踏实；读书、做事、关系都是如此。一次只开一扇窗。", "western": "塞涅卡以读书喻专注，反对知识的游荡，与《荀子·劝学》“梧鼠五技而穷”的告诫相通；罗马人重实用集中，荀子重专一积学。", "tags": ["专注", "阅读", "焦虑"]},
    {"id": "w1-056", "text": "一切都不属于我们，只有时间属于我们。", "source": "塞涅卡《书信集》", "concept": "时间之财", "explanation": "东西可以再买，关系可以再建，时间过去了就真的没有了。把时间花在你在意的人和事上，才算真正拥有它；别把全部时间都赊给以后。今天也算数。", "western": "塞涅卡把时间视为唯一真正属于人的财产，与《淮南子》“圣人不贵尺之璧而重寸之阴”相近；但塞涅卡要人精算时间，中国哲人更多以惜时劝学。", "tags": ["疲惫", "专注", "休息"]},
    {"id": "w1-057", "text": "贫穷的不是拥有太少，而是渴望更多。", "source": "塞涅卡《书信集》", "concept": "欲望之贫", "explanation": "匮乏感有时和拥有多少无关，而和“还想要”有关。辨认真正需要的，欲望就会松开一点；知足不是不进取，是不被缺口牵着走。少一点想要，多一点在场。", "western": "塞涅卡区分自然需要与意见欲望，接近《老子》“知足者富”；但斯多葛以理性界定需要，老子以“少私寡欲”回到朴素，一个靠分辨，一个靠减法。", "tags": ["焦虑", "反思", "释然"]},
    {"id": "w1-058", "text": "要与能让你变得更好的人交往。", "source": "塞涅卡《书信集》", "concept": "择友而处", "explanation": "身边人的语气和习惯，会慢慢变成你的。多靠近让你想变好的人，也让自己成为别人愿意靠近的人；关系是一种长期的环境。环境会替你用力。", "western": "塞涅卡重视友谊对德性的塑造，与孔子“益者三友，损者三友”、荀子“居楚而楚”的环境论相近；罗马人重择友，儒家兼重择邻与自省。", "tags": ["社交", "舒展", "期待"]},
    {"id": "w1-059", "text": "未来充满不确定，立刻开始生活。", "source": "塞涅卡《书信集》", "concept": "当下即行", "explanation": "等一切确定再开始，通常等不到。先过好今天能过的部分，不确定会在行动里慢慢缩小；你不需要先拥有全部答案，先走一步，路会清楚一点。", "western": "塞涅卡以未来的不可控催促当下行动，接近《今日歌》“人生百年几今日”的紧迫；斯多葛把当下视为唯一能负责的领域，中国诗人则更多感叹流光。", "tags": ["期待", "焦虑", "专注"]},
    {"id": "w1-060", "text": "哲学啊，你是生活的向导。", "source": "西塞罗《图斯库卢姆谈话录》", "concept": "哲学指引", "explanation": "哲学不只是课堂里的名词。它帮你判断什么值得追求、什么可以放下，是日常选择的一把尺；遇到难题时，先问它怎么看，再决定怎么做，让哲学回到具体的一天里。", "western": "西塞罗以哲学为生活的导师，延续希腊哲学的治疗传统，与孔子“志于道”、荀子“学以成人”相近；罗马人把哲学公共化，中国则把道落在修身与治世。", "tags": ["反思", "阅读", "平静"]},
    {"id": "w1-061", "text": "不知道自己出生前历史的人，永远是个孩子。", "source": "西塞罗《论演说家》", "concept": "历史意识", "explanation": "不知道来路，就容易把眼前当成全部。读一点历史，你会发现自己正站在许多人的经验和错误之上；理解过去，是为了不再被它悄悄支配。", "western": "西塞罗把历史意识视为成人的标志，接近《论语》“温故而知新”；但罗马人重政治传统的延续，孔子重通过旧知培养新的判断。", "tags": ["阅读", "反思", "迷茫"]},
    {"id": "w1-062", "text": "犯错是人之常情，坚持错误是愚蠢的。", "source": "西塞罗《腓力比克》", "concept": "改过之智", "explanation": "犯错不可怕，可怕的是为了面子继续错下去。早点承认，代价通常比硬撑小得多；认错不是否定自己，是把自己从错误里捞出来。认错也是一种能力。", "western": "西塞罗把改错视为理性成熟，与《论语》“过则勿惮改”“过而不改，是谓过矣”几乎同调；两者都把认错放进人的可完善性里。", "tags": ["反思", "烦躁", "释然"]},
    {"id": "w1-063", "text": "国家是人民的共同事业。", "source": "西塞罗《论共和国》", "concept": "公共之事", "explanation": "公共的事不是少数人的私产。你关心的那条规则、那次投票、那件小事，都在参与“我们共同的生活”；别把自己只当旁观者。参与，才有共同。从关心开始。", "western": "西塞罗的“res publica”强调共同体的公共性，接近孟子“民为贵”、《礼记》“天下为公”；但罗马仍以法律与共和制度承载公共性，儒家更重德治与民心。", "tags": ["社交", "反思", "期待"]},
    {"id": "w1-064", "text": "你为自己造了我们，我们的心直到安息于你，才得安宁。", "source": "奥古斯丁《忏悔录》", "concept": "心之安息", "explanation": "人心里有个填不满的洞，成绩、关系、娱乐都只能暂时盖住。承认自己在寻找一个更大的归宿，也是一种诚实；不必急着用忙碌把它填平。安息不是停下来，是归位。", "western": "奥古斯丁把人的不安理解为向无限者的归向，与《诗经》“心之忧矣，我歌且谣”的抒发不同；西方把归宿放在超越的上帝，中国常在人与自然的相安中安顿。", "tags": ["孤独", "反思", "平静"]},
    {"id": "w1-065", "text": "时间究竟是什么？没有人问我，我倒清楚；有人问我，我便茫然。", "source": "奥古斯丁《忏悔录》", "concept": "时间之谜", "explanation": "越熟悉的东西越难说清。说不清也没关系，先感受它：此刻你在怎样使用时间，比给时间下定义更重要；时间会在专注里变厚。把今天用厚一点。", "western": "奥古斯丁把时间从宇宙尺度拉回心灵的三重现在，预示了现象学的时间分析；庄子以“白驹过隙”写时间，却更重顺应而非追问其本质。", "tags": ["反思", "专注", "夜晚"]},
    {"id": "w1-066", "text": "恶不过是善的缺乏。", "source": "奥古斯丁《忏悔录》", "concept": "恶为善缺", "explanation": "有些坏不是一种独立的力量，而是好东西缺席了。面对伤害，除了仇恨，也可以问：这里缺的是安全、尊重，还是爱？找到缺口，才谈得上修补，也才谈得上不再重复。", "western": "奥古斯丁以 privatio boni 回应恶的问题，与柏拉图“善的理念”一脉相承；中国思想多以阴阳失衡、气禀偏驳解释恶，较少使用“缺乏”这一本体论结构。", "tags": ["低落", "反思", "平静"]},
    {"id": "w1-067", "text": "我逃到哪里，才能逃开你呢？", "source": "奥古斯丁《忏悔录》", "concept": "无处可逃", "explanation": "人有时想逃开自己，逃开那些不肯面对的事。但逃得越远，心里那块东西越跟着你；不如停下来看看它，它也许没有想象中那么可怕。面对，比逃更省力。", "western": "奥古斯丁的追问把“逃避自我”变成神学问题，与《庄子·庚桑楚》“不能自胜而强不从”的内心纠缠相近；一个求神收纳，一个求心之自胜。", "tags": ["焦虑", "孤独", "夜晚"]},
    {"id": "w1-068", "text": "太晚了，我才开始爱你。", "source": "奥古斯丁《忏悔录》", "concept": "迟来的爱", "explanation": "有些领悟来得晚，但不等于没有价值。对一个人、一件事、一种生活的珍惜，从今天开始也不算迟；晚来的爱仍然是爱，别用迟到否定它，从今天起，认真对待就好。", "western": "奥古斯丁的“迟爱”把悔改写成时间的翻转，与陶渊明“悟已往之不谏，知来者之可追”相近；西方重向神的回转，中国重归园田的自我安顿。", "tags": ["感激", "失去", "释然"]},
    {"id": "w1-069", "text": "人的最终幸福，在于看见上帝的本质。", "source": "托马斯·阿奎那《神学大全》", "concept": "终极幸福", "explanation": "你也许把幸福押在下一件事上：成绩、机会、一段关系。它们能带来快乐，却填不满最后那个问题；人真正渴望的，也许是看见那使一切成立的东西。", "western": "阿奎那将亚里士多德的思辨幸福推进为“荣福直观”，与孟子“尽心知性知天”、程朱“豁然贯通”可作对照；但阿奎那的终点是超越的上帝，儒家的天理仍在此世。", "tags": ["迷茫", "期待", "平静"]},
    {"id": "w1-070", "text": "恩典不废除自然，而是成全自然。", "source": "托马斯·阿奎那《神学大全》", "concept": "恩典成全", "explanation": "好的帮助不是把你换掉，而是让你原本的样子长得更完整。接受支持时，不必觉得那是否定了自己；被托住，也可以是一种成长，不必为此感到亏欠。", "western": "阿奎那的“恩典成全自然”为受造界的相对自主留出空间，类似《中庸》“致中和，天地位焉”的成全结构；但一个以恩典为高峰，一个以率性为道路。", "tags": ["感激", "舒展", "平静"]},
    {"id": "w1-071", "text": "凡被推动的，都由他物推动。", "source": "托马斯·阿奎那《神学大全》", "concept": "因果之链", "explanation": "一件事发生，通常有前因。追到不能再追时，你会遇到一个必须停下的地方；知道自己不是第一因，反而能松开控制欲，也松开自责。因果之外，还有边界。", "western": "阿奎那以因果序列推出不动的推动者，是亚里士多德论证的基督教化；老子说“道生一”，也追溯终极根据，但不走因果链，而走生成论。", "tags": ["反思", "焦虑", "平静"]},
    {"id": "w1-072", "text": "法律是旨在共同善的理性命令。", "source": "托马斯·阿奎那《神学大全》", "concept": "法律之理", "explanation": "规则若只为少数人服务，就失去了正当性。判断一条规则好不好，看它是否真的让共同生活变得更好；好规则也要经得起持续的追问，尤其要经得起被约束者的追问。", "western": "阿奎那把法律定义为理性对共同善的安排，接近《礼记》“礼者，天地之序也”；但罗马—基督教传统以立法理性为核心，中国礼治更重习俗与教化的浸润。", "tags": ["反思", "社交", "平静"]},
    {"id": "w1-073", "text": "入此门者，当舍弃一切希望。", "source": "但丁《神曲·地狱篇》", "concept": "地狱之门", "explanation": "有些路一旦走进去，就很难回头。做重大选择前，先看清它的代价，不要只被门口的光吸引；希望若被用来遮住代价，就成了幻觉。看清代价，再迈步。", "western": "但丁把地狱之门写成绝对的界限，与《庄子·人间世》“知其不可奈何而安之若命”不同；一个以希望的有无划分生死，一个以安命化解绝境。", "tags": ["迷茫", "焦虑", "反思"]},
    {"id": "w1-074", "text": "在人生旅程的中途，我迷失在一片幽暗的森林。", "source": "但丁《神曲·地狱篇》", "concept": "中途迷失", "explanation": "走到半途突然不知道方向，并不罕见。先承认自己迷路了，才可能停下来找路，而不是硬着头皮往前冲；迷失也可以是转折的入口。迷路时，先停下来。", "western": "但丁以“中途”写灵魂的危机与转向，结构上接近《离骚》“路漫漫其修远兮”的求索；但丁有向导与天国，屈原的求索最终落在故国与自身。", "tags": ["迷茫", "低落", "反思"]},
    {"id": "w1-075", "text": "走自己的路，让别人去说吧。", "source": "但丁《神曲·炼狱篇》", "concept": "自循其道", "explanation": "你不可能让所有人满意。分清哪些评价值得听、哪些只是噪音，然后把脚放回自己的路上；听见自己，比听见掌声更难，但也更重要，因为路要自己走完。", "western": "但丁这句经由马克思引用而广为人知，原意是坚持正当的事业而不惧流言；与庄子“举世誉之而不加劝”的独立相近，但但丁仍有明确的目的地。", "tags": ["社交", "焦虑", "舒展"]},
    {"id": "w1-076", "text": "是爱，推动太阳与其他星辰。", "source": "但丁《神曲·天堂篇》", "concept": "爱之推动", "explanation": "宏大的秩序背后，常有一个温暖的动力。你做一件事若出于爱，再累也会有一种向前的力量；但爱也需要休息，不必烧尽自己。爱也要有呼吸。", "western": "但丁以爱统摄宇宙，是基督教目的论的诗性表达，与《易传》“生生之谓易”的生成之爱可作对照；一个归于位格的爱，一个归于天地生物的德。", "tags": ["期待", "舒展", "夜晚"]},
    {"id": "w1-077", "text": "我找不到和平，也没有战争的力气。", "source": "彼特拉克《歌集》", "concept": "爱之矛盾", "explanation": "有些拉扯没有胜负：想靠近又怕受伤，想放下又不甘心。先允许自己停在这个矛盾里，不必马上选边；看见矛盾，已经是一种清醒。矛盾里也有真实。", "western": "彼特拉克把内心冲突写成现代自我的开端，接近李商隐“此情可待成追忆”的缠绕；但彼特拉克以忏悔收束欲望，李商隐让怅惘停留在诗里。", "tags": ["孤独", "烦躁", "反思"]},
    {"id": "w1-078", "text": "我最害怕的，是恐惧本身。", "source": "蒙田《随笔集》", "concept": "恐惧之怖", "explanation": "很多事还没发生，恐惧已经先消耗了你。把注意力拉回此刻能做的准备，恐惧就会失去一部分燃料；你怕的常常不是事，而是怕的感觉。怕是预告，不是事实。", "western": "蒙田把恐惧视为比危险更早到来的敌人，与《老子》“吾所以有大患者，为吾有身”的省察相近；一个以常识自嘲化解，一个以无为保全。", "tags": ["焦虑", "夜晚", "反思"]},
    {"id": "w1-079", "text": "习惯是第二自然，力量不亚于天性。", "source": "蒙田《随笔集》", "concept": "习惯之力", "explanation": "重复久了，行为会变成自动反应。想改变生活，不必和意志硬拼，改一个小习惯，让环境帮你；先换掉一个触发点，比反复发誓有用，也比责怪自己有用。", "western": "蒙田继承亚里士多德与西塞罗的习惯论，与《汉书》所引孔子“少成若天性，习惯如自然”几乎同调；两者都把教育理解为第二本性的塑造。", "tags": ["拖延", "反思", "专注"]},
    {"id": "w1-080", "text": "学会了死亡的人，就不再是奴隶。", "source": "蒙田《随笔集》（引塞涅卡）", "concept": "向死而自由", "explanation": "真正怕的往往是失去。把最坏的结果想清楚，你反而能更自由地选择，不再被“万一”牵着走；敢失去的人，才敢真正选择，也才可能真正承担。", "western": "蒙田以死亡练习换取自由，与庄子“齐生死”、塞涅卡“每日预备告别”相呼应；蒙田更重世俗生活的从容，不把希望押在彼岸。", "tags": ["焦虑", "失去", "释然"]},
    {"id": "w1-081", "text": "每个人都带着人类处境的全部印记。", "source": "蒙田《随笔集》", "concept": "人性样本", "explanation": "你遇到的每个人，都带着人类全部的处境：会怕、会爱、会老、会自欺。别用一个标签把谁看死，也别把自己看窄；理解这一点，傲慢会少很多，理解会多一点。", "western": "蒙田把普遍人性放进每个个体，与孟子“人皆可以为尧舜”、荀子“涂之人可以为禹”的可完善性相近；但蒙田更重承认限度，儒家更重德性修养。", "tags": ["社交", "反思", "平静"]},
    {"id": "w1-082", "text": "人人都把不合自己习俗的东西称为野蛮。", "source": "蒙田《随笔集》", "concept": "习俗之见", "explanation": "遇到不理解的做法，先别急着说它落后。很多判断只是习惯不同；多看一层，你会少一点傲慢，也多一点自由；理解不是认同，是看见。看见，不等于同意。", "western": "蒙田的相对主义为西方人类学埋下伏笔，与《庄子·秋水》“夏虫不可语冰”的视角主义相近；但蒙田仍保留普遍人性的判断，庄子更彻底地齐平是非。", "tags": ["社交", "反思", "迷茫"]},
    {"id": "w1-083", "text": "读史使人明智，读诗使人灵秀，数学使人周密。", "source": "培根《随笔》", "concept": "学问之益", "explanation": "不同类型的阅读，训练不同的能力。别只读一种书，让历史、诗和数学各自给你一副看世界的镜片；交叉着读，判断会更稳。阅读也要换镜头。", "western": "培根以知识分类指导阅读，是近代经验论与实用教育的先声，与孔子“兴于诗，立于礼，成于乐”的教化次序相近；一个重能力训练，一个重人格养成。", "tags": ["阅读", "专注", "复习考试"]},
    {"id": "w1-084", "text": "读书使人充实，讨论使人机智，笔记使人准确。", "source": "培根《随笔》", "concept": "读书之法", "explanation": "读进去只是第一步。把想法说出来、写下来，知识才会从“我见过”变成“我能用”，也才知道自己哪里还没懂；输出是最好的检验。写下来，才知道懂没懂。", "western": "培根把阅读、交谈与写作视为三种互补的工夫，接近《礼记》“博学、审问、慎思、明辨、笃行”；培根更重知识的效用，儒家更重德行的完成。", "tags": ["阅读", "社交", "写论文"]},
    {"id": "w1-085", "text": "顺境的美德是节制，逆境的美德是坚忍。", "source": "培根《随笔》", "concept": "顺逆之德", "explanation": "顺利时最容易放纵，困难时最容易放弃。两种处境各修一种能力：好时不飘，难时不散；知道自己正处在哪一种里，才知道该往哪里用力，也才知道什么时候该停。", "western": "培根把德性放进处境中考察，接近孟子“富贵不能淫，贫贱不能移”；但培根更冷静地分析权力的心理，孟子则以大丈夫人格为尺度。", "tags": ["舒展", "低落", "反思"]},
    {"id": "w1-086", "text": "君主必须像狐狸一样识别陷阱，像狮子一样吓退豺狼。", "source": "马基雅维利《君主论》", "concept": "狐狮之道", "explanation": "做事既要有判断力，也要有威慑力。只聪明不果断，容易被利用；只强硬不辨局，容易撞墙；先看清局面，再决定用哪一种力量。先辨局，再出手。", "western": "马基雅维利把政治从道德目的论中解放出来，与韩非的“法术势”最为接近；但韩非服务君主集权，马基雅维利更关心国家的获取与维持。", "tags": ["专注", "烦躁", "反思"]},
    {"id": "w1-087", "text": "被人畏惧比被人爱戴更安全。", "source": "马基雅维利《君主论》", "concept": "畏惧之安", "explanation": "在需要秩序的场合，明确的边界比讨人喜欢更可靠。但畏惧不能变成憎恨，否则秩序会从内部裂开；让人怕你，不如让人信你。信任比畏惧更长久。", "western": "马基雅维利对恐惧与爱戴的分析是政治现实主义的经典，与《韩非子》“明主之治”的威势论相近；两者都警惕道德修辞，但一个仍保留共和理想。", "tags": ["社交", "焦虑", "反思"]},
    {"id": "w1-088", "text": "命运主宰我们一半的行动。", "source": "马基雅维利《君主论》", "concept": "命运之半", "explanation": "努力不保证结果，运气确实占一部分。承认这一点，不会让你变懒，反而让你在失败时少一点自责；也能让你在顺利时多一点感激。尽人事，也要知天命。", "western": "马基雅维利以“命运之河”说明人的能动性，接近孟子“虽有智慧，不如乘势”；但他主张以堤坝与武力对抗命运，孟子更重顺势与得民。", "tags": ["变化", "焦虑", "释然"]},
    {"id": "w1-089", "text": "盲人国里，独眼者称王。", "source": "伊拉斯谟《箴言集》", "concept": "相对之见", "explanation": "在一个标准很低的环境里，稍微认真一点就显得突出。别因此自满，也别因为周围看不见而低估自己；换个环境，你会知道自己真正的位置。", "western": "伊拉斯谟以反讽写相对性，与《庄子》“小知不及大知”、鲁迅的“铁屋子”都有回声；但伊拉斯谟的讽刺指向具体的社会愚昧，庄子更偏认识论的齐物。", "tags": ["社交", "反思", "舒展"]},
    {"id": "w1-090", "text": "战争的甜蜜，只有没尝过的人才知道。", "source": "伊拉斯谟《箴言集》", "concept": "战争之甜", "explanation": "很多事在远处看很热血，走近才知道代价。对没经历过的苦，保持一点敬畏，不轻易鼓吹；也别用别人的牺牲，证明自己的勇敢。别替战争说好话。", "western": "伊拉斯谟继承基督教人文主义对战争的批判，与《老子》“兵者不祥之器”、孟子“善战者服上刑”相近；但伊拉斯谟诉诸理性与基督之爱，老子诉诸道之无为。", "tags": ["烦躁", "反思", "平静"]},
    {"id": "w1-091", "text": "我究竟是什么呢？是一个在思维的东西。", "source": "笛卡尔《第一哲学沉思集》", "concept": "思之确证", "explanation": "你也许会用一个职位、一段关系来定义自己，但这些都可能失去。剥到最后，那个仍在感受和思考的“我”，才是你此刻最确定的起点。先别急着定义。", "western": "笛卡尔以“我思”确立近代主体性，把确定性的地基从外部世界移入自我；这与陆九渊“宇宙便是吾心”形似，但笛卡尔由此走向机械世界，陆九渊走向心即理。", "tags": ["反思", "迷茫", "专注"]},
    {"id": "w1-092", "text": "凡我清晰分明地领会到的，都是真的。", "source": "笛卡尔《第一哲学沉思集》", "concept": "清晰分明", "explanation": "别在脑子一团雾时做决定。把问题写清楚、把事实摆出来，清楚本身就会给你一种可依靠的确定感；模糊时先不动，清楚比聪明更可靠，也更能被别人检验。", "western": "笛卡尔以清楚分明为真理标准，奠定了近代认识论的理性主义传统，与朱熹“格物穷理”的求索相近；但笛卡尔的标准在观念自身，朱熹的标准在天理与人伦。", "tags": ["专注", "写论文", "反思"]},
    {"id": "w1-093", "text": "判断的错误，源于意志超出了理智的范围。", "source": "笛卡尔《第一哲学沉思集》", "concept": "意志越界", "explanation": "很多错误不是知道得太少，而是急着下结论。让判断慢半拍，等证据跟上，你会少做许多后悔的决定；不确定时，先保留。慢一点，错会少。别抢答。", "western": "笛卡尔把错误归于意志的越界，延续了苏格拉底“无人自愿作恶”的理性主义，也接近孔子“毋意、毋必、毋固、毋我”的克制。", "tags": ["拖延", "反思", "专注"]},
    {"id": "w1-094", "text": "心灵与身体是两种不同的实体。", "source": "笛卡尔《第一哲学沉思集》", "concept": "心身二元", "explanation": "身体会累，心却不一定同步；心很急，身体也可能跟不上。把它们分开看，你会更懂得照顾两边的节奏，而不是用一边责怪另一边。两边都要被听见。", "western": "笛卡尔的心身二元论深刻塑造了近代西方哲学，也留下心身如何交互的难题；中国思想多以“形神相即”“气”贯通身心，较少走向实体二分。", "tags": ["疲惫", "休息", "反思"]},
    {"id": "w1-095", "text": "一切都在神之中，神就是自然。", "source": "斯宾诺莎《伦理学》", "concept": "神即自然", "explanation": "不必把神圣放在世界之外。认真看一片叶子、一阵风，也能遇见那种让万物如此运行的力量；它不在别处，就在事物的秩序里。秩序里也有神性。", "western": "斯宾诺莎以“神即自然”取消超越的造物主，是泛神论与近代理性主义的交汇，与庄子“道在屎溺”的遍在感相近；但斯宾诺莎以几何学方式把握必然。", "tags": ["平静", "舒展", "放空"]},
    {"id": "w1-096", "text": "自由的人最少想到死，他的智慧是对生的沉思。", "source": "斯宾诺莎《伦理学》", "concept": "向生之智", "explanation": "总盯着终点，反而过不好当下。把注意力放回今天还能生长的事——一次交谈、一页书、一顿饭，恐惧会慢慢退到背景里；自由不是不怕死，而是更愿意活。", "western": "斯宾诺莎把自由理解为对必然的认识，与庄子“安时而处顺，哀乐不能入”相近；但斯宾诺莎的自由是理性的提升，庄子是心的消解。", "tags": ["焦虑", "专注", "舒展"]},
    {"id": "w1-097", "text": "一种情感，只有用更强的相反情感才能克制。", "source": "斯宾诺莎《伦理学》", "concept": "情感制衡", "explanation": "硬压情绪通常没用。用另一种更强烈的感受去覆盖它：害怕时想起被爱的经验，嫉妒时去看自己真正想要什么；不是否认情绪，是换一种力量。", "western": "斯宾诺莎的情感力学把伦理变成可分析的因果，类似佛教“以楔出楔”的对治；但斯宾诺莎最终要人认识必然，佛教要人观空。", "tags": ["烦躁", "焦虑", "反思"]},
    {"id": "w1-098", "text": "幸福不是德性的报酬，而是德性本身。", "source": "斯宾诺莎《伦理学》", "concept": "幸福即德", "explanation": "做好人不是为了换好报。行动本身如果是对的，它已经在给你一种踏实的快乐，不必等别人发奖；这种快乐不喧哗，但很难被拿走。它就在行动里。", "western": "斯宾诺莎把幸福与德性同一，接近孔子“仁者安仁”、孟子“反身而诚，乐莫大焉”；但斯宾诺莎的德性是力量的增长，儒家的仁是关系的成全。", "tags": ["舒展", "平静", "感激"]},
    {"id": "w1-099", "text": "单子没有窗户，却各自映照整个宇宙。", "source": "莱布尼茨《单子论》", "concept": "单子无窗", "explanation": "每个人都从自己的角度理解世界，无法直接钻进另一个人的心里。所以表达和倾听，才显得那么重要；你看到的，永远是你那一扇窗。倾听是另一扇窗。", "western": "莱布尼茨的单子论以“无窗”说明实体的自足与预定和谐，与华严宗“因陀罗网”的互摄可作对照；但一个靠神预定，一个靠缘起，彼此映照的方式不同。", "tags": ["孤独", "社交", "反思"]},
    {"id": "w1-100", "text": "这个世界是一切可能世界中最好的。", "source": "莱布尼茨《神正论》", "concept": "最好世界", "explanation": "这不是说世界没有坏事，而是说在限制条件下，它仍有可理解的好。遇到不顺时，先别急着否定全部；好需要被辨认，也需要时间，别急着把世界判死。", "western": "莱布尼茨的神正论试图为恶的存在辩护，后来被伏尔泰在《老实人》中讽刺；与《老子》“天地不仁”相比，莱布尼茨坚持世界整体是善的秩序。", "tags": ["迷茫", "低落", "反思"]},
    {"id": "w1-101", "text": "现在满载着过去，也孕育着未来。", "source": "莱布尼茨《单子论》", "concept": "现在之孕", "explanation": "你现在的反应，藏着过去的经验；你现在的选择，也在长成未来的样子。此刻并不轻，它很有分量；别把它只当成通往明天的过道。此刻就是种子。", "western": "莱布尼茨以单子的知觉说明时间的连续性，接近《易传》“彰往而察来”；但莱布尼茨的连续性是预定和谐，中国的往来是阴阳消长。", "tags": ["专注", "变化", "反思"]},
    {"id": "w1-102", "text": "人心如白板，一切知识来自经验。", "source": "洛克《人类理解论》", "concept": "白板经验", "explanation": "没有谁天生就该懂什么。你不会的事，多半只是还没经历、还没练习；把自己当成可以重新书写的人，别急着定性，经验会慢慢重写你，你不必一次就写对。", "western": "洛克的白板说对抗天赋观念，奠定英国经验论，与荀子“性恶”须待师法、告子“生之谓性”都有可比处；但洛克把心灵视为被动受印，荀子更强调心的主宰。", "tags": ["复习考试", "阅读", "期待"]},
    {"id": "w1-103", "text": "没有天赋的观念，只有后得的观念。", "source": "洛克《人类理解论》", "concept": "观念后得", "explanation": "很多“我就是这样的人”，其实是后来学来的。既然是学来的，就有机会重新学一种更合适的方式；改变不是背叛自己，是更新自己。你可以再学一次。", "western": "洛克以经验发生学消解天赋观念，与王夫之“性日生日成”的生成论相近；但洛克重感官经验的积累，王夫之重气化日新的实践。", "tags": ["变化", "反思", "期待"]},
    {"id": "w1-104", "text": "政府的正当权力来自被统治者的同意。", "source": "洛克《政府论》", "concept": "同意之权", "explanation": "规则若要人服气，得让人有说话和选择的机会。小到一个小组，大到国家，都是这个道理；没有参与的服从，很难长久，同意需要被持续确认。", "western": "洛克的同意说为近代自由民主奠基，与孟子“得天下有道，得其民”、黄宗羲《明夷待访录》对君权的批判可作对照；但洛克以契约与权利为核心，儒家以民心与德治为核心。", "tags": ["社交", "反思", "期待"]},
    {"id": "w1-105", "text": "存在就是被感知，不被感知便无从谈起。", "source": "贝克莱《人类知识原理》", "concept": "存在即感知", "explanation": "一件事若完全不被任何心灵感知，我们其实无法说它“在”。这提醒你：你看见的世界，总带着感知的方式；别把一种看法当成全部。感知也有边界。", "western": "贝克莱以“存在即被感知”取消物质实体，与佛教“唯识所现”、王阳明“心外无物”常被并置；但贝克莱保留上帝作为终极感知者，阳明则归于心即理。", "tags": ["迷茫", "反思", "平静"]},
    {"id": "w1-106", "text": "我们直接看见的，只是观念。", "source": "贝克莱《人类知识原理》", "concept": "观念之幕", "explanation": "你以为自己看见的是“客观世界”，其实先经过眼睛、经验和语言。对同一个画面，不同人真的会看见不同东西；先承认这一层，再谈理解。先承认滤镜。", "western": "贝克莱把知觉对象观念化，推进了经验论的怀疑方向，与庄子、惠子“鱼之乐”之争的认识论隔阂相近；但贝克莱以神保证秩序，庄子则以“物化”取消人类中心。", "tags": ["社交", "反思", "迷茫"]},
    {"id": "w1-107", "text": "理性是，并且只应当是激情的奴隶。", "source": "休谟《人性论》", "concept": "理性之仆", "explanation": "人不是先想清楚才行动，常常是先有感受，再找理由。承认情感的分量，才不会假装自己完全理性；也别用“我想清楚了”骗自己。情感也在讲道理。", "western": "休谟把理性降为情感的工具，颠覆了柏拉图以来的理性主导传统，与荀子“心为之主”相反；但休谟由此走向情感主义伦理，荀子仍以心知道。", "tags": ["烦躁", "反思", "低落"]},
    {"id": "w1-108", "text": "习惯是人生伟大的向导。", "source": "休谟《人性论》", "concept": "习惯引路", "explanation": "人能从经验里学习，靠的不是天才，而是重复。想培养一种能力，就把它变成日常里不需要下决心的事；习惯会替你走路，也会替你走偏，所以要选。", "western": "休谟以习惯解释因果信念，接近亚里士多德“习惯成德”与荀子“化性起伪”；但休谟的习惯是心理联想，亚里士多德的习惯是德性实践。", "tags": ["拖延", "专注", "复习考试"]},
    {"id": "w1-109", "text": "因果的必然性，来自习惯而非理性。", "source": "休谟《人性论》", "concept": "因果之习", "explanation": "你认定“按这个按钮就会发生那件事”，多半是反复见过的结果。别把习惯当成铁律，偶尔验证一下；世界可能比你以为的更活。验证一次也好。", "western": "休谟的因果怀疑动摇了近代科学的基础，康德后来以先验范畴回应；这与佛教“缘起”否认自性因果有表面相似，但休谟停在心理习惯，佛教指向解脱。", "tags": ["实验", "反思", "专注"]},
    {"id": "w1-110", "text": "美不是事物本身的属性，而在观照者的心中。", "source": "休谟《人性论》", "concept": "美在心中", "explanation": "同一幅画，有人觉得美，有人无感。审美没有唯一答案，但可以练习看得更细，让感受有更多依据；别急着替别人规定美，美是相遇，不是标签。", "western": "休谟把美主观化，与庄子“毛嫱丽姬，人之所美也”的相对审美相通；但休谟仍诉诸共通的情感结构，庄子更彻底地齐美丑。", "tags": ["阅读", "平静", "舒展"]},
    {"id": "w1-111", "text": "人生而自由，却无往不在枷锁之中。", "source": "卢梭《社会契约论》", "concept": "自由之悖", "explanation": "自由不是没有限制，而是看清限制后仍想争取一点余地。先分清哪些枷锁来自外面，哪些是自己戴上的；前者要改，后者要松。自由要一点点争。", "western": "卢梭把自由与制度批判连在一起，启发了康德的自律与马克思的解放叙事；与庄子“逍遥”相比，卢梭的自由必须在社会中实现，庄子的自由则要退出社会。", "tags": ["焦虑", "反思", "社交"]},
    {"id": "w1-112", "text": "公意永远以共同利益为目标。", "source": "卢梭《社会契约论》", "concept": "公意所在", "explanation": "一个决定若只让少数人得利，就很难说是“我们”的决定。讨论公共事务时，试着从共同好处出发；但也别把自己的偏好冒充公意。共同不是口号。", "western": "卢梭的公意不同于多数票的总和，接近《礼记》“天下为公”；但卢梭以契约和主权者构造公意，儒家以礼与民心想象公共善。", "tags": ["社交", "反思", "专注"]},
    {"id": "w1-113", "text": "谁拒绝服从公意，谁就被迫自由。", "source": "卢梭《社会契约论》", "concept": "被迫自由", "explanation": "这句话很危险，也很深刻：自由不是想做什么就做什么，而是按共同认可的规则生活。边界感本身就是自由的一部分；但规则必须真的经过同意。", "western": "卢梭的“被迫自由”把自由与强制捆在一起，后来成为对极权主义的重要警告；与孔子“克己复礼为仁”相比，二者都讲自我约束，但卢梭的约束来自政治共同体。", "tags": ["烦躁", "社交", "反思"]},
    {"id": "w1-114", "text": "大自然希望儿童在成人以前就是儿童。", "source": "卢梭《爱弥儿》", "concept": "儿童之序", "explanation": "别急着把孩子或自己催熟。每个阶段有它的任务，先把这个阶段过好，后面的成熟才有根；慢一点，不等于落后，生长有它自己的钟。每个阶段都有光。", "western": "卢梭的消极教育尊重儿童的自然节律，与王阳明“童子之心”、李贽“童心说”相近；但卢梭把它写成教育方法，晚明童心说更多是对伪道学的批判。", "tags": ["期待", "舒展", "反思"]},
    {"id": "w1-115", "text": "劳动是社会的义务。", "source": "卢梭《爱弥儿》", "concept": "劳动之责", "explanation": "劳动不只是谋生，也是你和世界发生关系的方式。哪怕是一份小事，认真做，也会长出一点自尊；但别让劳动吞掉全部生活。劳动也需要休息。", "western": "卢梭把劳动视为公民独立的基础，与孟子“劳心者治人”的分工论不同，更接近墨家“赖其力者生”；但卢梭仍把劳动放进社会契约，墨家放在兼爱互助。", "tags": ["疲惫", "专注", "社交"]},
    {"id": "w1-116", "text": "有两样东西，我越想越充满敬畏：头顶的星空和心中的道德律。", "source": "康德《实践理性批判》", "concept": "星空道德律", "explanation": "一边是浩瀚的宇宙，一边是内心“我应该”的声音。前者让你谦卑，后者让你知道自己不只是被环境推着走；敬畏不是害怕，是知道边界。边界让人自由。", "western": "康德的敬畏把自然必然与道德自由并置，是近代主体哲学的高峰，与孔子“畏天命”“畏圣人之言”相比，康德的敬畏对象是理性自身的法则。", "tags": ["夜晚", "平静", "反思"]},
    {"id": "w1-117", "text": "要只按照你同时愿意它成为普遍法则的准则去行动。", "source": "康德《实践理性批判》", "concept": "普遍立法", "explanation": "做决定前问一句：如果所有人都这样做，世界还能运转吗？这个测试不能替你选，但能帮你排除明显自私的选项；它要求的是可普遍化。先问，再行动。", "western": "康德的绝对命令要求意志自我立法，与孔子“己所不欲，勿施于人”的恕道相近；但康德诉诸普遍化形式，孔子诉诸推己及人的具体关系。", "tags": ["反思", "专注", "社交"]},
    {"id": "w1-118", "text": "人是目的，不是手段。", "source": "康德《实践理性批判》", "concept": "人是目的", "explanation": "不要把自己或别人只当成工具。任何目标都不值得以吞掉一个人的尊严为代价，这条底线要守住；它也包括不把自己当成实现别人期待的工具。", "western": "康德的目的公式把人格尊严置于一切交换之外，与孟子“人人有贵于己者”、儒家“天地之性人为贵”相近；但康德根据理性自律，儒家根据德性天爵。", "tags": ["社交", "反思", "舒展"]},
    {"id": "w1-119", "text": "思想无内容则空，直观无概念则盲。", "source": "康德《纯粹理性批判》", "concept": "内容与概念", "explanation": "只有感受没有思考，会迷路；只有概念没有感受，会变硬。好的判断，总是让经验和框架互相校正；读书和做事，也是同一个道理。两边都要练。", "western": "康德以感性与知性的合作说明知识如何可能，接近朱熹“格物”与“豁然贯通”的结合；但康德划出不可知的物自体，朱熹相信天理可穷。", "tags": ["阅读", "专注", "反思"]},
    {"id": "w1-120", "text": "我不得不悬置知识，以便为信仰留出位置。", "source": "康德《纯粹理性批判》", "concept": "限制知识", "explanation": "承认理性的边界，不是投降，而是给那些不能被证明的东西留一点空间：信任、爱、意义，都不完全靠论证活着；但留空间不等于放弃求真。边界不是墙。", "western": "康德以限制知识保护信仰，与维特根斯坦“对于不可言说者应保持沉默”同属划界思维；与禅宗“说似一物即不中”相比，康德仍要守住理性的合法领域。", "tags": ["反思", "迷茫", "平静"]},
    {"id": "w1-121", "text": "美是无利害的愉悦对象。", "source": "康德《判断力批判》", "concept": "无利害之美", "explanation": "真正的审美不急着占有。看一朵花时，不把它折回家，也能在那一刻觉得好，这种愉悦比较轻；轻，才留得住，也才更接近自由，也不必急着拥有。", "western": "康德把审美从欲望和概念中分离，与庄子“无用之用”、苏轼“寓意于物而不留意于物”相近；但康德以主观的普遍性说明共通感，中国更重物我相忘。", "tags": ["舒展", "平静", "放空"]},
    {"id": "w1-122", "text": "凡是合乎理性的都是现实的，凡是现实的都是合乎理性的。", "source": "黑格尔《法哲学原理》", "concept": "理性与现实", "explanation": "这不是说眼前一切都合理，而是说现实有其内在逻辑。理解它为何如此，才谈得上改变它；先看懂，再动手，别把存在当成应该。理解是改变的前一步。", "western": "黑格尔的命题把理性与历史过程统一，后来被马克思倒转成“存在决定意识”；与王夫之“理在气中”相近，但黑格尔的理性是自我展开的精神。", "tags": ["反思", "迷茫", "专注"]},
    {"id": "w1-123", "text": "密涅瓦的猫头鹰要等黄昏才起飞。", "source": "黑格尔《法哲学原理》", "concept": "黄昏之思", "explanation": "智慧常常在事情发生后才来。别因为当时没看懂就责怪自己，回望本身也是理解的一部分；但要记得，黄昏之后还有新的清晨。反思来得晚，也算来。", "western": "黑格尔以此说明哲学是对已完成之事的反思，与孔子“温故而知新”、章学诚“六经皆史”相近；但黑格尔把反思放进世界精神的历史，儒家放进经典与人事。", "tags": ["反思", "夜晚", "平静"]},
    {"id": "w1-124", "text": "自我意识只有在另一个自我意识中才得到满足。", "source": "黑格尔《精神现象学》", "concept": "承认之争", "explanation": "人需要被看见，也需要看见别人。一个人若长期不被回应，很难确认自己是谁；关系因此不是奢侈品，而是自我形成的条件，但也别把全部自己交出去。", "western": "黑格尔的主奴辩证法把承认写成自我意识的构成条件，与孟子“知言养气”、儒家“成己成物”相比，黑格尔强调冲突与斗争，儒家强调推己与感通。", "tags": ["社交", "孤独", "反思"]},
    {"id": "w1-125", "text": "真理是整体，但整体只是通过自身发展而完成。", "source": "黑格尔《精神现象学》", "concept": "真理整体", "explanation": "别用一个片段给整个人生下结论。把时间拉长、把视角放宽，你看到的矛盾可能只是整体的一部分；但整体不是现成答案，它要慢慢长。整体需要耐心。", "western": "黑格尔以整体性反对片面的知性判断，与庄子“道通为一”、华严“一即一切”相近；但黑格尔的整体是辩证进展的总体，庄子的“一”是齐物后的无分别。", "tags": ["迷茫", "反思", "专注"]},
    {"id": "w1-126", "text": "世界是我的表象，而不是物自体。", "source": "叔本华《作为意志和表象的世界》", "concept": "世界表象", "explanation": "你看到的世界，经过你的感官和大脑加工。它不是假的，但也不是全部；对同一个处境，别人真的会看到不同，先别急着判定谁对谁错，先看看彼此站在哪里。", "western": "叔本华从康德的现象界出发，把世界化为意志的表象，与佛教“万法唯识”、王阳明“心外无物”常被并论；但叔本华保留一个盲目的意志本体。", "tags": ["迷茫", "反思", "阅读"]},
    {"id": "w1-127", "text": "人生在痛苦与无聊之间来回摇摆。", "source": "叔本华《作为意志和表象的世界》", "concept": "苦与无聊", "explanation": "欲望没满足时痛苦，满足后又无聊。看清这个循环，不必绝望；给生活找一点不靠“得到”的乐趣，比如走路、发呆、看云，那也是一种抵抗。给欲望放个假。", "western": "叔本华的悲观主义把欲望写成生存的根，与佛教“求不得苦”、老子“祸莫大于不知足”相近；但叔本华以审美和禁欲求解脱，佛教以八正道。", "tags": ["疲惫", "低落", "放空"]},
    {"id": "w1-128", "text": "审美观照是意志的暂时解脱。", "source": "叔本华《作为意志和表象的世界》", "concept": "审美解脱", "explanation": "看一幅画、听一段音乐时，你会短暂忘记“我想要什么”。那种不被欲望追赶的时刻，就是休息；它不解决问题，却让你喘一口气。喘口气，再回去。", "western": "叔本华把艺术视为摆脱意志的片刻，与庄子“心斋坐忘”、禅宗“无心”相近；但叔本华的艺术只是暂时，庄子的忘我则通向与道合一。", "tags": ["放空", "休息", "舒展"]},
    {"id": "w1-129", "text": "信仰是一次纵身跳跃。", "source": "克尔凯郭尔《恐惧与颤栗》", "concept": "信仰之跃", "explanation": "有些决定无法等证据齐全。看清风险后仍愿意迈出那一步，这就是信念；它不等于盲目，而是承担不确定，并为自己的选择负责。跃之前，先看清。", "western": "克尔凯郭尔的“跃”强调信仰不可由理性推演，与禅宗“顿悟”形似；但克尔凯郭尔保留一个位格的上帝与个体的决断，禅宗则扫相归空。", "tags": ["迷茫", "期待", "焦虑"]},
    {"id": "w1-130", "text": "单个的人，高于普遍。", "source": "克尔凯郭尔《恐惧与颤栗》", "concept": "个体高于普遍", "explanation": "有时多数人的道理，压不住你内心真实的召唤。不是鼓励任性，而是提醒：你最终要为自己的选择负责，不能把责任推给“大家都这样”。承担，而不是逃。", "western": "克尔凯郭尔以亚伯拉罕献子说明个体对普遍的悬置，与孟子“人人有贵于己者”的个体尊严不同；一个走向信仰的悖论，一个走向德性的普遍。", "tags": ["孤独", "反思", "焦虑"]},
    {"id": "w1-131", "text": "亚伯拉罕凭着荒诞而相信。", "source": "克尔凯郭尔《恐惧与颤栗》", "concept": "荒诞之信", "explanation": "有些相信不靠计算，也不靠胜算。它是在所有证据都说“不可能”时，仍愿意迈出一步；这不是愚蠢，而是把生命押在一种更大的可能上。信，也要承担。", "western": "克尔凯郭尔以亚伯拉罕写“荒诞”的信仰，与庄子“知其不可奈何而安之若命”不同；一个在不可能中向上跃，一个在必然中向下安。", "tags": ["迷茫", "期待", "焦虑"]},
    {"id": "w1-132", "text": "上帝死了，是我们杀死了他。", "source": "尼采《快乐的科学》", "concept": "上帝之死", "explanation": "这不是庆祝，而是诊断：旧的价值根基松动了。人必须自己面对“为什么活”，不能再等一个现成答案；自由因此变重，而不是变轻。重估，从自己开始。", "western": "尼采的“上帝之死”宣告西方形而上学与基督教价值的危机，与孔子“天何言哉”后的自力、禅宗“逢佛杀佛”都有破除权威的面向；但尼采要求重估一切价值。", "tags": ["迷茫", "反思", "孤独"]},
    {"id": "w1-133", "text": "人是一根绳索，系在动物与超人之间。", "source": "尼采《查拉图斯特拉如是说》", "concept": "人之绳索", "explanation": "人不是终点，而是过渡。你现在的样子不必是最终版本，但也别急着飞越；先承认自己还在路上，走好脚下这一段，绳索也需要两端。在路上，就够了。", "western": "尼采以超人作为人的自我超越，与《易传》“天行健，君子以自强不息”形似；但尼采的超人立法于自身，儒家的君子则效法天地。", "tags": ["迷茫", "期待", "专注"]},
    {"id": "w1-134", "text": "我的时代还没有到来，有些人死后方生。", "source": "尼采《查拉图斯特拉如是说》", "concept": "迟到的时代", "explanation": "不被当下理解，不代表你没有价值。有些想法、作品和生活方式需要时间发酵；先把它做出来，再安静地交给时间，你不必向每个路过的人证明。", "western": "尼采以“死后出生”写思想的时间差，与司马迁“藏之名山，传之其人”相近；但尼采期待未来的读者，司马迁相信后世知音，二者都把孤独交给时间。", "tags": ["孤独", "期待", "专注"]},
    {"id": "w1-135", "text": "精神变为骆驼，再变为狮子，最后变为婴儿。", "source": "尼采《查拉图斯特拉如是说》", "concept": "精神三变", "explanation": "成长要经过负重、反抗和重新开始。先学会承担，再学会说“不”，最后才可能轻装上路；但婴儿不是退回无知，而是重新获得创造的天真。天真不是幼稚。", "western": "尼采的精神三变写自我超越的阶段，与禅宗“见山是山”的三重境界结构相似；但尼采的终点是创造新价值的婴儿，禅宗的终点是无执的平常心。", "tags": ["变化", "期待", "舒展"]},
    {"id": "w1-136", "text": "理论是灰色的，而生命之树常青。", "source": "歌德《浮士德》", "concept": "生命常青", "explanation": "道理讲得再漂亮，也代替不了真实的生活。别只顾着研究“该怎么活”，去吃饭、走路、见人；生命的知识，多半在书斋外面，先活，再解释。别倒过来。", "western": "歌德让浮士德从书斋走向世界，这句话成为西方对抽象理性的经典警告，与庄子“得意忘言”、禅宗“不立文字”相近；但歌德仍要人在行动中完成自己。", "tags": ["阅读", "写论文", "放空"]},
    {"id": "w1-137", "text": "停一停吧，你多么美！", "source": "歌德《浮士德》", "concept": "此刻之美", "explanation": "这是浮士德与魔鬼的赌约：若有一刻让他满足到不愿前进，他就输了。美好的一刻值得珍惜，但不必赖在那里；停留太久，也会变成牢，但你可以选择何时离开。", "western": "歌德把“停留”写成对生命的最高诱惑，与苏轼“但愿人长久”的留恋不同；浮士德必须继续行动，苏轼则在祝愿中安放有限。", "tags": ["期待", "专注", "变化"]},
    {"id": "w1-138", "text": "我心中有两个灵魂，彼此想要分离。", "source": "歌德《浮士德》", "concept": "两个灵魂", "explanation": "人常同时想要安稳和冒险、靠近和自由。不必急着消灭其中一边，先听听它们各自在保护什么；两个灵魂也可能谈到一起，别急着选边。先听着。", "western": "歌德把现代人的内在分裂写成戏剧，与《离骚》“心犹豫而狐疑兮”的徘徊相近；但浮士德的分裂由魔鬼推动为行动，屈原的徘徊最终归于人格的坚守。", "tags": ["迷茫", "烦躁", "反思"]},
    {"id": "w1-139", "text": "凡自强不息者，我们终能拯救。", "source": "歌德《浮士德》", "concept": "自强得救", "explanation": "不是没有失败，而是失败后仍愿意继续。真正把人托住的，常常是那股不肯彻底放弃的劲；但自强不等于硬撑，也要允许自己停。停也是走。", "western": "歌德把“努力”视为得救的条件，与《易传》“天行健，君子以自强不息”几乎同调；但歌德的拯救来自更高的爱，儒家则把自强落在人的德性实践。", "tags": ["低落", "专注", "舒展"]},
    {"id": "w1-140", "text": "永恒的女性，引领我们飞升。", "source": "歌德《浮士德》", "concept": "永恒女性", "explanation": "人需要一种温柔的牵引，才不至于被现实拖住。它可以是一个人、一份爱，也可以是你心里不肯熄灭的美；被牵引，不是失去自主。牵引不是束缚。", "western": "歌德以永恒女性象征超越的牵引，与《诗经》“所谓伊人，在水一方”的企慕相近；但歌德把它写成救赎结构，中国诗更多停在可望不可即的美。", "tags": ["期待", "舒展", "夜晚"]},
    {"id": "w1-141", "text": "一切无常者，不过是虚幻。", "source": "歌德《浮士德》", "concept": "无常如幻", "explanation": "失去的东西会痛，但它本来就不是永恒的。珍惜拥有时的光，也允许它在时间里改变形状；无常不是背叛，是万物的常态，看清了，反而能爱。", "western": "歌德以“无常”收束《浮士德》，与佛教“诸行无常”、《金刚经》“如梦幻泡影”相近；但歌德把无常引向爱的拯救，佛教引向解脱。", "tags": ["失去", "变化", "释然"]},
    {"id": "w1-142", "text": "美是自由在现象中的显现。", "source": "席勒《卡利亚斯书简》", "concept": "美与自由", "explanation": "美不只是好看，它让你感到自己不被功利完全绑住。看一片风景、读一首诗，都是自由的练习；自由先在感受里出现，然后才进到生活。美先于规则。", "western": "席勒把审美视为通向自由的桥梁，与孔子“兴于诗，成于乐”相近；但席勒的自由是近代主体的自律，孔子的乐则落在人格与礼乐的和谐。", "tags": ["舒展", "平静", "放空"]},
    {"id": "w1-143", "text": "只有当人游戏时，他才完全是人。", "source": "席勒《审美教育书简》", "concept": "游戏成人", "explanation": "游戏不是为了有用，而是人自愿投入的创造。给自己留一点不为产出的时间，你会在那里更完整；玩得认真，本身就是一种自由，不必先问它有什么用。", "western": "席勒以“游戏冲动”统一感性与理性，与庄子“游刃有余”“逍遥游”的“游”相近；但席勒的游是审美教育，庄子的游是体道之境。", "tags": ["放空", "舒展", "休息"]},
    {"id": "w1-144", "text": "拥抱吧，亿万人民！这一吻献给全世界！", "source": "席勒《欢乐颂》", "concept": "万民之抱", "explanation": "快乐到了极处，会想分给别人。别把好东西攥得太紧；分享不会让它变少，反而会让它更真，也会把你和别人连在一起，一起唱才响，也才不至于走散。", "western": "席勒的《欢乐颂》把个体之爱扩展为人类大同，与《礼运》“天下大同”、张载“民胞物与”相近；但席勒诉诸审美与自由，儒家诉诸礼与仁。", "tags": ["社交", "舒展", "感激"]},
    {"id": "w1-145", "text": "哪里有危险，哪里就生长拯救。", "source": "荷尔德林《帕特莫斯》", "concept": "危中有救", "explanation": "最难的处境里，也常藏着转机。不是美化痛苦，而是提醒自己：别在危险面前把可能性全部关掉；拯救往往从看见危险、承认危险开始，而不是等它自己消失。", "western": "荷尔德林把这句诗放进历史诸神的来临与离去，海德格尔后来用它解释技术的危险与救渡；与老子“祸兮福之所倚”相近，但荷尔德林仍期待神的踪迹。", "tags": ["低落", "焦虑", "期待"]},
    {"id": "w1-146", "text": "在贫困的时代，诗人何为？", "source": "荷尔德林《面包与酒》", "concept": "诗人何为", "explanation": "当意义变得稀薄，仍有人愿意把感受说出来。你不一定是诗人，但你可以为自己的生活保留一点表达；说出来的，才不会完全消失。说，就是抵抗。", "western": "荷尔德林把诗人的职责放在诸神缺席的时代，海德格尔由此讨论“贫困时代”的栖居；与孔子“道不行，乘桴浮于海”的担当不同，诗人以言说守护存在。", "tags": ["迷茫", "孤独", "阅读"]},
    {"id": "w1-147", "text": "如果你觉得生活贫乏，不要抱怨生活，要怨你自己。", "source": "里尔克《给青年诗人的信》冯至译", "concept": "生活与诗", "explanation": "生活未必变好了，但你可以变得更能看见。培养一点感受力，普通的日子也会多出一些纹理；别急着怪生活，先看看自己的镜头。镜头可以换。", "western": "里尔克把贫乏归因于主体的感受力，与王国维“以我观物，故物皆著我之色彩”相近；但里尔克要求诗人向内成熟，王国维讲境界的生成。", "tags": ["低落", "阅读", "反思"]},
    {"id": "w1-148", "text": "让每一个印象在自身中成熟。", "source": "里尔克《给青年诗人的信》冯至译", "concept": "印象之熟", "explanation": "刚发生的事不必立刻解释。把它放在心里一段时间，等情绪沉淀，你才知道它真正教会了你什么；成熟需要不被催促的时间，你不必今天就交出答案。", "western": "里尔克把创作理解为耐心的等待，与苏轼“博观而约取，厚积而薄发”相近；但里尔克强调不可催促的内在成熟，苏轼强调学问的积累。", "tags": ["专注", "休息", "反思"]},
    {"id": "w1-149", "text": "美不过是恐怖的开端。", "source": "里尔克《杜伊诺哀歌》", "concept": "美与恐怖", "explanation": "真正打动你的美，常带一点让人发颤的东西。别急着把这种不安压下去，它可能是更深感受的入口；美不负责让你舒服，它负责让你醒，哪怕醒着并不舒服。", "western": "里尔克延续浪漫派对崇高的改写，把美与可怕并置；这与康德“崇高”、庄子“大美不言”都可对照：一个在震撼中超出感官，一个在无言中与道相遇。", "tags": ["夜晚", "反思", "舒展"]},
    {"id": "w1-150", "text": "每个天使都是可怕的。", "source": "里尔克《杜伊诺哀歌》", "concept": "天使之畏", "explanation": "那些看起来完美、强大、不可企及的东西，也会让人害怕。面对它们时，承认自己的渺小，不必假装镇定；但也不必跪下去，平视，才看得清。平视就好。", "western": "里尔克的天使不是宗教安慰，而是绝对存在的尺度，接近《庄子》“藐姑射之山”的神人；但里尔克在天使面前感到人的限度，庄子则借此打开逍遥的想象。", "tags": ["焦虑", "夜晚", "反思"]},
    {"id": "w1-151", "text": "对心中尚未解决的一切保持耐心。", "source": "里尔克《给青年诗人的信》冯至译", "concept": "耐心待问", "explanation": "不是每个问题都要今天想通。允许它先待在那里，继续生活、继续积累，答案会在某个时刻自己靠近；耐心不是拖延，是不逼自己。等，也是行动。", "western": "里尔克把“问题”当作需要被爱而非被解决的对象，与禅宗“只管打坐”、庄子“忘年忘义”的等待相近；但里尔克仍相信问题会成熟为答案。", "tags": ["焦虑", "专注", "平静"]},
    {"id": "w1-152", "text": "我辽阔广大，我包罗万象。", "source": "惠特曼《草叶集》", "concept": "自我之广", "explanation": "人不是单一标签。你身上可以同时有矛盾和多重面向，不必为了符合某个定义，把其余部分剪掉；辽阔也需要边界，容纳不等于没有原则。", "western": "惠特曼以“multitudes”写现代自我的复数性，与庄子“吾丧我”相反：惠特曼要扩张并拥抱全部自我，庄子要放下固定的自我；一个向外收，一个向内空。", "tags": ["舒展", "社交", "反思"]},
    {"id": "w1-153", "text": "我赞美我自己，歌唱我自己。", "source": "惠特曼《草叶集》", "concept": "自我之歌", "explanation": "自我肯定不是自恋。承认自己的存在本身值得歌唱，才有余力去真正看见别人；先把自己的灯点亮，灯亮了，才照得见路，也照得见人，不必等别人来点。", "western": "惠特曼把民主的平等写进自我赞歌，与《论语》“君子求诸己”、孟子“万物皆备于我”相比，惠特曼的自我是身体与欲望的全面肯定。", "tags": ["舒展", "专注", "晨间"]},
    {"id": "w1-154", "text": "我听见美洲在歌唱。", "source": "惠特曼《草叶集》", "concept": "众声之歌", "explanation": "一个共同体不只有一种声音。机械工、木匠、母亲、船夫都在唱；学会听见那些不在中心的声音，也允许自己的声音被听见，众声才是城，也才是真正的合唱。", "western": "惠特曼以复调写民主共同体，与《诗经》“国风”采集民间声音的结构相近；但惠特曼的民主是横向的平等并置，国风仍处在礼乐秩序的框架中。", "tags": ["社交", "舒展", "阅读"]},
    {"id": "w1-155", "text": "希望是长着羽毛的东西，栖在灵魂里。", "source": "狄金森《诗集》", "concept": "希望之翼", "explanation": "希望很轻，却能在最冷的时候留住一点温度。它不解决现实，但让你还愿意等到明天；别小看那一点不肯熄灭的东西，它一直在你里面。它很倔。", "western": "狄金森把希望写成内在的、无须证明的存在，与《周易》“复”卦一阳来复的微生意象相近；但狄金森的希望是私人的鸟，《周易》的复是宇宙的节律。", "tags": ["低落", "期待", "夜晚"]},
    {"id": "w1-156", "text": "我是无名之辈！你是谁？", "source": "狄金森《诗集》", "concept": "无名之问", "explanation": "不出名也可以过得很好。若你也在人群里感到自己渺小，这句话像一次悄悄的握手：我们都是无名之辈；但无名不等于无价值。无名也完整。", "western": "狄金森以反讽拒绝名声的公共尺度，与陶渊明“不为五斗米折腰”、庄子“名者，实之宾也”相近；但狄金森的退守是私密的灵魂空间，陶渊明归向田园。", "tags": ["孤独", "平静", "反思"]},
    {"id": "w1-157", "text": "如果我能让一颗心免于破碎，我便没有白活。", "source": "狄金森《诗集》", "concept": "免于心碎", "explanation": "意义不一定来自大成就。今天让一个人少难过一点，你的存在就已经有了分量；善可以很小，小到只是一句“我在”，也足够真，足够让今天不同。", "western": "狄金森把伦理意义缩小到具体的一个人，与孟子“亲亲而仁民”的推恩结构不同；狄金森不追求普遍功业，只在近处完成一件小事。", "tags": ["感激", "社交", "舒展"]},
    {"id": "w1-158", "text": "说出全部真理，但要绕着说。", "source": "狄金森《诗集》", "concept": "真理之斜", "explanation": "真话不必总是直愣愣地砸过去。换一个角度、留一点余地，别人更可能听得进去，你也更安全；绕不是为了骗，是为了让话真的到达，也让你不必伤人。", "western": "狄金森把迂回视为真理的传播方式，与《左传》引孔子“言之无文，行而不远”、庄子“寓言十九”相近；但狄金森更关注心灵的承受力，孔子更关注表达的文采与礼度。", "tags": ["社交", "反思", "写论文"]},
    {"id": "w1-159", "text": "大多数人在平静的绝望中生活。", "source": "梭罗《瓦尔登湖》", "concept": "平静绝望", "explanation": "不是所有痛苦都会喊出来。有些人只是安静地过着不适合自己的生活；承认这种绝望，是改变的第一步，别把它当成正常，也别习惯它，更别替它找理由。", "western": "梭罗把社会性的顺从诊断为“平静的绝望”，与鲁迅“铁屋子”的隐喻相近；但梭罗退到自然中寻找另一种可能，鲁迅则在黑暗中坚持呐喊。", "tags": ["低落", "迷茫", "反思"]},
    {"id": "w1-160", "text": "每一个早晨都是一个愉快的邀请。", "source": "梭罗《瓦尔登湖》", "concept": "清晨之邀", "explanation": "早晨不只是打卡的开始。把它当成一次邀请，问自己今天想把生活过成什么样，哪怕只兑现一小部分；清晨的光会替你壮胆。今天也算数。", "western": "梭罗把清晨写成生活实验的起点，与《大学》“苟日新”、陶渊明“晨兴理荒秽”相近；但梭罗的早晨是个体自愿的简朴，陶渊明的晨兴带着生计与归隐。", "tags": ["晨间", "期待", "舒展"]},
    {"id": "w1-161", "text": "一个人的富有，与他能放下多少东西成正比。", "source": "梭罗《瓦尔登湖》", "concept": "放下之富", "explanation": "真正的宽裕，不是拥有得多，而是不被拥有物牵着走。能放下一点，你就多一分自由；少一点维护，多一点生活，放下不是失去，是腾出手，去拿真正想要的东西。", "western": "梭罗把财富重新定义为自由，与《老子》“知足者富”、庄子“无用之用”相近；但梭罗仍以个人生活的实验来衡量，老子则以道的尺度衡量。", "tags": ["疲惫", "释然", "平静"]},
    {"id": "w1-162", "text": "湖泊是大地的眼睛。", "source": "梭罗《瓦尔登湖》", "concept": "大地之眼", "explanation": "自然也有它看世界的方式。站在水边，你会发现自己的心事被放大，也被慢慢收走一点；水不说话，却一直在听，看久了，心会清。水会替你收。", "western": "梭罗把自然写成有灵性的存在，与王维“行到水穷处，坐看云起时”的物我相融相近；但梭罗的自然仍是个体沉思的镜面，王维的自然更接近空寂。", "tags": ["平静", "放空", "休息"]},
    {"id": "w1-163", "text": "自然是精神的象征。", "source": "爱默生《随笔集》", "concept": "自然象征", "explanation": "你看见的风景，常常照出你的心境。不是自然变了，而是你看它的眼睛变了；可以去外面走走，换一换眼睛，也换一换心里的天气。心晴了，景也晴。", "western": "爱默生把自然视为精神的对应物，与庄子“天地与我并生，万物与我为一”相近；但爱默生的自然是个人灵魂的象征，庄子的自然是齐物的场域。", "tags": ["平静", "舒展", "放空"]},
    {"id": "w1-164", "text": "社会处处密谋反对每个成员的独立人格。", "source": "爱默生《随笔集》", "concept": "社会与自我", "explanation": "群体有它的惯性，会奖励顺从、惩罚不同。合群很重要，但别把“大家都能接受”当成唯一标准；有时候，孤独是保持清醒的代价。清醒要付代价。", "western": "爱默生对社会的警惕延续了清教个人主义，与庄子对“世俗之礼”的批判、尼采对群体道德的批判都有回声；但爱默生仍相信个体的自我完善。", "tags": ["社交", "孤独", "反思"]},
    {"id": "w1-165", "text": "相信你自己的思想，相信你内心深处认为对的东西。", "source": "爱默生《随笔集》", "concept": "自信之思", "explanation": "别人的建议只能参考。若一件事在你心里反复亮起，值得给它一次认真对待的机会；相信自己，不等于不听别人，是听完之后，仍愿意负责。", "western": "爱默生的自立把直觉置于传统权威之上，与王阳明“求之于心”、禅宗“自性自度”相近；但爱默生的自信服务于个人天才，阳明的良知通向天理。", "tags": ["专注", "期待", "反思"]},
    {"id": "w1-166", "text": "自信是成功的第一个秘诀。", "source": "爱默生《随笔集》", "concept": "自信之始", "explanation": "不是先有能力才自信，而是先愿意相信自己，能力才有机会长出来。先迈一步，再让证据跟上；自信不是空喊，是敢试，试过才作数，失败也算一次证据。", "western": "爱默生把自信写成自我实现的前提，与《论语》“君子求诸己”相近；但爱默生的自信是个人主义的起点，儒家的求己则通向成己成物。", "tags": ["专注", "期待", "舒展"]},
    {"id": "w1-167", "text": "比海洋更宽阔的是天空，比天空更宽阔的是人的心灵。", "source": "雨果《悲惨世界》", "concept": "心之辽阔", "explanation": "人的内心能装下比眼前更大的东西。别把自己缩小成一份成绩或一个身份，你比那些标签宽得多；心宽了，路也会宽一点，容得下别人，也容得下自己。", "western": "雨果把心灵写成无限的容器，与孟子“万物皆备于我”、陆九渊“宇宙便是吾心”相近；但雨果仍以人道主义为尺度，陆九渊以心即理为根本。", "tags": ["舒展", "低落", "平静"]},
    {"id": "w1-168", "text": "只要世上还有愚昧和困苦，这样的书就不会无用。", "source": "雨果《悲惨世界》", "concept": "人道之光", "explanation": "再正确的目标，也不能把人只当成代价。做选择时，先守住对人的基本尊重；有些胜利，若踩着具体的人上去，就已经输了，也丢掉了最初的自己。", "western": "雨果的人道主义继承基督教爱与启蒙博爱，与孟子“仁者爱人”、墨子“兼爱”相近；但雨果把它放在革命政治的悲剧之后，作为对暴力的校正。", "tags": ["反思", "社交", "平静"]},
    {"id": "w1-169", "text": "幸福的家庭都是相似的，不幸的家庭各有各的不幸。", "source": "托尔斯泰《安娜·卡列尼娜》", "concept": "幸福与不幸", "explanation": "幸福有共同的骨架：尊重、沟通、边界；不幸却各有各的破口。别拿别人的幸福模板硬套自己的关系，先看清你们缺的是哪一块。先补那一块。", "western": "托尔斯泰以家庭写社会与道德的裂缝，与《红楼梦》“大有大的难处”的家族叙事相近；但托尔斯泰要人在爱与合作中重建，曹雪芹更多看见盛衰无常。", "tags": ["社交", "低落", "反思"]},
    {"id": "w1-170", "text": "最强大的战士是时间和耐心。", "source": "托尔斯泰《战争与和平》", "concept": "时间与耐心", "explanation": "有些事急不来。时间会磨掉一部分痛，也会给耐心的人让出空间；先别在今天就要求终局，有些答案要等走完一段路，耐心不是被动。等，也是在走。", "western": "托尔斯泰把历史写成时间与耐心的合力，与老子“柔弱胜刚强”“大器晚成”相近；但托尔斯泰仍相信个人的道德努力，老子更重不争与无为。", "tags": ["焦虑", "专注", "平静"]},
    {"id": "w1-171", "text": "艺术是传达情感的活动。", "source": "托尔斯泰《艺术论》", "concept": "艺术传情", "explanation": "好的作品不是炫技，而是把一种感受交到你手里。看完之后你说不出道理，却知道自己被碰到了；艺术先动心，再动脑，别急着分析。先感受，再解释。", "western": "托尔斯泰以情感传达定义艺术，接近《毛诗序》“情动于中而形于言”；但托尔斯泰要求艺术服务于人类的道德团结，中国诗论更重兴观群怨与言志。", "tags": ["阅读", "放空", "舒展"]},
    {"id": "w1-172", "text": "人不是靠为自己操心活着，而是靠爱活着。", "source": "托尔斯泰《人靠什么活着》", "concept": "因爱而活", "explanation": "只顾自己，反而越活越窄。把一点注意力分给别人——听他说完、搭一把手——你会发现自己也被悄悄托住了；爱不是牺牲，是让生命有了出口。爱要有出口。", "western": "托尔斯泰把爱写成生存的根据，与孔子“仁者爱人”、孟子“恻隐之心”相近；但托尔斯泰的爱带有福音书的绝对要求，儒家的仁则在亲疏差等中展开。", "tags": ["社交", "感激", "舒展"]},
    {"id": "w1-173", "text": "如果没有上帝，是否一切都允许？", "source": "陀思妥耶夫斯基《卡拉马佐夫兄弟》", "concept": "无神之问", "explanation": "当外部约束消失，人靠什么守住底线？这个问题没有轻松答案，但它提醒你：自由需要自己承担；没有答案时，先不伤害，就是最低的底线。不伤害，是起点。", "western": "陀思妥耶夫斯基以此追问道德的本体论基础，与尼采的虚无主义诊断并列；与孟子“四端”相比，陀氏不信任人性自足，宁可把善放在信仰与受苦里。", "tags": ["迷茫", "反思", "焦虑"]},
    {"id": "w1-174", "text": "爱生活本身，甚于爱它的意义。", "source": "陀思妥耶夫斯基《卡拉马佐夫兄弟》", "concept": "爱生活本身", "explanation": "别等到想明白“为什么活”才开始活。先吃饭、走路、抱一抱身边的人，意义常在生活的后面追上来；生活比解释更早，也更宽，值得你先走进去。", "western": "陀思妥耶夫斯基让阿辽沙以具体的生活否定抽象的意义，与禅宗“平常心是道”、陶渊明“此中有真意”相近；但陀氏仍把生活放在东正教的复活希望里。", "tags": ["舒展", "低落", "平静"]},
    {"id": "w1-175", "text": "每个人都对所有人、所有事负有罪责。", "source": "陀思妥耶夫斯基《卡拉马佐夫兄弟》", "concept": "普遍罪责", "explanation": "这不是要你扛下所有错，而是承认人与人相连。你的一次冷漠或一次善意，都会在别处留下回声；责任因此不是负担，是关系。关系就是责任。", "western": "陀思妥耶夫斯基的普遍罪责观接近基督教的原罪与连带，与张载“民胞物与”、孟子“不忍人之心”相比，陀氏更强调共同体的罪与救赎。", "tags": ["社交", "反思", "低落"]},
    {"id": "w1-176", "text": "地狱就是“不能再爱”的痛苦。", "source": "陀思妥耶夫斯基《卡拉马佐夫兄弟》", "concept": "地狱之爱", "explanation": "最深的苦，不是没人爱你，而是你发现自己已经爱不动了。先恢复一点力气，再谈原谅和靠近；地狱不是地方，是一种封闭，门可以从里面开。", "western": "陀思妥耶夫斯基把地狱从物理场所改写为爱的无能，与佛教以嗔火喻地狱、孟子“麻木不仁”的隐喻相近；但陀氏的解药是主动的爱与信仰。", "tags": ["孤独", "低落", "释然"]},
    {"id": "w1-177", "text": "人的一切都应当是美的：面孔、衣裳、心灵和思想。", "source": "契诃夫《海鸥》", "concept": "全人之美", "explanation": "美不只是外表，也不只是内在。把自己收拾干净、把心放柔软、把想法理清楚，都是对自己的照顾；体面不是虚荣，是尊重，从今天的一件小事开始。", "western": "契诃夫把审美扩展到人的整体，接近《论语》“文质彬彬，然后君子”；但契诃夫更重日常生活的体面与温柔，孔子更重礼乐对人格的塑造。", "tags": ["晨间", "舒展", "专注"]},
    {"id": "w1-178", "text": "幸福的人之所以幸福，只是因为不幸的人在沉默地承受。", "source": "契诃夫《醋栗》", "concept": "幸福之默", "explanation": "你的安稳背后，可能有人在替你承担。看见这一点，不会让你不敢幸福，而会让你多一点感激和体谅；幸福也可以带着歉意去分享，而不是假装看不见。", "western": "契诃夫以社会结构拆解幸福，与杜甫“朱门酒肉臭，路有冻死骨”的对照相近；但契诃夫更冷静地写日常的麻木，杜甫的控诉更直接。", "tags": ["感激", "社交", "反思"]},
    {"id": "w1-179", "text": "少数派永远是对的。", "source": "易卜生《人民公敌》", "concept": "少数之真", "explanation": "这不是说少数一定正确，而是提醒：多数也会错。别因为人少就否定自己，也别因为人多就放弃判断；少数也需要理由，不是姿态。理由比姿态重要。", "western": "易卜生借斯多克芒医生写真理与共同体的冲突，与屈原“举世皆浊我独清”、鲁迅对庸众的批判相近；但易卜生仍相信个体可以推动社会更新。", "tags": ["孤独", "社交", "反思"]},
    {"id": "w1-180", "text": "世上最强大的人，是那个最孤独的人。", "source": "易卜生《人民公敌》", "concept": "孤独之强", "explanation": "能独自站稳的人，反而不容易被裹挟。孤独不总是可怜，它也可能是一种力量的形状；但别把孤立当成荣耀，仍要留一扇门，让风进来，也让人进来。", "western": "易卜生把孤独写成个体对抗多数的手段，与尼采的“更高的人”相近；与庄子“独与天地精神往来”相比，易卜生的孤独仍要在社会中争取承认。", "tags": ["孤独", "专注", "舒展"]},
    {"id": "w1a-01", "text": "如果幸福在于肉体的快感，那么牛找到草吃时也是幸福的。", "source": "赫拉克利特《残篇》", "concept": "幸福之辨", "explanation": "把快乐只等同于满足欲望，就把人降低到动物的层面。真正的满足还包括清醒、友谊和不被欲望牵着走。", "western": "赫拉克利特用牛的比喻批评单纯享乐，与伊壁鸠鲁区分纵欲与身体无痛相近；但他更强调逻各斯的尺度。", "tags": ["焦虑", "反思", "释然"]},
    {"id": "w1a-02", "text": "人的性格就是他的命运。", "source": "赫拉克利特《残篇》", "concept": "性格即命运", "explanation": "反复出现的反应，慢慢成了性格；性格又替你选出常走的路。想改命，先看看自己在小事上怎样回应。", "western": "赫拉克利特将性格视为命运的源头，强调日常选择会沉淀为人生走向；《中庸》说“率性之谓道”，更信任本性展开。", "tags": ["反思", "迷茫", "专注"]},
    {"id": "w1a-03", "text": "博学并不能使人智慧。", "source": "赫拉克利特《残篇》", "concept": "博学非智", "explanation": "读得多、知道得多，不等于看得透。把知识放回具体处境，问它能否帮你判断和行动，才算向智慧靠近。", "western": "赫拉克利特区分见闻与智慧，接近孔子“学而不思则罔”；但他更强调把握万物共通的逻各斯。", "tags": ["阅读", "专注", "反思", "迷茫"]},
    {"id": "w1a-04", "text": "不要用眼睛和耳朵判断，要用理性裁决。", "source": "巴门尼德《残篇》", "concept": "理性裁决", "explanation": "感官看到的多是片段，容易被一时的表象带走。遇到大事，先把看到的、听到的放一放，让理性把线索重新排一遍。", "western": "巴门尼德把真理之路交给理性，开启西方理性主义传统；这与荀子“解蔽”相通，都要求越过感官的局限。", "tags": ["专注", "反思", "迷茫"]},
    {"id": "w1a-05", "text": "存在者不能从不存在者产生。", "source": "巴门尼德《残篇》", "concept": "存在不生", "explanation": "一件事不会凭空出现。看似突然的结果，往往有没被看见的条件；去找那条来路，比停在惊讶里更有用。", "western": "巴门尼德以此否定生成与毁灭，与老子“有无相生”形成对照：一个守住存在，一个让有无互相转化。", "tags": ["变化", "反思", "写论文"]},
    {"id": "w1a-06", "text": "未经省察的人生不值得过。", "source": "苏格拉底（柏拉图《申辩篇》转述）", "concept": "省察人生", "explanation": "每天被事情推着走，久了会忘记自己为什么这样活。留一点时间回看：我到底在追什么，又避开了什么。", "western": "苏格拉底把哲学拉回日常，要求人为自己的选择给出理由；孔子说“吾日三省吾身”，同样把反省当作成人的工夫。", "tags": ["反思", "迷茫", "夜晚"]},
    {"id": "w1a-07", "text": "重要的不是活着，而是活得好。", "source": "苏格拉底（柏拉图《克力同篇》转述）", "concept": "活出意义", "explanation": "“活着”只是长度，“活得好”才问到质量。今天不必解决一生所有难题，只问这一件事是否对得起你想成为的人。", "western": "苏格拉底在《克力同篇》里把“好生活”置于生命之上，与孟子“舍生取义”相近；但他更强调灵魂的理性秩序。", "tags": ["反思", "低落", "专注"]},
    {"id": "w1a-08", "text": "惊奇是哲学的开端。", "source": "柏拉图《泰阿泰德篇》", "concept": "惊奇启思", "explanation": "还会觉得某件事奇怪，说明你没有把它当成理所当然。顺着这份惊奇多问一句，熟悉的世界会重新打开。", "western": "柏拉图在《泰阿泰德篇》把惊奇视为哲学家的标志，与孔子“不愤不启”都重视问题被真正感到的时刻。", "tags": ["阅读", "期待", "放空", "反思"]},
    {"id": "w1a-09", "text": "一切学习都是回忆。", "source": "柏拉图《美诺篇》", "concept": "学习即忆", "explanation": "新知识不是硬塞进来，而是把你本来就有的经验唤醒。学的时候多连回已经知道的东西，理解会比背诵更稳。", "western": "柏拉图的回忆说认为灵魂早已见过真理，学习只是重新记起；这与王阳明“心即理”相近，但更依赖超越的预设。", "tags": ["复习考试", "阅读", "专注"]},
    {"id": "w1a-10", "text": "爱是一种神圣的疯狂。", "source": "柏拉图《斐德罗篇》", "concept": "爱如狂迷", "explanation": "爱会让人离开熟悉的安全区，看到平时看不见的东西。别急着把这份失控治好，也别把它当成全部的答案。", "western": "柏拉图把爱看作灵魂回忆美的疯狂，与《诗经》“发乎情，止乎礼”形成张力：一个向上超越，一个落在节制。", "tags": ["期待", "孤独", "释然"]},
    {"id": "w1a-11", "text": "人天生是政治动物。", "source": "亚里士多德《政治学》", "concept": "政治动物", "explanation": "人要在共同体里说话、协作、争辩，才长成完整的人。别把一切关系都当负担，也别把自己关成一座孤岛。", "western": "亚里士多德把城邦视为人的自然完成，接近荀子“能群”之说；但他更强调公民参与，荀子更重礼义分工。", "tags": ["社交", "孤独", "专注"]},
    {"id": "w1a-12", "text": "悲剧借怜悯与恐惧净化情感。", "source": "亚里士多德《诗学》", "concept": "情感净化", "explanation": "看别人的故事流泪，不全是逃避。被牵动之后，心里积压的东西有了出口；散场时，把自己轻轻带回现实。", "western": "亚里士多德的“净化说”把悲剧当作情感的疏导，与孔子“诗可以怨”相近；但他更看重艺术对情绪的秩序化。", "tags": ["夜晚", "释然", "低落", "休息"]},
    {"id": "w1a-13", "text": "诗比历史更富哲学性，也更严肃。", "source": "亚里士多德《诗学》", "concept": "诗近普遍", "explanation": "历史记下个别的事，诗写出许多人共有的处境。读小说或诗时，你也在辨认自己正在经历的那一类难题。", "western": "亚里士多德认为诗写普遍，史写个别，与司马迁“究天人之际”的抱负不同：一个向普遍提纯，一个在具体中见道。", "tags": ["阅读", "写论文", "反思"]},
    {"id": "w1a-14", "text": "友谊是凡人所能有的不朽之善。", "source": "伊壁鸠鲁《梵蒂冈格言》", "concept": "友谊不朽", "explanation": "人终有一死，但朋友之间的信任和照料，能在当下抵住一点无常。别只算人脉，也留下几段经得起沉默的关系。", "western": "伊壁鸠鲁把友谊视为凡人的不朽之善，与孔子“友直，友谅，友多闻”相近；但他更看重友谊带来的心灵安稳。", "tags": ["社交", "孤独", "感激"]},
    {"id": "w1a-15", "text": "对不知足的人，没有什么是足够的。", "source": "伊壁鸠鲁《梵蒂冈格言》", "concept": "知足之难", "explanation": "欲望会把“够了”的门槛不断往前推。今天试着列一张已经够用的清单，让眼睛从缺少的东西上移开一会儿。", "western": "伊壁鸠鲁以知足界定快乐，接近老子“知足者富”；但他仍以感觉的舒适为标准，老子则要人回到无欲无为。", "tags": ["焦虑", "释然", "感激", "平静"]},
    {"id": "w1a-16", "text": "一切感觉都是真实的。", "source": "伊壁鸠鲁《致希罗多德的信》", "concept": "感觉为真", "explanation": "你此刻的累、疼或欢喜，不需要先证明才成立。先承认它真实，再问它从哪来、要怎样安放，别急着否定自己。", "western": "伊壁鸠鲁以感觉为真理标准，把哲学变成治疗；这与王阳明“知行合一”重视体验，但一个诉诸感官，一个诉诸良知。", "tags": ["疲惫", "低落", "反思"]},
    {"id": "w1a-17", "text": "宗教所招致的罪恶何其多。", "source": "卢克莱修《物性论》", "concept": "宗教之弊", "explanation": "以神之名做出的残忍，历史上并不少见。信仰若要求人放弃判断、伤害他人，就该停下来问：这真是善吗？", "western": "卢克莱修继承伊壁鸠鲁，把宗教恐惧视为人的枷锁，与荀子“君子以为文，百姓以为神”的理性态度相似，但更激烈。", "tags": ["反思", "迷茫", "平静"]},
    {"id": "w1a-18", "text": "万物消解之后，又回到最初的种子。", "source": "卢克莱修《物性论》", "concept": "万物归元", "explanation": "失去并不总是消失，也可能是拆回原来的材料。一段关系结束后，留下的经验仍会进入下一段生活，不必急着清空。", "western": "卢克莱修用原子与虚空解释生灭，接近王充“气聚气散”的自然观；但他要人借这套解释摆脱宗教恐惧。", "tags": ["失去", "变化", "释然"]},
    {"id": "w1a-19", "text": "使人不安的不是事物，而是人对事物的看法。", "source": "爱比克泰德《手册》", "concept": "看法扰人", "explanation": "同一件事，换个解释，心里的重量就不同。先分清事实和你加在上面的判断，再决定要不要为那个判断受苦。", "western": "爱比克泰德把情绪归因于判断，是斯多亚“控制二分”的延伸；这与佛教“境由心造”相近，但斯多亚仍肯定理性秩序。", "tags": ["焦虑", "烦躁", "反思", "平静"]},
    {"id": "w1a-20", "text": "困难能显出人的本色。", "source": "爱比克泰德《论说集》", "concept": "困难见人", "explanation": "顺境里大家都差不多，卡住时才看得见一个人的选择。别急着抱怨难题，它也在告诉你，自己真正看重什么。", "western": "爱比克泰德把困难当作训练德性的场地，与孟子“生于忧患”相近；他更强调区分可控与不可控，不把成败当德性。", "tags": ["烦躁", "专注", "反思"]},
    {"id": "w1a-21", "text": "先想清楚要成为什么人，再做该做的事。", "source": "爱比克泰德《手册》", "concept": "以人定事", "explanation": "光列任务清单，容易忙成别人期待的样子。先确定想成为什么样的人，再让今天的行动向那个方向靠一点。", "western": "爱比克泰德把哲学落到每日操练，与曾子“吾日三省吾身”相近；但他的落点是内在自由，儒家则兼及人伦责任。", "tags": ["专注", "拖延", "期待"]},
    {"id": "w1a-22", "text": "阻碍行动的东西会推动行动，挡在路上的东西就是路。", "source": "马可·奥勒留《沉思录》", "concept": "障碍即路", "explanation": "卡住你的地方，往往也指出下一步该练什么。别只想着绕开，先看看这道阻力能不能变成方法的一部分。", "western": "马可·奥勒留把障碍纳入理性秩序，与老子“反者道之动”相通；但他不主张退回无为，而要在阻碍中继续行动。", "tags": ["拖延", "烦躁", "专注", "写论文"]},
    {"id": "w1a-23", "text": "不要再谈论好人应该是什么样子，去做一个好人。", "source": "马可·奥勒留《沉思录》", "concept": "行胜于言", "explanation": "关于“应该怎样”的话可以说很久，真正的改变却发生在下一次选择里。今天少解释一句，多做一件符合标准的小事。", "western": "马可·奥勒留把哲学当作练习而非谈论，与孔子“君子欲讷于言而敏于行”相近；但他更强调内在判断的端正。", "tags": ["拖延", "专注", "反思"]},
    {"id": "w1a-24", "text": "人所拥有的只有当下，所失去的也只有当下。", "source": "马可·奥勒留《沉思录》", "concept": "当下唯一", "explanation": "过去已经不能更改，未来还没到手，真正能碰到的只有这一刻。把注意力放回眼前的一件事，焦虑会少一点落脚处。", "western": "马可·奥勒留以当下为唯一属于人的时间，与禅宗“活在当下”相近；但他把当下放进宇宙理性的整体里理解。", "tags": ["焦虑", "平静", "专注", "放空"]},
    {"id": "w1a-25", "text": "并非人生短暂，而是我们浪费太多。", "source": "塞涅卡《论生命之短暂》", "concept": "惜时之要", "explanation": "一天并不算短，只是常被无意识地漏掉。先找出最常吞时间的那件事，哪怕只收回半小时，也会不一样。", "western": "塞涅卡把时间视为唯一真正属于我们的财富，与孔子“逝者如斯夫”同有感喟；但他更强调对时间的主权。", "tags": ["拖延", "焦虑", "反思", "晨间"]},
    {"id": "w1a-26", "text": "愤怒是短暂的疯狂。", "source": "塞涅卡《论愤怒》", "concept": "怒如短狂", "explanation": "怒气上来时，人容易把一时冲动当成全部真相。先让身体慢下来，等那阵热过去，再决定要不要说、要不要做。", "western": "塞涅卡承袭斯多亚传统，把愤怒视为可根治的判断错误，与孔子“不迁怒”相近；但他要求拔除怒根，儒家更重节度。", "tags": ["烦躁", "焦虑", "平静", "休息"]},
    {"id": "w1a-27", "text": "命运牵着愿意的人，拖着不愿的人。", "source": "塞涅卡《道德书简》引克里安提斯", "concept": "顺命而行", "explanation": "同样的事，抗拒会让它变成拖拽，接受会让它变成同行。接受不是认输，而是先停止和已经发生的事较劲。", "western": "塞涅卡引克里安提斯说明斯多亚的命运观，与庄子“安时而处顺”相近；但他仍保留理性对命运的主动认同。", "tags": ["焦虑", "释然", "平静", "变化"]},
    {"id": "w1a-28", "text": "法律是植根于自然的最高理性。", "source": "西塞罗《论法律》", "concept": "自然之法", "explanation": "好的法律不只是谁定的规矩，还要经得起理性的追问。遇到规则时，除了问“合不合法”，也问“合不合理”。", "western": "西塞罗把自然法置于成文法之上，与儒家“礼本于天”的思路相近；但他依据普遍理性，儒家更重人伦传统。", "tags": ["反思", "专注", "社交"]},
    {"id": "w1a-29", "text": "习惯会变成第二天性。", "source": "西塞罗《论至善与至恶》", "concept": "习以成性", "explanation": "同一个动作重复久了，会不再需要决心。想养成什么，就把起点缩小到每天都能完成；想戒掉什么，先改掉触发它的环境。", "western": "西塞罗的“第二天性”与荀子“化性起伪”相近；但他不否弃自然，只承认习惯在自然之上的塑造力。", "tags": ["拖延", "专注", "晨间", "变化"]},
    {"id": "w1a-30", "text": "友谊只能存在于好人之间。", "source": "西塞罗《论友谊》", "concept": "友以德立", "explanation": "真正的朋友不是彼此纵容，而是都愿意变得更好。若一段关系总让你做更坏的自己，就该重新看看它的分量。", "western": "西塞罗继承亚里士多德的德性友谊观，与孔子“友其士之仁者”相近；但他更强调友谊与政治共同体之间的联系。", "tags": ["社交", "孤独", "反思", "感激"]},
    {"id": "w1b-01", "text": "我对我自己成了一个问题。", "source": "奥古斯丁《忏悔录》", "concept": "自我之问", "explanation": "你以为了解自己，可一被追问，就发现心里全是没解开的结。承认自己复杂，不必急着下定义；愿意发问，已经是靠近自己的开始。", "western": "奥古斯丁把认识自己变成对上帝的自白，在神面前照见深渊；曾子三省吾身，把反省落在日常伦理。", "tags": ["迷茫", "反思", "夜晚"]},
    {"id": "w1b-02", "text": "愿我认识你，也认识我自己。", "source": "奥古斯丁《独语录》", "concept": "知神知己", "explanation": "认识世界之前，先认识那个在认识的人。你不必一次看清全部，只要肯诚实地看自己一眼，很多纠结就会松开一点；看清，才有安放。", "western": "奥古斯丁把认识自己与认识神绑在一起，自我知识由此带上超越维度；孔子则把自知落在诚实的求知上。", "tags": ["反思", "迷茫", "晨间"]},
    {"id": "w1b-03", "text": "奇迹并不违反自然，只违反我们关于自然的知识。", "source": "奥古斯丁《上帝之城》", "concept": "奇迹与自然", "explanation": "所谓奇迹，常常只是我们还没弄懂的事。遇到想不通的，先别急着归因于神秘；把不懂当作边界，而不是结论，心会安定许多。", "western": "奥古斯丁以此区分自然与奇迹，休谟质疑奇迹的证据；孔子不语怪力乱神，对越界之言同样审慎。", "tags": ["迷茫", "反思", "期待"]},
    {"id": "w1b-04", "text": "人的终极幸福在于默观真理。", "source": "托马斯·阿奎那《反异教大全》", "concept": "默观真理", "explanation": "幸福不一定在热闹里。安静下来，认真看一件事、想一个问题，心里会生出一种不依赖外物的满足；那种满足，比奖赏更耐久。", "western": "阿奎那把终极幸福放在默观真理上，承接亚里士多德而归于神；程朱格物致知，也相信理能被认识。", "tags": ["专注", "阅读", "平静"]},
    {"id": "w1b-05", "text": "自然法无非是理性受造物对永恒法的分有。", "source": "托马斯·阿奎那《神学大全》", "concept": "自然之法", "explanation": "心里那句“这样不对”，并非凭空而来。它像一条写进人性里的底线，提醒你什么该做、什么不该做；顺着它走，人会安稳。", "western": "阿奎那以自然法连接永恒法与人间法，是西方自然法学的中枢；孟子四端则把道德之根扎在人心。", "tags": ["反思", "平静", "迷茫"]},
    {"id": "w1b-06", "text": "你们生来不是为了像野兽那样活着，而是为了追求美德与知识。", "source": "但丁《神曲·地狱篇》", "concept": "求德求知", "explanation": "别把自己活成只会应付日常的人。你身上还有一部分，是想要弄明白、想要变得更好的；那部分需要被喂养，别让它一直饿着。", "western": "但丁借尤利西斯之口说，人的尊严在于求知与德性，这是人文主义的先声；荀子学不可以已，亦以进取立人。", "tags": ["迷茫", "期待", "写论文"]},
    {"id": "w1b-07", "text": "上帝赐予人最大的礼物，是自由意志。", "source": "但丁《神曲·天堂篇》", "concept": "自由意志", "explanation": "自由不是没有约束，而是你还能选择怎么回应。处境可以限制脚步，却拦不住你决定以什么姿态面对它；这份决定权，谁也拿不走。", "western": "但丁把自由意志写成神的最高赠礼，人因此要为自己的选择负责；孟子万物皆备于我的自主精神，可与之对话。", "tags": ["迷茫", "变化", "舒展"]},
    {"id": "w1b-08", "text": "我们从不在自己家中，总是活在别处。", "source": "蒙田《随笔集》", "concept": "活在别处", "explanation": "人常把心放在下一件事上：等忙完这阵、等到了周末、等某个结果。身体在这里，心思却在别处；把一部分注意力收回今天，日子才真的开始过。", "western": "蒙田说人被恐惧与希望抛向未来，从不在自己家中；庄子不将不迎的应物之道，同样劝人回到当下。", "tags": ["焦虑", "放空", "平静"]},
    {"id": "w1b-09", "text": "害怕痛苦的人，已经在承受他所害怕的痛苦。", "source": "蒙田《随笔集》", "concept": "预支之苦", "explanation": "很多痛苦还没发生，你已经替它排练了好几遍。把想象里的灾难放回未来，先处理眼前这一件小事；恐惧常常一被看清就缩小。", "western": "蒙田以怀疑精神拆解恐惧，主张按人的尺度生活；这与庄子安时而处顺的态度相近，都把力气收回当下。", "tags": ["焦虑", "烦躁", "反思"]},
    {"id": "w1b-10", "text": "命运对我们无所谓善恶，她只提供材料。", "source": "蒙田《随笔集》", "concept": "命运材料", "explanation": "同一件事落在不同人身上，会长成不同的样子。事情本身只给你材料，怎么解释、怎么用，仍在你手里；先别急着说它一定是坏事。", "western": "蒙田承斯多亚与怀疑论，认为祸福多半取决于意见而非事物本身；王阳明心外无物相近，但蒙田更保留犹疑。", "tags": ["失去", "变化", "平静"]},
    {"id": "w1b-11", "text": "有些书可供一尝，有些书可以吞下，有不多的几部书则应当咀嚼消化。", "source": "培根《随笔·论读书》", "concept": "浅尝深味", "explanation": "书不都一样对待。有的翻翻就够，有的要读完，少数几本值得反复咀嚼；把力气花在值得的书上，阅读才不会变成负担。", "western": "培根把读书分成怡情、傅彩、长才三层，强调经验校正书本；孔子学而不思则罔的告诫，同样反对读死书。", "tags": ["阅读", "专注", "复习考试"]},
    {"id": "w1b-12", "text": "读书补天然之不足，经验又补读书之不足。", "source": "培根《随笔·论读书》", "concept": "读书补拙", "explanation": "天分不够的地方，读书可以补一点；书读多了却不动手，也容易空。让书本和经验互相校正，你才会真的长本事，而不是只长谈资。", "western": "培根以知识就是力量推动近代实验科学，却提醒学问须经经验修剪；这与荀子善假于物的实践智慧相通。", "tags": ["阅读", "反思", "专注"]},
    {"id": "w1b-13", "text": "良知是世界上分配得最公平的东西。", "source": "笛卡尔《谈谈方法》", "concept": "良知平等", "explanation": "不必先怀疑自己不够聪明。判断力人人都有份，差别多在有没有用好它；把注意力放在如何用，而不是够不够好，你会走得更远。", "western": "笛卡尔以普遍良知为起点，把方法而非天赋当作真理的保障；孟子人皆可以为尧舜的平等信念，遥相呼应。", "tags": ["焦虑", "反思", "专注"]},
    {"id": "w1b-14", "text": "读一切好书，就是和许多高尚的人谈话。", "source": "笛卡尔《谈谈方法》", "concept": "开卷晤谈", "explanation": "读书不是独自熬着。你是在和几百年前的人对话，他们的困惑与你相似；翻开一本好书，孤独会变成一种有回声的安静。", "western": "笛卡尔把阅读视为与往昔贤者的交谈，由此建立近代哲学的我思起点；刘勰披文以入情的读书观，可相参看。", "tags": ["阅读", "孤独", "夜晚"]},
    {"id": "w1b-15", "text": "单有良好的心智不够，重要的是善用它。", "source": "笛卡尔《谈谈方法》", "concept": "善用心智", "explanation": "聪明不稀罕，稀罕的是把聪明用在正地方。与其反复证明自己有能力，不如挑一件具体的事做完；做出来的东西，比资质更有说服力。", "western": "笛卡尔把善用理性定为方法的第一要务，近代主体哲学由此开端；王阳明知行合一对实践的强调，可以互参。", "tags": ["专注", "写论文", "反思"]},
    {"id": "w1b-16", "text": "不要哭，不要笑，要理解。", "source": "斯宾诺莎《政治论》", "concept": "理解之静", "explanation": "情绪上来时，别急着哭或骂。先试着弄明白它从哪儿来、在保护什么；理解不是认同，但它能让那股力慢慢松开，给你一点余地。", "western": "斯宾诺莎以理解代替褒贬，把自由建立在认识必然之上；庄子知其不可奈何而安之若命，相近而更重理性。", "tags": ["平静", "反思", "烦躁"]},
    {"id": "w1b-17", "text": "最大的骄傲与最大的自卑，都表示心灵的软弱无力。", "source": "斯宾诺莎《伦理学》", "concept": "骄傲自卑", "explanation": "把自己捧得很高，和把自己踩得很低，常常是同一件事的两面：都太依赖别人的眼光。回到你正在做的事上，心会稳一些。", "western": "斯宾诺莎把骄傲与自卑同归于心灵的无力，认为二者都源于想象；论语过犹不及的中道，都在劝人离开极端。", "tags": ["低落", "社交", "反思"]},
    {"id": "w1b-18", "text": "欲望是人的本质本身。", "source": "斯宾诺莎《伦理学》", "concept": "欲望本质", "explanation": "欲望不是需要羞耻的东西，它就是你生命力的形状。与其压着它装作没有，不如看清它想要什么，再决定要不要给它让路。", "western": "斯宾诺莎把欲望定义为人的本质，不把情感当作缺陷；荀子人生而有欲同样坦率，却更强调节欲。", "tags": ["拖延", "迷茫", "反思"]},
    {"id": "w1b-19", "text": "法律的目的不是废除或限制自由，而是保护和扩大自由。", "source": "洛克《政府论》", "concept": "法护自由", "explanation": "规则不一定是在跟你作对。好的边界挡住的是任意与伤害，留下的才是可以安心行动的空间；先看清它在保护什么，再谈要不要改。", "western": "洛克把法律的目的定为保护和扩大自由，为近代自由主义奠基；礼记礼者理之不可易也的秩序观，可以对照。", "tags": ["社交", "反思", "平静"]},
    {"id": "w1b-20", "text": "健全的心灵寓于健全的身体。", "source": "洛克《教育漫话》", "concept": "身心相养", "explanation": "身体不是心灵的附属品。睡够、动一动、吃顿安稳饭，很多想不通的事会松动；照顾好这副身体，是你能给自己最实在的托底。", "western": "洛克把健康身体视为健全心智的前提，教育思想由此转向现世；吕氏春秋流水不腐的养生观，同样重视日常。", "tags": ["运动", "休息", "睡眠"]},
    {"id": "w1b-21", "text": "很少有人思考，但人人都有意见。", "source": "贝克莱《海拉斯与斐洛诺斯对话三篇》", "concept": "思与意见", "explanation": "有观点很容易，真正想过却很难。下次脱口而出之前，先问自己一句：这是我查过的，还是听来的？多想一步，判断就少错一点。", "western": "贝克莱以存在即被感知挑战物质实体，又把常识从怀疑论中救回；王阳明心外无物相近，但贝克莱归于上帝。", "tags": ["反思", "专注", "社交"]},
    {"id": "w1b-22", "text": "一切科学都或多或少与人性有关。", "source": "休谟《人性论》", "concept": "科学与人", "explanation": "再专门的知识，最后都要回到人身上。你研究的东西，会影响谁、帮到谁、让谁为难？带着这个问题做学问，方向会清楚很多。", "western": "休谟把人性论设为一切科学的基础，经验论由此走向彻底；孟子求其放心，也把学问收回人心。", "tags": ["阅读", "写论文", "反思"]},
    {"id": "w1b-23", "text": "最生动的思想，也比不上最迟钝的感觉。", "source": "休谟《人性论》", "concept": "感觉之基", "explanation": "想得再远，也别忘了先感受。一杯热水、一阵风、脚下的地面，这些具体的触感把你拉回当下；观念会飘，感觉不会骗你太久。", "western": "休谟以印象先于观念，划出经验的边界，也把形而上学请下神坛；禅宗吃茶去的当下工夫，意外地同调。", "tags": ["专注", "放空", "平静"]},
    {"id": "w1b-24", "text": "明智的人，让信念与证据相称。", "source": "休谟《人类理解研究》", "concept": "信念与证据", "explanation": "相信一件事之前，先看看它有多少证据。不是要你变得冷漠，而是让判断站得住脚；证据够了再信，心里会少很多后悔。", "western": "休谟以温和怀疑论要求信念与证据相称，为现代科学方法立下分寸；胡适大胆假设、小心求证，几乎同调。", "tags": ["写论文", "反思", "实验"]},
    {"id": "w1b-25", "text": "大自然从不欺骗我们，欺骗我们的是我们自己。", "source": "卢梭《爱弥儿》", "concept": "自然不欺", "explanation": "很多时候，让你难受的不是事情本身，而是你对自己的解释。回到事实，少加一层想象；自然不骗人，骗人的常是我们自己。", "western": "卢梭以自然为善的尺度，批判文明对人的扭曲；这与老子复归于朴相近，但卢梭更寄望于教育。", "tags": ["迷茫", "反思", "晴"]},
    {"id": "w1b-26", "text": "良心是灵魂的声音，欲念是肉体的声音。", "source": "卢梭《爱弥儿》", "concept": "良心之声", "explanation": "心里那点不安，往往比道理更早提醒你。别急着用忙碌盖住它，安静听一听；良心不是来审判你的，它只是想把你领回正路。", "western": "卢梭把良心说成灵魂的声音，与理性并列甚至更高；孟子恻隐之心相近，但卢梭的良心带有自然神论色彩。", "tags": ["反思", "平静", "夜晚"]},
    {"id": "w1b-27", "text": "忍耐是苦涩的，但它的果实是甜的。", "source": "卢梭《爱弥儿》", "concept": "忍耐之果", "explanation": "有些事急不来。眼下这段枯燥、难熬的重复，是在替以后攒力气；忍过这一阵，甜味才尝得出来。别在半熟的时候揭锅。", "western": "卢梭在爱弥儿中强调等待与自然节奏，反对催熟的教育；孟子揠苗助长的寓言，说的是同一个道理。", "tags": ["拖延", "写论文", "低落"]},
    {"id": "w1b-28", "text": "要有勇气运用你自己的理性！", "source": "康德《答复这个问题：什么是启蒙？》", "concept": "启蒙勇气", "explanation": "很多不敢，其实是不敢自己拿主意。你已经有判断的能力，只是还没习惯用它；从一件小事开始自己决定，勇气是练出来的。", "western": "康德把启蒙定义为脱离自我招致的不成熟，理性由此获得公共品格；陈寅恪独立之精神，正是这种担当。", "tags": ["迷茫", "专注", "期待"]},
    {"id": "w1b-29", "text": "道德不是教我们如何获得幸福，而是教我们如何配得上幸福。", "source": "康德《实践理性批判》", "concept": "配得幸福", "explanation": "幸福不是奖品，不能靠运气兑换。你更该问的是：我有没有成为配得上它的人？把力气放在值得的事上，幸福来不来，你都不亏。", "western": "康德区分幸福与配享幸福，把道德价值置于幸福之上；孔子忧道不忧贫重心相近，但康德诉诸普遍法则。", "tags": ["低落", "反思", "感激"]},
    {"id": "w1b-30", "text": "我们的一切知识都从经验开始，但并非都来自经验。", "source": "康德《纯粹理性批判》", "concept": "经验之始", "explanation": "所有的认识都从经历开始，但不是所有认识都只来自经历。你心里那套理解世界的方式，也在参与构造你看见的东西；觉察它，才不被它牵着走。", "western": "康德以先天综合判断调停经验论与唯理论，完成认识论的哥白尼式革命；朱熹即物穷理的路径正好相反。", "tags": ["实验", "反思", "写论文"]},
    {"id": "w1c-01", "text": "自我意识就是欲望。", "source": "黑格尔《精神现象学》", "concept": "欲望自我", "explanation": "你想被看见、被回应，不是虚荣。人正是在欲望里意识到自己，也意识到别人；承认这份想要，再想想怎样让它不吞掉你，关系会清楚一些。", "western": "黑格尔把自我意识建立在欲望与承认上，后经科耶夫发挥；孟子由四端见性，他却更重冲突与相互承认。", "tags": ["社交", "反思", "迷茫"]},
    {"id": "w1c-02", "text": "人生在痛苦与无聊之间像钟摆一样来回摆动。", "source": "叔本华《作为意志和表象的世界》", "concept": "钟摆人生", "explanation": "欲望没满足时难受，满足之后又空。看清这个来回，不必把它当成失败；给生活留一点不靠欲望支撑的事，钟摆的幅度会小一些。", "western": "叔本华把人生放在意志的匮乏与满足之间，悲观而清醒；庄子讲无待，也想跳出这循环，只是叔本华更近苦谛。", "tags": ["低落", "反思", "放空"]},
    {"id": "w1c-03", "text": "财富就像海水，饮得越多，渴得越厉害。", "source": "叔本华《附录与补遗》", "concept": "财富如海", "explanation": "钱能解决具体难处，却很难填住心里的洞。越把安全感押在数字上，越容易觉得不够；分清需要和想要，日子会松一点。", "western": "叔本华以此揭示欲望的无底，与伊壁鸠鲁的知足、老子的少私寡欲相通；区别在于他并不相信理性真能止渴。", "tags": ["焦虑", "感激", "反思"]},
    {"id": "w1c-04", "text": "只有当一个人独处的时候，他才可以完全成为自己。", "source": "叔本华《人生的智慧》", "concept": "独处成己", "explanation": "独处不是被世界落下，而是暂时关掉别人的目光。一个人待着时，你才听得见自己的节奏；学会享受一点安静，回到人群里也会更稳。", "western": "叔本华把独处视为精神自足的条件，与庄子独与天地精神往来相近；但他更冷峻，认为多数社交只是交换空虚。", "tags": ["孤独", "平静", "休息"]},
    {"id": "w1c-05", "text": "平庸的人关心怎样消磨时间，有才能的人竭力利用时间。", "source": "叔本华《人生的智慧》", "concept": "时间之用", "explanation": "时间怎么过，慢慢就把人分开了。不必把每刻都填满，但要知道自己在拿它换什么；哪怕只认真用半小时，也比整天空转踏实。", "western": "叔本华以对待时间的方式区分精神等级，近于荀子劝学；但他更悲观，认为多数忙碌只是逃避自身。", "tags": ["专注", "拖延", "反思"]},
    {"id": "w1c-06", "text": "绝望是致死的疾病。", "source": "克尔凯郭尔《致死的疾病》", "concept": "绝望之病", "explanation": "绝望不一定哭喊，它也可能很安静：照常上班、说笑，却和自己断了线。承认这种断线，不是给自己贴病名，而是重新接上自己的开始。", "western": "克尔凯郭尔把绝望看作自我与自身的关系失调，而非单纯情绪；庄子安命，他却要在信仰中重建自我。", "tags": ["低落", "反思", "夜晚"]},
    {"id": "w1c-07", "text": "结婚，你将会后悔；不结婚，你也将会后悔。", "source": "克尔凯郭尔《非此即彼》", "concept": "两难皆悔", "explanation": "有些选择没有无痛选项。无论往哪边走，都要放弃另一边的可能；成熟不是找到完美答案，而是选一条，承担它的遗憾，不再反复算账。", "western": "克尔凯郭尔以反讽揭示选择的不可通约，逼人从审美转向伦理决断；庄子两行之道化解两难，他却要人承担。", "tags": ["迷茫", "社交", "反思"]},
    {"id": "w1c-08", "text": "那些杀不死我的，使我更强大。", "source": "尼采《偶像的黄昏》", "concept": "更强之我", "explanation": "不是所有难处都值得感谢，但熬过来之后，你确实多了一层底气。别急着歌颂苦难，先承认自己撑住了，再把这份力气用下去。", "western": "尼采把痛苦看作权力意志的磨石，反对以怜悯削弱人；孟子说苦其心志，也信磨难成人，但尼采更重超越。", "tags": ["疲惫", "低落", "运动", "释然"]},
    {"id": "w1c-09", "text": "当你凝视深渊时，深渊也在凝视着你。", "source": "尼采《善恶的彼岸》", "concept": "深渊回望", "explanation": "长期盯着黑暗，黑暗也会改变你看它的方式。不是叫你别看，而是提醒你留一只脚在岸上；觉察自己被什么吸引，才不至于沉进去。", "western": "尼采提醒人：与恶周旋须防被同化，认识深渊不等于住进深渊；这与孟子养浩然之气相参，都讲守住自身。", "tags": ["夜晚", "反思", "低落"]},
    {"id": "w1c-10", "text": "没有音乐，生活将是一场错误。", "source": "尼采《偶像的黄昏》", "concept": "音乐之必需", "explanation": "有些东西不解决具体问题，却让人愿意继续活。音乐、散步、一场好睡，都是这样的东西；别只留下有用的，把救命的也留着。", "western": "尼采沿叔本华把音乐视作意志的直接表达；孔子成于乐，也重音乐的成人，但尼采更野，是酒神式肯定。", "tags": ["放空", "休息", "舒展"]},
    {"id": "w1c-11", "text": "你真美呀，请停留一下！", "source": "歌德《浮士德》郭沫若译", "concept": "留住此刻", "explanation": "总有一个时刻，好得让你想请它停下。别急着拍照发圈，先真的在里面待一会儿；人能给当下的最好礼物，就是注意力。", "western": "浮士德以赌约换体验的深度，歌德借此肯定现世；苏轼说此心安处，也珍惜当下，但浮士德的停留带着危险交换。", "tags": ["感激", "期待", "平静"]},
    {"id": "w1c-12", "text": "谁不能主宰自己，永远是一个奴隶。", "source": "歌德《格言与反思》", "concept": "自我主宰", "explanation": "自由不只是没人管你，还包括你能管住自己。说好要做的，哪怕只做十分钟；一次次小的兑现，会把“奴隶”慢慢变成主人。", "western": "歌德把自我节制视为自由的入口，与康德自律即自由相通；但歌德不走普遍法则，而诉诸个人修养与自我塑形。", "tags": ["拖延", "专注", "反思"]},
    {"id": "w1c-13", "text": "只有当人游戏的时候，他才完全是人。", "source": "席勒《审美教育书简》", "concept": "游戏成人", "explanation": "这里的游戏不是消磨时间，而是不为功利、只因喜欢而做的事。人在那样的时刻最完整；给自己留一点这样的余地，不算浪费。", "western": "席勒以审美游戏连接感性与理性，认为自由在美中显现；这与孔子游于艺相通，都让闲暇成为成人的一部分。", "tags": ["放空", "休息", "舒展"]},
    {"id": "w1c-14", "text": "只有通过美，人们才能走向自由。", "source": "席勒《审美教育书简》", "concept": "美通自由", "explanation": "规则让人守秩序，美却让人愿意。看一幅画、听一段曲子，你不为交差，只因喜欢；这种不被逼迫的时刻，是自由的练习。", "western": "席勒把审美教育设为政治自由的预备，人先要在美中成为完整的人；孔子兴于诗，相近，但席勒更重主体解放。", "tags": ["舒展", "平静", "阅读"]},
    {"id": "w1c-15", "text": "哪里有危险，哪里也生救渡。", "source": "荷尔德林《帕特莫斯》", "concept": "危中有救", "explanation": "最难的地方，往往也藏着转机。不是危险本身有好处，而是被逼到边上时，人会看见平时看不见的路；先别在最暗处下结论。", "western": "荷尔德林在《帕特莫斯》里把危机与拯救放在同一处，后被海德格尔反复引用；这与老子祸兮福所倚的辩证相近。", "tags": ["低落", "期待", "释然"]},
    {"id": "w1c-16", "text": "有何胜利可言？挺住意味着一切。", "source": "里尔克《观看者》冯至译", "concept": "挺住一切", "explanation": "不是每件事都有赢法。有些阶段，能稳住、能继续，就已经够了。别拿结果否定自己，先把今天撑过去，挺住本身就是一种完成。", "western": "里尔克把英雄主义缩回承受与等待，不靠征服证明意义；儒家知其不可而为之，同样在无望处坚持，却更重担当。", "tags": ["疲惫", "低落", "专注", "释然"]},
    {"id": "w1c-17", "text": "我相信一片草叶不亚于星球的运转。", "source": "惠特曼《自我之歌》", "concept": "草叶星辰", "explanation": "宏大的事容易吸引目光，微小的事也在运转。认真看一片叶子、一顿饭、一次呼吸，你会发现意义不必总在远处；近处也有完整。", "western": "惠特曼把平等推及万物，草叶与星辰同值；王阳明说草木瓦石皆有良知，相近，但惠特曼更带民主热情。", "tags": ["专注", "放空", "晴"]},
    {"id": "w1c-18", "text": "我轻松愉快地走上大路。", "source": "惠特曼《大路之歌》", "concept": "走上大路", "explanation": "有时不必想清终点才出发。把身体带出门，走一段路，风会替你换掉脑子里的死结；行动先于答案，路会慢慢显出来。", "western": "惠特曼把远行写成民主个人的敞开，身体与道路皆肯定生命；李白仗剑远游也有豪情，但他更重平等与同伴。", "tags": ["舒展", "运动", "期待"]},
    {"id": "w1c-19", "text": "我本可以忍受黑暗，如果我不曾见过太阳。", "source": "狄金森《如果我不曾见过太阳》", "concept": "见光难返", "explanation": "见过更好的样子，回不去时最难受。可那份光也说明你知道什么是好；别把失去变成对自己的惩罚，允许自己怀念，也允许慢慢适应。", "western": "狄金森写失去后知觉被永久改变，近于柏拉图洞穴中见光者难返；但她把光留在日常的刺痛里。", "tags": ["失去", "低落", "夜晚"]},
    {"id": "w1c-20", "text": "灵魂选择自己的伴侣。", "source": "狄金森《灵魂选择自己的伴侣》", "concept": "灵魂择伴", "explanation": "真正的亲近，不是谁都能进来。灵魂会自己挑，有时挑得很少，却挑得很准；不必为圈子小发愁，先尊重这份挑剔。", "western": "狄金森把择友写成灵魂的封闭与自足，近于庄子“相濡以沫，不如相忘于江湖”；但她并非无情，只把门留给少数人。", "tags": ["孤独", "社交", "平静"]},
    {"id": "w1c-21", "text": "永恒是由无数个现在组成的。", "source": "狄金森《永恒是由无数个现在组成的》", "concept": "此刻即永恒", "explanation": "别把生活押在某个遥远的以后。永恒听起来很大，其实由一个个此刻拼成；认真过好眼前这一小段，就已经在过一生。", "western": "狄金森以瞬间承载永恒，把超越拉回当下；这与禅宗“一念万年”相近，但她不否定彼岸，只是让永恒从此刻生长。", "tags": ["专注", "晨间", "放空"]},
    {"id": "w1c-22", "text": "我步入丛林，因为我希望生活得有意义。", "source": "梭罗《瓦尔登湖》", "concept": "步入丛林", "explanation": "不是非要住进森林，而是给生活划出一块不被催促的地方。问自己：如果只保留最重要的几件事，会是哪几件？答案会帮你删掉很多。", "western": "梭罗把简化生活当作求真的方法，反对被物与惯例牵着走；这与老子为道日损相近，但他更相信亲自实验。", "tags": ["放空", "变化", "期待"]},
    {"id": "w1c-23", "text": "时间只是我垂钓的溪流。", "source": "梭罗《瓦尔登湖》", "concept": "时间之溪", "explanation": "时间不只是日程表上的格子。你也可以坐在它旁边，看它流；发一会儿呆、钓一会儿鱼，不算把日子浪费掉，那也是生活。", "western": "梭罗把时间比作可垂钓的溪流，强调体验而非效率；这与庄子“吾生也有涯”的感慨不同，他更愿意在流逝中安住。", "tags": ["放空", "平静", "休息"]},
    {"id": "w1c-24", "text": "我们为什么要这样急于成功，从事这样荒唐的事业？", "source": "梭罗《瓦尔登湖》", "concept": "急功之问", "explanation": "忙起来时，很少问自己在忙什么。停一下，看看这件事是你真想做的，还是怕落后才做的；分清这两种，力气才不白花。", "western": "梭罗质疑以效率为名的狂奔，主张按自己的尺度生活；老子说驰骋畋猎令人心发狂，相近，但梭罗更重实践。", "tags": ["焦虑", "反思", "写论文"]},
    {"id": "w1c-25", "text": "自信是成功的第一秘诀。", "source": "爱默生《论自助》", "concept": "自信之秘", "explanation": "自信不是相信自己不会错，而是相信自己能处理出错。先把一件小事做成，信心就有了落点；它长在经验里，不长在打气里。", "western": "爱默生把自信置于成败之前，视之为德性与创造的门槛；孔子当仁不让相近，但爱默生更强调突破惯例。", "tags": ["期待", "专注", "运动"]},
    {"id": "w1c-26", "text": "释放无限光明的是人心，制造无边黑暗的也是人心。", "source": "雨果《悲惨世界》", "concept": "人心明暗", "explanation": "同一颗心，能救人也能伤人。别把自己想得太好或太坏；看见这份两面，才有真正的选择。今天你往哪边多用一点力，很重要。", "western": "雨果把善恶之源收回人心，既拒绝把罪推给制度，也不把人理想化；与王阳明致良知相通，但更带社会关怀。", "tags": ["反思", "社交", "低落"]},
    {"id": "w1c-27", "text": "人好比河流，有的地方河水宽，有的地方河水窄。", "source": "托尔斯泰《复活》", "concept": "人如河流", "explanation": "人不是固定不变的。有时流得急，有时缓，有时清，有时浑；别用某一个阶段给自己定性。你现在窄，不等于一辈子都窄。", "western": "托尔斯泰以河流喻人性流动，反对用一次过错判人终身；荀子化性起伪相近，但他更信良心的苏醒。", "tags": ["变化", "释然", "反思"]},
    {"id": "w1c-28", "text": "如果上帝不存在，那么一切都是允许的。", "source": "陀思妥耶夫斯基《卡拉马佐夫兄弟》", "concept": "一切允许", "explanation": "这句话不是在鼓励放纵，而是在问：当没有外在的奖惩，你还凭什么守住底线？答案只能落回你自己；自由很重，得自己承担。", "western": "陀思妥耶夫斯基借此追问无神世界的道德根基，开出存在主义先声；孔子敬鬼神而远之，也把伦理收回人自身。", "tags": ["迷茫", "反思", "焦虑"]},
    {"id": "w1c-29", "text": "苦难是意识的唯一原因。", "source": "陀思妥耶夫斯基《地下室手记》", "concept": "苦难意识", "explanation": "痛苦会让人醒过来，但不必因此歌颂痛苦。它提醒你哪里不对，至于要不要一直待在里头，仍是你的事；看见，不等于沉溺。", "western": "陀思妥耶夫斯基把苦难写成意识觉醒的代价，反对廉价幸福；孟子说生于忧患，相近，但他更怀疑理性。", "tags": ["低落", "反思", "写论文"]},
    {"id": "w1c-30", "text": "人的一切都应该是美的：面容、衣裳、心灵、思想。", "source": "契诃夫《万尼亚舅舅》", "concept": "整体之美", "explanation": "美不只是长相。衣服整洁、说话有分寸、心里有善意、脑子里有东西，都是一个人发出来的光；不必完美，但要肯在自己身上用点心。", "western": "契诃夫借医生之口把美扩展为整体修养，承接俄国人道传统；孔子说文质彬彬，相近，但他更重日常体面。", "tags": ["晨间", "社交", "感激"]},
    {"id": "w2-001", "text": "意识总是关于某物的意识", "source": "胡塞尔《逻辑研究》", "concept": "意识的意向性", "explanation": "焦虑有时没有具体对象，只觉得整片天压下来。试着把“我到底在担心什么”写成一个句子；雾一旦显出轮廓，你就知道该从哪件小事开始动手。", "western": "胡塞尔用“意向性”说明意识从不空洞，它总指向某个对象。现象学的第一步不是解释世界，而是如实描述经验如何把对象交给我们。", "tags": ["焦虑", "反思", "写论文"]},
    {"id": "w2-002", "text": "生活世界是一切科学的意义基础", "source": "胡塞尔《欧洲科学的危机与超越论的现象学》", "concept": "生活世界", "explanation": "公式和指标背后，先有一个能被看见、被摸到的日常世界。推导卡住的时候，回到具体的现象本身，往往比继续堆叠抽象概念更有效，也更容易重新开始。", "western": "胡塞尔晚年警告，科学把可计算之物当成全部实在，反而遗忘了前科学的直观经验。生活世界不是理论的残余，而是理论得以成立的地基。", "tags": ["专注", "反思", "写论文"]},
    {"id": "w2-003", "text": "存在总是我的存在", "source": "海德格尔《存在与时间》", "concept": "向来我属", "explanation": "别人的进度表不能替你过日子。你可以参考，却仍要回答这件事对我意味着什么。把问题收回自己身上，选择才会从模糊的应该变成具体的下一步。", "western": "海德格尔把“向来我属”视为此在的结构：存在从不以中立方式发生，它总以某个人的方式被承担。回避这一点，就落入了“常人”的平均状态。", "tags": ["迷茫", "反思", "焦虑"]},
    {"id": "w2-004", "text": "诗人的天职是还乡", "source": "海德格尔《荷尔德林诗的阐释》", "concept": "诗人的天职", "explanation": "写东西的人，最终都要回到让自己安心的一块地方。它可能是一座小城、一段方言，或者一个你愿意反复讲述的人；回去不是退步，是取回力气。", "western": "海德格尔借荷尔德林的诗句，把诗人的职责理解为还乡：不是退回熟悉，而是把被遮蔽的亲近重新带回来。语言在此让人第一次真正抵达家园。", "tags": ["孤独", "舒展", "阅读"]},
    {"id": "w2-005", "text": "技术的本质绝不是技术性的东西", "source": "海德格尔《林中路·技术的追问》", "concept": "技术座架", "explanation": "工具本身不可怕，可怕的是把一切都看成待优化的资源，包括你自己。今天留一件不产出的事，提醒自己不是一件等待处理的材料。这一点，比工具本身更值得留意。", "western": "海德格尔用“座架”描述现代技术的支配方式：万物被摆置为可计算、可调用的储备。危险不在机器，而在于这种解蔽方式吞没了其他显现方式。", "tags": ["疲惫", "反思", "放空"]},
    {"id": "w2-006", "text": "死亡是此在最本己的可能性", "source": "海德格尔《存在与时间》", "concept": "向死存在", "explanation": "想到时间有限，不必立刻变得恐慌。它更像一次校准：哪些事其实可以不做，哪些人值得现在就联系，哪些拖延只是害怕开始。把有限当成尺子，而不是当成威胁。", "western": "海德格尔把死亡理解为不可替代、不可越过的最本己可能性。先行到死不是悲观，而是把此在从日常沉沦中唤回，让它本真地选择。", "tags": ["失去", "反思", "平静"]},
    {"id": "w2-007", "text": "此在的本质在于它的生存", "source": "海德格尔《存在与时间》", "concept": "生存论结构", "explanation": "你不是一张已经写好的性格说明书。人在做事、在关系、在一次次选择里成为自己，所以此刻还不确定，并不等于你出了问题。所以别急着给自己盖章定论。", "western": "海德格尔用“生存”区分此在与其他存在者：石头有属性，人却有待实现的可能性。人的“是什么”始终悬置于他“如何存在”之中。", "tags": ["迷茫", "舒展", "反思"]},
    {"id": "w2-008", "text": "艺术就是真理的生成和发生", "source": "海德格尔《林中路·艺术作品的本源》", "concept": "真理的发生", "explanation": "一幅画、一首歌有时会让你突然看清某种一直存在却说不出的东西。那不是装饰，而是认识换了一种抵达方式，绕过了论证，直接落在身上。", "western": "海德格尔反对把艺术当作审美体验的对象，主张作品让世界与大地的争执显现，真理因此被设置入作品。艺术是一种原初的解蔽方式。", "tags": ["阅读", "平静", "舒展"]},
    {"id": "w2-009", "text": "教育是人的灵魂的教育，而非理智知识的堆积", "source": "雅斯贝尔斯《什么是教育》", "concept": "灵魂的教育", "explanation": "绩点和证书会记录你学过什么，却记录不了你被什么点亮过。允许自己为某个问题多停留一会儿，那通常才是真正留下来的学习。被点亮过的东西，往往记得更久。", "western": "雅斯贝尔斯把教育理解为存在者之间的交往与唤醒，而非知识的单向灌输。真正的教育指向自由与责任，要求学生成为能自己思考的人。", "tags": ["复习考试", "阅读", "反思"]},
    {"id": "w2-010", "text": "人的存在先于他的本质", "source": "萨特《存在主义是一种人道主义》", "concept": "存在先于本质", "explanation": "先有你这个人在世上，然后才由你的选择说明你是谁。过去的失败是材料，不是判决书；今天做的这件小事，也在参与定义你。这一点，既是自由，也是压力。", "western": "萨特以此反对预定人性：人先被抛入世界，再通过选择造就自身。由此人对自己的一切负有不可推卸的责任，也没有现成的借口。", "tags": ["迷茫", "焦虑", "反思"]},
    {"id": "w2-011", "text": "人是被判定为自由的", "source": "萨特《存在与虚无》", "concept": "被判决的自由", "explanation": "没有哪种处境能替你做完选择。承认这一点会有点重，但也意味着：即使条件不理想，下一步往哪个方向走，仍然有一部分握在你手里。承认它，比假装无所谓更有用。", "western": "“判定”一词刻意保留法律意味：自由不是人主动争取的奖赏，而是无法推卸的处境。人注定要选择，也注定要为选择承担后果。", "tags": ["焦虑", "迷茫", "期待"]},
    {"id": "w2-012", "text": "不选择，其实也是一种选择", "source": "萨特《存在与虚无》（意译）", "concept": "回避即介入", "explanation": "拖着不回复、迟迟不开始，也在替你做决定，只是把主动权交给了时间。把“我还没选”改写成“我暂时选了等待”，你会更清楚它的代价。写下来，代价就没那么模糊。", "western": "萨特否认人有“不行动”的余地：回避本身就是一种介入，沉默同样在塑造处境。自由无法被搁置，只能被以不同方式行使。", "tags": ["拖延", "焦虑", "反思"]},
    {"id": "w2-013", "text": "女人不是天生的，而是变成的", "source": "波伏娃《第二性》", "concept": "性别建构", "explanation": "很多“女生应该怎样”并不是天生偏好，而是被反复教导出来的。分辨哪些是自己的愿望、哪些是别人的期待，是一场缓慢但值得的松绑。不必一次分清，慢慢来也可以。", "western": "波伏娃区分生理性别与社会角色的塑造过程，指出“女性气质”是被文化生产出来的。这一诊断属于存在主义伦理学：人通过处境中的选择成为自身。", "tags": ["反思", "迷茫", "社交"]},
    {"id": "w2-014", "text": "应当想象西西弗是幸福的", "source": "加缪《西西弗神话》", "concept": "荒诞与反抗", "explanation": "有些重复不会通向宏大的结果：通勤、改稿、洗碗。但当你清楚它在做什么，并且仍然愿意推上去，那一刻的力气就确实属于你。重复本身不等于浪费。", "western": "加缪让西西弗在无意义的惩罚中保持清醒，把荒诞转化为反抗。幸福不来自问题的解决，而来自对处境的意识与不肯屈服。", "tags": ["疲惫", "平静", "专注"]},
    {"id": "w2-015", "text": "我反抗，故我们存在", "source": "加缪《反抗者》", "concept": "反抗的联合", "explanation": "说“这样不对”的时候，你其实已经站在了某个共同体里。反抗不只是发火，它同时说明了你愿意和谁站在一起、愿意守住什么。愤怒里常常藏着在乎的东西。", "western": "加缪由“我反抗”推出“我们存在”：反抗者所捍卫的价值具有普遍性，因而把孤立的个体联结成共同体，这是对虚无主义的正面回应。", "tags": ["烦躁", "孤独", "反思"]},
    {"id": "w2-016", "text": "今天，妈妈死了。也许是在昨天", "source": "加缪《局外人》（柳鸣九译）", "concept": "不表演的悲伤", "explanation": "默尔索的平静让所有人不适，因为他不肯表演悲伤。你也不必按标准剧本表达情绪，真实有时只是“我还没反应过来”这一句。给自己一点反应的时间。", "western": "加缪用一个拒绝表演情感的第一人称，暴露社会对情绪的规范化要求。默尔索被判死刑，部分原因正是他不肯完成那套情感仪式。", "tags": ["失去", "低落", "孤独"]},
    {"id": "w2-017", "text": "自由不过是一个变得更好的机会", "source": "加缪《夏天集》", "concept": "自由的机会", "explanation": "自由不是想做什么就做什么，而是此刻还能调整一点。哪怕只是把睡觉时间提前半小时，也是在认真用掉手里的这个机会。机会很小，但它确实还在。", "western": "加缪把自由从抽象权利拉回具体实践：它是一种可以被使用、也可以被浪费的可能性，其价值取决于人如何用它改造自己的处境。", "tags": ["期待", "变化", "专注"]},
    {"id": "w2-018", "text": "我向世界温柔的冷漠敞开心扉", "source": "加缪《局外人》（柳鸣九译）", "concept": "与荒诞和解", "explanation": "世界不欠你一个解释，也不总在针对你。承认它有时只是冷淡，反而能松开那根一直绷着的弦，让你把力气留给真正能回应你的人。不必急着和世界讲和，先站稳。", "western": "小说结尾，默尔索不再向宇宙索取意义，而是接受它的冷漠，并在其中感到平等与安宁。这是加缪式的和解：清醒，但不投降。", "tags": ["平静", "释然", "孤独"]},
    {"id": "w2-019", "text": "世界不是我思考的，而是我经历的", "source": "梅洛-庞蒂《知觉现象学》", "concept": "身体知觉", "explanation": "有些道理听一百遍也没用，走一趟、做一次就懂了。身体知道的常常比脑子更早，所以别只在椅子上想，先起身去碰一碰那件事。身体先懂了，道理才跟得上。", "western": "梅洛-庞蒂以身体主体取代纯粹意识，认为意义首先在知觉与行动中生成。世界不是被判断的对象，而是被身体居住的场域。", "tags": ["运动", "专注", "放空"]},
    {"id": "w2-020", "text": "他人的面容是一种命令：不可杀人", "source": "列维纳斯《总体与无限》", "concept": "他者伦理", "explanation": "面对一个具体的人时，抽象的道理会退后。那双眼睛会打断你的自说自话，要求你先别把他当成障碍、当成一件需要处理的事。先把人当人看，再谈别的。", "western": "列维纳斯把伦理学置于本体论之前：面容的裸露是一种伦理召唤，禁止我将他者化约为可支配的对象。责任先于自由，也先于认识。", "tags": ["社交", "反思", "烦躁"]},
    {"id": "w2-021", "text": "伦理学是第一哲学", "source": "列维纳斯《总体与无限》", "concept": "伦理优先", "explanation": "在处理“这是什么”之前，先遇到“我该如何对待他”。这个顺序的调整，会让很多关系里的争执显得不必那么用力。顺序一变，很多争执就不必发生。", "western": "列维纳斯颠倒了自柏拉图以来的哲学次序：不是先有存在论再有伦理，而是对他者的责任构成了主体成立的条件，自我是被召唤出来的。", "tags": ["反思", "社交", "平静"]},
    {"id": "w2-022", "text": "人通过行动与言说显示自己是谁", "source": "阿伦特《人的境况》", "concept": "行动与显现", "explanation": "简历写的是你具备什么，谈话和做事才显出你是谁。不必急着包装自己，先让自己出现在具体的事情里，被看见的部分会慢慢变多。被看见，需要先出现。", "western": "阿伦特区分劳动、工作与行动：唯有行动与言说在公共领域中显现“谁”，而非“什么”。人的尊严在于这种不可替代的显现。", "tags": ["社交", "迷茫", "反思"]},
    {"id": "w2-023", "text": "行动的能力，就是开始新事情的能力", "source": "阿伦特《人的境况》", "concept": "开端的能力", "explanation": "开始一件新事，不需要先证明自己配得上。人能开始，本身就说明过去不构成全部；哪怕只是打开文档写第一行，也算一次开始。开始这件事，本身就已经算数。", "western": "阿伦特以“诞生性”命名人的这一能力：每个新生儿都带来一个全新的开始。行动因此总带着不可预测性，也总保留着打断旧循环的可能。", "tags": ["期待", "变化", "拖延"]},
    {"id": "w2-024", "text": "我的语言的界限，意味着我的世界的界限", "source": "维特根斯坦《逻辑哲学论》", "concept": "语言的界限", "explanation": "说不清的地方，往往也想不清。给一种情绪找到更准确的词，它就不再是一团无法处理的东西，而变成一个可以商量的问题。词准了，事才好办。", "western": "维特根斯坦在此把语言与世界的可能性绑定：能被言说的才进入事实领域。但他同时承认，还有不可言说者以沉默的方式显示自身。", "tags": ["反思", "写论文", "焦虑"]},
    {"id": "w2-025", "text": "对于不可言说之物，必须保持沉默", "source": "维特根斯坦《逻辑哲学论》", "concept": "沉默的边界", "explanation": "不是所有感受都需要被分析成句子。有些事安静地放在那里，比强行解释更尊重它，也更能保住它原本的分量。有些东西只能被显示，不能被说明。", "western": "这句话常被误读为禁欲的禁令。维特根斯坦的原意是：伦理、审美与生命意义不在事实语言之内，它们只能显示，不能被命题化。", "tags": ["平静", "放空", "反思"]},
    {"id": "w2-026", "text": "一个词的意义，就是它在语言中的用法", "source": "维特根斯坦《哲学研究》", "concept": "语言游戏", "explanation": "同一个词在家里和在群里，意思可能完全不同。听懂一个人，往往要先听懂他正在玩哪种游戏，而不是急着纠正他用词不准。所以别急着争对错，先看场合。", "western": "维特根斯坦以“语言游戏”取代指称论：词不靠对应某个对象获得意义，而在具体的生活形式与规则中获得功能。哲学的任务是描述用法。", "tags": ["社交", "反思", "阅读"]},
    {"id": "w2-027", "text": "哲学是一场反对我们的语言迷惑我们的理智的斗争", "source": "维特根斯坦《哲学研究》", "concept": "语言的迷障", "explanation": "很多苦恼来自用错词：把“我最近状态不好”说成“我完了”。换一个准确的说法，问题才回到它原本的大小，也才谈得上处理。把话说清楚，常常比想通更快。", "western": "维特根斯坦认为哲学问题多源于语言空转时产生的幻象。哲学不提供新理论，而是通过看清语法，消解那些被自己造出来的困惑。", "tags": ["反思", "烦躁", "写论文"]},
    {"id": "w2-028", "text": "世界的意义必定在世界之外", "source": "维特根斯坦《逻辑哲学论》", "concept": "意义的位置", "explanation": "意义不像一件物品，找到就归你所有。它更像是你看世界的方式，随你的位置一起移动，所以换个坐处，看到的东西也会变。它更像一副眼镜，而不是一件东西。", "western": "维特根斯坦把价值排除在事实世界之外：世界如何，是科学的问题；世界竟然存在，则不是。意义不是世界内部的成分，而是看世界的眼光。", "tags": ["迷茫", "平静", "反思"]},
    {"id": "w2-029", "text": "如果狮子会说话，我们也无法理解它", "source": "维特根斯坦《哲学研究》", "concept": "生活形式", "explanation": "沟通失败有时和表达技巧无关，而是彼此的生活经验差得太远。这时需要的不是更用力解释，而是先靠近对方的世界一点。靠近，比解释更有效。", "western": "维特根斯坦以此说明理解语言须共享生活形式。听懂不只是解码句子，而是能够参与那句话所在的实践，并对它作出相似的反应。", "tags": ["孤独", "社交", "反思"]},
    {"id": "w2-030", "text": "幸福的秘诀是：让你的兴趣尽量扩大", "source": "罗素《幸福之路》", "concept": "兴趣的宽度", "explanation": "把全部注意力压在一件事上，它稍一失手就能压垮你。多养一两个无关紧要的爱好，是给情绪留一条备用出口，也是给自己留退路。兴趣是分给未来的余量。", "western": "罗素把幸福理解为可练习的能力：兴趣越广，自我越不容易被单一挫败吞没。这是经验主义的幸福论，而不是道德劝诫。", "tags": ["舒展", "焦虑", "阅读"]},
    {"id": "w2-031", "text": "对爱情的渴望，对知识的追求，对人类苦难的同情", "source": "罗素《自传》序言", "concept": "三种激情", "explanation": "罗素把一生概括为三股力气。你也可以问问自己：现在撑着我的，是哪一股？找到它，日子会重新有一点方向，而不是只剩任务清单。三股力气不必同时都在。", "western": "罗素以这三种激情解释自己的一生，并承认它们把他反复带入痛苦。这份坦白说明：值得过的生活往往不是无痛的，而是有指向的。", "tags": ["反思", "期待", "孤独"]},
    {"id": "w2-032", "text": "一个理论不能被证实，只能被证伪", "source": "波普尔《科学发现的逻辑》", "concept": "可证伪性", "explanation": "与其不断寻找支持自己的例子，不如先问：什么情况会证明我错了？这个问题会让判断变诚实，也能省下大量自我辩护的力气。敢被推翻的想法，才值得认真对待。", "western": "波普尔以可证伪性划界：科学理论必须是敢冒被反驳风险的普遍陈述。支持的例证再多也不构成证明，一次反例却足以推翻全称命题。", "tags": ["写论文", "实验", "反思"]},
    {"id": "w2-033", "text": "我们只能通过试错来学习", "source": "波普尔《猜想与反驳》", "concept": "猜想与反驳", "explanation": "先做一个能被检验的小版本，比在心里推演十遍更有用。错了也只是排除掉一个选项，而不是给自己添一条新的罪状。先跑一次，再谈完善。", "western": "波普尔把知识增长描述为猜想与反驳的循环：我们从问题出发提出假设，再让它在检验中死亡，以此替代自己的死亡。错误因此有认识论价值。", "tags": ["实验", "代码", "写论文"]},
    {"id": "w2-034", "text": "无限度的宽容，必然导致宽容的消失", "source": "波普尔《开放社会及其敌人》", "concept": "宽容的悖论", "explanation": "宽容不等于对伤害也保持中立。守住“不伤害”这条线，才能让不同的生活方式都还有空间，否则退让只会把空间让给最凶的那一方。边界清楚，宽容才站得住。", "western": "波普尔提出宽容的悖论：若对不宽容者无限宽容，宽容社会终将被摧毁。因此开放社会有权自卫，但须以制度而非情绪来划定边界。", "tags": ["烦躁", "社交", "反思"]},
    {"id": "w2-035", "text": "狐狸知道很多事，刺猬知道一件大事", "source": "伯林《刺猬与狐狸》", "concept": "两种人格", "explanation": "有人靠一个中心信念活得坚定，有人靠广泛的好奇活得灵活。两种都不是缺陷，关键是知道自己属于哪一种，并接受它带来的代价。认清自己那一类，比模仿别人省力。", "western": "伯林借古希腊残句区分两类思想家：刺猬把一切归于一个单一原则，狐狸则承认经验的多歧。他借此批评用一元论改写历史的诱惑。", "tags": ["反思", "阅读", "迷茫"]},
    {"id": "w2-036", "text": "善与善之间，也可能无法相容", "source": "伯林《两种自由概念》", "concept": "价值多元", "explanation": "两个都值得的选择，可能真的不能同时要。承认这一点，比反复责怪自己不够努力更接近真相，也更容易做出不那么勉强的取舍。取舍的难受，不等于你选错了。", "western": "伯林主张价值多元论：终极价值彼此不可通约，冲突无法靠单一尺度调和。自由的意义正在于让人能在不可兼得的善之间作出选择。", "tags": ["迷茫", "反思", "焦虑"]},
    {"id": "w2-037", "text": "权力无处不在，因为它来自一切地方", "source": "福柯《性史》第一卷", "concept": "微观权力", "explanation": "权力不只在文件和大楼里，也在“正常人应该怎样”的日常默契里。看清它，才能分辨哪些要求其实不必内化成对自己的责备。看清规则，才知道哪里可以松动。", "western": "福柯反对把权力视为自上而下的占有物，主张它是关系网络中弥散运作的策略。权力与抵抗同生，任何支配都不曾彻底封闭。", "tags": ["反思", "烦躁", "社交"]},
    {"id": "w2-038", "text": "规训制造出驯顺而有用的身体", "source": "福柯《规训与惩罚》", "concept": "规训的权力", "explanation": "时间表、考核、打卡，会慢慢把外在要求变成自己的习惯。偶尔问一句“这是我想要的节奏吗”，能帮你从自动运行里拿回一点主动。节奏是可以商量的，前提是你先发现它。", "western": "福柯分析学校、军营与工厂如何通过时间表、监视与考核塑造身体。权力在此不靠暴力，而靠让人自己监督自己的技术。", "tags": ["焦虑", "反思", "疲惫"]},
    {"id": "w2-039", "text": "哪里有权力，哪里就有抵抗", "source": "福柯《性史》第一卷", "concept": "抵抗的共生", "explanation": "感到被安排、被定义时，那点不适本身就是线索。它提醒你还有拒绝和商量的余地，不必先把不舒服解释成自己太敏感。不适感，往往就是那条线索。", "western": "福柯强调抵抗从不外在于权力，而是与它同时出现、同样弥散。抵抗不必是宏大的起义，也可以是局部的、日常的、不断移动的不服从。", "tags": ["烦躁", "期待", "反思"]},
    {"id": "w2-040", "text": "人将被抹去，如同海边沙滩上的一张脸", "source": "福柯《词与物》", "concept": "人的终结", "explanation": "我们习惯把“人”当成永恒的中心，其实这个形象只有两百多年历史。意识到它是被构造出来的，反而能让人稍微松一口气。被构造的东西，也可以被改写。", "western": "福柯在《词与物》结尾预告“人之死”：作为知识型产物的人会随知识型的更替而消失。这不是悲观预言，而是对人文主义确定性的拆解。", "tags": ["迷茫", "反思", "阅读"]},
    {"id": "w2-041", "text": "文本之外，别无他物", "source": "德里达《论文字学》", "concept": "文本的边界", "explanation": "你以为的直接事实，往往已经过一层叙述和解释。多问一句“这是谁说的、怎么说的”，世界会变得更有层次，也更难被一句话概括。多一点追问，少一点理所当然。", "western": "德里达这句常被误读为否认现实。他的意思是：意义总在文本网络中被延异，没有未经中介的纯粹在场，也没有最终的解释终点。", "tags": ["反思", "阅读", "写论文"]},
    {"id": "w2-042", "text": "意义在差异与延迟中生成", "source": "德里达《声音与现象》（意译）", "concept": "差异与延迟", "explanation": "一个词的意思，取决于它不是什么，也取决于后面还接什么。理解因此永远不会一次完成，读慢一点、想久一点都是正常的。慢，是理解的一部分。", "western": "“延异”合并了差异与推迟两义：符号的意义既由与其他符号的差异确定，又总被推迟到下一次补充，因此没有最终的封闭。", "tags": ["阅读", "反思", "写论文"]},
    {"id": "w2-043", "text": "读者的诞生，须以作者的死亡为代价", "source": "巴特《作者之死》", "concept": "作者之死", "explanation": "一本书写完，解释权就不只在作者手里。你的读法也是它的一部分，不必总担心自己理解错了，先把打动你的那一处说清楚。读法不同，书就长出不同的样子。", "western": "巴特反对以作者意图作为文本的最终尺度，主张文本是引文的编织，意义在阅读中完成。这抬高了读者的主动性，也取消了唯一正解。", "tags": ["阅读", "写论文", "反思"]},
    {"id": "w2-044", "text": "历史的天使面朝过去，被风暴吹向未来", "source": "本雅明《历史哲学论纲》", "concept": "历史的天使", "explanation": "回望时看见的多是堆积的残骸，而推着我们前进的力量却不由自己挑选。承认这种被动，反而更能理解自己为什么总是累。累，有时是因为一直在被推着走。", "western": "本雅明借保罗·克利的画描述历史天使：它想停下来修补废墟，却被名为进步的风暴推向前方。历史唯物论由此反对线性的进步叙事。", "tags": ["疲惫", "反思", "失去"]},
    {"id": "w2-045", "text": "灵光在机械复制的时代衰竭", "source": "本雅明《机械复制时代的艺术作品》", "concept": "灵光的消失", "explanation": "一张照片可以无限复制，但“此刻此地只有这一张”的感觉消失了。珍惜某种不可复制的在场，也是抵抗麻木的一种方式。所以别把一切都交给屏幕。", "western": "本雅明用“灵光”指作品独一无二的此时此地性，即它的膜拜价值。复制技术摧毁了这种距离感，同时释放出艺术的政治潜能。", "tags": ["变化", "反思", "阅读"]},
    {"id": "w2-046", "text": "在临界境况中，人才能真正开始哲学思考", "source": "雅斯贝尔斯《哲学导论》", "concept": "临界境况", "explanation": "疾病、失败、告别，会把人推到语言的边上。那时的问题不再是“怎么做得更好”，而是“我还怎么活下去”。哲学常从这种地方开始，不是因为想不开，而是因为终于认真了。", "western": "雅斯贝尔斯把死亡、苦难、斗争与罪责称为临界境况：它们无法被改变，只能被承担。人面对它们时才会越过日常的安稳，触到存在的底层。", "tags": ["失去", "迷茫", "反思"]},
    {"id": "w2-047", "text": "思考是我与自己之间无声的对话", "source": "阿伦特《精神生活》", "concept": "自我对话", "explanation": "一个人待着时，脑子里其实仍有两个人在说话。这个声音值得被认真听见：它会替你把今天的事过一遍，也会在你要做亏心事时先开口反对。", "western": "阿伦特借苏格拉底的“我与自己”说明思考的伦理意义：思考让人分裂为二，从而无法与自己讲和地作恶。这直接通向她对“恶的平庸性”的讨论。", "tags": ["反思", "孤独", "平静"]},
    {"id": "w2-048", "text": "爱是一门艺术，需要学习和实践", "source": "弗洛姆《爱的艺术》", "concept": "爱的能力", "explanation": "爱不是碰上一个对的人就自动完成的事。它包含关心、责任、尊重和了解，也包含练习：怎么听、怎么表达、怎么在冲突里不逃跑。这些都可以学。", "western": "弗洛姆反对把爱看作被动坠入的情感，主张它是一种主动的能力与人格倾向。爱由此成为实践哲学的问题：它要求人先成为能独立站立的人。", "tags": ["社交", "反思", "期待"]},
    {"id": "w2-049", "text": "不成熟的爱说：我爱你，因为我需要你", "source": "弗洛姆《爱的艺术》", "concept": "成熟的爱", "explanation": "需要一个人，和爱一个人，常常被混在一起。前者是想被接住，后者是愿意看见对方本来的样子。分清楚这两件事，关系里会少很多无名委屈。", "western": "弗洛姆以这句对照成熟的爱：“我需要你，因为我爱你。”前者把对方当作填补匮乏的工具，后者以自身的完整为前提，是主动的给予而非索取。", "tags": ["孤独", "社交", "反思"]},
    {"id": "w2-050", "text": "多数人把爱的问题看成被爱的问题", "source": "弗洛姆《爱的艺术》", "concept": "被爱的幻觉", "explanation": "我们常花力气让自己更可爱、更值得被选，却很少练习怎么去爱一个人。前者是在争取位置，后者才是在建立关系。两种功课的方向完全不同。", "western": "弗洛姆把这种错位追溯到现代社会的交换逻辑：人把自己包装成商品，期待在婚恋市场上获得等价回报。爱因此被降格为获取认可的手段。", "tags": ["社交", "迷茫", "反思"]},
    {"id": "w2-051", "text": "直到你把无意识变成意识，它会支配你的生活，而你会称之为命运", "source": "荣格《荣格文集》", "concept": "无意识的命运", "explanation": "同样的争吵、同样的退缩，一次次重复，久了就像命。把它们认出来、叫出名字，重复才有松动的可能；这不是玄学，只是让暗处的东西见光。看见，就是改变的开始。", "western": "荣格把无意识视为人格的另一半：被压抑的内容会以症状、投射与重复的方式回来。分析的目标不是消除它，而是与之对话，使意识扩容。", "tags": ["迷茫", "反思", "变化"]},
    {"id": "w2-052", "text": "任何东西都可以被夺走，除了选择态度的自由", "source": "弗兰克尔《活出意义来》", "concept": "最后的自由", "explanation": "处境未必能选，回应方式还有余地。这不是要求你永远乐观，而是说：在很难的时候，你仍然可以对这件事采取什么姿态，还留着一点决定权。", "western": "弗兰克尔从集中营经验出发，指出人最后的自由是选择对境遇的态度。意义治疗不提供现成答案，而是帮人看见自己仍可承担的那部分责任。", "tags": ["低落", "疲惫", "释然"]},
    {"id": "w2-053", "text": "生命的意义因人而异，因时而异", "source": "弗兰克尔《活出意义来》", "concept": "意义的具体性", "explanation": "意义不是一道有标准答案的题，也不在某个地方等你找到。它在具体的人、具体的时刻显出形状，所以别人的人生方案，未必能直接搬过来用。", "western": "弗兰克尔反对把意义抽象成普遍命题：它总在具体处境中向具体的人提出要求。人不是去追问生命的意义，而是被生命追问，并以行动作答。", "tags": ["迷茫", "反思", "期待"]},
    {"id": "w2-054", "text": "我心里一直都在暗暗设想，天堂应该是图书馆的模样", "source": "博尔赫斯《关于天赐的诗》", "concept": "图书馆的天堂", "explanation": "有些地方能让人安静下来，不是因为禁止说话，而是因为书在那里排着队，提醒你世界比眼前这件事大得多。走进去，呼吸会慢一点。安静也可以是种阅读的准备。", "western": "博尔赫斯把图书馆写成无限的迷宫：书目无穷，秩序可疑，却仍是人唯一能接近整全的场所。这一意象属于他对无限与分类的持续迷恋。", "tags": ["阅读", "平静", "专注"]},
    {"id": "w2-055", "text": "时间永远分岔，通向无数的将来", "source": "博尔赫斯《小径分岔的花园》", "concept": "分岔的时间", "explanation": "你做的每个选择，都让别的可能性同时存在。遗憾之所以难消，是因为那些路真的还在想象里延伸；承认它们，然后走好脚下这一条。脚只踩得住一条。", "western": "博尔赫斯用一个包含所有可能结局的侦探故事，提出非线性的时间模型：所有分支同时发生。它挑战了因果单一的历史观，也取消了唯一的结局。", "tags": ["迷茫", "反思", "变化"]},
    {"id": "w2-056", "text": "任何命运，无论多么漫长复杂，实际上只反映于一个瞬间", "source": "博尔赫斯《塔德奥·伊西多罗·克鲁斯小传》", "concept": "顿悟的瞬间", "explanation": "人可能用很多年才明白自己是谁，而明白往往只发生在很短的一刻：一次拒绝、一句真话，或一个忽然不想再解释的下午。之后的一切，都只是把那一刻活出来。", "western": "博尔赫斯让克鲁斯在临死前认出自己真正的身份：一生不过是回到那个瞬间。这接近斯宾诺莎式的必然，也带着尼采式的命运之爱。", "tags": ["反思", "变化", "释然"]},
    {"id": "w2-057", "text": "地狱如果存在，它已经在此存在", "source": "卡尔维诺《看不见的城市》", "concept": "此世的地狱", "explanation": "有些消耗不需要等到未来才叫地狱：每天耗掉你的那间办公室、那段对话，就已经是了。看清它，再决定是离开，还是改变与它相处的方式。", "western": "卡尔维诺借马可·波罗之口说，地狱不在别处，就在我们每天生活的城里。他给出的两种办法是接受它，或者在其中辨认出不属于地狱的人与事。", "tags": ["疲惫", "反思", "烦躁"]},
    {"id": "w2-058", "text": "城市就像梦境，由欲望与恐惧构成", "source": "卡尔维诺《看不见的城市》", "concept": "欲望与恐惧", "explanation": "你喜欢的城市，往往照出你想要的生活；你害怕的城市，也照出你不愿成为的样子。旅行有时不是为了看风景，而是为了看清这两样东西。", "western": "卡尔维诺把城市读成心理的投影：街道的布局对应欲望的路径，城墙对应恐惧的边界。地理在此成为内在世界的语法。", "tags": ["期待", "变化", "放空"]},
    {"id": "w2-059", "text": "你即将开始阅读伊塔洛·卡尔维诺的新小说", "source": "卡尔维诺《如果在冬夜，一个旅人》", "concept": "读者的位置", "explanation": "这本书开口就对“你”说话，把读者直接拉进故事里。阅读从来不是旁观：你的期待、停顿和走神，也在参与这本书的完成，所以怎么读都不算错。", "western": "卡尔维诺用第二人称和十部残稿，拆解“读小说”这一行为本身。它属于后现代元叙事：故事不断暴露自己的构造，读者被迫意识到自己在场。", "tags": ["阅读", "专注", "放空"]},
    {"id": "w2-060", "text": "一只笼子在寻找一只鸟", "source": "卡夫卡《八本八开本笔记》", "concept": "颠倒的束缚", "explanation": "通常以为是鸟被关进笼子，卡夫卡偏说笼子在找鸟。有些困境也是这样：不是你先有问题才被规则困住，而是规则先在那里，等着你去符合它。", "western": "卡夫卡用一句倒置的寓言，把束缚写成主动的猎手。这种把被动与主动对调的写法，正是他对官僚系统与罪感结构的核心洞察。", "tags": ["焦虑", "反思", "烦躁"]},
    {"id": "w2-061", "text": "目标只有一个，道路却无一条", "source": "卡夫卡《对罪愆、苦难、希望和真正的道路的观察》", "concept": "道路的踌躇", "explanation": "想做的事很清楚，具体怎么走却处处是岔口。卡夫卡说所谓道路不过是踌躇，这话不温柔，却诚实：犹豫不是没上路，犹豫本身就是路的一部分。", "western": "卡夫卡把行动的自由写成困境：目标确定，方法却无限且无一可靠。这与克尔凯郭尔式的生存悖论相近——选择无法被理性预先保证。", "tags": ["迷茫", "拖延", "焦虑"]},
    {"id": "w2-062", "text": "一天早晨，格里高尔从不安的睡梦中醒来", "source": "卡夫卡《变形记》", "concept": "醒来的错位", "explanation": "醒来发现一切都不对了，这种经验并不罕见：身体、工作、关系，某个早上忽然变得陌生。卡夫卡不解释原因，只是让你先待在那份错位里。先允许自己发一会儿愣。", "western": "《变形记》开篇用最平静的语调报告最不可能的事件，制造出荒诞的日常感。这种冷静正是卡夫卡式恐怖：灾难被当作一件待处理的事务。", "tags": ["疲惫", "焦虑", "晨间"]},
    {"id": "w2-063", "text": "我一无所是，也永远不会成为什么", "source": "佩索阿《烟草店》", "concept": "虚无的自认", "explanation": "这句话不悲伤，反而有点解脱。承认自己不必成为什么，就不必每天为“还不够好”付利息。空出来的地方，正好可以放一点真正想做的事。空着不是失败，是腾地方。", "western": "佩索阿借异名者之口说出彻底的自我取消，与克尔凯郭尔的“绝望”形成呼应：当人不再执着于成为某个形象，反而可能第一次如实存在。", "tags": ["低落", "释然", "迷茫"]},
    {"id": "w2-064", "text": "我的灵魂是一支秘密的乐队", "source": "佩索阿《惶然录》（韩少功译）", "concept": "内在的复调", "explanation": "心里同时响着好几种声音：想休息的、想努力的、想消失的。它们不必被协调成一个调子，允许它们各演奏各的，也是一种安定。不必急着调音，也别嫌它吵。", "western": "佩索阿用“异名”写作把自我拆成多个作者，这句比喻正是其方法的写照。它预示了后来心理学与文学中的复调自我观：统一并非真实。", "tags": ["孤独", "平静", "放空"]},
    {"id": "w2-065", "text": "如此幸福的一天。雾一早就散了", "source": "米沃什《礼物》", "concept": "当下的礼物", "explanation": "诗里没有大事发生：雾散了，在花园干活，看见蜂鸟。幸福被写成一种注意力，而不是一种成就；它只要求你此刻真的在场，抬头看一眼也算。", "western": "米沃什在此接近现象学的还原：把评价悬置，只让事物如其所是地出现。幸福不是拥有更多，而是不再向世界索要别的样子。", "tags": ["平静", "晨间", "感激"]},
    {"id": "w2-066", "text": "我偏爱写诗的荒谬，胜过不写诗的荒谬", "source": "辛波斯卡《种种可能》（陈黎、张芬龄译）", "concept": "选择的荒谬", "explanation": "既然怎样都逃不开荒谬，那不如选一个自己愿意承担的那种。这句话对写诗成立，对别的事也成立：先问哪种辛苦你受得住，答案常常就在这里。", "western": "辛波斯卡把价值选择写成趣味与偏爱，而非道德论证。这与伯林的价值多元论相通：不存在唯一合理的活法，只有被承担的选择。", "tags": ["迷茫", "期待", "阅读"]},
    {"id": "w2-067", "text": "他们彼此深信，是瞬间迸发的热情让他们相遇", "source": "辛波斯卡《一见钟情》（陈黎、张芬龄译）", "concept": "偶然的必然", "explanation": "相遇看起来像奇迹，其实由无数个没被注意的擦肩堆成。承认偶然不会让感情变轻，反而让人更愿意对眼前这段关系负责。被注意到的偶然，就成了故事。", "western": "辛波斯卡把爱情的必然感写成事后的叙事缝合：人需要意义，于是把偶然读成命运。这首诗温柔地拆穿了这种自我叙述，却不拆掉它的温度。", "tags": ["期待", "社交", "感激"]},
    {"id": "w2-068", "text": "美无非是我们尚能承受的可怕之物的开端", "source": "里尔克《杜伊诺哀歌》第一首", "concept": "美的限度", "explanation": "有些美让人发慌：一片过于辽阔的海、一段好得不像真的关系。它并没有要害你，只是超出了你此刻能承受的容量。承认限度，才能继续靠近。", "western": "里尔克在《哀歌》里把美与恐怖绑在一起，延续了尼采与荷尔德林对崇高之极限的追问：美不是安慰，而是存在强度的临界点。", "tags": ["平静", "反思", "孤独"]},
    {"id": "w2-069", "text": "爱是两个孤独的人相互保护、相互问候", "source": "里尔克《给青年诗人的信》", "concept": "两个孤独", "explanation": "好的关系不是把两个人合成一个，而是各自站得住，还愿意彼此照看。靠得太紧会窒息，离得太远会冷，边界需要一次次重新商量。这段距离，值得好好谈。", "western": "里尔克反对把爱理解为融合与占有，主张爱是守护彼此的孤独。这接近列维纳斯的他者伦理：真正的相遇以不可吞并的差异为前提。", "tags": ["社交", "孤独", "平静"]},
    {"id": "w2-070", "text": "你必须改变你的生活", "source": "里尔克《远古的阿波罗残躯》", "concept": "被美命令", "explanation": "站在一件真正的好作品面前，人会有一种被要求的感觉：不是被批评，而是忽然看见自己过得太潦草。那种推力，往往比任何计划都持久。", "western": "里尔克让阿波罗残躯的注视发出命令：美具有伦理的强制力。这与列维纳斯的“面容”结构惊人相似——他者的注视先于我的自由。", "tags": ["变化", "反思", "阅读"]},
    {"id": "w2-071", "text": "四月是最残忍的月份", "source": "艾略特《荒原》（赵萝蕤译）", "concept": "残忍的春天", "explanation": "春天并不总是温柔的，它逼着人从冬眠里醒过来，面对还没解决的事。如果你在别人兴高采烈时感到沉重，那不是你有问题，醒来本身就需要力气。", "western": "艾略特让春天成为残忍的：丁香从死去的土地里长出，记忆与欲望同时被唤醒。这句开篇奠定了《荒原》的调性——再生以死亡为代价。", "tags": ["低落", "疲惫", "焦虑"]},
    {"id": "w2-072", "text": "我们一切探索的终点，将是到达我们出发的地方", "source": "艾略特《四个四重奏·小吉丁》", "concept": "回到起点", "explanation": "走了很远，才发现要弄明白的是最初那件事：家、口音、小时候的一个疑问。这不是绕圈，因为回来的你，已经能第一次真正看见它。不必急着否认走过的路。", "western": "艾略特借《四重奏》的循环结构表达一种时间的神学：终点不是重复起点，而是“第一次认识那个地方”。这接近奥古斯丁式的回返。", "tags": ["迷茫", "释然", "反思"]},
    {"id": "w2-073", "text": "我们在信息中失去的知识，在哪里", "source": "艾略特《岩石》", "concept": "知识的位置", "explanation": "每天刷到的东西很多，能说清楚的却很少。信息不缺，缺的是把它放进一个结构里的耐心；那需要慢，也需要一点安静，慢下来才长得出判断。", "western": "艾略特在合唱诗里连续追问知识、智慧与信仰的失落，指向现代性的意义空洞。这一诊断与阿多诺对启蒙理性的批判互为回声。", "tags": ["阅读", "反思", "焦虑"]},
    {"id": "w2-074", "text": "女人要写小说，必须有钱和一间自己的房间", "source": "伍尔夫《一间自己的房间》", "concept": "创作的条件", "explanation": "伍尔夫说的不只是钱和房子，而是不被打断的时间与不必解释的空间。任何认真做事的人，都需要一块属于自己的、可以关门的角落。哪怕只是每天半小时。", "western": "伍尔夫把女性创作受阻追溯到物质条件与话语权的分配，而非天赋差异。这是把审美问题还原为政治经济学条件的经典论证。", "tags": ["专注", "写论文", "孤独"]},
    {"id": "w2-075", "text": "达洛维夫人说，她要自己去买花", "source": "伍尔夫《达洛维夫人》", "concept": "日常的自主", "explanation": "一句琐碎的日常宣告，却包含一个人对自己一天的支配权。给自己买花、做饭、走一段路，这些小事在替你说：生活还是我的。别把它们排在所有任务之后。", "western": "伍尔夫用意识流把琐碎提升为存在的证据：意义不在事件的大小，而在意识如何照亮此刻。这与现象学“回到事物本身”的取向相通。", "tags": ["晨间", "平静", "舒展"]},
    {"id": "w2-076", "text": "生活是一圈明亮的光晕，一个半透明的封套", "source": "伍尔夫《现代小说》", "concept": "生活的光晕", "explanation": "生活不是排好的日程表，而是一团忽明忽暗的感受。承认它本来就模糊，你就不必逼自己把每一天都解释成一条清晰的线。模糊不是失败，是它的质地。", "western": "伍尔夫以此反对爱德华式小说的线性情节，主张记录意识接收到的无数印象。这是现代主义的美学纲领：真实在微屑之处，而非在事件之中。", "tags": ["阅读", "放空", "平静"]},
    {"id": "w2-077", "text": "所有的动物都是平等的，但有些动物更平等", "source": "奥威尔《动物农场》", "concept": "平等的修辞", "explanation": "口号喊得越整齐，越值得看看谁在例外名单上。规则对所有人都一样，才是真的规则；一旦有了例外，它就开始变成特权的说法。看到例外，就该多问一句。", "western": "奥威尔用一句自相矛盾的标语揭示宣传的语法：平等被保留在词里，等级被落实在句中。这是对极权语言最简洁的分析。", "tags": ["烦躁", "反思", "社交"]},
    {"id": "w2-078", "text": "谁控制过去就控制未来，谁控制现在就控制过去", "source": "奥威尔《一九八四》", "concept": "记忆的政治", "explanation": "记忆不是私人保险箱，它会被改写、被删掉、被反复讲述成另一个版本。所以保留自己的记录、日记和证词，是一件比想象中更有分量的事。", "western": "奥威尔把极权统治的核心放在对记忆的持续修订上：现实由当下的权力定义。这与福柯关于话语生产的分析可以互相印证。", "tags": ["反思", "焦虑", "失去"]},
    {"id": "w2-079", "text": "政治语言的存在，就是为了让谎言听起来真实", "source": "奥威尔《政治与英语》", "concept": "语言的腐坏", "explanation": "当词语被用来遮掩而不是说明，人就开始失去判断的抓手。反过来，把话说得具体、可核对，也是一种抵抗，哪怕只在自己的小群里。具体，是诚实的第一步。", "western": "奥威尔在随笔中主张，思想的混乱与语言的腐坏互为因果。清晰的写作因此具有政治意义，这一立场与法兰克福学派的语言批判同向。", "tags": ["写论文", "反思", "烦躁"]},
    {"id": "w2-080", "text": "重要的不是遭遇了什么，而是你记住了什么", "source": "马尔克斯《活着为了讲述》", "concept": "记忆的构造", "explanation": "同一件事，不同的人记住的部分完全不同。你反复回想的那一版，慢慢就成了你的人生故事；而故事是可以重写的，只要换一个记住的角度。", "western": "马尔克斯把记忆当作叙事的原料而非档案，这与现象学对回忆的分析相近：过去总以当下的意义被重新组织。身份因此是叙述的产物。", "tags": ["反思", "变化", "失去"]},
    {"id": "w2-081", "text": "我要在你身上做，春天对樱桃树做的事", "source": "聂鲁达《二十首情诗和一首绝望的歌》", "concept": "欲望的季节", "explanation": "这句诗把爱写成季节的力量：不是占有，而是让某样东西自己开花。好的关系大概也是这样，让对方长成他本来的样子，用力过猛反而折枝。", "western": "聂鲁达把欲望自然化，用植物的生长替换占有的语法。这一写法与巴塔耶对爱欲之越界的讨论相邻：欲望指向丰盈，而非填补匮乏。", "tags": ["期待", "社交", "舒展"]},
    {"id": "w2-082", "text": "今夜我可以写出最哀伤的诗句", "source": "聂鲁达《二十首情诗和一首绝望的歌》", "concept": "失去的语法", "explanation": "失去一个人之后，最先恢复的往往是语言：你又能把它写成句子了。写下来不等于好了，但至少那份重量有了一个可以安放的地方。句子立住了，人也慢慢站住。", "western": "聂鲁达用“可以写出”这样的能力句写悲伤，把痛苦转成可操作的形式。这接近亚里士多德式的净化：情感的再现本身具有整理力量。", "tags": ["失去", "低落", "夜晚"]},
    {"id": "w2-083", "text": "爱是这么短，遗忘是这么长", "source": "聂鲁达《二十首情诗和一首绝望的歌》", "concept": "遗忘的长度", "explanation": "热恋的浓度很高，退潮却要很久。别用“怎么还没走出来”催自己；遗忘有自己的速度，它不按你的日程表工作，你能做的只是别再给它加戏。", "western": "聂鲁达把时间的不对称写成爱情的真相：强度与长度并不成比例。这与柏格森对绵延的区分呼应——心理时间从不服从钟表。", "tags": ["失去", "低落", "孤独"]},
    {"id": "w2-084", "text": "使生如夏花之绚烂，死如秋叶之静美", "source": "泰戈尔《飞鸟集》（郑振铎译）", "concept": "生死的姿态", "explanation": "这句诗不催人拼命绚烂，它把生与死放在同一个节奏里：该盛放时盛放，该落下时安静地落下，不必都用同一种力气。不必用同一种力气，也不必互相解释。", "western": "泰戈尔把生死写成同一种自然节律的两面，接近斯宾诺莎的必然性：不把死亡当作失败，而是当作实体的一部分来接受。", "tags": ["平静", "释然", "晴"]},
    {"id": "w2-085", "text": "世界以它的痛苦吻我，却要我以歌声回报", "source": "泰戈尔《飞鸟集》", "concept": "回应的姿态", "explanation": "这不是要求你感恩苦难，也不是说痛必须被美化成歌。它更像一种姿态：不否认伤，但也不让伤成为你唯一的语言，留一个别的出口。歌不必好听，能唱就行。", "western": "泰戈尔的“以歌回报”接近尼采式的命运之爱：不是消除痛苦，而是肯定包括痛苦在内的整体。差别在于他把它落在虔诚，而非力量。", "tags": ["低落", "释然", "感激"]},
    {"id": "w2-086", "text": "我们把世界看错了，反说它欺骗我们", "source": "泰戈尔《飞鸟集》（郑振铎译）", "concept": "投射的错觉", "explanation": "很多“世界对我不好”，其实是期待与现实没对上。把期待说清楚，失望就有了具体形状，也才有了可以商量的余地，含糊的委屈最磨人。把话说清楚，委屈就少一半。", "western": "这句诗接近斯宾诺莎与爱比克泰德的共同立场：困扰来自判断，而非事物本身。认知的校正先于环境的改变，这一步往往比改变环境更可行。", "tags": ["烦躁", "反思", "平静"]},
    {"id": "w2-087", "text": "讲故事的技艺正在消失", "source": "本雅明《讲故事的人》", "concept": "经验的贬值", "explanation": "以前的故事靠口耳相传，带着讲述者的温度和停顿；现在信息很快，却不容易留下什么。想保留一点经验，得有人愿意慢慢讲、慢慢听。听，也是一种稀缺的能力。", "western": "本雅明把讲故事的衰落与经验共同体的解体联系起来：一战之后，可传达的经验被技术信息取代。这与阿多诺对文化工业的判断同源。", "tags": ["孤独", "阅读", "变化"]},
    {"id": "w2-088", "text": "奥斯维辛之后，写诗是野蛮的", "source": "阿多诺《文化批判与社会》", "concept": "之后的艺术", "explanation": "这句话不是在禁止写诗，而是在质问：面对巨大的灾难，美的形式是否还站得住。它要求创作者先诚实，再谈技巧，轻巧的抒情需要更多理由。", "western": "阿多诺的命题针对文化在暴行之后仍照常运作的麻木。他后来补充：苦难也需要被表达，否则会被再次抹去。批判因此指向形式本身的责任。", "tags": ["失去", "反思", "阅读"]},
    {"id": "w2-089", "text": "同一性思维抹去了非同一者的痕迹", "source": "阿多诺《否定的辩证法》", "concept": "非同一性", "explanation": "把人和事都归进一个概念，最省事，也最容易漏掉它真正特别的地方。留一点说不清的余地，是在保护对方，也是在保护你自己的复杂。留白，是给它留位置。", "western": "阿多诺以“非同一者”抵抗概念的暴力：辩证法不应把差异收进同一，而应守住概念的剩余。这是对黑格尔体系最尖锐的内在批判。", "tags": ["反思", "烦躁", "写论文"]},
    {"id": "w2-090", "text": "文化工业所制造的，正是它所要满足的需求", "source": "阿多诺《启蒙辩证法》", "concept": "文化工业", "explanation": "有些欲望是被生产出来的：先让你觉得自己缺什么，再把东西卖给你。意识到这一层，选择会多一点，虽然不一定更轻松，但被制造的需要也可以放下。", "western": "阿多诺与霍克海默指出，文化工业的标准化产品同时塑造并满足大众需求，形成闭合的循环。启蒙由此退化为神话，批判理性被工具理性取代。", "tags": ["烦躁", "反思", "社交"]},
    {"id": "w2-091", "text": "愿中国青年都摆脱冷气，只是向上走", "source": "鲁迅《热风·随感录四十一》", "concept": "摆脱冷气", "explanation": "冷气不只是天气，也是那种“反正没用”的语气。它不一定来自别人，有时已经搬进自己心里。向上走不必轰轰烈烈，先做一件不肯敷衍的小事。", "western": "尼采把这种自我矮化称为“末人”的舒适：不再渴望，也不再冒险。鲁迅的“向上”不是乐观主义，而是一种不肯把虚无当成终点的意志。", "tags": ["低落", "疲惫", "期待"]},
    {"id": "w2-092", "text": "有一分热，发一分光", "source": "鲁迅《热风·随感录四十一》", "concept": "微小的光", "explanation": "不必等到自己足够强、足够完整才开始。你现在有的那一点力气，就够照亮脚边一小块地方；而那一小块，常常正好是别人需要的。光小，也照得到脚下。", "western": "这接近阿伦特所说的“行动”：人不必先具备资格才可开始，开始本身就是人的能力。微小的行动进入公共世界，会产生无法预设的后果。", "tags": ["疲惫", "期待", "专注"]},
    {"id": "w2-093", "text": "希望是附丽于存在的，有存在，便有希望", "source": "鲁迅《华盖集续编·记谈话》", "concept": "希望与存在", "explanation": "希望不是先有情绪再有的东西，它依附在“还活着、还在场”这个事实上。状态很差的时候，先保住存在本身，希望会慢慢跟上来。先把自己留在场上。", "western": "这与布洛赫“希望的原理”相近：希望不是对未来的预测，而是尚未实现之可能性的在场。存在先于意义，希望寄居在存在之中。", "tags": ["低落", "释然", "期待"]},
    {"id": "w2-094", "text": "绝望之为虚妄，正与希望相同", "source": "鲁迅《野草·希望》", "concept": "绝望的虚妄", "explanation": "绝望和希望一样，都是对未来的断言，而未来并不接受这种断言。这句话不是让你乐观，而是把“一切都不会好”从结论降回猜测。断言越绝对，越容易被现实驳回。", "western": "鲁迅借裴多菲的句子拆掉绝望的确定性。这与加缪对荒诞的处理相通：既不屈服于虚无，也不假装意义已被保证，只在不确定中行动。", "tags": ["低落", "迷茫", "释然"]},
    {"id": "w2-095", "text": "待我成尘时，你将见我的微笑", "source": "鲁迅《野草·墓碣文》", "concept": "向死的从容", "explanation": "这句话有一种奇特的轻松：把最坏的结果先看完，反而不再被它追着跑。不是不在乎，而是不再用恐惧替自己做决定。心里有了底，脚下就稳一点。", "western": "这与海德格尔“先行到死”的结构同构：先把死亡纳入视野，此在才可能从日常的遮蔽中脱身，本真地选择当下。怕，也就不再支配人。", "tags": ["平静", "释然", "反思"]},
    {"id": "w2-096", "text": "其实地上本没有路，走的人多了，也便成了路", "source": "鲁迅《故乡》", "concept": "路的生成", "explanation": "很多路不是先存在再等人走，而是有人先踩过去，才慢慢成了路。你的尝试即使没人走过，也不必先证明它合理，走下去它才算数。走的人多了，才叫路。", "western": "这接近维特根斯坦的“规则遵循”：规则不由先验条文决定，而在共同实践中被反复确认。路是集体行动沉淀出来的习惯。", "tags": ["迷茫", "期待", "变化"]},
    {"id": "w2-097", "text": "真的猛士，敢于直面惨淡的人生", "source": "鲁迅《记念刘和珍君》", "concept": "直面人生", "explanation": "勇敢不是不害怕，而是不把害怕改写成别的东西：不装作无所谓，也不把责任推给命运。先看清楚，再决定怎么办，看清本身就要力气。看清楚，是行动的第一步。", "western": "这接近亚里士多德所说的勇敢作为中道：在鲁莽与怯懦之间，勇敢以对处境的准确判断为前提，而非以情绪的强弱衡量。", "tags": ["焦虑", "疲惫", "反思"]},
    {"id": "w2-098", "text": "不在沉默中爆发，就在沉默中灭亡", "source": "鲁迅《记念刘和珍君》", "concept": "沉默的代价", "explanation": "压下去的话不会消失，它会以别的形式回来：失眠、易怒、突然的崩溃。找一个安全的出口说一点，比等到爆发更省力。早一点说，代价小一些。", "western": "弗洛伊德式的压抑模型在此可见：被抑制的情感并不消失，而会转化为症状。鲁迅的句子更政治化，沉默也是被安排的处境。", "tags": ["烦躁", "焦虑", "社交"]},
    {"id": "w2-099", "text": "我实在再没有吃到那夜似的好豆", "source": "鲁迅《社戏》", "concept": "回不去的好", "explanation": "那夜的豆未必真那么好吃，好的是那段夜路、那群人、那种不必赶时间的心情。承认这一点，就不会一直拿现在的日子和它比较。也不必要求现在复刻它。", "western": "这接近普鲁斯特式的记忆结构：味道只是引信，真正被唤回的是整段经验。怀旧的对象从来不是物，而是当时的自己。", "tags": ["平静", "失去", "夜晚"]},
    {"id": "w2-100", "text": "悲剧将人生的有价值的东西毁灭给人看", "source": "鲁迅《再论雷峰塔的倒掉》", "concept": "悲剧的定义", "explanation": "悲剧之所以让人难受，不是因为它惨，而是因为它先让你看见那东西有多值得，再把它拿走。所以难过是有理由的，不必急着止住。难受本身就是一种证据。", "western": "这呼应亚里士多德《诗学》的悲剧理论：悲剧通过引起怜悯与恐惧完成净化。价值先被建立再被摧毁，落差才是情感力量的来源。", "tags": ["失去", "低落", "阅读"]},
    {"id": "w2-101", "text": "我们自古以来，就有埋头苦干的人", "source": "鲁迅《且介亭杂文·中国人失掉自信力了吗》", "concept": "沉默的脊梁", "explanation": "有些支撑不发声：修桥的人、备课的人、把一件事做到底的人。他们不在热搜上，却构成了生活的地面。你也可以是这样的人。他们不响，但地基是他们打的。", "western": "这接近阿伦特对“工作”的划分：作品留下持久的世界，与消费性的劳动不同。文明的连续性由这些不显眼的建造维持。", "tags": ["专注", "疲惫", "感激"]},
    {"id": "w2-102", "text": "希望本是无所谓有，无所谓无的", "source": "鲁迅《故乡》", "concept": "希望的非实体", "explanation": "希望不像一件可以清点的东西，有或没有都不准确。它更像一种走法：走起来，它才出现；停下来追问它是否存在，它反而更稀薄。所以别等它，先走两步。", "western": "这与实用主义的真理观有亲缘：观念的意义在于它引出的行动差异。希望不是被发现的实体，而是在实践中被验证的方向。", "tags": ["迷茫", "期待", "反思"]},
    {"id": "w2-103", "text": "我们于日用必需的东西以外，必须还有一点无用的游戏与享乐", "source": "周作人《北京的茶食》", "concept": "无用的必需", "explanation": "生活不能只有效率和必需。看一会儿云、摆弄一盆植物、走一条绕远的路，这些不产出的时刻，恰恰在维持你对生活的兴趣。它们是生活的余味，不是浪费。", "western": "这接近席勒的“游戏冲动”：人只有在不为功利所迫的游戏中才是完整的人。无用之用，是审美教育对工具理性的修正。", "tags": ["舒展", "放空", "休息"]},
    {"id": "w2-104", "text": "喝茶当于瓦屋纸窗之下，清泉绿茶，用素雅的陶瓷茶具", "source": "周作人《喝茶》", "concept": "日常的仪式", "explanation": "喝茶的讲究不在贵，而在那些多余的小动作：等水开、温杯、看叶子舒展开。它们把一段时间从任务里切出来，交还给你。水开了，心也就慢下来。", "western": "这可以读作一种世俗化的仪式理论：重复的身体动作制造出可预期的秩序，从而暂时隔开焦虑。仪式的作用在形式，而非信仰。", "tags": ["平静", "休息", "晨间"]},
    {"id": "w2-105", "text": "我的故乡不止一个，凡我住过的地方都是故乡", "source": "周作人《故乡的野菜》", "concept": "故乡的复数", "explanation": "人可以在很多地方生根：一间宿舍、一条通勤路、一个常去的面馆。承认故乡是复数的，迁徙就不必总是失去，也可以是一次次抵达。不必只认一个来处。", "western": "这与海德格尔的“栖居”相近：家不是地理坐标，而是人建立关系、留下痕迹的方式。栖居是一种实践，而非出生地的属性。", "tags": ["孤独", "舒展", "变化"]},
    {"id": "w2-106", "text": "人生本来就是一种较广义的艺术", "source": "朱光潜《谈美》", "concept": "人生的艺术化", "explanation": "把生活当成作品，不是要求它完美，而是承认你在选择它的形状。同样的素材，有人过得潦草，有人过得有分寸，差别常在细节的用心。分寸感，是可以慢慢养的。", "western": "这延续了席勒与尼采的审美人生观：把存在当作可塑造的作品，而非既定事实。伦理在此与美学合流，性格成为风格。", "tags": ["舒展", "反思", "期待"]},
    {"id": "w2-107", "text": "以出世的精神，做入世的事业", "source": "朱光潜《谈美》", "concept": "出世与入世", "explanation": "做事时全力以赴，对结果保留一点距离。这不是不在乎，而是不让成败决定你整个人的价值，从而能够长期做下去。用力，但不把命押上。这样才走得远。", "western": "这接近斯多葛的“控制二分法”：尽力属于我，结果不属于我。爱比克泰德以此区分意志之内与之外，从而保住行动的自由。", "tags": ["专注", "焦虑", "平静"]},
    {"id": "w2-108", "text": "兴味要在青年时设法培养，过了正常时节，便会萎谢", "source": "朱光潜《给青年的十二封信·谈读书》", "concept": "兴味的时节", "explanation": "好奇心是有季节的，长期不用会变钝。不必等到有空才去读、去试；现在给它一点时间，它以后才有能力陪你度过漫长的日子。现在开始，还不算晚。", "western": "这接近杜威的经验论：兴趣不是天赋的存量，而是在经验中被养成的倾向。教育的任务正是让兴趣获得继续生长的条件。", "tags": ["阅读", "期待", "专注"]},
    {"id": "w2-109", "text": "读书并不在多，最重要的是选得精，读得彻底", "source": "朱光潜《给青年的十二封信·谈读书》", "concept": "精读的耐心", "explanation": "列一长串书单很容易，读完一本却很难。与其在十本书的前言里打转，不如把一本读到自己能复述、能反驳，那种扎实感会留下来。慢读一本，胜过翻十本。", "western": "这与分析哲学的训练相通：真正的理解表现为能重述论证、指出前提。阅读的深度以可检验的理解为准，而不是以页数计。", "tags": ["阅读", "专注", "复习考试"]},
    {"id": "w2-110", "text": "要见出事物本身的美，须把它摆在适当的距离之外", "source": "朱光潜《谈美·当局者迷，旁观者清》", "concept": "心理的距离", "explanation": "离得太近，看到的是需求和麻烦；离得太远，又只剩模糊。美常常出现在那个刚好的距离上，所以换一个位置看，感受会完全不同。站远一点，也站近一点。", "western": "这是布洛的“心理距离”说：审美态度要求暂时悬置实用关切。朱光潜把它接进中国美学，用以解释艺术与人生的分寸。", "tags": ["平静", "放空", "反思"]},
    {"id": "w2-111", "text": "凡是艺术家都须有一半是诗人，一半是匠人", "source": "朱光潜《谈美》", "concept": "诗人与匠人", "explanation": "灵感负责开头，手艺负责完成。只有热情，作品停在半途；只有技术，作品没有温度。两者都缺一点的时候，先补那个更弱的，别急着定型。补短处，比等灵感可靠。", "western": "这接近亚里士多德的技术论：技艺包含可传授的规则，而创造又需要超出规则的判断。艺术因此同时是制作与领悟。", "tags": ["写论文", "专注", "反思"]},
    {"id": "w2-112", "text": "散步是自由自在、无拘无束的行动", "source": "宗白华《美学散步》", "concept": "散步的自由", "explanation": "散步没有目的地，也不计算步数，走到哪儿算哪儿。思路卡住时，正是这种没有目标的移动，容易把僵住的注意力松开。走二十分钟，脑子会松一格。", "western": "这可以对照康德的“无利害的愉悦”：审美经验不服务于目的，因而自由。散步是这种自由在身体层面的练习，不为抵达，只为经过。", "tags": ["放空", "运动", "舒展"]},
    {"id": "w2-113", "text": "我的心为四事所占据了：天上的神明与星辰，人间的艺术与儿童", "source": "丰子恺《儿女》", "concept": "心的四事", "explanation": "把心交给几样具体而干净的东西，人就不容易被琐碎的怨气占满。不必是星辰与艺术，也可以是植物、乐器、一只猫。重要的不是清单，是那份认真。", "western": "这接近奥古斯丁式的“爱的秩序”：人的心总被某物占据，问题在于所爱之物的次序。丰子恺给出的是他自己的排序。", "tags": ["平静", "舒展", "感激"]},
    {"id": "w2-114", "text": "使人生圆滑进行的微妙的要素，莫如“渐”", "source": "丰子恺《渐》", "concept": "渐的力量", "explanation": "人很少被一次巨大的变故击倒，更多是被每天一点点的消耗磨平。反过来，恢复也是渐的：每天好一点，不容易被看见，但确实在发生。所以别小看今天这一点。", "western": "这接近柏格森的绵延：真实的変化是连续、不可分割的，而钟表把它切成可计数的段落。渐的力量正在于它躲过了注意。", "tags": ["变化", "疲惫", "反思"]},
    {"id": "w2-115", "text": "人间的事，只要生机不灭，即使重遭天灾人祸，暂被阻抑，终有抬头的日子", "source": "丰子恺《生机》", "concept": "不灭的生机", "explanation": "被压住不等于被消灭。植物被踩过还会从侧面长出来，人也常常如此。眼下要做的可能只是保住那一点生机：吃饭、睡觉、见人。先活下来，再谈别的。", "western": "这接近斯宾诺莎的“努力”概念：每个存在者都倾向于维持并增强自身的存在。生机不是乐观情绪，而是存在本身的倾向。", "tags": ["疲惫", "低落", "期待"]},
    {"id": "w2-116", "text": "我要求孩子们的举止同我自己一样，何其乖谬", "source": "丰子恺《儿女》", "concept": "不复制自己", "explanation": "把自己没做到的标准拿去要求孩子，是最容易也最无效的教育。承认这一点会有点难堪，但关系往往从这句承认开始变好。对身边人，也一样。", "western": "这触及卢梭以来的教育悖论：教育者总想复制自己，却忘了儿童是独立的存在。康德式的尊重要求把他人当作目的本身。", "tags": ["社交", "反思", "烦躁"]},
    {"id": "w2-117", "text": "人的生活可以分作三层：物质、精神、灵魂", "source": "丰子恺《我与弘一法师》", "concept": "生活的三层", "explanation": "先要活得下去，再要活得有意思，最后才问活得值不值得。三层不必都齐，但只停在一层，日子会慢慢变薄，哪怕物质并不缺。往上走一步，就够了。", "western": "这近乎克尔凯郭尔的三阶段：审美的、伦理的、宗教的生存方式。层次不是高低评判，而是人以何种方式与自己的存在发生关系。", "tags": ["反思", "迷茫", "阅读"]},
    {"id": "w2-118", "text": "这个人也许永远不回来了，也许明天回来", "source": "沈从文《边城》", "concept": "开放的等待", "explanation": "《边城》把结局留成两半：可能永远，也可能明天。这种不确定让人难受，却也保留了余地；有些等待不必先要一个答案才能继续。等与不等，都还是活着。", "western": "这接近克尔凯郭尔的“悬置”：可能性未被收束时，人必须在不确信中生活。小说拒绝闭合，正是拒绝替读者做形而上的结算。", "tags": ["孤独", "期待", "失去"]},
    {"id": "w2-119", "text": "日头没有辜负我们，我们也切莫辜负日头", "source": "沈从文《边城》", "concept": "与日子的对答", "explanation": "日子给过你光，也难免给你雨。这句话不是劝你感恩，而是提醒一种对等：既然太阳照常升起，你也还可以做点什么，哪怕很小。对得起今天，就不算输。", "western": "这接近尼采的“命运之爱”：不是忍受生活，而是愿意它如其所是地再来一次。肯定当下，是对虚无最实际的回答，是肯定而非忍耐。", "tags": ["晨间", "晴", "舒展"]},
    {"id": "w2-120", "text": "一个人的口味要宽一点、杂一点", "source": "汪曾祺《四方食事》", "concept": "口味的宽度", "explanation": "吃得杂一点，是不给自己设太多禁令。生活也一样：愿意试一试没做过的事，人的世界就不会只剩下熟悉的那一小块。先尝一口，再决定喜不喜欢。", "western": "这接近密尔的“生活实验”：人的发展需要接触多样的经验，单一样式不足以判断何为好生活。宽容由此具有认识论的价值。", "tags": ["期待", "舒展", "社交"]},
    {"id": "w2-121", "text": "如果你来访我，我不在，请和我门外的花坐一会儿", "source": "汪曾祺《人间草木》", "concept": "待客的余裕", "explanation": "这句话把“没见到”也安排得温柔：不必尴尬，不必改天，先在门口坐坐。人和人之间，有时不必完成一次见面才算有情分。门口的花，也算主人。", "western": "这接近列维纳斯的“欢迎”：伦理关系首先是一种无条件的接待姿态，不取决于对方是否在场、是否回报。花是待客的替代性在场。", "tags": ["社交", "平静", "舒展"]},
    {"id": "w2-122", "text": "家人闲坐，灯火可亲", "source": "汪曾祺《冬天》", "concept": "灯火的温度", "explanation": "最好的时刻常常没有内容：几个人坐着，灯亮着，谁也没说什么要紧话。这种平常，是很多年后回想起来最清楚的部分。灯亮着，人就还在一起。", "western": "这接近海德格尔的“栖居”：家的本质不在建筑，而在事物被安放、人被聚集的方式。灯与闲坐，让空间成为可以停留的地方。", "tags": ["平静", "夜晚", "感激"]},
    {"id": "w2-123", "text": "围在城里的人想逃出来，城外的人想冲进去", "source": "钱锺书《围城》", "concept": "围城的循环", "explanation": "得不到的想进去，进去了又想出来。这不只是婚姻，也适用于专业、城市、生活方式。看清这一点，选择会少一点浪漫的误判：想清楚你要的是入口，还是里面。", "western": "这接近叔本华式的欲望结构：满足只是短暂的间隙，欲求随即转向下一个目标。围城的循环正是欲望自身的形状。", "tags": ["迷茫", "反思", "社交"]},
    {"id": "w2-124", "text": "吃饭有时很像结婚，名义上最主要的东西，其实往往是附属品", "source": "钱锺书《围城》", "concept": "名与实的错位", "explanation": "名义上重要的，常常只是由头：吃饭的重点是社交，结婚的重点也许是别的。识别一场活动真正的目的，能省下很多不必要的用力。看清目的，才不白忙。", "western": "这接近分析哲学对“表面语法”的警惕：句子的形式会掩盖真正的逻辑结构。钱锺书的讽刺正是日常语言层面的祛魅。", "tags": ["社交", "反思", "烦躁"]},
    {"id": "w2-125", "text": "忠厚老实人的恶毒，像饭里的沙砾或者出骨鱼片里未净的刺", "source": "钱锺书《围城》", "concept": "隐蔽的恶意", "explanation": "有些伤害不来自明显的敌人，而来自看起来无害的人：一句关切的评判，一次好意的安排。它不致命，却让人一直不舒服。别因为对方无恶意，就否认自己的疼。", "western": "这接近福柯式的微观权力：最有效的支配往往不表现为暴力，而藏在善意与常识里。识别它需要分辨语气背后的位置。", "tags": ["烦躁", "社交", "反思"]},
    {"id": "w2-126", "text": "譬如一串葡萄到手，一种人挑最好的先吃", "source": "钱锺书《围城》", "concept": "两种吃法", "explanation": "先吃好的，剩下的是越来越差的；先吃差的，剩下的是越来越好的。两种人都没错，只是对时间的态度不同，也各自付出不同的代价。没有哪种吃法更高级。", "western": "这可以读作对“延迟满足”的朴素反驳：把最好的留到最后未必更幸福，只是把希望押在未来。边沁式的当下计算在此更诚实。", "tags": ["反思", "期待", "平静"]},
    {"id": "w2-127", "text": "于千万人之中遇见你所要遇见的人，于千万年之中，时间的无涯的荒野里", "source": "张爱玲《爱》", "concept": "相遇的偶然", "explanation": "把相遇放进千万人和千万年的尺度里，它几乎是奇迹；放回日常，它又只是一次恰好。两种看法都对，差别在于你愿不愿意珍惜这个恰好。", "western": "这接近巴迪欧对爱的定义：爱是两个人从偶然相遇中创造出的持续世界。偶然是起点，忠诚才是把偶然变成命运的动作。", "tags": ["期待", "感激", "社交"]},
    {"id": "w2-128", "text": "生命是一袭华美的袍，爬满了蚤子", "source": "张爱玲《天才梦》", "concept": "华袍与蚤子", "explanation": "外表的光鲜和贴身的不适常常同时存在。承认这一点，就不必因为自己“看起来不错却很难受”而怀疑感受的真实性。体面与辛苦，可以并存。", "western": "这是对表象与本真的经典区分：袍是呈现给他人的外观，蚤子是无法转嫁的身体经验。张爱玲让两者同处一具身体，拒绝单方面的叙述。", "tags": ["疲惫", "反思", "低落"]},
    {"id": "w2-129", "text": "长的是磨难，短的是人生", "source": "张爱玲《公寓生活记趣》", "concept": "磨难与人生", "explanation": "难熬的部分总显得很长，好过的日子一晃就没了。这不是要你悲观，而是提醒：正因为短，才不必把有限的时间都用来忍受。能改的，尽早改。", "western": "这与塞涅卡对生命短暂的诊断相通：生命并不短，是我们把大量时间交给了不值得的事。时间感的主观拉长，正暴露了生活的失配。", "tags": ["疲惫", "低落", "反思"]},
    {"id": "w2-130", "text": "回忆这东西若是有气味的话，那就是樟脑的香", "source": "张爱玲《更衣记》", "concept": "回忆的气味", "explanation": "樟脑的味道属于旧衣柜：甜，微凉，带一点防蛀的涩。回忆大概也是这样，既让人安心，又提醒你有些东西正在被保存而不是被使用。旧物会替人记住一些事。", "western": "这接近普鲁斯特的“非自愿记忆”：气味绕过理智，直接唤回整段过去。记忆的入口常常是感官，气味是最不讲道理的那一种。", "tags": ["夜晚", "平静", "失去"]},
    {"id": "w2-131", "text": "出名要早呀，来得太晚的话，快乐也不那么痛快", "source": "张爱玲《〈传奇〉再版序》", "concept": "出名的时机", "explanation": "这句话里有坦率的急躁：想要的东西，晚到了，滋味也会变。它不必被当成人生纲领，但可以提醒你别总把想做的事推到“以后”。想做的事，别一直排队。", "western": "这接近伊壁鸠鲁派对时间的看法：快乐与它发生的时刻有关，延迟会改变它的性质。张爱玲的坦白属于一种世俗的享乐主义。", "tags": ["期待", "焦虑", "反思"]},
    {"id": "w2-132", "text": "我喜欢钱，因为我没吃过钱的苦", "source": "张爱玲《童言无忌》", "concept": "坦率的世俗", "explanation": "承认自己喜欢安稳的物质条件，并不庸俗。人不必为想过得舒服而道歉，只要不把它当成衡量别人的尺子，也不假装自己完全不在乎。坦率，比清高更好相处。", "western": "这接近桑塔亚那对体面生活的辩护：物质条件是好生活的必要成分，而非道德的污点。张爱玲拒绝把清贫浪漫化。", "tags": ["舒展", "反思", "社交"]},
    {"id": "w2-133", "text": "生命有它的图案，我们惟有临摹", "source": "张爱玲《倾城之恋》", "concept": "图案与临摹", "explanation": "有些事像早就画好的图样：性格、家境、时代。人能做的不是另起一张纸，而是在给定的线条里，决定用什么样的笔触去填。线条是给定的，笔触不是。", "western": "这接近斯宾诺莎的决定论与自由的关系：自由不在于取消必然，而在于认识它并按其本性行动。临摹因此可以是一种主动。", "tags": ["迷茫", "平静", "反思"]},
    {"id": "w2-134", "text": "文学是可爱的，生活是好玩的，艺术是要有所牺牲的", "source": "木心《文学回忆录》", "concept": "文学与生活", "explanation": "把文学说成可爱，把生活说成好玩，是拒绝用沉重的腔调谈它们；而艺术要有所牺牲，是承认喜欢的东西也要付账，时间、力气，甚至一点安稳。", "western": "这接近尼采对“轻”的肯定：真正的深刻不必以沉重为标志。木心把审美态度还给日常，同时保留代价意识，避免廉价的乐观。", "tags": ["阅读", "舒展", "反思"]},
    {"id": "w2-135", "text": "从前的日色变得慢，车，马，邮件都慢", "source": "木心《从前慢》", "concept": "慢的密度", "explanation": "慢不等于更幸福，但慢下来时，一件事的密度会变大：一封信要等很久，所以读得认真。今天也可以人为地制造一点这样的慢。慢下来，才看得见细节。", "western": "这接近本雅明对“经验”的怀念：技术的加速改变了感知的节奏，使经验难以沉淀。慢是对注意力的一种重新分配。", "tags": ["平静", "夜晚", "阅读"]},
    {"id": "w2-136", "text": "岁月不饶人，我亦未曾饶过岁月", "source": "木心《云雀叫了一整天》", "concept": "互不轻饶", "explanation": "时间会磨损人，这是没法商量的；但人也可以不把它全用来衰老：读、写、走、爱，都算还手。这句话的力气不在豪迈，而在不肯白过。还手的方式，各有各的。", "western": "这接近尼采的“命运之爱”与“权力意志”的日常版本：不是接受时间，而是与之角力。人通过还手，把被动的时间变成自己的时间。", "tags": ["变化", "疲惫", "期待"]},
    {"id": "w2-137", "text": "我是一个在黑暗中大雪纷飞的人", "source": "木心《云雀叫了一整天》", "concept": "内在的暴雪", "explanation": "外表安静，里面却下着大雪。这句话替很多说不出的状态找到了形状：不是没事，只是热闹都在别人看不见的地方。不必急着解释给谁听。", "western": "这接近克尔凯郭尔对“内在性”的强调：真正的生存状态无法被外在行为完整表达。黑暗中的雪，是主体性的过剩而非匮乏。", "tags": ["孤独", "平静", "低落"]},
    {"id": "w2-138", "text": "如欲相见，我在各种悲喜交集处", "source": "木心《琼美卡随想录》", "concept": "悲喜交集", "explanation": "人最真实的样子，常在情绪的交叉口：既高兴又难过，既想留下又想走。愿意在这种地方见人，关系才不至于只停在体面的表面。不必先把自己整理好。", "western": "这接近亚里士多德对悲剧情感的描述：怜悯与恐惧同时发生，情感不是单色的。木心把这种混合状态当作相遇的地址。", "tags": ["社交", "反思", "平静"]},
    {"id": "w2-139", "text": "没有审美力是绝症，知识也救不了", "source": "木心《文学回忆录》", "concept": "审美的能力", "explanation": "知识可以背下来，品味却要慢慢养。它体现在你选什么、留什么、为什么事停下来；这些选择合起来，就是你的生活质地。多看真东西，眼光会自己长。", "western": "这接近康德《判断力批判》的难题：审美判断不可教，只能通过范例与练习培养。趣味因此是自由与教养的交界处。", "tags": ["阅读", "反思", "舒展"]},
    {"id": "w2-140", "text": "黑夜给了我黑色的眼睛，我却用它寻找光明", "source": "顾城《一代人》", "concept": "黑暗中的寻找", "explanation": "这句诗常被当成励志口号，其实它更冷：眼睛是黑夜给的，寻找是后来的选择。承认处境塑造了你，同时不把它当作终点。寻找是后来的事，也是你的事。", "western": "这接近阿多诺的否定辩证法：认识必须从否定出发，而不是从光明出发。顾城的寻找，是在被规定之处生出不被规定的动作。", "tags": ["低落", "期待", "夜晚"]},
    {"id": "w2-141", "text": "草在结它的种子，风在摇它的叶子", "source": "顾城《门前》", "concept": "无言的相处", "explanation": "诗里两个人站着不说话，各自看草和风。关系里最舒服的时刻，往往不是说了什么，而是沉默也不尴尬。能一起安静，是难得的默契。不说话，也算在一起。", "western": "这接近海德格尔的“共在”：本真的相处不必靠交谈填满，共同置身于世界本身就是一种理解。沉默也可以是关系的形式。", "tags": ["平静", "社交", "放空"]},
    {"id": "w2-142", "text": "我是一个任性的孩子", "source": "顾城《我是一个任性的孩子》", "concept": "任性的坚持", "explanation": "任性在这里不是耍脾气，而是不肯把想要的东西全部换成“应该”。保留一点不合时宜的偏好，人就不容易被日子磨成一个模子。留一点，就不算全交出去。", "western": "这接近尼采对“孩子”这一精神阶段的描述：经过骆驼与狮子之后，孩子以游戏的方式重新肯定世界。任性可以是创造的前身。", "tags": ["舒展", "期待", "反思"]},
    {"id": "w2-143", "text": "睡吧，合上双眼，世界就与我无关", "source": "顾城《生命幻想曲》", "concept": "睡眠的边界", "explanation": "这句诗把睡觉写成一种温柔的撤退：世界还在转，但暂时不归你管。睡不着的时候，也可以先不强迫自己，只把眼睛和屏幕都关上。明天再管，也来得及。", "western": "这接近胡塞尔式的“中止判断”：把世界的有效性暂时加括号。睡眠是最日常的悬置练习，人借此从持续的任务中脱身。", "tags": ["睡眠", "夜晚", "休息"]},
    {"id": "w2-144", "text": "我要在大地上画满窗子", "source": "顾城《我是一个任性的孩子》", "concept": "画满窗子", "explanation": "这句诗想做的事很孩子气：给所有习惯黑暗的眼睛开窗。它提醒人，改变不一定要靠宏大方案，也可以先给某个人一点光。窗子小，但方向是亮的。", "western": "这接近布洛赫的“尚未意识”：乌托邦冲动以图像的方式先行。画窗不是逃避现实，而是把尚未存在的可能，先画进现实里。", "tags": ["期待", "舒展", "低落"]},
    {"id": "w2-145", "text": "面朝大海，春暖花开", "source": "海子《面朝大海，春暖花开》", "concept": "向往的姿态", "explanation": "这八个字被用得太多，几乎成了装饰。放回原诗，它其实是一个还没实现的心愿：想要简单的生活，也想要与人与己和解。愿望本身，也是力气。", "western": "这接近布洛赫的“尚未”：希望指向还未到来的可能，而非已有的现实。诗句的力量正来自它尚未兑现，而不是已经圆满。", "tags": ["期待", "舒展", "晴"]},
    {"id": "w2-146", "text": "从明天起，做一个幸福的人", "source": "海子《面朝大海，春暖花开》", "concept": "从明天起", "explanation": "把开始推到明天，是很多人的习惯，也是这首诗最动人的地方：它诚实得近乎脆弱。你也可以把“明天”改成今天的一件小事，哪怕只是认真吃一顿饭。", "western": "这接近奥古斯丁对时间的分析：人总在期待未来，却难以安住当下。海子的“明天”既是希望的语法，也是推迟生活的语法。", "tags": ["期待", "低落", "晨间"]},
    {"id": "w2-147", "text": "你来人间一趟，你要看看太阳", "source": "海子《夏天的太阳》", "concept": "抬头看太阳", "explanation": "这句话朴素得像叮嘱：既然来了，就别只低头赶路。太阳在这里不是风景，而是提醒你还有身体、有白天、有不需要理由的暖。抬头这件事，不需要理由。", "western": "这接近第欧根尼式的犬儒主义：好生活不在理论里，而在身体能感到的当下。晒太阳是一种最低限度的幸福实践。", "tags": ["晨间", "舒展", "晴"]},
    {"id": "w2-148", "text": "活在这珍贵的人间，太阳强烈，水波温柔", "source": "海子《活在这珍贵的人间》", "concept": "人间的珍贵", "explanation": "诗里没有说人间完美，只说它珍贵：有强烈的太阳，也有温柔的水波。承认苦与好同时存在，人才不必在两者之间选边。珍贵不等于轻松，只是值得。", "western": "这接近尼采的“肯定”：肯定生命包括它的残酷，而非只肯定其中的甜美。太阳的强烈与水波的温柔，是同一世界的两面。", "tags": ["平静", "舒展", "感激"]},
    {"id": "w2-149", "text": "姐姐，今夜我在德令哈", "source": "海子《日记》", "concept": "异乡的夜", "explanation": "一句地名加一个称呼，就把孤独说完了。人在陌生城市时，往往只需要一个可以叫出名字的人，哪怕他并不在身边。名字本身就有温度。名字念出来，本身就有温度。", "western": "这接近海德格尔的“无家可归”：现代人的栖居被打断，地点只剩坐标。呼唤一个称呼，是在荒凉中重建最小的关系。", "tags": ["孤独", "夜晚", "低落"]},
    {"id": "w2-150", "text": "天空一无所有，为何给我安慰", "source": "海子《黑夜的献诗》", "concept": "空的安慰", "explanation": "天空什么也没给，人却觉得被安慰了。这种经验说明：安慰不一定来自回应，有时只是有一个足够大的东西，让你把心事放进去。大，也是一种容纳。", "western": "这接近崇高的美学：面对超出尺度的对象，人先感到压迫，随后获得提升。空无因此具有肯定性的力量，而不只是缺失。", "tags": ["平静", "放空", "夜晚"]},
    {"id": "w2-151", "text": "要有最朴素的生活，与最遥远的梦想", "source": "海子《枫》", "concept": "朴素与遥远", "explanation": "生活要能落地：吃饭、睡觉、交房租；梦想可以远得看不清。两者并不矛盾，反而是彼此的条件，只有朴素撑着，遥远才不至于变成空话。朴素是地基，遥远是窗。", "western": "这接近斯多葛与理想主义的奇怪组合：对日常保持最低要求，对可能性保持最大开放。人因此既不被琐事吞没，也不被幻想带走。", "tags": ["期待", "平静", "专注"]},
    {"id": "w2-152", "text": "卑鄙是卑鄙者的通行证，高尚是高尚者的墓志铭", "source": "北岛《回答》", "concept": "颠倒的秩序", "explanation": "当规则被颠倒，坏成了通行证，好成了墓志铭。认清这种颠倒，不是为了变得犬儒，而是为了知道自己站在哪一边、为什么付代价。站定，比赢更难，也更要紧。", "western": "这接近阿多诺对“同一性”的批判：当价值被系统倒置，道德语汇本身也被污染。北岛的句子是一种拒绝被同化的命名。", "tags": ["烦躁", "反思", "低落"]},
    {"id": "w2-153", "text": "告诉你吧，世界，我不相信", "source": "北岛《回答》", "concept": "拒绝相信", "explanation": "这句“不相信”不是虚无，而是拒绝接受现成答案。怀疑本身需要力气，也需要承担：你说不信之后，还得自己去找能信的东西。信什么，得自己长出来。", "western": "这接近笛卡尔的怀疑方法，却少了重建的保证：怀疑成为姿态而非步骤。也接近加缪的反抗——拒绝，是保持清醒的方式。", "tags": ["迷茫", "烦躁", "反思"]},
    {"id": "w2-154", "text": "那时我们有梦，关于文学，关于爱情", "source": "北岛《波兰来客》", "concept": "旧日的梦", "explanation": "这句话的痛点在“那时”两个字：梦不是没了，是不再好意思提。中年人把它写进散文，年轻人读到时，会提前心疼一下自己。梦可以变小，但别注销，也别嘲笑从前的自己。", "western": "这接近本雅明对“经验”的哀悼：曾经可分享的激情被日常磨损。怀旧在此不是美化过去，而是指认当下的匮乏，因而也是一种批判。", "tags": ["失去", "变化", "夜晚"]},
    {"id": "w2-155", "text": "一切都是命运，一切都是烟云", "source": "北岛《一切》", "concept": "命运的排比", "explanation": "把一切都说成命运，是一种疲惫的智慧：既不争了，也不指望了。读到这样的句子，人反而会松一口气，因为不用再假装积极。松一口气，也是真的松。", "western": "这接近斯多葛的宿命论与虚无主义的交界：前者仍保留德性，后者只剩消散。北岛的排比把两者压在同一句里，形成反讽。", "tags": ["低落", "释然", "迷茫"]},
    {"id": "w2-156", "text": "你没有如期归来，而这正是离别的意义", "source": "北岛《白日梦》", "concept": "离别的意义", "explanation": "离别之所以成立，是因为期待没有兑现。这句话把等待的落空说成一种结构，而不是一次意外；承认它，反而能开始收拾行李。落空，也是一种答复。", "western": "这接近拉康式的缺失：意义由缺口构成，而非由在场构成。缺席不是意义的反面，而是意义得以发生的条件，缺口先于完整。", "tags": ["失去", "孤独", "释然"]},
    {"id": "w2-157", "text": "死是一件不必急于求成的事，死是一个必然会降临的节日", "source": "史铁生《我与地坛》", "concept": "向死的安心", "explanation": "把死亡说成节日，是一种奇特的松弛：既然它一定会来，就不必自己赶路。这句话救过很多人，因为它把“要不要活”暂时从桌上拿走了。先把这道题放下。", "western": "这几乎是对海德格尔“向死存在”的中文改写，但方向相反：不是通过死来激活生，而是通过承认死的必然来卸下生的急躁。急切因此被卸下。", "tags": ["低落", "平静", "释然"]},
    {"id": "w2-158", "text": "一个人，出生了，这就不再是一个可以辩论的问题", "source": "史铁生《我与地坛》", "concept": "既成的事实", "explanation": "有些事实不需要同意就已经生效：出生、身体、家庭。与其反复追问“为什么是我”，不如把力气放在既成之后还能做什么。接受不是认输，是省力。省下的力气，可以用在别处。", "western": "这接近海德格尔的“被抛”：此在总已被交付给某些不由自己选择的条件。自由从接受被抛开始，而不是从否认它开始。", "tags": ["迷茫", "平静", "反思"]},
    {"id": "w2-159", "text": "就命运而言，休论公道", "source": "史铁生《我与地坛》", "concept": "不问公道", "explanation": "命运不讲道理，追问“凭什么”往往只得到更多愤怒。这不是让你认命，而是把力气从算账转向应对：接下来怎么办，才是能动的部分。剩下的事，才是你的。", "western": "这接近尼采对“怨恨”的批判：弱者以道德问责代替行动，把无力感包装成正义。史铁生的句子更温和，是及时止损，而非蔑视。", "tags": ["低落", "释然", "反思"]},
    {"id": "w2-160", "text": "但是太阳，他每时每刻都是夕阳也都是旭日", "source": "史铁生《我与地坛》", "concept": "同时的夕与晨", "explanation": "同一个太阳，对这边是落日，对那边是日出。你正经历的结束，在别处也许正是开始；这不安慰人，但确实扩大了视野。换个时区看，结论会变。", "western": "这接近赫拉克利特的流变与视角主义：同一事物的性质取决于观察位置。史铁生用天文学的画面，做出了相对性的哲学表述。", "tags": ["平静", "变化", "释然"]},
    {"id": "w2-161", "text": "人真正的名字，叫做欲望", "source": "史铁生《我与地坛》", "concept": "欲望的名字", "explanation": "人总是想要点什么：想要好起来、想要被爱、想要意义。承认这一点，就不必为自己的不满足羞愧；欲望不是缺陷，是还在活的证据。它不体面，但很诚实。", "western": "这接近斯宾诺莎的“欲望即本质”：人的本质就是有意识的欲求。区别在于史铁生更悲观，也更温和地接受了这种无休止。", "tags": ["迷茫", "反思", "期待"]},
    {"id": "w2-162", "text": "命定的局限尽可永在，但不屈的挑战不可须臾或缺", "source": "史铁生《我的梦想》", "concept": "局限与挑战", "explanation": "局限不会因为努力就消失，这是实话；但人也不必等局限消失才开始。挑战的意义不在于赢，而在于让日子保持向前的形状。两件事可以同时为真。", "western": "这接近加缪的西西弗：荒诞不会被解决，反抗却必须持续。史铁生把英雄式的反抗改成日常的、几乎温情的坚持。", "tags": ["疲惫", "期待", "专注"]},
    {"id": "w2-163", "text": "一个人只拥有此生此世是不够的，他还应该拥有诗意的世界", "source": "王小波《万寿寺》", "concept": "诗意的世界", "explanation": "此生此世是有限的：一份工作、一个城市、一副身体。诗意不是逃避，而是给这有限的现实加一层自己的解释和想象。那层东西，别人夺不走。", "western": "这接近尼采的“艺术形而上学”：人需要审美的外观来承受存在的沉重。诗意世界不是幻觉，而是让现实可被居住的构造。", "tags": ["阅读", "舒展", "放空"]},
    {"id": "w2-164", "text": "我活在世上，无非想要明白些道理，遇见些有趣的事", "source": "王小波《沉默的大多数》", "concept": "明白与有趣", "explanation": "把人生目标定得这么低，反而很难做到：明白需要诚实，有趣需要好奇心。两者都不产出绩效，却决定了日子有没有滋味。这两样，都不进考核表。", "western": "这接近密尔式的幸福论：幸福不在于目标达成，而在于多样而活跃的经验。王小波把功利主义的目的论换成了趣味论。", "tags": ["阅读", "舒展", "期待"]},
    {"id": "w2-165", "text": "似水流年是一个人所有的一切", "source": "王小波《似水流年》", "concept": "似水流年", "explanation": "人真正拥有的，不是成就清单，而是一段流过的时间，以及其中记得住的几个人、几件事。这样想，很多焦虑会显得没那么紧急。剩下的，都是身外之物。", "western": "这接近柏格森的绵延：自我就是时间本身，而不是时间中的物件。王小波用最俗的词，说出了最不俗的同一性理论。", "tags": ["平静", "失去", "反思"]},
    {"id": "w2-166", "text": "人活在世界上，快乐和痛苦本就分不清", "source": "王小波《黄金时代》", "concept": "苦乐难分", "explanation": "有些快乐里带着疼，有些痛苦过后又觉得值得。非要给感受分类，反而会错过它本来的样子；先允许它混着，再慢慢辨认。混着，也是一种真实。", "western": "这接近亚里士多德对混合情感的分析，也接近尼采的“痛苦中的欢愉”：对立面并不彼此排斥，而在同一经验里互为条件。", "tags": ["低落", "释然", "反思"]},
    {"id": "w2-167", "text": "乡愁是一枚小小的邮票", "source": "余光中《乡愁》", "concept": "乡愁的形状", "explanation": "乡愁被写成邮票、船票、坟墓、海峡，都是很小的东西。人对家的想念，往往附着在具体的物件上，而不是抽象的“故乡”两个字。邮票小，装得下一个家。", "western": "这接近巴什拉的“空间诗学”：情感依附于具体的物与场所，而非概念。邮票是微小的容器，装下了不能随身携带的家。", "tags": ["孤独", "失去", "夜晚"]},
    {"id": "w2-168", "text": "酒入豪肠，七分酿成了月光", "source": "余光中《寻李白》", "concept": "豪气与月光", "explanation": "这两句把喝酒写得像炼金：豪气进去，月光出来。它夸张，却准确地说出了某种状态：人被自己的情绪抬高，连看世界的方式都变了。世界跟着变形，也说得通。", "western": "这接近尼采的“酒神精神”：酒精与狂欢使人暂时摆脱个体化的界限，进入更原始的肯定。余光中把它接回了中国的诗酒传统。", "tags": ["舒展", "夜晚", "放空"]},
    {"id": "w2-169", "text": "掉头一去是风吹黑发，回首再来已雪满白头", "source": "余光中《浪子回头》", "concept": "一去一回", "explanation": "离开和回来之间，隔着一整个人生的长度。这句话不劝人别走，只是提醒：有些告别当时很轻，回头才知道它有多重。想回去，就早点回去。回头，也是一种抵达。", "western": "这接近赫拉克利特的河流：人不能两次回到同一个地方，因为回去的人也已经不同。时间在身体上留下了可读的刻度。", "tags": ["失去", "变化", "低落"]},
    {"id": "w2-170", "text": "前尘隔海，古屋不再", "source": "余光中《听听那冷雨》", "concept": "隔海的旧居", "explanation": "八个字里有两重失去：地理上隔着海，时间上古屋也没了。想回去的地方，往往在你能回去之前就已经改变，这份遗憾值得被承认。承认它，才放得下。", "western": "这接近本雅明对“灵光”的哀悼：原真性一旦失去，复制与回忆都无法真正替代。故乡在此成为一种不可复原的在场。", "tags": ["失去", "孤独", "雨"]},
    {"id": "w2-171", "text": "世间好物不坚牢，彩云易散琉璃脆", "source": "杨绛《我们仨》", "concept": "好物不坚牢", "explanation": "杨绛在书里反复引用这句，因为它说中了她的处境：越好的东西越容易散。承认脆弱，不是提前悲伤，而是提醒你在它还完整时好好看它。", "western": "这接近斯多葛的“预想失去”：提前承认无常，以便在拥有时不被恐惧支配。脆弱性不是反对爱的理由，而是爱的前提。", "tags": ["失去", "平静", "感激"]},
    {"id": "w2-172", "text": "我一个人思念我们仨", "source": "杨绛《我们仨》", "concept": "一个人的怀念", "explanation": "“我们仨”变成了“我一个人”，中间的落差没有形容词。哀悼常常就是这样安静：日子照过，只是身边少了两个位置。不必急着填满它们。位置空着，也是一种在。", "western": "这接近列维纳斯的“他者的缺席”：逝者不在场，却仍构成自我的一部分。怀念因此是一种继续的关系，而不是关系的结束。", "tags": ["失去", "孤独", "夜晚"]},
    {"id": "w2-173", "text": "从今往后，咱们只有死别，不再生离", "source": "杨绛《我们仨》", "concept": "不再生离", "explanation": "这句话把“分开”分成两种：还能再见的那种，和不能的那种。说过之后，日子仍然会有摩擦，但底线被重新划清楚了。知道底线，人反而松。说清楚，日子才过得下去。", "western": "这接近海德格尔对“存在到头”的分析：死亡是不可替代的界限，而生离仍留有再见的可能。杨绛用一句家常话，划出了两者的差别。", "tags": ["失去", "社交", "平静"]},
    {"id": "w2-174", "text": "惟有身处卑微的人，最有机缘看到世态人情的真相", "source": "杨绛《隐身衣》", "concept": "卑微的视角", "explanation": "站在低处，看得见高处的表演，也看得见同处低处的人的难处。这种视角不舒服，却更接近真实；它让人少一点幻想，多一点体谅。低处看见的，往往更真。", "western": "这接近马克思式的“底层视角”：被压迫者的位置具有认识论优势，能看见系统运作的缝隙。杨绛把它写成了温和的世故。", "tags": ["反思", "低落", "社交"]},
    {"id": "w2-175", "text": "赤子孤独了，会创造一个世界", "source": "傅雷《傅雷家书》", "concept": "孤独的创造", "explanation": "傅雷把孤独说成一种材料，而不是一种病。人在没人陪伴的时候，往往会退回自己的内部，那里有可能长出一点只属于你的东西。孤独不必急着填满。", "western": "这接近尼采对“孤独”的肯定：创造需要从群体的噪音中退出。也接近弗洛姆的区分——孤独可以是生产的条件，也可以是恐惧的来源。", "tags": ["孤独", "专注", "期待"]},
    {"id": "w2-176", "text": "得失成败尽量置之度外，只求竭尽所能，无愧于心", "source": "傅雷《傅雷家书》", "concept": "尽力与无愧", "explanation": "把结果放在一边，不是说结果不重要，而是不让它在你动手之前就把你压住。先问自己有没有尽力，这是唯一还能由你回答的问题。这一问，随时可以答。", "western": "这是斯多葛“控制二分法”的家书版本：意志之内的是努力，之外的是成败。爱比克泰德认为，把幸福系于外物必然导致焦虑。", "tags": ["焦虑", "专注", "平静"]},
    {"id": "w2-177", "text": "太阳太强烈，会把五谷晒焦；雨水太猛，也会淹死庄稼", "source": "傅雷《傅雷家书》", "concept": "过度的伤害", "explanation": "好的东西过量，也会变成灾害：关心太密会窒息，努力太猛会垮掉。傅雷用它劝儿子节制，这句话对今天拼命的人同样适用。分寸，是长期主义的一部分。", "western": "这接近亚里士多德的中道伦理：德性在过度与不足之间，勇敢介于鲁莽与怯懦。适度不是平庸，而是可持续的条件。", "tags": ["疲惫", "反思", "平静"]},
    {"id": "w2-178", "text": "先做人，其次做艺术家，再次做音乐家", "source": "傅雷《傅雷家书》", "concept": "做人的次序", "explanation": "技艺可以练，做人却要一辈子。傅雷把顺序排得很清楚：先成为一个像样的人，再谈成为什么样的专家。这个次序，今天仍然稀缺。次序对了，急也少些。", "western": "这接近康德“人是目的”的立场：专业身份不能替代人格。也接近古希腊的德性教育——先成为一个完整的人，再成为一个出色的专家。", "tags": ["反思", "专注", "阅读"]},
    {"id": "w2-179", "text": "人一辈子都在高潮、低潮中浮沉", "source": "傅雷《傅雷家书》", "concept": "人生的浮沉", "explanation": "没有谁能一直待在高处，也没有谁永远在低处。把波动当成常态，人就不必在低谷时追问“为什么是我”，也不必在高处时害怕掉下来。起伏是常态，不必当成判决。", "western": "这接近赫拉克利特的流变与斯多葛的“命运之轮”：状态本就周期性更替。理性的人不与之争，只调整自己的姿态。", "tags": ["低落", "平静", "变化"]},
    {"id": "w2-180", "text": "心中的苦闷不在家信中发泄，又哪里去发泄呢", "source": "傅雷《傅雷家书》", "concept": "倾诉的出口", "explanation": "傅雷在信里主动给儿子留了一个可以诉苦的地方。人需要一个不必体面、不必振作的出口；如果家里不是，就去找一个能接住你的人。有人接住，就不用硬扛。", "western": "这接近亚里士多德论友爱的功用：朋友是另一个自我，向其倾诉使痛苦获得形式。弗洛伊德后来把这种“说出来”发展为谈话疗法。", "tags": ["孤独", "社交", "低落"]},
]
# 固定种子打乱，避免总从同一句开始，同时保证每次运行顺序一致。
random.Random(20261111).shuffle(QUOTES)


def quote_for_day(day: date | None = None) -> dict[str, Any]:
    day = day or date.today()
    return QUOTES[day.toordinal() % len(QUOTES)]


def quote_at(index: int) -> dict[str, Any]:
    return QUOTES[index % len(QUOTES)]


def quote_index(quote: dict[str, Any]) -> int:
    return next((i for i, item in enumerate(QUOTES) if item["id"] == quote["id"]), 0)
